INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "今", "is_correct": true, "explanation": "「昔」の対義語で、現在を指す。辞書でも対になる語として挙げられている。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す名詞で、「昔」と対になる関係にはない。"}, {"text": "音楽", "is_correct": false, "explanation": "芸術のジャンルを表す語で、時間の対義語ではない。"}, {"text": "家", "is_correct": false, "explanation": "住まいを表す語で、「昔」と対になる関係にはない。"}], "correct_answer": "今", "explanations": {"今": "「昔」の対義語で、現在を指す。辞書でも対になる語として挙げられている。", "天気": "空模様を表す名詞で、「昔」と対になる関係にはない。", "音楽": "芸術のジャンルを表す語で、時間の対義語ではない。", "家": "住まいを表す語で、「昔」と対になる関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「昔から」で、過去のある時点を起点として示す。"}, {"text": "を", "is_correct": false, "explanation": "「昔を人気があります」は成り立たない。「を」は目的語を示すが、ここでは「人気がある」の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」では、時間の起点を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、「人気がある」と結びつかない。"}], "correct_answer": "から", "explanations": {"から": "「昔から」で、過去のある時点を起点として示す。", "を": "「昔を人気があります」は成り立たない。「を」は目的語を示すが、ここでは「人気がある」の対象にならない。", "で": "場所や手段を示す「で」では、時間の起点を表せない。", "へ": "方向を示す「へ」では、「人気がある」と結びつかない。"}, "error_tags": {"を": "object", "で": "location_or_means", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "今", "is_correct": true, "explanation": "「昔」の対義語で、現在を指す。辞書でも対になる語として挙げられている。"}, {"text": "海", "is_correct": false, "explanation": "自然の場所を表す名詞で、時間の対義語ではない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物を表す名詞で、「昔」と対になる関係にはない。"}, {"text": "靴", "is_correct": false, "explanation": "身につける物を表す名詞で、「昔」と対になる関係にはない。"}], "correct_answer": "今", "explanations": {"今": "「昔」の対義語で、現在を指す。辞書でも対になる語として挙げられている。", "海": "自然の場所を表す名詞で、時間の対義語ではない。", "電車": "乗り物を表す名詞で、「昔」と対になる関係にはない。", "靴": "身につける物を表す名詞で、「昔」と対になる関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっとまえのこと。", "primary_collocate": null, "pronunciation": "むかし", "ipa": "mɯkaɕi", "syllable_count": 3, "sentences": [{"text": "昔、ここに大きな木がありました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "昔[むかし]、ここに大[おお]きな木[き]がありました。", "sentence_source": "generated"}, {"text": "祖父は昔、先生でした。", "target_word": "昔", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔[むかし]、先生[せんせい]でした。", "sentence_source": "generated"}, {"text": "この町は昔より静かになりました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "この町[まち]は昔[むかし]より静[しず]かになりました。", "sentence_source": "generated"}, {"text": "昔の友達に手紙を書きました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "昔[むかし]の友達[ともだち]に手紙[てがみ]を書[か]きました。", "sentence_source": "generated"}, {"text": "昔は電話がなかったので、手紙で連絡しました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "昔[むかし]は電話[でんわ]がなかったので、手紙[てがみ]で連絡[れんらく]しました。", "sentence_source": "generated"}, {"text": "母は昔の写真を見て笑いました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "母[はは]は昔[むかし]の写真[しゃしん]を見[み]て笑[わら]いました。", "sentence_source": "generated"}, {"text": "私は昔、ピアノを習っていましたが、今はやめました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "私[わたし]は昔[むかし]、ピアノを習[なら]っていましたが、今[いま]はやめました。", "sentence_source": "generated"}, {"text": "この店は昔から人気があります。", "target_word": "昔", "complexity_tier": "T3", "furigana": "この店[みせ]は昔[むかし]から人気[にんき]があります。", "sentence_source": "generated"}, {"text": "昔の道は狭くて、車が通れませんでした。", "target_word": "昔", "complexity_tier": "T3", "furigana": "昔[むかし]の道[みち]は狭[せま]くて、車[くるま]が通[とお]れませんでした。", "sentence_source": "generated"}, {"text": "昔の遊びを、祖母が教えてくれました。", "target_word": "昔", "complexity_tier": "T3", "furigana": "昔[むかし]の遊[あそ]びを、祖母[そぼ]が教[おし]えてくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昔", "label": "基本形"}, {"form": "昔の", "label": "連体修飾形"}], "register": "中立", "sense_fingerprint": "ずっと前の過去の時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昔", "is_correct": true, "explanation": "ずっと前の時期を表す「昔」が入ると、過去の出来事を述べる文に合う。"}, {"text": "来年", "is_correct": false, "explanation": "未来の時期を表す語で、「ありました」という過去の文と合わない。"}, {"text": "明日", "is_correct": false, "explanation": "未来の日を表す語で、過去の出来事の説明には合わない。"}, {"text": "来週", "is_correct": false, "explanation": "未来の時期を表す語で、過去のことを述べる文には合わない。"}], "explanations": {"昔": "ずっと前の時期を表す「昔」が入ると、過去の出来事を述べる文に合う。", "来年": "未来の時期を表す語で、「ありました」という過去の文と合わない。", "明日": "未来の日を表す語で、過去の出来事の説明には合わない。", "来週": "未来の時期を表す語で、過去のことを述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "昔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツは昔で、もう着られません。", "explanation": "ここは「古い」の意味。「昔」は名詞で、物の古さを言うには「古い」を使う。"}, {"text": "彼は昔の時間に合わせて、今朝出かけた。", "explanation": "ここは「昔」を時刻の意味で使っている。「昔」は遠い過去を指す語で、時刻を表すのは「午前」などの語。"}, {"text": "来週の旅行は昔が楽しみだ。", "explanation": "「昔」は過去の時期を指す。未来の楽しみには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昔", "is_correct": true, "explanation": "過去の時期を表す「昔」が入ると、「今はやめました」と対比する文に合う。"}, {"text": "来月", "is_correct": false, "explanation": "未来の時期を表す語で、過去の習いごとを述べる文と合わない。"}, {"text": "将来", "is_correct": false, "explanation": "未来を表す語で、過去の習いごとを述べる文と合わない。"}, {"text": "明後日", "is_correct": false, "explanation": "未来の日を表す語で、過去の出来事の説明には合わない。"}], "explanations": {"昔": "過去の時期を表す「昔」が入ると、「今はやめました」と対比する文に合う。", "来月": "未来の時期を表す語で、過去の習いごとを述べる文と合わない。", "将来": "未来を表す語で、過去の習いごとを述べる文と合わない。", "明後日": "未来の日を表す語で、過去の出来事の説明には合わない。"}, "sentence_index": 6, "correct_answer": "昔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は昔だ。", "explanation": "ここは「昔」を現在の日を指す意味で使っている。「昔」は遠い過去を指す語なので、今日には当てはまらない。"}, {"text": "宿題を昔終わらせた。", "explanation": "「昔」は遠い過去を指す名詞で、「すぐに」の意味の副詞としては使えない。"}, {"text": "この箱は昔でいっぱいだ。", "explanation": "ここは「昔」を物の中身の意味で使っている。「昔」は遠い過去を指す語で、箱を満たす中身にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "おばあちゃんから昔を話を聞きました。", "corrected_sentence": "おばあちゃんから昔の話を聞きました。", "error_description": "「昔の話」の「の」を「を」に変えたため誤り。「昔」は「話」を修飾するので、「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34996, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔で、この町は静かでした。", "corrected_sentence": "昔から、この町は静かでした。", "error_description": "「昔から」の「から」を「で」に変えたため誤り。起点を表す「から」が必要で、「で」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
