INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35000, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをつくったりうごかしたりする、でんきやエンジンではたらくどうぐ。", "primary_collocate": null, "pronunciation": "きかい", "ipa": "kikai", "syllable_count": 3, "sentences": [{"text": "工場では大きな機械が一日中動いています。", "target_word": "機械", "complexity_tier": "T3", "furigana": "工場[こうじょう]では大[おお]きな機械[きかい]が一日中[いちにちじゅう]動[うご]いています。", "sentence_source": "generated"}, {"text": "この機械は電気で動くので、スイッチを入れてください。", "target_word": "機械", "complexity_tier": "T3", "furigana": "この機械[きかい]は電気[でんき]で動[うご]くので、スイッチを入[い]れてください。", "sentence_source": "generated"}, {"text": "機械が故障したため、工場の仕事が止まりました。", "target_word": "機械", "complexity_tier": "T3", "furigana": "機械[きかい]が故障[こしょう]したため、工場[こうじょう]の仕事[しごと]が止[と]まりました。", "sentence_source": "generated"}, {"text": "古い機械を新しいものに取りかえました。", "target_word": "機械", "complexity_tier": "T3", "furigana": "古[ふる]い機械[きかい]を新[あたら]しいものに取[と]りかえました。", "sentence_source": "generated"}, {"text": "機械の使い方がわからないときは、先生に聞きます。", "target_word": "機械", "complexity_tier": "T3", "furigana": "機械[きかい]の使[つか]い方[かた]がわからないときは、先生[せんせい]に聞[き]きます。", "sentence_source": "generated"}, {"text": "父は機械を直すのが上手で、家の電気製品もよく直します。", "target_word": "機械", "complexity_tier": "T3", "furigana": "父[ちち]は機械[きかい]を直[なお]すのが上手[じょうず]で、家[いえ]の電気製品[でんきせいひん]もよく直[なお]します。", "sentence_source": "generated"}, {"text": "この機械でパンの生地をこねています。", "target_word": "機械", "complexity_tier": "T3", "furigana": "この機械[きかい]でパンの生地[きじ]をこねています。", "sentence_source": "generated"}, {"text": "機械は人より速く、同じ形の部品を作ります。", "target_word": "機械", "complexity_tier": "T3", "furigana": "機械[きかい]は人[ひと]より速[はや]く、同[おな]じ形[かたち]の部品[ぶひん]を作[つく]ります。", "sentence_source": "generated"}, {"text": "機械の音が大きくて、話し声が聞こえません。", "target_word": "機械", "complexity_tier": "T3", "furigana": "機械[きかい]の音[おと]が大[おお]きくて、話[はな]し声[ごえ]が聞[き]こえません。", "sentence_source": "generated"}, {"text": "新しい機械を買うために、会社はお金をためています。", "target_word": "機械", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]を買[か]うために、会社[かいしゃ]はお金[かね]をためています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "機械", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "電気やエンジンで動き、ものを作ったり動かしたりする道具・装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 取りかえ (Zipf 1.48)']::text[], '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35000, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "機械", "is_correct": true, "explanation": "電気やエンジンで一日中動く装置なので、「大きな機械が一日中動いている」に合う。"}, {"text": "植物", "is_correct": false, "explanation": "植物は育つもので、工場で一日中動くものではないので文に合わない。"}, {"text": "文房具", "is_correct": false, "explanation": "文字を書く道具で、工場で一日中動くものではないので文に合わない。"}, {"text": "建物", "is_correct": false, "explanation": "建っている物で一日中動くことはないので、文に合わない。"}], "explanations": {"機械": "電気やエンジンで一日中動く装置なので、「大きな機械が一日中動いている」に合う。", "植物": "植物は育つもので、工場で一日中動くものではないので文に合わない。", "文房具": "文字を書く道具で、工場で一日中動くものではないので文に合わない。", "建物": "建っている物で一日中動くことはないので、文に合わない。"}, "sentence_index": 0, "correct_answer": "機械"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "理科の実験では、ビーカーなどの機械を使います。", "explanation": "ここは〈器具〉（実験で使う容器や道具）の意味。ビーカーのような器具は〈器具〉で、電気やエンジンで動く〈機械〉とは言わない。"}, {"text": "鉛筆は、字を書くための機械です。", "explanation": "ここは〈道具〉の意味。鉛筆は手で使う道具で、電気やエンジンで動く〈機械〉とは言わない。"}, {"text": "この会社の機械は、社員の意見を集めて決めることです。", "explanation": "ここは〈仕組み〉の意味。会社の決め方は〈仕組み〉で表し、〈機械〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35000, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "機械", "is_correct": true, "explanation": "電気などで動く機械で、パン生地をこねる用途に合う。"}, {"text": "包丁", "is_correct": false, "explanation": "切るための道具で、生地をこねるのには使わないので合わない。"}, {"text": "洗剤", "is_correct": false, "explanation": "汚れを落とすもので、生地をこねる道具ではないので合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食べ物を冷やす家電で、生地をこねる道具ではないので合わない。"}], "explanations": {"機械": "電気などで動く機械で、パン生地をこねる用途に合う。", "包丁": "切るための道具で、生地をこねるのには使わないので合わない。", "洗剤": "汚れを落とすもので、生地をこねる道具ではないので合わない。", "冷蔵庫": "食べ物を冷やす家電で、生地をこねる道具ではないので合わない。"}, "sentence_index": 6, "correct_answer": "機械"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市の機械が、住民の相談を毎週受け付けています。", "explanation": "ここは〈機関〉（役所などの組織）の意味。役所には〈機関〉を使い、〈機械〉とは言わない。"}, {"text": "このアプリの機械は、写真を自動で明るくします。", "explanation": "ここは〈機能〉（働き）の意味。アプリの働きは〈機能〉で表し、〈機械〉とは言わない。"}, {"text": "今日の機械は、午後から雨です。", "explanation": "ここは〈天気〉の意味。空模様は〈天気〉で表し、〈機械〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35000, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い機械を壊れて、新しい機械を買いました。", "corrected_sentence": "古い機械が壊れて、新しい機械を買いました。", "error_description": "「機械を」の助詞が誤り。「壊れる」は自動詞なので主語に「が」を使う（正：機械が）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35000, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい機械を動きました。", "corrected_sentence": "新しい機械が動きました。", "error_description": "「機械を」の助詞が誤り。「動く」は自動詞なので主語に「が」を使う（正：機械が）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
