INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35004, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "たくさんは、おおいといういみです。", "primary_collocate": null, "pronunciation": "たくさん", "ipa": "takɯsaɴ", "syllable_count": 4, "sentences": [{"text": "公園で、子どもたちが沢山遊んでいる。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "公園[こうえん]で、子[こ]どもたちが沢山[たくさん]遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "夏休みに、本を沢山読むつもりだ。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、本[ほん]を沢山[たくさん]読[よ]むつもりだ。", "sentence_source": "generated"}, {"text": "今日は宿題が沢山あるので、遊びに行けない。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "今日[きょう]は宿題[しゅくだい]が沢山[たくさん]あるので、遊[あそ]びに行[い]けない。", "sentence_source": "generated"}, {"text": "母は私のために、料理を沢山作ってくれた。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]のために、料理[りょうり]を沢山[たくさん]作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "昨日の雨で、道に水が沢山たまっている。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "昨日[きのう]の雨[あめ]で、道[みち]に水[みず]が沢山[たくさん]たまっている。", "sentence_source": "generated"}, {"text": "この店には、おもしろい漫画が沢山ある。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "この店[みせ]には、おもしろい漫画[まんが]が沢山[たくさん]ある。", "sentence_source": "generated"}, {"text": "パーティーの食べ物が沢山残ったので、持って帰った。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "パーティーの食[た]べ物[もの]が沢山[たくさん]残[のこ]ったので、持[も]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "友だちから沢山のプレゼントをもらって、うれしかった。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "友[とも]だちから沢山[たくさん]のプレゼントをもらって、うれしかった。", "sentence_source": "generated"}, {"text": "試験の前に、漢字を沢山覚えなければならない。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、漢字[かんじ]を沢山[たくさん]覚[おぼ]えなければならない。", "sentence_source": "generated"}, {"text": "沢山食べたので、もうおなかがいっぱいです。", "target_word": "沢山", "complexity_tier": "T3", "furigana": "沢山[たくさん]食[た]べたので、もうおなかがいっぱいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "沢山", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数や量が多いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35004, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沢山", "is_correct": true, "explanation": "「子どもたちが沢山遊んでいる」の形で、多くの量や回数を表す副詞として正しい。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は否定の文と結びつく副詞で、肯定の「遊んでいる」には合わない。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "「ぜんぜん」は否定の文と結びつく副詞で、肯定の「遊んでいる」には合わない。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも」は否定の文と結びつく副詞で、肯定の「遊んでいる」には合わない。"}], "explanations": {"沢山": "「子どもたちが沢山遊んでいる」の形で、多くの量や回数を表す副詞として正しい。", "決して": "「決して」は否定の文と結びつく副詞で、肯定の「遊んでいる」には合わない。", "ぜんぜん": "「ぜんぜん」は否定の文と結びつく副詞で、肯定の「遊んでいる」には合わない。", "少しも": "「少しも」は否定の文と結びつく副詞で、肯定の「遊んでいる」には合わない。"}, "sentence_index": 0, "correct_answer": "沢山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は、沢山静かだ。", "explanation": "〈とても〉の場面。沢山は量の多さを表すので、形容詞の程度を強める用法には使わない。"}, {"text": "彼は沢山一人で暮らしている。", "explanation": "沢山は多さを表すので、一人という少ない人数とは矛盾し、この用法では使わない。"}, {"text": "沢山の昔に、祖父は亡くなった。", "explanation": "〈はるか昔〉の場面。沢山は量の多さを表すので、時間の遠さを表す用法には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35004, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沢山", "is_correct": true, "explanation": "「食べ物が沢山残った」の形で、残った量が多いことを表す副詞として正しい。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも」は否定の文と結びつく副詞で、「食べ物が残った」の肯定文には合わない。"}, {"text": "一度も", "is_correct": false, "explanation": "「一度も」は否定の文と結びつく副詞で、肯定の「残った」には合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで」は比喩の文と結びつく副詞で、「食べ物が残った」の事実の説明には合わない。"}], "explanations": {"沢山": "「食べ物が沢山残った」の形で、残った量が多いことを表す副詞として正しい。", "必ずしも": "「必ずしも」は否定の文と結びつく副詞で、「食べ物が残った」の肯定文には合わない。", "一度も": "「一度も」は否定の文と結びつく副詞で、肯定の「残った」には合わない。", "まるで": "「まるで」は比喩の文と結びつく副詞で、「食べ物が残った」の事実の説明には合わない。"}, "sentence_index": 6, "correct_answer": "沢山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は沢山ゆっくり歩いた。", "explanation": "沢山は量の多さを表すので、歩き方の様子を表す「ゆっくり」とは結びつかず、この用法では使わない。"}, {"text": "今朝は沢山寒いので、上着を着た。", "explanation": "〈とても〉の場面。沢山は量の多さを表すので、寒さの程度を強める用法には使わない。"}, {"text": "その写真は、沢山の一枚しかない。", "explanation": "沢山は多さを表すので、「一枚しかない」という少ない数と矛盾し、この用法では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35004, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭に、沢山な花が咲いている。", "corrected_sentence": "庭に、沢山の花が咲いている。", "error_description": "「沢山」の後に名詞を続けるときは「の」を使う。「沢山な花」は誤りで、正しくは「沢山の花」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35004, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄から沢山なお金をもらった。", "corrected_sentence": "兄から沢山のお金をもらった。", "error_description": "「沢山」の後に名詞を続けるときは「の」を使う。「沢山なお金」は誤りで、正しくは「沢山のお金」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「窓のそばに移します」と移動先を示す「に」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「花を」という目的語がある文で、「〜が移します」とは成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「花を」で既に使われており、二つ目の「を」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「窓のそばの移します」は動詞に続かず不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「窓のそばに移します」と移動先を示す「に」。", "が": "主語を示す「が」。「花を」という目的語がある文で、「〜が移します」とは成り立たない。", "を": "目的語の「を」は「花を」で既に使われており、二つ目の「を」は不自然。", "の": "連体の「の」。「窓のそばの移します」は動詞に続かず不自然。"}, "error_tags": {"が": "subject", "を": "object", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「大阪に移す」と移動先を示す「に」。"}, {"text": "と", "is_correct": false, "explanation": "引用や共同の「と」。「大阪と移す」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「大阪の移す」では動詞に続かず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。移動先を示さず、「大阪より移す」は不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「大阪に移す」と移動先を示す「に」。", "と": "引用や共同の「と」。「大阪と移す」は成り立たない。", "の": "連体の「の」。「大阪の移す」では動詞に続かず不自然。", "より": "比較の「より」。移動先を示さず、「大阪より移す」は不自然。"}, "error_tags": {"と": "quotation", "の": "possessive", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを　べつの　ばしょに　うごかす。", "primary_collocate": null, "pronunciation": "うつす", "ipa": "ɯtsɯsɯ", "syllable_count": 3, "sentences": [{"text": "重い荷物を、玄関から部屋の中に移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を、玄関[げんかん]から部屋[へや]の中[なか]に移[うつ]した。", "sentence_source": "generated"}, {"text": "日当たりが悪いので、花を窓のそばに移します。", "target_word": "移します", "complexity_tier": "T3", "furigana": "日当[ひあ]たりが悪[わる]いので、花[はな]を窓[まど]のそばに移[うつ]します。", "sentence_source": "generated"}, {"text": "古いデータを新しいパソコンに移すのに、二時間かかった。", "target_word": "移す", "complexity_tier": "T3", "furigana": "古[ふる]いデータを新[あたら]しいパソコンに移[うつ]すのに、二時間[にじかん]かかった。", "sentence_source": "generated"}, {"text": "部屋が暑かったので、病人を涼しい場所に移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "部屋[へや]が暑[あつ]かったので、病人[びょうにん]を涼[すず]しい場所[ばしょ]に移[うつ]した。", "sentence_source": "generated"}, {"text": "会議室がせまいため、イスを隣の部屋へ移してください。", "target_word": "移して", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]がせまいため、イスを隣[となり]の部屋[へや]へ移[うつ]してください。", "sentence_source": "generated"}, {"text": "引っ越しのとき、住民票を新しい町に移す手続きをした。", "target_word": "移す", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのとき、住民票[じゅうみんひょう]を新[あたら]しい町[まち]に移[うつ]す手続[てつづ]きをした。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、パーティーを室内に移すことにした。", "target_word": "移す", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、パーティーを室内[しつない]に移[うつ]すことにした。", "sentence_source": "generated"}, {"text": "彼は本社を東京から大阪に移すと発表した。", "target_word": "移す", "complexity_tier": "T3", "furigana": "彼[かれ]は本社[ほんしゃ]を東京[とうきょう]から大阪[おおさか]に移[うつ]すと発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "小さな苗を庭の畑に移すと、すぐに根がついた。", "target_word": "移す", "complexity_tier": "T3", "furigana": "小[ちい]さな苗[なえ]を庭[にわ]の畑[はたけ]に移[うつ]すと、すぐに根[ね]がついた。", "sentence_source": "generated"}, {"text": "机の上の本を、棚に移しておいてくれますか。", "target_word": "移し", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の本[ほん]を、棚[たな]に移[うつ]しておいてくれますか。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移す", "label": "終止形"}, {"form": "移さない", "label": "否定形"}, {"form": "移します", "label": "丁寧形"}, {"form": "移して", "label": "て形"}, {"form": "移した", "label": "過去形"}, {"form": "移せば", "label": "仮定形"}, {"form": "移そう", "label": "意志形"}, {"form": "移される", "label": "受身形"}], "register": "plain", "sense_fingerprint": "ものを今の場所から別の場所へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移した", "is_correct": true, "explanation": "正解。他動詞「移す」の過去形で、「荷物を」という目的語をとって「〜を移した」となる。"}, {"text": "移った", "is_correct": false, "explanation": "自動詞「移る」の過去形。「荷物が移った」なら成り立つが、「荷物を」とは合わない。"}, {"text": "移し", "is_correct": false, "explanation": "連用形で、文末にできず文が途中で終わってしまう。"}, {"text": "移して", "is_correct": false, "explanation": "て形で、文末にできない。「移してください」などの続きが必要になる。"}], "explanations": {"移した": "正解。他動詞「移す」の過去形で、「荷物を」という目的語をとって「〜を移した」となる。", "移った": "自動詞「移る」の過去形。「荷物が移った」なら成り立つが、「荷物を」とは合わない。", "移し": "連用形で、文末にできず文が途中で終わってしまう。", "移して": "て形で、文末にできない。「移してください」などの続きが必要になる。"}, "sentence_index": 0, "correct_answer": "移した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鏡に自分の顔を移して、髪を整えた。", "explanation": "ここは「映す（姿を映し出す）」の意味。移すは場所を動かすことなので、鏡に姿を映す意味では合わない。"}, {"text": "部屋が暑かったので、病人の服を涼しいものに移した。", "explanation": "ここは「変える」の意味。移すは場所を動かすことなので、服を別の種類に替える意味では合わない。"}, {"text": "急に寒くなったので、部屋の温度を移した。", "explanation": "ここは「上げる（温度を高くする）」の意味。移すは場所を動かすことなので、温度を上げる意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移す", "is_correct": true, "explanation": "正解。「移すことにした」の辞書形。「〜ことにした」に直接つく。"}, {"text": "移せ", "is_correct": false, "explanation": "命令形。「〜ことにした」には続かない。"}, {"text": "移れ", "is_correct": false, "explanation": "命令形（移る）。「〜ことにした」に続かず、文として成り立たない。"}, {"text": "移さ", "is_correct": false, "explanation": "未然形。「〜ことにした」の前には辞書形が必要。"}], "explanations": {"移す": "正解。「移すことにした」の辞書形。「〜ことにした」に直接つく。", "移せ": "命令形。「〜ことにした」には続かない。", "移れ": "命令形（移る）。「〜ことにした」に続かず、文として成り立たない。", "移さ": "未然形。「〜ことにした」の前には辞書形が必要。"}, "sentence_index": 6, "correct_answer": "移す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の上の本を写真に移しておいてくれますか。", "explanation": "ここは「写す（写真に撮る）」の意味。移すは物を場所に動かすことなので、撮影の意味では合わない。"}, {"text": "机の上の本を、新しい本に移しておいてくれますか。", "explanation": "ここは「替える（入れ替える）」の意味。移すは場所を動かすことなので、別の本と入れ替える意味では合わない。"}, {"text": "毎晩のお酒の量を、少しずつ移している。", "explanation": "ここは「減らす」の意味。移すは場所を動かすことなので、量を減らす意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が強くなったので、洗濯物が室内に移した。", "corrected_sentence": "雨が強くなったので、洗濯物を室内に移した。", "error_description": "「移す」は動かす対象に「を」をとる。「洗濯物が」では主語になり、目的語がないため不自然。正しくは「洗濯物を室内に移した」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "移します", "is_correct": true, "explanation": "正解。丁寧形（現在）で、文全体の現在の時制に合う。"}, {"text": "移し", "is_correct": false, "explanation": "連用形。文末にできず、文が途中で終わってしまう。"}, {"text": "移して", "is_correct": false, "explanation": "て形で、文末にできず続きが必要になる。"}, {"text": "移せば", "is_correct": false, "explanation": "仮定形で、「〜ば」の続きが必要なので文末にできない。"}], "correct_form": "移します", "base_form": "移す", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"移します": "正解。丁寧形（現在）で、文全体の現在の時制に合う。", "移し": "連用形。文末にできず、文が途中で終わってしまう。", "移して": "て形で、文末にできず続きが必要になる。", "移せば": "仮定形で、「〜ば」の続きが必要なので文末にできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35006, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、本棚を二階に移した予定です。", "corrected_sentence": "来週、本棚を二階に移す予定です。", "error_description": "「来週」は未来なので、過去形「移した」ではなく辞書形「移す」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "移す", "is_correct": true, "explanation": "正解。辞書形で、引用の「と」の前に置く。"}, {"text": "移し", "is_correct": false, "explanation": "連用形。「と」の前では文が途切れてしまう。"}, {"text": "移さ", "is_correct": false, "explanation": "未然形。「と」の前で文が成り立たない。"}, {"text": "移される", "is_correct": false, "explanation": "受身形。「移されると」は「移される時」の意味になり、発表の内容と合わない。"}], "correct_form": "移す", "base_form": "移す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"移す": "正解。辞書形で、引用の「と」の前に置く。", "移し": "連用形。「と」の前では文が途切れてしまう。", "移さ": "未然形。「と」の前で文が成り立たない。", "移される": "受身形。「移されると」は「移される時」の意味になり、発表の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「静かな部屋に移した」と移動先を示す「に」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「部屋が移した」となり不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「静かな部屋の移した」は動詞に続かず不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用の「と」。「部屋と移した」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「静かな部屋に移した」と移動先を示す「に」。", "が": "主語を示す「が」。「部屋が移した」となり不自然。", "の": "連体の「の」。「静かな部屋の移した」は動詞に続かず不自然。", "と": "共同や引用の「と」。「部屋と移した」は成り立たない。"}, "error_tags": {"が": "subject", "の": "possessive", "と": "quotation"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「屋根の下に移した」と移動先を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「荷物を」で既に使われており、「下を移した」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「下の移した」では動詞に続かず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。移動先を示さず、「下より移した」は不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「屋根の下に移した」と移動先を示す「に」。", "を": "目的語の「を」は「荷物を」で既に使われており、「下を移した」は不自然。", "の": "連体の「の」。「下の移した」では動詞に続かず不自然。", "より": "比較の「より」。移動先を示さず、「下より移した」は不自然。"}, "error_tags": {"を": "object", "の": "possessive", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や人を別の場所や状態に動かすこと。", "primary_collocate": null, "pronunciation": "うつす", "ipa": "ɯtsɯsɯ", "syllable_count": 3, "sentences": [{"text": "日当たりが悪いので、植木鉢を庭の南側に移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "日[ひ]当[あ]たりが悪[わる]いので、植木鉢[うえきばち]を庭[にわ]の南側[みなみがわ]に移[うつ]した。", "sentence_source": "generated"}, {"text": "看護師は患者を静かな部屋に移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "看護師[かんごし]は患者[かんじゃ]を静[しず]かな部屋[へや]に移[うつ]した。", "sentence_source": "generated"}, {"text": "会社は本社を東京から大阪に移すことにした。", "target_word": "移す", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は本社[ほんしゃ]を東京[とうきょう]から大阪[おおさか]に移[うつ]すことにした。", "sentence_source": "generated"}, {"text": "考えるだけでなく、計画を実行に移すことが大切だ。", "target_word": "移す", "complexity_tier": "T4", "furigana": "考[かんが]えるだけでなく、計画[けいかく]を実行[じっこう]に移[うつ]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "眠った赤ちゃんをそっとベッドに移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "眠[ねむ]った赤[あか]ちゃんをそっとベッドに移[うつ]した。", "sentence_source": "generated"}, {"text": "古いパソコンから新しいパソコンへデータを移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "古[ふる]いパソコンから新[あたら]しいパソコンへデータを移[うつ]した。", "sentence_source": "generated"}, {"text": "彼は窓の外から時計へ視線を移した。", "target_word": "移した", "complexity_tier": "T4", "furigana": "彼[かれ]は窓[まど]の外[そと]から時計[とけい]へ視線[しせん]を移[うつ]した。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、荷物を屋根の下に移した。", "target_word": "移した", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、荷物[にもつ]を屋根[やね]の下[した]に移[うつ]した。", "sentence_source": "generated"}, {"text": "小さい水槽が狭くなったので、魚を大きい水槽に移して飼っている。", "target_word": "移して", "complexity_tier": "T4", "furigana": "小[ちい]さい水槽[すいそう]が狭[せま]くなったので、魚[さかな]を大[おお]きい水槽[すいそう]に移[うつ]して飼[か]っている。", "sentence_source": "generated"}, {"text": "店を駅の近くに移してから、客が増えた。", "target_word": "移して", "complexity_tier": "T3", "furigana": "店[みせ]を駅[えき]の近[ちか]くに移[うつ]してから、客[きゃく]が増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移す", "label": "辞書形"}, {"form": "移さ", "label": "未然形"}, {"form": "移し", "label": "連用形"}, {"form": "移せ", "label": "命令形"}, {"form": "移そう", "label": "意志形"}, {"form": "移した", "label": "過去形"}, {"form": "移して", "label": "て形"}, {"form": "移さない", "label": "否定形"}], "register": "plain", "sense_fingerprint": "物・人・拠点・視線などを別の場所や段階へ動かす（他動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移した", "is_correct": true, "explanation": "正解。過去形で「植木鉢を〜に移した」と目的語「を」をとる。"}, {"text": "移し", "is_correct": false, "explanation": "連用形で、文末にできず文が途中で終わる。"}, {"text": "移して", "is_correct": false, "explanation": "て形で、文末にできない。"}, {"text": "移った", "is_correct": false, "explanation": "自動詞。「植木鉢が移った」となり、「を」とは合わない。"}], "explanations": {"移した": "正解。過去形で「植木鉢を〜に移した」と目的語「を」をとる。", "移し": "連用形で、文末にできず文が途中で終わる。", "移して": "て形で、文末にできない。", "移った": "自動詞。「植木鉢が移った」となり、「を」とは合わない。"}, "sentence_index": 0, "correct_answer": "移した"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "池の水面に富士山を移していた。", "explanation": "ここは「映す（映し出す）」の意味。移すは物や人を動かすことなので、水面に映し出す意味では合わない。"}, {"text": "自分の考えを移すのは難しい。", "explanation": "ここは「変える」の意味。移すは場所や段階を動かすことなので、考えを変える意味では合わない。"}, {"text": "教室が静かだったので、先生は声を大きく移した。", "explanation": "ここは「上げる（大きくする）」の意味。移すは物や人を動かすことなので、声の大きさを上げる意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移した", "is_correct": true, "explanation": "正解。過去形で「視線を〜へ移した」と目的語「を」をとる。"}, {"text": "移せ", "is_correct": false, "explanation": "命令形。過去の出来事を述べる文と合わず、命令文になってしまう。"}, {"text": "移れ", "is_correct": false, "explanation": "命令形（移る）。自動詞で「視線を」とは合わない。"}, {"text": "移さ", "is_correct": false, "explanation": "未然形。文末で止まり、成り立たない。"}], "explanations": {"移した": "正解。過去形で「視線を〜へ移した」と目的語「を」をとる。", "移せ": "命令形。過去の出来事を述べる文と合わず、命令文になってしまう。", "移れ": "命令形（移る）。自動詞で「視線を」とは合わない。", "移さ": "未然形。文末で止まり、成り立たない。"}, "sentence_index": 6, "correct_answer": "移した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋の様子を、カメラで移した。", "explanation": "ここは「写す（撮影する）」の意味。移すは場所を動かすことなので、撮影の意味では合わない。"}, {"text": "鏡に姿を移した。", "explanation": "ここは「映す（映し出す）」の意味。移すは場所を動かすことなので、姿を映す意味では合わない。"}, {"text": "出かける前に、時計を正しい時刻に移した。", "explanation": "ここは「合わせる（正しくする）」の意味。移すは物を別の場所に動かすことなので、時刻を合わせる意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日、荷物を新居に移しました。", "corrected_sentence": "明日、荷物を新居に移します。", "error_description": "「明日」は未来なので、過去形「移しました」ではなく「移します」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "移した", "is_correct": true, "explanation": "正解。過去形で、動作が終わったことを表す。"}, {"text": "移して", "is_correct": false, "explanation": "て形で、文末にできない。"}, {"text": "移される", "is_correct": false, "explanation": "受身形。「患者が移される」となり、看護師が動かす意味と合わない。"}, {"text": "移せば", "is_correct": false, "explanation": "仮定形で、「〜ば」の続きが必要なので文末にできない。"}], "correct_form": "移した", "base_form": "移す", "form_label": "過去形", "sentence_index": 1, "explanations": {"移した": "正解。過去形で、動作が終わったことを表す。", "移して": "て形で、文末にできない。", "移される": "受身形。「患者が移される」となり、看護師が動かす意味と合わない。", "移せば": "仮定形で、「〜ば」の続きが必要なので文末にできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35007, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越しの後、家具が新しい部屋に移した。", "corrected_sentence": "引っ越しの後、家具を新しい部屋に移した。", "error_description": "「移す」は動かす対象に「を」をとる。「家具が」では主語になり、目的語がないため不自然。正しくは「家具を新しい部屋に移した」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "移した", "is_correct": true, "explanation": "正解。過去形で、雨の後に荷物を動かした出来事を表す。"}, {"text": "移して", "is_correct": false, "explanation": "て形。文末にできず、文が続かない。"}, {"text": "移し", "is_correct": false, "explanation": "連用形。文末にできず、文が途中で終わってしまう。"}, {"text": "移さ", "is_correct": false, "explanation": "未然形。文末で止まり、成り立たない。"}], "correct_form": "移した", "base_form": "移す", "form_label": "過去形", "sentence_index": 7, "explanations": {"移した": "正解。過去形で、雨の後に荷物を動かした出来事を表す。", "移して": "て形。文末にできず、文が続かない。", "移し": "連用形。文末にできず、文が途中で終わってしまう。", "移さ": "未然形。文末で止まり、成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
