INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35010, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まだなかったものを、はじめてつくること。", "primary_collocate": null, "pronunciation": "はつめい", "ipa": "hatsɯmeː", "syllable_count": 4, "sentences": [{"text": "エジソンは電球を発明した人として有名です。", "target_word": "発明", "complexity_tier": "T3", "furigana": "エジソンは電球[でんきゅう]を発明[はつめい]した人[ひと]として有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "新しいものを発明するには、たくさんの時間が必要です。", "target_word": "発明", "complexity_tier": "T3", "furigana": "新[あたら]しいものを発明[はつめい]するには、たくさんの時間[じかん]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "電話の発明で、遠くの人と話せるようになりました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "電話[でんわ]の発明[はつめい]で、遠[とお]くの人[ひと]と話[はな]せるようになりました。", "sentence_source": "generated"}, {"text": "彼は便利な道具を発明して、特許を取りました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "彼[かれ]は便利[べんり]な道具[どうぐ]を発明[はつめい]して、特許[とっきょ]を取[と]りました。", "sentence_source": "generated"}, {"text": "紙の発明は、人々の生活を大きく変えました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "紙[かみ]の発明[はつめい]は、人々[ひとびと]の生活[せいかつ]を大[おお]きく変[か]えました。", "sentence_source": "generated"}, {"text": "子どものころから発明が好きで、ノートにアイデアを書いていました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "子[こ]どものころから発明[はつめい]が好[す]きで、ノートにアイデアを書[か]いていました。", "sentence_source": "generated"}, {"text": "この発明のおかげで、洗濯が楽になりました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "この発明[はつめい]のおかげで、洗濯[せんたく]が楽[らく]になりました。", "sentence_source": "generated"}, {"text": "昔の人が車輪を発明したので、重い荷物を運べるようになりました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]が車輪[しゃりん]を発明[はつめい]したので、重[おも]い荷物[にもつ]を運[はこ]べるようになりました。", "sentence_source": "generated"}, {"text": "兄は新しい掃除の道具を発明しようと、毎晩図面をかいています。", "target_word": "発明", "complexity_tier": "T3", "furigana": "兄[あに]は新[あたら]しい掃除[そうじ]の道具[どうぐ]を発明[はつめい]しようと、毎晩[まいばん]図面[ずめん]をかいています。", "sentence_source": "generated"}, {"text": "発明のアイデアを発表する大会で、ぼくの作品が一番になりました。", "target_word": "発明", "complexity_tier": "T3", "furigana": "発明[はつめい]のアイデアを発表[はっぴょう]する大会[たいかい]で、ぼくの作品[さくひん]が一番[いちばん]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発明", "label": "基本形"}, {"form": "発明する", "label": "動詞形"}, {"form": "発明した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "それまでなかった物や方法を、初めて考え出して作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発明", "is_correct": true, "explanation": "まだなかったものを初めて作ることで、電球を作った人の文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かけることで、「電球を散歩した」とは言えず文に合わない。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かすことで、電球に対しては使えないので文に合わない。"}, {"text": "出発", "is_correct": false, "explanation": "出かけることで、電球を目的語に取れないので文に合わない。"}], "explanations": {"発明": "まだなかったものを初めて作ることで、電球を作った人の文に合う。", "散歩": "歩いて出かけることで、「電球を散歩した」とは言えず文に合わない。", "運動": "体を動かすことで、電球に対しては使えないので文に合わない。", "出発": "出かけることで、電球を目的語に取れないので文に合わない。"}, "sentence_index": 0, "correct_answer": "発明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その研究者は、深海で昔から知られていた生き物を発明しました。", "explanation": "ここは〈発見〉の意味。もとからいた生き物を見つけることは〈発見〉で、〈発明〉（まだなかったものを作る）とは言わない。"}, {"text": "研究の結果を、来月の学会で発明しました。", "explanation": "ここは〈発表〉（人前で知らせる）の意味。研究の結果を知らせるのは〈発表〉で、〈発明〉ではない。"}, {"text": "この町は、駅前を発明して、にぎやかになりました。", "explanation": "ここは〈開発〉（土地や町を整えて使えるようにする）の意味。土地には〈開発〉を使い、〈発明〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発明", "is_correct": true, "explanation": "便利な道具として洗濯を楽にするものなので、文に合う。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることで、洗濯を楽にする理由にはならないので合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "出かけることで、洗濯が楽になる理由にはならないので合わない。"}, {"text": "試合", "is_correct": false, "explanation": "競い合うことで、洗濯が楽になる理由にはならないので合わない。"}], "explanations": {"発明": "便利な道具として洗濯を楽にするものなので、文に合う。", "料理": "食べ物を作ることで、洗濯を楽にする理由にはならないので合わない。", "旅行": "出かけることで、洗濯が楽になる理由にはならないので合わない。", "試合": "競い合うことで、洗濯が楽になる理由にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "発明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、大会のためにこの歌を発明しました。", "explanation": "ここは〈作曲〉の意味。歌や曲は〈作曲〉で作るので、〈発明〉とは言わない。"}, {"text": "先生は、この小説を英語に発明しました。", "explanation": "ここは〈翻訳〉の意味。ある言葉を別の言葉に置きかえるのは〈翻訳〉で、〈発明〉ではない。"}, {"text": "彼は三年かけて、この小説を発明しました。", "explanation": "ここは〈執筆〉（文章を書く）の意味。小説は〈執筆〉で書くので、〈発明〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電球の発明を、夜も明るく過ごせるようになりました。", "corrected_sentence": "電球の発明で、夜も明るく過ごせるようになりました。", "error_description": "「発明を」の助詞が誤り。原因を表す「で」が必要で、「を」では文が成り立たない（正：発明で）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その発明を、人々の生活を助けています。", "corrected_sentence": "その発明が、人々の生活を助けています。", "error_description": "「発明を」が誤り。「助けている」の主語には「が」を使う（正：発明が）。「を」が二つになり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「あの人は」の「は」。話題として取り上げる人を示す助詞として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「あの人を、私の高校の先生です」は目的格として文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「あの人に、私の高校の先生です」は相手を示す助詞として文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「あの人で、私の高校の先生です」は手段を示す助詞として文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「あの人は」の「は」。話題として取り上げる人を示す助詞として正しい。", "を": "「あの人を、私の高校の先生です」は目的格として文が成り立たない。", "に": "「あの人に、私の高校の先生です」は相手を示す助詞として文が成り立たない。", "で": "「あの人で、私の高校の先生です」は手段を示す助詞として文が成り立たない。"}, "error_tags": {"を": "目的格", "に": "相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「電話に出た人は」の「は」。話題として取り上げる人を示す助詞として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「電話に出た人を、店長を呼んでくれた」は目的語が二つ重なり、文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「電話に出た人で、すぐに店長を呼んでくれた」は手段の意味になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「電話に出た人の、すぐに店長を呼んでくれた」は連体の「の」で文が切れ、成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「電話に出た人は」の「は」。話題として取り上げる人を示す助詞として正しい。", "を": "「電話に出た人を、店長を呼んでくれた」は目的語が二つ重なり、文として不自然。", "で": "「電話に出た人で、すぐに店長を呼んでくれた」は手段の意味になり、文が成り立たない。", "の": "「電話に出た人の、すぐに店長を呼んでくれた」は連体の「の」で文が切れ、成り立たない。"}, "error_tags": {"を": "目的格", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人は、人間のことです。", "primary_collocate": null, "pronunciation": "ひと", "ipa": "çito", "syllable_count": 2, "sentences": [{"text": "駅の前に、たくさんの人が立っている。", "target_word": "人", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に、たくさんの人[ひと]が立[た]っている。", "sentence_source": "generated"}, {"text": "あの人は、私の高校の先生です。", "target_word": "人", "complexity_tier": "T3", "furigana": "あの人[ひと]は、私[わたし]の高校[こうこう]の先生[せんせい]です。", "sentence_source": "generated"}, {"text": "親切な人に道を教えてもらった。", "target_word": "人", "complexity_tier": "T3", "furigana": "親切[しんせつ]な人[ひと]に道[みち]を教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "この町には、やさしい人が多い。", "target_word": "人", "complexity_tier": "T3", "furigana": "この町[まち]には、やさしい人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "知らない人について行ってはいけません。", "target_word": "人", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]について行[い]ってはいけません。", "sentence_source": "generated"}, {"text": "私は人の話を最後まで聞くようにしている。", "target_word": "人", "complexity_tier": "T3", "furigana": "私[わたし]は人[ひと]の話[はなし]を最後[さいご]まで聞[き]くようにしている。", "sentence_source": "generated"}, {"text": "パーティーに来た人は、みんな笑顔だった。", "target_word": "人", "complexity_tier": "T3", "furigana": "パーティーに来[き]た人[ひと]は、みんな笑顔[えがお]だった。", "sentence_source": "generated"}, {"text": "電話に出た人は、すぐに店長を呼んでくれた。", "target_word": "人", "complexity_tier": "T3", "furigana": "電話[でんわ]に出[で]た人[ひと]は、すぐに店長[てんちょう]を呼[よ]んでくれた。", "sentence_source": "generated"}, {"text": "好きな人ができて、毎日が楽しくなった。", "target_word": "人", "complexity_tier": "T3", "furigana": "好[す]きな人[ひと]ができて、毎日[まいにち]が楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "人は、助け合って生きていくものだ。", "target_word": "人", "complexity_tier": "T3", "furigana": "人[ひと]は、助[たす]け合[あ]って生[い]きていくものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人間、ひと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人", "is_correct": true, "explanation": "「たくさんの人が立っている」の形で、駅の前にいる人々を指す語として正しい。"}, {"text": "雨", "is_correct": false, "explanation": "「たくさんの雨が立っている」は意味が通らず、雨は立つものではない。"}, {"text": "電話", "is_correct": false, "explanation": "「たくさんの電話が立っている」は意味が通らず、電話は立つものではない。"}, {"text": "言葉", "is_correct": false, "explanation": "「たくさんの言葉が立っている」は意味が通らず、言葉は立つものではない。"}], "explanations": {"人": "「たくさんの人が立っている」の形で、駅の前にいる人々を指す語として正しい。", "雨": "「たくさんの雨が立っている」は意味が通らず、雨は立つものではない。", "電話": "「たくさんの電話が立っている」は意味が通らず、電話は立つものではない。", "言葉": "「たくさんの言葉が立っている」は意味が通らず、言葉は立つものではない。"}, "sentence_index": 0, "correct_answer": "人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱には、りんごが三人入っている。", "explanation": "りんごは「個」で数えるもので、「人」は人を数える助数詞なので合わない。"}, {"text": "この店の人は、一つ百円で売られている。", "explanation": "「人」は人を指す語で、商品には使えない。商品なら「品」や「もの」を使う。"}, {"text": "この森には、熊が一人いる。", "explanation": "熊は「頭」で数えるもので、「人」は人を数える助数詞なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人", "is_correct": true, "explanation": "「パーティーに来た人は」の形で、会に来た人を指す語として正しい。"}, {"text": "窓", "is_correct": false, "explanation": "「パーティーに来た窓」は意味が通らず、窓はパーティーに来るものではない。"}, {"text": "歌", "is_correct": false, "explanation": "「パーティーに来た歌」は意味が通らず、歌は来るものではない。"}, {"text": "水", "is_correct": false, "explanation": "「パーティーに来た水」は意味が通らず、水は来るものではない。"}], "explanations": {"人": "「パーティーに来た人は」の形で、会に来た人を指す語として正しい。", "窓": "「パーティーに来た窓」は意味が通らず、窓はパーティーに来るものではない。", "歌": "「パーティーに来た歌」は意味が通らず、歌は来るものではない。", "水": "「パーティーに来た水」は意味が通らず、水は来るものではない。"}, "sentence_index": 6, "correct_answer": "人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池には、金魚が一人泳いでいる。", "explanation": "金魚は「匹」で数えるもので、「人」は人を数える助数詞なので合わない。"}, {"text": "ネコの人が窓辺で眠っている。", "explanation": "「人」は人を指す語で、動物には使えない。ネコは「ネコ」や「匹」で表す。"}, {"text": "机の上には、本の人が三冊ある。", "explanation": "「人」は人を指す語で、本を表す語として使えない。本は「冊」で数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの店の前に、たくさんの人を並んでいる。", "corrected_sentence": "あの店の前に、たくさんの人が並んでいる。", "error_description": "「並んでいる」の主語を示す助詞は「が」。「人を並んでいる」は目的格の「を」を使った誤りで、正しくは「人が並んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35014, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室に、人が五本いる。", "corrected_sentence": "教室に、人が五人いる。", "error_description": "人を数える助数詞は「人」。「五本」は細長いものを数える助数詞で、「人」を数えるには誤りで、正しくは「五人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35016, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減る", "is_correct": true, "explanation": "正解。数や量が多くなることの反対で、少なくなる意味を表す。"}, {"text": "残る", "is_correct": false, "explanation": "残るは後に留まる意味で、増減の反対語ではない。"}, {"text": "育つ", "is_correct": false, "explanation": "育つは成長することで、数の減少を表さない。"}, {"text": "集まる", "is_correct": false, "explanation": "集まるは人や物が寄ることで、数が少なくなる意味ではない。"}], "correct_answer": "減る", "explanations": {"減る": "正解。数や量が多くなることの反対で、少なくなる意味を表す。", "残る": "残るは後に留まる意味で、増減の反対語ではない。", "育つ": "育つは成長することで、数の減少を表さない。", "集まる": "集まるは人や物が寄ることで、数が少なくなる意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
