INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35016, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かずがおおくなる。", "primary_collocate": null, "pronunciation": "ふえる", "ipa": "ɸɯeɾɯ", "syllable_count": 3, "sentences": [{"text": "最近、この町に住む外国人が増えている。", "target_word": "増えている", "complexity_tier": "T3", "furigana": "最近[さいきん]、この町[まち]に住[す]む外国人[がいこくじん]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "春になると、公園を散歩する人が増える。", "target_word": "増える", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]を散歩[さんぽ]する人[ひと]が増[ふ]える。", "sentence_source": "generated"}, {"text": "本棚の本が増えて、部屋が狭くなった。", "target_word": "増えて", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の本[ほん]が増[ふ]えて、部屋[へや]が狭[せま]くなった。", "sentence_source": "generated"}, {"text": "宿題が増えたせいで、夜遅くまで起きている。", "target_word": "増えた", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が増[ふ]えたせいで、夜遅[よるおそ]くまで起[お]きている。", "sentence_source": "generated"}, {"text": "犬を飼い始めてから、家族の笑顔が増えた。", "target_word": "増えた", "complexity_tier": "T3", "furigana": "犬[いぬ]を飼[か]い始[はじ]めてから、家族[かぞく]の笑顔[えがお]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "このクラスは転校生が来て、生徒が三人増えた。", "target_word": "増えた", "complexity_tier": "T3", "furigana": "このクラスは転校生[てんこうせい]が来[き]て、生徒[せいと]が三人[さんにん]増[ふ]えた。", "sentence_source": "generated"}, {"text": "来月から留学生が増えるので、寮の部屋を用意する。", "target_word": "増える", "complexity_tier": "T3", "furigana": "来月[らいげつ]から留学生[りゅうがくせい]が増[ふ]えるので、寮[りょう]の部屋[へや]を用意[ようい]する。", "sentence_source": "generated"}, {"text": "駅前に新しい店ができたが、客はなかなか増えない。", "target_word": "増えない", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に新[あたら]しい店[みせ]ができたが、客[きゃく]はなかなか増[ふ]えない。", "sentence_source": "generated"}, {"text": "夏は虫が増えるので、窓を開けるときは気をつける。", "target_word": "増える", "complexity_tier": "T3", "furigana": "夏[なつ]は虫[むし]が増[ふ]えるので、窓[まど]を開[あ]けるときは気[き]をつける。", "sentence_source": "generated"}, {"text": "友達が増えて、学校へ行くのが楽しくなった。", "target_word": "増えて", "complexity_tier": "T3", "furigana": "友達[ともだち]が増[ふ]えて、学校[がっこう]へ行[い]くのが楽[たの]しくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増える", "label": "終止形"}, {"form": "増えた", "label": "過去形"}, {"form": "増えて", "label": "て形"}, {"form": "増えない", "label": "否定形"}, {"form": "増えている", "label": "進行・状態形"}], "register": "中立（普通体）", "sense_fingerprint": "数や量が多くなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増えている", "is_correct": true, "explanation": "正解。外国人の数が多くなっている状態を表す。"}, {"text": "眠っている", "is_correct": false, "explanation": "眠っているは睡眠の状態を表し、数が多くなる意味にはならない。"}, {"text": "叫んでいる", "is_correct": false, "explanation": "叫んでいるは大声を出す動作で、数の変化を表さない。"}, {"text": "壊れている", "is_correct": false, "explanation": "壊れているは故障の状態を表し、人の数には使えない。"}], "explanations": {"増えている": "正解。外国人の数が多くなっている状態を表す。", "眠っている": "眠っているは睡眠の状態を表し、数が多くなる意味にはならない。", "叫んでいる": "叫んでいるは大声を出す動作で、数の変化を表さない。", "壊れている": "壊れているは故障の状態を表し、人の数には使えない。"}, "sentence_index": 0, "correct_answer": "増えている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さが増えて、体がふるえた。", "explanation": "ここは〈増す〉（程度が強くなる）の意味。寒さのような程度は増すで表し、増えるは数や量が多くなる場合に使う。"}, {"text": "子どもの身長がぐんと増えた。", "explanation": "ここは〈伸びる〉の意味。身長は高くなるもので、数が多くなる増えるは使わない。"}, {"text": "風が増えてきて、傘をさせなくなった。", "explanation": "ここは〈強まる〉の意味。風の勢いが強くなる場合は強まるを使い、増えるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増える", "is_correct": true, "explanation": "正解。留学生の数が多くなるという意味で、「ので」に続く。"}, {"text": "鳴る", "is_correct": false, "explanation": "鳴るは音が出ること。留学生には使えない。"}, {"text": "止まる", "is_correct": false, "explanation": "止まるは動きが終わること。留学生の人数を表す文には合わない。"}, {"text": "付く", "is_correct": false, "explanation": "付くは物がくっつくこと。留学生が付くという文は成り立たない。"}], "explanations": {"増える": "正解。留学生の数が多くなるという意味で、「ので」に続く。", "鳴る": "鳴るは音が出ること。留学生には使えない。", "止まる": "止まるは動きが終わること。留学生の人数を表す文には合わない。", "付く": "付くは物がくっつくこと。留学生が付くという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "増える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋が増えて、木々が赤く色づいた。", "explanation": "ここは〈深まる〉の意味。季節が進む様子は深まるで表し、数の増加を表す増えるは使わない。"}, {"text": "夕日が増えて、空がオレンジに染まった。", "explanation": "ここは〈沈む〉の意味。太陽が低くなる様子は沈むで表し、増えるとは言わない。"}, {"text": "試合の形勢が増えて、勝利を手にした。", "explanation": "ここは〈逆転〉の意味。流れが変わる場合は逆転を使い、増えるは数や量の増加に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年は入学者が増えるないと、学校の予算が足りなくなる。", "corrected_sentence": "来年は入学者が増えないと、学校の予算が足りなくなる。", "error_description": "誤りは否定形。「増える」の否定形は「増えない」。「増えるない」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "増える", "is_correct": true, "explanation": "正解。文末の終止形で、「人が増える」の述語になる。"}, {"text": "増えろ", "is_correct": false, "explanation": "命令形。習慣を述べる平叙文の述語にはならない。"}, {"text": "増えて", "is_correct": false, "explanation": "て形で文を続ける形。文末には立たない。"}, {"text": "増えよう", "is_correct": false, "explanation": "意向形。習慣を述べる文の述語にはならない。"}], "correct_form": "増える", "base_form": "増える", "form_label": "終止形", "sentence_index": 1, "explanations": {"増える": "正解。文末の終止形で、「人が増える」の述語になる。", "増えろ": "命令形。習慣を述べる平叙文の述語にはならない。", "増えて": "て形で文を続ける形。文末には立たない。", "増えよう": "意向形。習慣を述べる文の述語にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人口が増やしたので、新しい学校を建てることになった。", "corrected_sentence": "町の人口が増えたので、新しい学校を建てることになった。", "error_description": "誤りは動詞の選択。「増やす」は他動詞で、何を増やすかを示す必要がある。ここは自動詞「増える」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "増えない", "is_correct": true, "explanation": "正解。否定形で、客が増えないという状況を表す。"}, {"text": "増えたい", "is_correct": false, "explanation": "願望形。「客が増えたい」という意味になり、状況を述べる述語にはならない。"}, {"text": "増えさせる", "is_correct": false, "explanation": "使役形。目的語がないと文が完結せず、「客」の状況を述べる文にはならない。"}, {"text": "増えなくて", "is_correct": false, "explanation": "否定のて形。文を言い切れず、続きが必要な形になる。"}], "correct_form": "増えない", "base_form": "増える", "form_label": "否定形", "sentence_index": 7, "explanations": {"増えない": "正解。否定形で、客が増えないという状況を表す。", "増えたい": "願望形。「客が増えたい」という意味になり、状況を述べる述語にはならない。", "増えさせる": "使役形。目的語がないと文が完結せず、「客」の状況を述べる文にはならない。", "増えなくて": "否定のて形。文を言い切れず、続きが必要な形になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「情報が多すぎて」と主語を示す「が」。"}, {"text": "で", "is_correct": false, "explanation": "動作の場所や手段を表す「で」。「情報で多すぎて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "対象や移動先の「に」。「情報に多すぎて」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「情報から多すぎて」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「情報が多すぎて」と主語を示す「が」。", "で": "動作の場所や手段を表す「で」。「情報で多すぎて」は成り立たない。", "に": "対象や移動先の「に」。「情報に多すぎて」は不自然。", "から": "起点の「から」。「情報から多すぎて」は意味が通らない。"}, "error_tags": {"で": "location_or_means", "に": "target", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事について伝えられる知らせや知識。", "primary_collocate": null, "pronunciation": "じょうほう", "ipa": "dʑoːhoː", "syllable_count": 4, "sentences": [{"text": "旅行の前に、インターネットで天気の情報を調べた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、インターネットで天気[てんき]の情報[じょうほう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "電車が止まったという情報が、スマホに届いた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったという情報[じょうほう]が、スマホに届[とど]いた。", "sentence_source": "generated"}, {"text": "正しい情報がないと、どうすればいいか決められない。", "target_word": "情報", "complexity_tier": "T4", "furigana": "正[ただ]しい情報[じょうほう]がないと、どうすればいいか決[き]められない。", "sentence_source": "generated"}, {"text": "友達から新しい店の情報を聞いて、すぐ行ってみた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "友達[ともだち]から新[あたら]しい店[みせ]の情報[じょうほう]を聞[き]いて、すぐ行[い]ってみた。", "sentence_source": "generated"}, {"text": "古い情報だったので、店はもう閉まっていた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "古[ふる]い情報[じょうほう]だったので、店[みせ]はもう閉[し]まっていた。", "sentence_source": "generated"}, {"text": "ニュースは世界中の情報を私たちに伝えてくれる。", "target_word": "情報", "complexity_tier": "T3", "furigana": "ニュースは世界中[せかいじゅう]の情報[じょうほう]を私[わたし]たちに伝[つた]えてくれる。", "sentence_source": "generated"}, {"text": "先生は試験の日程について、大切な情報を教えてくれた。", "target_word": "情報", "complexity_tier": "T3", "furigana": "先生[せんせい]は試験[しけん]の日程[にってい]について、大切[たいせつ]な情報[じょうほう]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "情報が多すぎて、何を信じていいか分からなくなった。", "target_word": "情報", "complexity_tier": "T4", "furigana": "情報[じょうほう]が多[おお]すぎて、何[なに]を信[しん]じていいか分[わ]からなくなった。", "sentence_source": "generated"}, {"text": "事故の情報を集めるために、警察が町の人に話を聞いている。", "target_word": "情報", "complexity_tier": "T4", "furigana": "事故[じこ]の情報[じょうほう]を集[あつ]めるために、警察[けいさつ]が町[まち]の人[ひと]に話[はなし]を聞[き]いている。", "sentence_source": "generated"}, {"text": "彼女は情報を整理してから、みんなの前で発表した。", "target_word": "情報", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は情報[じょうほう]を整理[せいり]してから、みんなの前[まえ]で発表[はっぴょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "情報", "label": "基本形"}], "register": "plain", "sense_fingerprint": "物事についての知らせや知識（ニュース・データなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情報", "is_correct": true, "explanation": "正解。「天気の情報」として、天気についての知らせを表す名詞。"}, {"text": "意見", "is_correct": false, "explanation": "「天気の意見」は不自然。意見は考えや主張を指す。"}, {"text": "感情", "is_correct": false, "explanation": "「天気の感情」は成り立たない。感情は人の気持ちを指す。"}, {"text": "信号", "is_correct": false, "explanation": "「天気の信号」は不自然。信号は合図や機械の表示を指す。"}], "explanations": {"情報": "正解。「天気の情報」として、天気についての知らせを表す名詞。", "意見": "「天気の意見」は不自然。意見は考えや主張を指す。", "感情": "「天気の感情」は成り立たない。感情は人の気持ちを指す。", "信号": "「天気の信号」は不自然。信号は合図や機械の表示を指す。"}, "sentence_index": 0, "correct_answer": "情報"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は情報を込めて、ゆっくり歌った。", "explanation": "ここは「感情」の意味。情報は事実や知らせを指すので、感情を込める意味では合わない。"}, {"text": "踏切の情報が点滅したので、子どもは立ち止まった。", "explanation": "ここは「信号」の意味。情報は事実や知らせを指すので、光が点滅する意味では合わない。"}, {"text": "彼は仕事への情報を失わない。", "explanation": "ここは「情熱」の意味。情報は事実や知らせを指すので、仕事への熱意の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情報", "is_correct": true, "explanation": "正解。「大切な情報を教えてくれた」として、知らせや事実を表す名詞。"}, {"text": "写真", "is_correct": false, "explanation": "「大切な写真を教えてくれた」は成り立たない。写真は画像を指す。"}, {"text": "機械", "is_correct": false, "explanation": "「大切な機械を教えてくれた」は不自然。教えるのは機械ではない。"}, {"text": "衣装", "is_correct": false, "explanation": "「大切な衣装を教えてくれた」は成り立たない。衣装は服装を指す。"}], "explanations": {"情報": "正解。「大切な情報を教えてくれた」として、知らせや事実を表す名詞。", "写真": "「大切な写真を教えてくれた」は成り立たない。写真は画像を指す。", "機械": "「大切な機械を教えてくれた」は不自然。教えるのは機械ではない。", "衣装": "「大切な衣装を教えてくれた」は成り立たない。衣装は服装を指す。"}, "sentence_index": 6, "correct_answer": "情報"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は情報を整理してから、みんなの前で料理した。", "explanation": "ここは「材料」の意味。情報は料理には使わないので、料理の材料の意味では合わない。"}, {"text": "彼女は情報を整理してから、みんなの前で畳んだ。", "explanation": "ここは「洗濯物」の意味。情報は畳むものではないので合わない。"}, {"text": "彼女は情報を整理してから、みんなの前で飲んだ。", "explanation": "ここは「薬」の意味。情報は飲むものではないので、薬の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その新聞は、地元の事故の情報が毎日載せている。", "corrected_sentence": "その新聞は、地元の事故の情報を毎日載せている。", "error_description": "「載せる」は目的語に「を」をとる。「情報が」は主語の形で、「が」は誤り。正しくは「情報を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35018, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日、新しい情報を共有した。", "corrected_sentence": "明日、新しい情報を共有する。", "error_description": "「明日」は未来なので、過去形「共有した」ではなく辞書形「共有する」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
