INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35020, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "みんなのこと。", "primary_collocate": null, "pronunciation": "みな", "ipa": "mina", "syllable_count": 2, "sentences": [{"text": "試験が終わって、皆ほっとした顔をしていました。", "target_word": "皆", "complexity_tier": "T3", "furigana": "試験[しけん]が終[お]わって、皆[みな]ほっとした顔[かお]をしていました。", "sentence_source": "generated"}, {"text": "皆で協力したので、仕事は早く終わった。", "target_word": "皆", "complexity_tier": "T3", "furigana": "皆[みな]で協力[きょうりょく]したので、仕事[しごと]は早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、皆が笑いました。", "target_word": "皆", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]を聞[き]いて、皆[みな]が笑[わら]いました。", "sentence_source": "generated"}, {"text": "先生は皆に同じ宿題を出しました。", "target_word": "皆", "complexity_tier": "T3", "furigana": "先生[せんせい]は皆[みな]に同[おな]じ宿題[しゅくだい]を出[だ]しました。", "sentence_source": "generated"}, {"text": "部屋にいた皆は、突然の音に驚きました。", "target_word": "皆", "complexity_tier": "T3", "furigana": "部屋[へや]にいた皆[みな]は、突然[とつぜん]の音[おと]に驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "皆の意見をまとめてから、計画を決めましょう。", "target_word": "皆", "complexity_tier": "T3", "furigana": "皆[みな]の意見[いけん]をまとめてから、計画[けいかく]を決[き]めましょう。", "sentence_source": "generated"}, {"text": "雨が降ったので、皆濡れて帰ってきました。", "target_word": "皆", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、皆[みな]濡[ぬ]れて帰[かえ]ってきました。", "sentence_source": "generated"}, {"text": "家族の皆が、私の合格を喜んでくれました。", "target_word": "皆", "complexity_tier": "T3", "furigana": "家族[かぞく]の皆[みな]が、私[わたし]の合格[ごうかく]を喜[よろこ]んでくれました。", "sentence_source": "generated"}, {"text": "祭りの日には、町の皆が広場に集まります。", "target_word": "皆", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]には、町[まち]の皆[みな]が広場[ひろば]に集[あつ]まります。", "sentence_source": "generated"}, {"text": "約束の時間になっても、皆はまだ来ませんでした。", "target_word": "皆", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]になっても、皆[みな]はまだ来[き]ませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "皆", "label": "基本形"}, {"form": "皆が", "label": "主語の形"}, {"form": "皆で", "label": "全員での動作の形"}], "register": "標準語（やや改まった中立）", "sense_fingerprint": "その場や集団にいる全員、またはすべての人を指す語。「みんな」よりやや改まる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皆", "is_correct": true, "explanation": "ここは〈皆〉の意味。試験が終わって、みんながほっとした様子を表す文に合う。"}, {"text": "誰", "is_correct": false, "explanation": "「誰」は疑問の語で、「誰ほっとした顔」とは続かない。"}, {"text": "何", "is_correct": false, "explanation": "「何」は物事を尋ねる語で、ほっとした人を表すことはできない。"}, {"text": "どこ", "is_correct": false, "explanation": "「どこ」は場所を尋ねる語で、人を表す主語にはならない。"}], "explanations": {"皆": "ここは〈皆〉の意味。試験が終わって、みんながほっとした様子を表す文に合う。", "誰": "「誰」は疑問の語で、「誰ほっとした顔」とは続かない。", "何": "「何」は物事を尋ねる語で、ほっとした人を表すことはできない。", "どこ": "「どこ」は場所を尋ねる語で、人を表す主語にはならない。"}, "sentence_index": 0, "correct_answer": "皆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の皆は、とても重い。", "explanation": "ここは〈全部〉の意味。皆は人の集まりを指すので、一つの箱の全体には使わない。"}, {"text": "皆は一人で、静かに本を読んでいる。", "explanation": "ここは〈一人〉の意味。皆は複数の人の集まりを指すので、一人だけを指す文では使えない。"}, {"text": "彼は皆で、スポーツが得意だ。", "explanation": "ここは〈一緒に〉の意味。「皆で」は複数の人がいっしょにすることを表すので、一人の性質には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皆", "is_correct": true, "explanation": "ここは〈皆〉の意味。雨で濡れて帰ってきた人たち全体を指す文に合う。"}, {"text": "どなた", "is_correct": false, "explanation": "「どなた」は誰かを丁寧に尋ねる語で、濡れて帰った人を表す主語にはならない。"}, {"text": "どれ", "is_correct": false, "explanation": "「どれ」は物を選ぶ時に使う語で、人を表す主語にはならない。"}, {"text": "どちら", "is_correct": false, "explanation": "「どちら」は二つのうちどちらかを尋ねる語で、ここでは主語として合わない。"}], "explanations": {"皆": "ここは〈皆〉の意味。雨で濡れて帰ってきた人たち全体を指す文に合う。", "どなた": "「どなた」は誰かを丁寧に尋ねる語で、濡れて帰った人を表す主語にはならない。", "どれ": "「どれ」は物を選ぶ時に使う語で、人を表す主語にはならない。", "どちら": "「どちら」は二つのうちどちらかを尋ねる語で、ここでは主語として合わない。"}, "sentence_index": 6, "correct_answer": "皆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この犬は皆、まだ子どもだ。", "explanation": "ここは〈全部〉の意味。皆は複数の人を指す語で、一匹の犬には使わない。"}, {"text": "地図の皆を、一度開いて確認した。", "explanation": "ここは〈全部〉の意味。皆は人について言う語で、地図のような物には使わない。"}, {"text": "この車の皆は、新しく塗り直された。", "explanation": "ここは〈全部〉の意味。皆は人の集まりを指すので、一台の車の部品全体には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の話を聞いて、皆を静かになった。", "corrected_sentence": "彼女の話を聞いて、皆が静かになった。", "error_description": "「静かになる」は主語に「が」をとる。誤りは「皆を」の「を」で、正しくは「皆が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは皆を、公園の掃除をした。", "corrected_sentence": "子どもたちは皆で、公園の掃除をした。", "error_description": "「皆で」は複数の人がいっしょに行うことを表す。誤りは「皆を」の「を」で、ここでは「で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
