INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35022, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "むずかしくない。すぐわかる。", "primary_collocate": null, "pronunciation": "かんたん", "ipa": "kaɲtaɴ", "syllable_count": 4, "sentences": [{"text": "この問題は簡単なので、すぐに答えがわかった。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "このもんだいはかんたんなので、すぐにこたえがわかった。", "sentence_source": "generated"}, {"text": "先生の説明は簡単で、子どもでも理解できた。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "せんせいのせつめいはかんたんで、こどもでもりかいできた。", "sentence_source": "generated"}, {"text": "使い方は簡単だから、説明書を読まなくても大丈夫です。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "つかいかたはかんたんだから、せつめいしょをよまなくてもだいじょうぶです。", "sentence_source": "generated"}, {"text": "このパソコンは操作が簡単で、初めての人でもすぐ使える。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "操作[そうさ]が簡単[かんたん]で、初[はじ]めての人[ひと]でもすぐ使[つか]える。", "sentence_source": "generated"}, {"text": "テストが簡単すぎて、三十分で終わってしまった。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "テストがかんたんすぎて、さんじゅっぷんでおわってしまった。", "sentence_source": "generated"}, {"text": "道は簡単で、駅からまっすぐ行くだけだ。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "みちはかんたんで、えきからまっすぐいくだけだ。", "sentence_source": "generated"}, {"text": "この漢字は形が簡単なので、すぐ覚えられる。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "このかんじはかたちがかんたんなので、すぐおぼえられる。", "sentence_source": "generated"}, {"text": "簡単な英語の本から読み始めると、続けやすい。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "かんたんなえいごのほんからよみはじめると、つづけやすい。", "sentence_source": "generated"}, {"text": "彼の話は簡単にまとめられていて、わかりやすかった。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "かれのはなしはかんたんにまとめられていて、わかりやすかった。", "sentence_source": "generated"}, {"text": "ルールが簡単なゲームは、みんなで楽しめる。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "ルールがかんたんなゲームは、みんなでたのしめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡単だ", "label": "終止形"}, {"form": "簡単な", "label": "連体形"}, {"form": "簡単に", "label": "連用形"}, {"form": "簡単で", "label": "て形"}, {"form": "簡単ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "複雑でなく、むずかしくなくてすぐ理解できる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35022, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "簡単", "is_correct": true, "explanation": "「この問題は簡単なので」の空所に入り、むずかしくないという意味で文に合う。"}, {"text": "静か", "is_correct": false, "explanation": "「この問題は静かなので」では、問題の難しさを表せず意味が通らない。"}, {"text": "元気", "is_correct": false, "explanation": "人の様子を表す語で、問題の難しさの説明にならない。"}, {"text": "派手", "is_correct": false, "explanation": "見た目が目立つことを表す語で、問題の難しさの説明にならない。"}], "explanations": {"簡単": "「この問題は簡単なので」の空所に入り、むずかしくないという意味で文に合う。", "静か": "「この問題は静かなので」では、問題の難しさを表せず意味が通らない。", "元気": "人の様子を表す語で、問題の難しさの説明にならない。", "派手": "見た目が目立つことを表す語で、問題の難しさの説明にならない。"}, "sentence_index": 0, "correct_answer": "簡単"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は簡単な性格で、人を疑わない。", "explanation": "ここは〈単純〉の意味。簡単は手間がかからない意味で、人の性格は表さない。"}, {"text": "それは簡単なうわさにすぎない。", "explanation": "ここは〈単なる〉の意味。簡単は手間がかからないことで、「ただの」の意味は表さない。"}, {"text": "この部屋は簡単で、家具も少なく落ち着く。", "explanation": "ここは〈簡素〉の意味。簡単は手間がかからない意味で、飾りが少ない様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35022, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "簡単", "is_correct": true, "explanation": "「この漢字は形が簡単なので」の空所に入り、形の易しさを表す。"}, {"text": "豪快", "is_correct": false, "explanation": "「形が豪快なので」では意味が通らず、形の易しさを表せない。"}, {"text": "健康", "is_correct": false, "explanation": "「形が健康なので」では意味が通らない。"}, {"text": "正直", "is_correct": false, "explanation": "性格を表す語で、形の易しさを表せない。"}], "explanations": {"簡単": "「この漢字は形が簡単なので」の空所に入り、形の易しさを表す。", "豪快": "「形が豪快なので」では意味が通らず、形の易しさを表せない。", "健康": "「形が健康なので」では意味が通らない。", "正直": "性格を表す語で、形の易しさを表せない。"}, "sentence_index": 6, "correct_answer": "簡単"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員は簡単な態度で客に接した。", "explanation": "ここは〈そっけない〉の意味。簡単は手間がかからない意味で、冷たい態度は表さない。"}, {"text": "彼女は簡単な服が好きで、いつも黒を選ぶ。", "explanation": "ここは〈地味〉の意味。簡単は手間がかからない意味で、服の目立たなさは表さない。"}, {"text": "この花は簡単にきれいだ。", "explanation": "「簡単に」は動作の程度を表す副詞で、「きれい」という状態の程度は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35022, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計算は簡単な解けるので、すぐ終わる。", "corrected_sentence": "この計算は簡単に解けるので、すぐ終わる。", "error_description": "「簡単に解ける」の「に」が「な」になっている。「簡単な」は名詞を修飾する形で、動詞「解ける」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "簡単で", "is_correct": true, "explanation": "「説明は簡単で、〜」の形で、て形として続けて理解しやすさを述べる。"}, {"text": "簡単だ", "is_correct": false, "explanation": "終止形で、文を言い切る形になるため、「、子どもでも」と続けられない。"}, {"text": "簡単な", "is_correct": false, "explanation": "連体形で、後ろに名詞が必要になるため、「説明は簡単な、」では続かない。"}, {"text": "簡単ではない", "is_correct": false, "explanation": "否定形で、理解できたという文の内容と合わない。"}], "correct_form": "簡単で", "base_form": "簡単", "form_label": "て形", "sentence_index": 1, "explanations": {"簡単で": "「説明は簡単で、〜」の形で、て形として続けて理解しやすさを述べる。", "簡単だ": "終止形で、文を言い切る形になるため、「、子どもでも」と続けられない。", "簡単な": "連体形で、後ろに名詞が必要になるため、「説明は簡単な、」では続かない。", "簡単ではない": "否定形で、理解できたという文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35022, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "簡単が練習問題から始めると、続けやすい。", "corrected_sentence": "簡単な練習問題から始めると、続けやすい。", "error_description": "「簡単な練習問題」の「な」が「が」になっている。簡単は名詞を修飾するとき「な」が必要で、「が」は文の成分にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "簡単な", "is_correct": true, "explanation": "連体形で、「簡単な英語の本」と後ろの名詞を修飾している。"}, {"text": "簡単で", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、「簡単で英語の本」では続かない。"}, {"text": "簡単さ", "is_correct": false, "explanation": "名詞の「簡単さ」は後ろの名詞に直接つながらず、「簡単さ英語の本」は成り立たない。"}, {"text": "簡単だ", "is_correct": false, "explanation": "終止形は名詞を修飾できず、「簡単だ英語の本」は成り立たない。"}], "correct_form": "簡単な", "base_form": "簡単", "form_label": "連体形", "sentence_index": 7, "explanations": {"簡単な": "連体形で、「簡単な英語の本」と後ろの名詞を修飾している。", "簡単で": "て形は名詞を直接修飾できず、「簡単で英語の本」では続かない。", "簡単さ": "名詞の「簡単さ」は後ろの名詞に直接つながらず、「簡単さ英語の本」は成り立たない。", "簡単だ": "終止形は名詞を修飾できず、「簡単だ英語の本」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
