INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35023, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "むずかしくないこと。すぐにできること。", "primary_collocate": null, "pronunciation": "かんたん", "ipa": "kaɲtaɴ", "syllable_count": 4, "sentences": [{"text": "この料理は簡単に作れるので、忙しい日に便利だ。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "このりょうりはかんたんにつくれるので、いそがしいひにべんりだ。", "sentence_source": "generated"}, {"text": "申し込みは簡単で、名前を書くだけで済む。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "もうしこみはかんたんで、なまえをかくだけですむ。", "sentence_source": "generated"}, {"text": "ボタンを押すだけの簡単な作業だから、すぐ終わる。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "ボタンをおすだけのかんたんなさぎょうだから、すぐおわる。", "sentence_source": "generated"}, {"text": "そんなに簡単には、新しい仕事は見つからない。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "そんなにかんたんには、あたらしいしごとはみつからない。", "sentence_source": "generated"}, {"text": "傘を直すのは、思ったより簡単だった。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "かさをなおすのは、おもったよりかんたんだった。", "sentence_source": "generated"}, {"text": "簡単な朝ごはんを食べて、急いで家を出た。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "かんたんなあさごはんをたべて、いそいでいえをでた。", "sentence_source": "generated"}, {"text": "この機械は簡単に動かせるので、お年寄りにも人気がある。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "このきかいはかんたんにうごかせるので、おとしよりにもにんきがある。", "sentence_source": "generated"}, {"text": "外国語を話せるようになるのは、簡単なことではない。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "がいこくごをはなせるようになるのは、かんたんなことではない。", "sentence_source": "generated"}, {"text": "簡単にできる運動から、毎日続けてみよう。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "かんたんにできるうんどうから、まいにちつづけてみよう。", "sentence_source": "generated"}, {"text": "このアプリを使えば、切符の予約も簡単だ。", "target_word": "簡単", "complexity_tier": "T3", "furigana": "このアプリをつかえば、きっぷのよやくもかんたんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡単だ", "label": "終止形"}, {"form": "簡単な", "label": "連体形"}, {"form": "簡単に", "label": "連用形"}, {"form": "簡単で", "label": "て形"}, {"form": "簡単ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "手間がかからず、すぐにできる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2bc8fb-5cad-4828-a8e5-f8d473bc523b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35023, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "簡単", "is_correct": true, "explanation": "「この料理は簡単に作れる」の空所に入り、手間がかからない意味で文に合う。"}, {"text": "派手", "is_correct": false, "explanation": "「派手に作れる」では手間がかからないという意味にならない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かに作れる」では手間の少なさを表せず、意味が通らない。"}, {"text": "健康", "is_correct": false, "explanation": "「健康に作れる」では手間の少なさを表せず、意味が通らない。"}], "explanations": {"簡単": "「この料理は簡単に作れる」の空所に入り、手間がかからない意味で文に合う。", "派手": "「派手に作れる」では手間がかからないという意味にならない。", "静か": "「静かに作れる」では手間の少なさを表せず、意味が通らない。", "健康": "「健康に作れる」では手間の少なさを表せず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "簡単"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は簡単な性格で、人を疑わない。", "explanation": "ここは〈単純〉の意味。簡単は手間がかからない意味で、人の性格は表さない。"}, {"text": "彼女は簡単な服ばかり選んで、目立たない色を好む。", "explanation": "ここは〈地味〉の意味。簡単は手間がかからない意味で、服の目立たなさは表さない。"}, {"text": "この店では、簡単な値段でおいしいものを食べられる。", "explanation": "ここは〈手軽〉の意味。手軽は費用の少なさも表すが、簡単は手間のかからなさを表すので、値段の安さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35023, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "簡単", "is_correct": true, "explanation": "「この機械は簡単に動かせる」の空所に入り、手間がかからない意味で文に合う。"}, {"text": "正直", "is_correct": false, "explanation": "「正直に動かせる」では手間の少なさを表せず、意味が通らない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気に動かせる」では手間の少なさを表せず、意味が通らない。"}, {"text": "誠実", "is_correct": false, "explanation": "人の態度を表す語で、手間の少なさの説明にならない。"}], "explanations": {"簡単": "「この機械は簡単に動かせる」の空所に入り、手間がかからない意味で文に合う。", "正直": "「正直に動かせる」では手間の少なさを表せず、意味が通らない。", "陽気": "「陽気に動かせる」では手間の少なさを表せず、意味が通らない。", "誠実": "人の態度を表す語で、手間の少なさの説明にならない。"}, "sentence_index": 6, "correct_answer": "簡単"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その計画は簡単な夢にすぎない。", "explanation": "ここは〈単なる〉の意味。簡単は手間がかからない意味で、「ただの」の意味は表さない。"}, {"text": "店員は簡単な態度で客に接した。", "explanation": "ここは〈そっけない〉の意味。簡単は手間がかからない意味で、冷たい態度は表さない。"}, {"text": "この町は簡単に静かだ。", "explanation": "「簡単に」は動作の程度を表す副詞で、「静か」という状態の程度は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35023, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このスープは簡単を作れるので、朝にも便利だ。", "corrected_sentence": "このスープは簡単に作れるので、朝にも便利だ。", "error_description": "「簡単に作れる」の「に」が「を」になっている。簡単は作る対象の名詞ではなく、「に」で動詞を修飾する形で使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "簡単で", "is_correct": true, "explanation": "「申し込みは簡単で、〜」の形で、て形として続けて手間の少なさを述べる。"}, {"text": "簡単な", "is_correct": false, "explanation": "連体形は後ろに名詞が必要になるため、「申し込みは簡単な、」では続かない。"}, {"text": "簡単だ", "is_correct": false, "explanation": "終止形で文を言い切る形になるため、「、名前を書く」と続けられない。"}, {"text": "簡単に", "is_correct": false, "explanation": "連用形は文の述語にならず、「申し込みは簡単に、」は文として続かない。"}], "correct_form": "簡単で", "base_form": "簡単", "form_label": "て形", "sentence_index": 1, "explanations": {"簡単で": "「申し込みは簡単で、〜」の形で、て形として続けて手間の少なさを述べる。", "簡単な": "連体形は後ろに名詞が必要になるため、「申し込みは簡単な、」では続かない。", "簡単だ": "終止形で文を言い切る形になるため、「、名前を書く」と続けられない。", "簡単に": "連用形は文の述語にならず、「申し込みは簡単に、」は文として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35023, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この作業は簡単な終わるので、昼休みまでに片付く。", "corrected_sentence": "この作業は簡単に終わるので、昼休みまでに片付く。", "error_description": "「簡単に終わる」の「に」が「な」になっている。「簡単な」は名詞を修飾する形で、動詞「終わる」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "簡単な", "is_correct": true, "explanation": "連体形で、「簡単なことではない」と後ろの名詞「こと」を修飾している。"}, {"text": "簡単なら", "is_correct": false, "explanation": "仮定形で、後ろの名詞「こと」を修飾できないため、「簡単ならことではない」は成り立たない。"}, {"text": "簡単になり", "is_correct": false, "explanation": "連用形に「なり」が付いた形で、「こと」を修飾できず、「簡単になりことではない」は成り立たない。"}, {"text": "簡単さ", "is_correct": false, "explanation": "名詞形で、「の」がなければ「こと」に直接続かず、「簡単さことではない」は成り立たない。"}], "correct_form": "簡単な", "base_form": "簡単", "form_label": "連体形", "sentence_index": 7, "explanations": {"簡単な": "連体形で、「簡単なことではない」と後ろの名詞「こと」を修飾している。", "簡単なら": "仮定形で、後ろの名詞「こと」を修飾できないため、「簡単ならことではない」は成り立たない。", "簡単になり": "連用形に「なり」が付いた形で、「こと」を修飾できず、「簡単になりことではない」は成り立たない。", "簡単さ": "名詞形で、「の」がなければ「こと」に直接続かず、「簡単さことではない」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742dd52d-0209-473e-8839-0d7d77993960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
