INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35024, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「五月に入る」の「に」。時点や期間の始まりを表す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を表す「を」。「五月を入る」では時点が立たず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」。「五月で入る」とは言わないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す「と」。「五月と入る」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「五月に入る」の「に」。時点や期間の始まりを表す。", "を": "動作の対象を表す「を」。「五月を入る」では時点が立たず、文が成り立たない。", "で": "場所や手段を表す「で」。「五月で入る」とは言わないので合わない。", "と": "共同や引用を表す「と」。「五月と入る」は意味が通らない。"}, "error_tags": {"を": "動作の対象（時点を表せない）", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35024, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ごがつ。いちねんのなかの、ごばんめのつきです。", "primary_collocate": null, "pronunciation": "ごがつ", "ipa": "ɡoɡatsɯ", "syllable_count": 3, "sentences": [{"text": "四月が終わると、次の月は五月になります。", "target_word": "五月", "complexity_tier": "T3", "furigana": "四月[しがつ]が終[お]わると、次[つぎ]の月[つき]は五月[ごがつ]になります。", "sentence_source": "generated"}, {"text": "私の誕生日は五月の十日です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "私[わたし]の誕生日[たんじょうび]は五月[ごがつ]の十日[とおか]です。", "sentence_source": "generated"}, {"text": "五月になると、だんだん暑い日が増えてきます。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]になると、だんだん暑[あつ]い日[ひ]が増[ふ]えてきます。", "sentence_source": "generated"}, {"text": "来年の五月に、友達と旅行する予定です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "来年[らいねん]の五月[ごがつ]に、友達[ともだち]と旅行[りょこう]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "一月から数えると、五月は五番目の月です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "一月[いちがつ]から数[かぞ]えると、五月[ごがつ]は五番目[ごばんめ]の月[つき]です。", "sentence_source": "generated"}, {"text": "五月の最後の日は、三十一日です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]の最後[さいご]の日[ひ]は、三十一日[さんじゅういちにち]です。", "sentence_source": "generated"}, {"text": "去年の五月は雨が少なくて、庭の花がよく育ちました。", "target_word": "五月", "complexity_tier": "T3", "furigana": "去年[きょねん]の五月[ごがつ]は雨[あめ]が少[すく]なくて、庭[にわ]の花[はな]がよく育[そだ]ちました。", "sentence_source": "generated"}, {"text": "五月に入ってから、毎週末に出かけています。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]に入[はい]ってから、毎週末[まいしゅうまつ]に出[で]かけています。", "sentence_source": "generated"}, {"text": "会議は四月ではなく、五月に行われます。", "target_word": "五月", "complexity_tier": "T3", "furigana": "会議[かいぎ]は四月[しがつ]ではなく、五月[ごがつ]に行[おこな]われます。", "sentence_source": "generated"}, {"text": "姉は五月に結婚式を挙げます。", "target_word": "五月", "complexity_tier": "T3", "furigana": "姉[あね]は五月[ごがつ]に結婚式[けっこんしき]を挙[あ]げます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "五月", "label": "基本形"}, {"form": "五月に", "label": "時を表す形"}, {"form": "五月の", "label": "連体の形"}], "register": "標準語（中立）", "sense_fingerprint": "一年の五番目の月。四月の次、六月の前にあたる暦の月の名前。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35024, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "五月", "is_correct": true, "explanation": "月の名前。四月の次の月として文に合う。"}, {"text": "五日", "is_correct": false, "explanation": "日付の五日。月の名前ではないので「次の月は〜になります」に合わない。"}, {"text": "五時", "is_correct": false, "explanation": "時刻の五時。月の名前としては入らない。"}, {"text": "五年", "is_correct": false, "explanation": "年数の五年。次の月の名前にはならない。"}], "explanations": {"五月": "月の名前。四月の次の月として文に合う。", "五日": "日付の五日。月の名前ではないので「次の月は〜になります」に合わない。", "五時": "時刻の五時。月の名前としては入らない。", "五年": "年数の五年。次の月の名前にはならない。"}, "sentence_index": 0, "correct_answer": "五月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お店は毎日五月に閉まるので、急いで行きましょう。", "explanation": "ここは〈五時〉の意味。店の閉店時刻は五時と言い、月の名前の五月は合わない。"}, {"text": "給料は毎月五月に払われます。", "explanation": "ここは〈五日〉の意味。毎月の日付は五日と言い、月の名前の五月は合わない。"}, {"text": "留学は五月かかるので、就職は来年にします。", "explanation": "ここは〈五か月〉の意味。期間の長さは五か月と言い、五月は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35024, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "五月", "is_correct": true, "explanation": "月の名前。去年の一時期を表すので文に合う。"}, {"text": "五週", "is_correct": false, "explanation": "週の数。「去年の五週は」では意味が通らない。"}, {"text": "五世紀", "is_correct": false, "explanation": "世紀の名前。雨が少ない時期の説明には入らない。"}, {"text": "五回", "is_correct": false, "explanation": "回数。時期を表す語としては入らない。"}], "explanations": {"五月": "月の名前。去年の一時期を表すので文に合う。", "五週": "週の数。「去年の五週は」では意味が通らない。", "五世紀": "世紀の名前。雨が少ない時期の説明には入らない。", "五回": "回数。時期を表す語としては入らない。"}, "sentence_index": 6, "correct_answer": "五月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議室には五月集まりました。", "explanation": "ここは〈五人〉の意味。人数は五人と言い、月の名前の五月は合わない。"}, {"text": "夏休みは五月続きます。", "explanation": "ここは〈五週間〉の意味。期間の長さは五週間と言い、五月では合わない。"}, {"text": "薬は一日に五月飲みます。", "explanation": "ここは〈五回〉の意味。回数は五回と言い、五月は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35024, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年の五月を、家族は引っ越しました。", "corrected_sentence": "去年の五月に、家族は引っ越しました。", "error_description": "時点を表す「五月」には「に」を使う。「を」は動作の対象で、引っ越しの時点は表せないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35024, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "五月な連休に、家族で温泉へ行きました。", "corrected_sentence": "五月の連休に、家族で温泉へ行きました。", "error_description": "名詞の「五月」を次の名詞につなぐには「の」を使う。「な」は形容動詞などにつくので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
