INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35025, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す「に」。「毎年五月に」で、毎年の五月の時点を示す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を表す「を」。「五月を」では時点が立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」。時点の五月には使えない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す「と」。時点の説明には合わない。"}], "correct_answer": "に", "explanations": {"に": "時点を表す「に」。「毎年五月に」で、毎年の五月の時点を示す。", "を": "動作の対象を表す「を」。「五月を」では時点が立たない。", "で": "場所や手段を表す「で」。時点の五月には使えない。", "と": "共同や引用を表す「と」。時点の説明には合わない。"}, "error_tags": {"を": "動作の対象（時点を表せない）", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35025, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一年の五番目の月。新緑の季節で、こどもの日があります。", "primary_collocate": null, "pronunciation": "ごがつ", "ipa": "ɡoɡatsɯ", "syllable_count": 3, "sentences": [{"text": "五月は新緑がきれいで、散歩にぴったりの季節です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]は新緑[しんりょく]がきれいで、散歩[さんぽ]にぴったりの季節[きせつ]です。", "sentence_source": "generated"}, {"text": "五月五日のこどもの日には、家にこいのぼりを飾ります。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]五日[いつか]のこどもの日[ひ]には、家[いえ]にこいのぼりを飾[かざ]ります。", "sentence_source": "generated"}, {"text": "五月の風は気持ちよく、窓を開けて過ごしたくなります。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]の風[かぜ]は気持[きも]ちよく、窓[まど]を開[あ]けて過[す]ごしたくなります。", "sentence_source": "generated"}, {"text": "五月になると、山の木々が鮮やかな緑色に変わります。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]になると、山[やま]の木々[きぎ]が鮮[あざ]やかな緑色[みどりいろ]に変[か]わります。", "sentence_source": "generated"}, {"text": "五月の連休には、家族で公園へお弁当を持って行きました。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]の連休[れんきゅう]には、家族[かぞく]で公園[こうえん]へお弁当[べんとう]を持[も]って行[い]きました。", "sentence_source": "generated"}, {"text": "こどもの日があるので、五月は子どもたちが楽しみにしている月です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "こどもの日[ひ]があるので、五月[ごがつ]は子[こ]どもたちが楽[たの]しみにしている月[つき]です。", "sentence_source": "generated"}, {"text": "五月の朝は空気が澄んでいて、早起きも苦になりません。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]の朝[あさ]は空気[くうき]が澄[す]んでいて、早起[はやお]きも苦[く]になりません。", "sentence_source": "generated"}, {"text": "毎年五月に、祖母の家で柏餅を食べます。", "target_word": "五月", "complexity_tier": "T3", "furigana": "毎年[まいとし]五月[ごがつ]に、祖母[そぼ]の家[いえ]で柏餅[かしわもち]を食[た]べます。", "sentence_source": "generated"}, {"text": "新緑の五月、私たちは湖のそばでキャンプをしました。", "target_word": "五月", "complexity_tier": "T3", "furigana": "新緑[しんりょく]の五月[ごがつ]、私[わたし]たちは湖[みずうみ]のそばでキャンプをしました。", "sentence_source": "generated"}, {"text": "五月は暑すぎず寒すぎず、外で遊ぶのにちょうどいい時期です。", "target_word": "五月", "complexity_tier": "T3", "furigana": "五月[ごがつ]は暑[あつ]すぎず寒[さむ]すぎず、外[そと]で遊[あそ]ぶのにちょうどいい時期[じき]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "五月", "label": "基本形"}, {"form": "五月に", "label": "時を表す形"}, {"form": "五月の", "label": "連体の形"}], "register": "標準語（中立）", "sense_fingerprint": "新緑がまぶしく、こどもの日や連休がある季節としての五月。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35025, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "五月", "is_correct": true, "explanation": "月の名前。新緑の季節を指すので文に合う。"}, {"text": "五日", "is_correct": false, "explanation": "日付の五日。季節の説明には入らない。"}, {"text": "五時", "is_correct": false, "explanation": "時刻の五時。季節の名前にはならない。"}, {"text": "五分", "is_correct": false, "explanation": "短い時間の五分。季節を表さない。"}], "explanations": {"五月": "月の名前。新緑の季節を指すので文に合う。", "五日": "日付の五日。季節の説明には入らない。", "五時": "時刻の五時。季節の名前にはならない。", "五分": "短い時間の五分。季節を表さない。"}, "sentence_index": 0, "correct_answer": "五月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お湯が沸くのを五月待ちました。", "explanation": "ここは〈五分〉の意味。短い時間の長さは五分と言い、月の名前の五月は合わない。"}, {"text": "ケーキにろうそくを五月立てました。", "explanation": "ここは〈五本〉の意味。細長いものの数は五本と言い、五月は合わない。"}, {"text": "私の部屋は五月にあります。", "explanation": "ここは〈五階〉の意味。階数は五階と言い、五月は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35025, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "五月", "is_correct": true, "explanation": "月の名前。五月の朝は季節の朝として自然に入る。"}, {"text": "五本", "is_correct": false, "explanation": "細長いものの数。「〜の朝」には入らない。"}, {"text": "五人", "is_correct": false, "explanation": "人数。朝の時期を表さない。"}, {"text": "五枚", "is_correct": false, "explanation": "薄いものの数。朝の時期を表さない。"}], "explanations": {"五月": "月の名前。五月の朝は季節の朝として自然に入る。", "五本": "細長いものの数。「〜の朝」には入らない。", "五人": "人数。朝の時期を表さない。", "五枚": "薄いものの数。朝の時期を表さない。"}, "sentence_index": 6, "correct_answer": "五月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この荷物は五月重いので、一人では運べません。", "explanation": "ここは〈五キロ〉の意味。重さは五キロと言い、五月は合わない。"}, {"text": "夏合宿は五月続きます。", "explanation": "ここは〈五週間〉の意味。期間の長さは五週間と言い、五月は合わない。"}, {"text": "うがいは一日に五月します。", "explanation": "ここは〈五回〉の意味。回数は五回と言い、五月は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35025, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "五月を、新緑がきれいになり、外で遊ぶ人が増えます。", "corrected_sentence": "五月に新緑がきれいになり、外で遊ぶ人が増えます。", "error_description": "時点を表す「五月」には「に」を使う。「を」は動作の対象で、時点には使えないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35025, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "五月な風が気持ちよく、窓を開けてみたくなります。", "corrected_sentence": "五月の風が気持ちよく、窓を開けてみたくなります。", "error_description": "名詞の「五月」を次の名詞につなぐには「の」を使う。「な」は形容動詞などにつくので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
