INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35026, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "じぶんで つくる。", "primary_collocate": null, "pronunciation": "こしらえる", "ipa": "koɕiɾaeɾɯ", "syllable_count": 5, "sentences": [{"text": "母は毎朝、私のためにお弁当を拵えてくれます。", "target_word": "拵えて", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、私[わたし]のためにお弁当[べんとう]を拵[こしら]えてくれます。", "sentence_source": "generated"}, {"text": "祖父は庭に小さな犬小屋を拵えた。", "target_word": "拵えた", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]に小[ちい]さな犬小屋[いぬごや]を拵[こしら]えた。", "sentence_source": "generated"}, {"text": "買うと高いので、自分で本棚を拵えることにしました。", "target_word": "拵える", "complexity_tier": "T3", "furigana": "買[か]うと高[たか]いので、自分[じぶん]で本棚[ほんだな]を拵[こしら]えることにしました。", "sentence_source": "generated"}, {"text": "夏祭りの前に、子どもたちは紙でお面を拵えました。", "target_word": "拵えました", "complexity_tier": "T3", "furigana": "夏祭[なつまつ]りの前[まえ]に、子[こ]どもたちは紙[かみ]でお面[めん]を拵[こしら]えました。", "sentence_source": "generated"}, {"text": "彼女は古い布で、かわいい人形を拵えている。", "target_word": "拵えている", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は古[ふる]い布[ぬの]で、かわいい人形[にんぎょう]を拵[こしら]えている。", "sentence_source": "generated"}, {"text": "父は日曜日に、木で小さな椅子を拵えています。", "target_word": "拵えて", "complexity_tier": "T3", "furigana": "父[ちち]は日曜日[にちようび]に、木[き]で小[ちい]さな椅子[いす]を拵[こしら]えています。", "sentence_source": "generated"}, {"text": "時間がなかったので、簡単な夕飯だけ拵えました。", "target_word": "拵えました", "complexity_tier": "T3", "furigana": "時間[じかん]がなかったので、簡単[かんたん]な夕飯[ゆうはん]だけ拵[こしら]えました。", "sentence_source": "generated"}, {"text": "雪が降った朝、兄は庭に雪だるまを拵えた。", "target_word": "拵えた", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]った朝[あさ]、兄[あに]は庭[にわ]に雪[ゆき]だるまを拵[こしら]えた。", "sentence_source": "generated"}, {"text": "祖母は毎年、自分で梅干しを拵えて近所に配ります。", "target_word": "拵えて", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎年[まいとし]、自分[じぶん]で梅干[うめぼ]しを拵[こしら]えて近所[きんじょ]に配[くば]ります。", "sentence_source": "generated"}, {"text": "友達の誕生日に、手紙と小さな箱を拵えて渡しました。", "target_word": "拵えて", "complexity_tier": "T3", "furigana": "友達[ともだち]の誕生日[たんじょうび]に、手紙[てがみ]と小[ちい]さな箱[はこ]を拵[こしら]えて渡[わた]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拵える", "label": "辞書形"}, {"form": "拵えた", "label": "過去形"}, {"form": "拵えて", "label": "テ形"}, {"form": "拵えない", "label": "否定形"}, {"form": "拵えます", "label": "丁寧形"}, {"form": "拵えれば", "label": "仮定形"}, {"form": "拵えよう", "label": "意向形"}, {"form": "拵えられる", "label": "可能形"}], "register": "やや口語的（親しみのある表現）", "sense_fingerprint": "料理や工作などを、買わずに自分の手で作り上げる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35026, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拵えて", "is_correct": true, "explanation": "「お弁当を作ってくれる」の意味で、「くれます」につながるテ形。"}, {"text": "読んで", "is_correct": false, "explanation": "文字を追う動作。お弁当を読むとは言わない。"}, {"text": "眺めて", "is_correct": false, "explanation": "じっと見る動作。お弁当を眺めてくれる、とは言わない。"}, {"text": "歌って", "is_correct": false, "explanation": "声に出す動作。お弁当には合わない。"}], "explanations": {"拵えて": "「お弁当を作ってくれる」の意味で、「くれます」につながるテ形。", "読んで": "文字を追う動作。お弁当を読むとは言わない。", "眺めて": "じっと見る動作。お弁当を眺めてくれる、とは言わない。", "歌って": "声に出す動作。お弁当には合わない。"}, "sentence_index": 0, "correct_answer": "拵えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、壊れた椅子を拵えました。", "explanation": "ここは〈直す〉の意味。壊れたものを元に戻すなら直すと言い、拵えるは材料から作ることなので合わない。"}, {"text": "床にジュースを拵えました。", "explanation": "ここは〈こぼす〉の意味。液体を床に落としたならこぼすと言い、拵えるは合わない。"}, {"text": "道で財布を拵えました。", "explanation": "ここは〈拾う〉の意味。落ちているものを見つけて取るなら拾うと言い、拵えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拵えました", "is_correct": true, "explanation": "丁寧な過去形。夕飯を用意したという文に合う。"}, {"text": "叩きました", "is_correct": false, "explanation": "強くたたく動作。夕飯を叩いたとは言わない。"}, {"text": "壊しました", "is_correct": false, "explanation": "壊す動作。夕飯を壊すとは言わない。"}, {"text": "磨きました", "is_correct": false, "explanation": "磨く動作。食べ物を磨く文脈には合わない。"}], "explanations": {"拵えました": "丁寧な過去形。夕飯を用意したという文に合う。", "叩きました": "強くたたく動作。夕飯を叩いたとは言わない。", "壊しました": "壊す動作。夕飯を壊すとは言わない。", "磨きました": "磨く動作。食べ物を磨く文脈には合わない。"}, "sentence_index": 6, "correct_answer": "拵えました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館で本を拵えて、来週返しました。", "explanation": "ここは〈借りる〉の意味。図書館から借りて返すなら借りるが正しく、拵えるは合わない。"}, {"text": "電車に傘を拵えてしまいました。", "explanation": "ここは〈落とす〉の意味。持ち物を置き忘れたなら落とすと言い、拵えるは合わない。"}, {"text": "店でお菓子を拵えて、そのまま逃げました。", "explanation": "ここは〈盗む〉の意味。持ち去る行為は盗むと言い、拵えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35026, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は毎朝、孫のためにおにぎりを拵えくれます。", "corrected_sentence": "祖母は毎朝、孫のためにおにぎりを拵えてくれます。", "error_description": "「拵える」に「くれます」を続けるには、テ形の「て」が必要。「て」が抜けているので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拵えた", "is_correct": true, "explanation": "過去の動作を表す普通形の過去形。文を締めくくる形として合う。"}, {"text": "拵えて", "is_correct": false, "explanation": "テ形。文末にできず、文が続いてしまう。"}, {"text": "拵えたり", "is_correct": false, "explanation": "並列の「たり」形。「〜たり」で止まり、文を締めくくれない。"}, {"text": "拵えれば", "is_correct": false, "explanation": "仮定形。「作れば」となり、過去の出来事を述べる文として締まらない。"}], "correct_form": "拵えた", "base_form": "拵える", "form_label": "過去形", "sentence_index": 1, "explanations": {"拵えた": "過去の動作を表す普通形の過去形。文を締めくくる形として合う。", "拵えて": "テ形。文末にできず、文が続いてしまう。", "拵えたり": "並列の「たり」形。「〜たり」で止まり、文を締めくくれない。", "拵えれば": "仮定形。「作れば」となり、過去の出来事を述べる文として締まらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35026, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の夜、弟は庭に小さな船に拵えた。", "corrected_sentence": "昨日の夜、弟は庭に小さな船を拵えた。", "error_description": "作る対象には「を」を使う。「に」は場所や相手を示すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拵えた", "is_correct": true, "explanation": "過去の普通形。「雪が降った朝」という過去の出来事に合う。"}, {"text": "拵えよう", "is_correct": false, "explanation": "意向形。「作ろう」の意味で、過去の出来事には合わない。"}, {"text": "拵えず", "is_correct": false, "explanation": "「作らず」の連用形。文末にできず、文が続いてしまう。"}, {"text": "拵えながら", "is_correct": false, "explanation": "同時進行の「ながら」形。文が途中で切れ、締めくくれない。"}], "correct_form": "拵えた", "base_form": "拵える", "form_label": "過去形", "sentence_index": 7, "explanations": {"拵えた": "過去の普通形。「雪が降った朝」という過去の出来事に合う。", "拵えよう": "意向形。「作ろう」の意味で、過去の出来事には合わない。", "拵えず": "「作らず」の連用形。文末にできず、文が続いてしまう。", "拵えながら": "同時進行の「ながら」形。文が途中で切れ、締めくくれない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
