INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35027, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "材料や部品を集めて、自分で作る。", "primary_collocate": null, "pronunciation": "こしらえる", "ipa": "koɕiɾaeɾɯ", "syllable_count": 5, "sentences": [{"text": "木材と釘を集めて、物置を拵えることにした。", "target_word": "拵える", "complexity_tier": "T3", "furigana": "木材[もくざい]と釘[くぎ]を集[あつ]めて、物置[ものおき]を拵[こしら]えることにした。", "sentence_source": "generated"}, {"text": "古い部品を集めて、弟はラジオを拵えました。", "target_word": "拵えました", "complexity_tier": "T3", "furigana": "古[ふる]い部品[ぶひん]を集[あつ]めて、弟[おとうと]はラジオを拵[こしら]えました。", "sentence_source": "generated"}, {"text": "必要な材料がそろったので、さっそく模型を拵え始めました。", "target_word": "拵え", "complexity_tier": "T3", "furigana": "必要[ひつよう]な材料[ざいりょう]がそろったので、さっそく模型[もけい]を拵[こしら]え始[はじ]めました。", "sentence_source": "generated"}, {"text": "近所の人たちが材料を持ち寄って、舞台を拵えました。", "target_word": "拵えました", "complexity_tier": "T3", "furigana": "近所[きんじょ]の人[ひと]たちが材料[ざいりょう]を持[も]ち寄[よ]って、舞台[ぶたい]を拵[こしら]えました。", "sentence_source": "generated"}, {"text": "彼は廃材を集めて、小さな舟を拵えた。", "target_word": "拵えた", "complexity_tier": "T3", "furigana": "彼[かれ]は廃材[はいざい]を集[あつ]めて、小[ちい]さな舟[ふね]を拵[こしら]えた。", "sentence_source": "generated"}, {"text": "店で買った部品を組み合わせて、自分用の机を拵えた。", "target_word": "拵えた", "complexity_tier": "T3", "furigana": "店[みせ]で買[か]った部品[ぶひん]を組[く]み合[あ]わせて、自分用[じぶんよう]の机[つくえ]を拵[こしら]えた。", "sentence_source": "generated"}, {"text": "余った布と糸を集めて、娘は人形の服を拵えています。", "target_word": "拵えて", "complexity_tier": "T3", "furigana": "余[あま]った布[ぬの]と糸[いと]を集[あつ]めて、娘[むすめ]は人形[にんぎょう]の服[ふく]を拵[こしら]えています。", "sentence_source": "generated"}, {"text": "材料を買い足してから、ベランダに花壇を拵えました。", "target_word": "拵えました", "complexity_tier": "T3", "furigana": "材料[ざいりょう]を買[か]い足[た]してから、ベランダに花壇[かだん]を拵[こしら]えました。", "sentence_source": "generated"}, {"text": "古い自転車の部品を集めて、新しい一台を拵えたそうだ。", "target_word": "拵えた", "complexity_tier": "T3", "furigana": "古[ふる]い自転車[じてんしゃ]の部品[ぶひん]を集[あつ]めて、新[あたら]しい一台[いちだい]を拵[こしら]えたそうだ。", "sentence_source": "generated"}, {"text": "竹と紙を集めて、七夕の飾りを拵えましょう。", "target_word": "拵えましょう", "complexity_tier": "T3", "furigana": "竹[たけ]と紙[かみ]を集[あつ]めて、七夕[たなばた]の飾[かざ]りを拵[こしら]えましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拵える", "label": "辞書形"}, {"form": "拵えた", "label": "過去形"}, {"form": "拵えて", "label": "テ形"}, {"form": "拵えない", "label": "否定形"}, {"form": "拵えます", "label": "丁寧形"}, {"form": "拵えれば", "label": "仮定形"}, {"form": "拵えよう", "label": "意向形"}, {"form": "拵えられる", "label": "可能形"}], "register": "やや口語的（親しみのある表現）", "sense_fingerprint": "木材・部品・布などの材料をそろえて、自分の手で形あるものに作り上げる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35027, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拵える", "is_correct": true, "explanation": "作るという意味の辞書形。「物置を作ることにした」として文に合う。"}, {"text": "歌う", "is_correct": false, "explanation": "声に出す動作。物置を歌うとは言わない。"}, {"text": "読む", "is_correct": false, "explanation": "文字を読む動作。物置を読むとは言わない。"}, {"text": "笑う", "is_correct": false, "explanation": "表情に関する動作。物置を笑うとは言わない。"}], "explanations": {"拵える": "作るという意味の辞書形。「物置を作ることにした」として文に合う。", "歌う": "声に出す動作。物置を歌うとは言わない。", "読む": "文字を読む動作。物置を読むとは言わない。", "笑う": "表情に関する動作。物置を笑うとは言わない。"}, "sentence_index": 0, "correct_answer": "拵える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "なくした書類を拵えて、一時間も机の上で悩みました。", "explanation": "ここは〈探す〉の意味。見当たらないものを捜すのは探すと言い、材料から作る拵えるは合わない。"}, {"text": "台風の夜、舞台を拵えてしまいました。", "explanation": "ここは〈壊れる〉の意味。被害で壊れた場合は壊れてしまうと言い、拵えるは合わない。"}, {"text": "近所の人を拵えて、広場に集めました。", "explanation": "ここは〈人を呼び寄せる〉の意味。人を呼ぶのは別の動作で、材料から作る拵えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35027, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拵えて", "is_correct": true, "explanation": "「〜ている」に続くテ形。服を作っている状態に合う。"}, {"text": "呼んで", "is_correct": false, "explanation": "名前などを呼ぶ動作。服を呼ぶとは言わない。"}, {"text": "唱えて", "is_correct": false, "explanation": "声に出して言う動作。服には使わない。"}, {"text": "叫んで", "is_correct": false, "explanation": "大声を出す動作。服には合わない。"}], "explanations": {"拵えて": "「〜ている」に続くテ形。服を作っている状態に合う。", "呼んで": "名前などを呼ぶ動作。服を呼ぶとは言わない。", "唱えて": "声に出して言う動作。服には使わない。", "叫んで": "大声を出す動作。服には合わない。"}, "sentence_index": 6, "correct_answer": "拵えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れた机を拵えて、きれいに直しました。", "explanation": "ここは〈修理〉の意味。壊れたものを元どおりにするのは修理と言い、材料から新しく作る拵えるは合わない。"}, {"text": "大事な鍵を拵えてしまい、家に入れません。", "explanation": "ここは〈失くす〉の意味。持ち物をなくしたなら失くすと言い、拵えるは合わない。"}, {"text": "お皿を拵えて、台所で洗いました。", "explanation": "ここは〈汚れを落とす〉の意味。皿を清める行為は別の動作で、材料から作る拵えるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35027, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人と相談して、小屋に拵えることにしました。", "corrected_sentence": "友人と相談して、小屋を拵えることにしました。", "error_description": "作る対象には「を」を使う。「に」は場所を表すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拵えました", "is_correct": true, "explanation": "丁寧な過去形。過去の出来事を述べる文に合う。"}, {"text": "拵えて", "is_correct": false, "explanation": "テ形。文末にできず、文が続いてしまう。"}, {"text": "拵えません", "is_correct": false, "explanation": "丁寧な否定形。「作らない」の意味になり、文の内容と合わない。"}, {"text": "拵えましょう", "is_correct": false, "explanation": "丁寧な意向形。勧めや意志を表し、過去の出来事に合わない。"}], "correct_form": "拵えました", "base_form": "拵える", "form_label": "丁寧な過去形", "sentence_index": 1, "explanations": {"拵えました": "丁寧な過去形。過去の出来事を述べる文に合う。", "拵えて": "テ形。文末にできず、文が続いてしまう。", "拵えません": "丁寧な否定形。「作らない」の意味になり、文の内容と合わない。", "拵えましょう": "丁寧な意向形。勧めや意志を表し、過去の出来事に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35027, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "娘は紙で人形の服を拵えでいます。", "corrected_sentence": "娘は紙で人形の服を拵えています。", "error_description": "「拵える」のテ形は「て」になる。「で」は読む・飲むなどの濁音の動詞につくので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拵えました", "is_correct": true, "explanation": "丁寧な過去形。花壇を作ったという過去の事実に合う。"}, {"text": "拵えて", "is_correct": false, "explanation": "テ形。文末にできず、文が続いてしまう。"}, {"text": "拵えれば", "is_correct": false, "explanation": "仮定形。「作れば」となり、文を締めくくれない。"}, {"text": "拵えまして", "is_correct": false, "explanation": "丁寧なテ形。文が続いてしまい、文末にできない。"}], "correct_form": "拵えました", "base_form": "拵える", "form_label": "丁寧な過去形", "sentence_index": 7, "explanations": {"拵えました": "丁寧な過去形。花壇を作ったという過去の事実に合う。", "拵えて": "テ形。文末にできず、文が続いてしまう。", "拵えれば": "仮定形。「作れば」となり、文を締めくくれない。", "拵えまして": "丁寧なテ形。文が続いてしまい、文末にできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「席に座る」の「に」。座る場所を示し、文の意味と合う。"}, {"text": "を", "is_correct": false, "explanation": "「席を座る」は誤り。座る場所は「に」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「席が座る」は席が座ることになり、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「席の座る」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「席に座る」の「に」。座る場所を示し、文の意味と合う。", "を": "「席を座る」は誤り。座る場所は「に」で示す。", "が": "「席が座る」は席が座ることになり、不自然。", "の": "「席の座る」は意味が通らない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「前の席の人」の「の」。席にいる人を結ぶ所属の意味で、文と合う。"}, {"text": "へ", "is_correct": false, "explanation": "「前の席へ人」は方向の形で、人の頭の所属にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「前の席から人」は起点の意味になり、文の流れに合わない。"}, {"text": "より", "is_correct": false, "explanation": "「前の席より人」は比較の意味になり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「前の席の人」の「の」。席にいる人を結ぶ所属の意味で、文と合う。", "へ": "「前の席へ人」は方向の形で、人の頭の所属にはならない。", "から": "「前の席から人」は起点の意味になり、文の流れに合わない。", "より": "「前の席より人」は比較の意味になり、意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "すわる ところ。", "primary_collocate": null, "pronunciation": "せき", "ipa": "seki", "syllable_count": 2, "sentences": [{"text": "バスの席が空いたので、私は荷物を持ったまま座った。", "target_word": "席", "complexity_tier": "T3", "furigana": "バスのせきがあいたので、わたしはにもつをもったまますわった。", "sentence_source": "generated"}, {"text": "教室では、先生が決めた席に座るきまりだ。", "target_word": "席", "complexity_tier": "T3", "furigana": "きょうしつでは、せんせいがきめたせきにすわるきまりだ。", "sentence_source": "generated"}, {"text": "遅れて入った劇場で、暗い中、自分の席を探した。", "target_word": "席", "complexity_tier": "T3", "furigana": "おくれてはいったげきじょうで、くらいなか、じぶんのせきをさがした。", "sentence_source": "generated"}, {"text": "子どもは、父の隣の席がいいと言ってゆずらなかった。", "target_word": "席", "complexity_tier": "T3", "furigana": "こどもは、ちちのとなりのせきがいいといってゆずらなかった。", "sentence_source": "generated"}, {"text": "新幹線の席を、旅行の一か月前に予約した。", "target_word": "席", "complexity_tier": "T3", "furigana": "しんかんせんのせきを、りょこうのいっかげつまえによやくした。", "sentence_source": "generated"}, {"text": "この席は日当たりがいいので、冬でも暖かい。", "target_word": "席", "complexity_tier": "T3", "furigana": "このせきはひあたりがいいので、ふゆでもあたたかい。", "sentence_source": "generated"}, {"text": "立っていた男の子に、母が自分の席をゆずった。", "target_word": "席", "complexity_tier": "T3", "furigana": "たっていたおとこのこに、ははがじぶんのせきをゆずった。", "sentence_source": "generated"}, {"text": "前の席の人の頭が大きくて、舞台がよく見えなかった。", "target_word": "席", "complexity_tier": "T3", "furigana": "まえのせきのひとのあたまがおおきくて、ぶたいがよくみえなかった。", "sentence_source": "generated"}, {"text": "席が足りなかったので、数人は壁ぎわに立って聞いていた。", "target_word": "席", "complexity_tier": "T3", "furigana": "せきがたりなかったので、すうにんはかべぎわにたってきいていた。", "sentence_source": "generated"}, {"text": "彼は店に入ると、いつもの席に座って、コーヒーを頼んだ。", "target_word": "席", "complexity_tier": "T3", "furigana": "かれはみせにはいると、いつものせきにすわって、コーヒーをたのんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "席", "label": "基本形"}], "register": "中立（普通体の書き言葉）", "sense_fingerprint": "すわる場所としての席", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ゆずら (Zipf 2.14)','sentence 6 above tier T2: contains vocabulary far above tier T2: ゆずっ (Zipf 2.48)','sentence 8 above tier T2: contains vocabulary far above tier T2: ぎわ (Zipf 2.18)']::text[], '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "席", "is_correct": true, "explanation": "「バスの席が空いた」は座る場所が空くことを表し、文と合う。"}, {"text": "運転手", "is_correct": false, "explanation": "「バスの運転手が空いた」は人の状態として不自然。"}, {"text": "荷物", "is_correct": false, "explanation": "「バスの荷物が空いた」は意味が通らない。"}, {"text": "切符", "is_correct": false, "explanation": "「バスの切符が空いた」は座る場所の空きを表さない。"}], "explanations": {"席": "「バスの席が空いた」は座る場所が空くことを表し、文と合う。", "運転手": "「バスの運転手が空いた」は人の状態として不自然。", "荷物": "「バスの荷物が空いた」は意味が通らない。", "切符": "「バスの切符が空いた」は座る場所の空きを表さない。"}, "sentence_index": 0, "correct_answer": "席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は古い席を磨いて、居間に置いた。", "explanation": "ここは〈椅子〉の意味。磨いて居間に置くのは物としての椅子で、すわる場所の〈席〉とは言わない。"}, {"text": "この部屋は窓が大きく、明るい席だ。", "explanation": "ここは〈空間〉の意味。席は座るための場所なので、部屋の明るさは言えない。"}, {"text": "この席は取っ手が取れていて、物が落ちそうだ。", "explanation": "ここは〈戸棚〉の意味。取っ手や扉を持つ収納を指すので、座る場所の〈席〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "席", "is_correct": true, "explanation": "「自分の席」は自分が座る場所で、「ゆずった」と合う。"}, {"text": "影", "is_correct": false, "explanation": "影は座る場所ではなく、「自分の影をゆずる」は意味が通らない。"}, {"text": "呼吸", "is_correct": false, "explanation": "「呼吸をゆずる」は不自然で、座る場所を表さない。"}, {"text": "足跡", "is_correct": false, "explanation": "「足跡をゆずる」は意味が通らない。"}], "explanations": {"席": "「自分の席」は自分が座る場所で、「ゆずった」と合う。", "影": "影は座る場所ではなく、「自分の影をゆずる」は意味が通らない。", "呼吸": "「呼吸をゆずる」は不自然で、座る場所を表さない。", "足跡": "「足跡をゆずる」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅館の部屋で、広い席にシーツを敷いた。", "explanation": "ここは〈寝台〉の意味。シーツを敷いて眠る場所は寝台のことで、すわる場所の〈席〉とは言わない。"}, {"text": "ペンは、引き出しのいつもの席にあった。", "explanation": "ここは〈場所〉の意味。席は座るための場所に使うので、引き出しの中の位置には言わない。"}, {"text": "家具の席を変えると、部屋が広く見える。", "explanation": "ここは〈配置〉の意味。家具の並べ方を指すので、人が座る場所の〈席〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓際の席が選んで座った。", "corrected_sentence": "窓際の席を選んで座った。", "error_description": "誤: 席が選んで / 正: 席を選んで。「選ぶ」は目的語に「を」を使うため、「席が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35028, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "後ろの席を座って、本を読んだ。", "corrected_sentence": "後ろの席に座って、本を読んだ。", "error_description": "誤: 席を座って / 正: 席に座って。座る場所は「に」で示す。「席を座る」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「席をゆずった」の「を」。ゆずるの目的語で、文の意味と合う。"}, {"text": "が", "is_correct": false, "explanation": "「席がゆずった」は席が譲る形になり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「席よりゆずった」は比較の形にならず、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「席のゆずった」は名詞をつなぐ形で、動詞に続かない。"}], "correct_answer": "を", "explanations": {"を": "「席をゆずった」の「を」。ゆずるの目的語で、文の意味と合う。", "が": "「席がゆずった」は席が譲る形になり、不自然。", "より": "「席よりゆずった」は比較の形にならず、意味が通らない。", "の": "「席のゆずった」は名詞をつなぐ形で、動詞に続かない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「後ろの席になった」の「に」。なるの結果の場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「席をなった」は誤り。「なる」は結果を「に」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「席へなった」は方向を示す形で、結果の意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「席でなった」は場所や手段の「で」で、なるの結果を表せない。"}], "correct_answer": "に", "explanations": {"に": "「後ろの席になった」の「に」。なるの結果の場所を示す。", "を": "「席をなった」は誤り。「なる」は結果を「に」で示す。", "へ": "「席へなった」は方向を示す形で、結果の意味にならない。", "で": "「席でなった」は場所や手段の「で」で、なるの結果を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が座るための場所。座席。", "primary_collocate": null, "pronunciation": "せき", "ipa": "seki", "syllable_count": 2, "sentences": [{"text": "放課後の静かな美術室で、私は窓辺の席につきクレヨンを走らせている。", "target_word": "席", "complexity_tier": "T3", "furigana": "ほうかごのしずかなびじゅつしつで、わたしはまどべのせきにつきクレヨンをはしらせている。", "sentence_source": "mined"}, {"text": "電車が混んでいたので、おばあさんに席をゆずった。", "target_word": "席", "complexity_tier": "T3", "furigana": "でんしゃがこんでいたので、おばあさんにせきをゆずった。", "sentence_source": "generated"}, {"text": "映画館の席は予約のときに自分で選べる。", "target_word": "席", "complexity_tier": "T3", "furigana": "えいがかんのせきはよやくのときにじぶんでえらべる。", "sentence_source": "generated"}, {"text": "先生は「自分の席に戻って、教科書を開きなさい」と言った。", "target_word": "席", "complexity_tier": "T3", "furigana": "せんせいは「じぶんのせきにもどって、きょうかしょをひらきなさい」といった。", "sentence_source": "generated"}, {"text": "店は満席で、私たちは席が空くまで三十分待った。", "target_word": "席", "complexity_tier": "T3", "furigana": "みせはまんせきで、わたしたちはせきがあくまでさんじゅっぷんまった。", "sentence_source": "generated"}, {"text": "彼女は私の隣の席に、かばんを置いた。", "target_word": "席", "complexity_tier": "T3", "furigana": "かのじょはわたしのとなりのせきに、かばんをおいた。", "sentence_source": "generated"}, {"text": "飛行機では、窓側の席のほうが景色がよく見える。", "target_word": "席", "complexity_tier": "T3", "furigana": "ひこうきでは、まどがわのせきのほうがけしきがよくみえる。", "sentence_source": "generated"}, {"text": "席替えで後ろの席になったので、黒板の字が小さく見える。", "target_word": "席", "complexity_tier": "T3", "furigana": "せきがえでうしろのせきになったので、こくばんのじがちいさくみえる。", "sentence_source": "generated"}, {"text": "会議が始まる前に、全員が席についた。", "target_word": "席", "complexity_tier": "T3", "furigana": "かいぎがはじまるまえに、ぜんいんがせきについた。", "sentence_source": "generated"}, {"text": "食堂の席は、昼になるとすぐにいっぱいになる。", "target_word": "席", "complexity_tier": "T3", "furigana": "しょくどうのせきは、ひるになるとすぐにいっぱいになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "席", "label": "基本形"}], "register": "中立（普通体の書き言葉）", "sense_fingerprint": "人が座るために決められた場所、座席", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: ゆずっ (Zipf 2.48)']::text[], '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "席", "is_correct": true, "explanation": "「窓辺の席」は窓際で座る場所を指し、「席につき」と合う。他の選択肢は入らない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓辺の窓」は意味が重なり、「につき」とも続かない。"}, {"text": "壁", "is_correct": false, "explanation": "「窓辺の壁につき」は座る動作と結びつかない。"}, {"text": "筆", "is_correct": false, "explanation": "筆は座る場所ではないので、「窓辺の筆につき」は不自然。"}], "explanations": {"席": "「窓辺の席」は窓際で座る場所を指し、「席につき」と合う。他の選択肢は入らない。", "窓": "「窓辺の窓」は意味が重なり、「につき」とも続かない。", "壁": "「窓辺の壁につき」は座る動作と結びつかない。", "筆": "筆は座る場所ではないので、「窓辺の筆につき」は不自然。"}, "sentence_index": 0, "correct_answer": "席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家具店で、店員が新しい席を組み立てた。", "explanation": "ここは〈椅子〉の意味。組み立てるのは物としての椅子で、すわる場所の〈席〉とは言わない。"}, {"text": "探していた本は、本棚のいつもの席にあった。", "explanation": "ここは〈場所〉の意味。席は人が座るための場所に使うので、本棚の位置には言わない。"}, {"text": "この席は扉が一つ外れていて、中の本がこぼれそうだ。", "explanation": "ここは〈棚〉の意味。扉の付いた収納を指すので、座る場所の〈席〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "席", "is_correct": true, "explanation": "「窓側の席」は窓際の座る場所を指し、「のほうが景色がよく見える」と合う。"}, {"text": "翼", "is_correct": false, "explanation": "翼は座る場所ではないので、「窓側の翼」は不自然。"}, {"text": "機体", "is_correct": false, "explanation": "機体は乗り物の本体で、座るところを指さない。"}, {"text": "荷物", "is_correct": false, "explanation": "荷物は座る場所ではなく、「窓側の荷物」は意味が通らない。"}], "explanations": {"席": "「窓側の席」は窓際の座る場所を指し、「のほうが景色がよく見える」と合う。", "翼": "翼は座る場所ではないので、「窓側の翼」は不自然。", "機体": "機体は乗り物の本体で、座るところを指さない。", "荷物": "荷物は座る場所ではなく、「窓側の荷物」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅館の部屋で、大きな席にシーツを広げた。", "explanation": "ここは〈寝台〉の意味。シーツを広げて眠る場所は寝台のことで、すわる場所の〈席〉とは言わない。"}, {"text": "この部屋は天井が高く、広い席だ。", "explanation": "ここは〈空間〉の意味。席は人が座る場所なので、部屋全体の広さには使わない。"}, {"text": "この機械は、ボタンの席を少し変えるだけで動きが変わる。", "explanation": "ここは〈位置〉の意味。ボタンの配置を指すので、人が座る場所の〈席〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅で席を空いたので、私は座った。", "corrected_sentence": "駅で席が空いたので、私は座った。", "error_description": "誤: 席を空いた / 正: 席が空いた。「空く」は自動詞なので、主語に「が」を使う。「席を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35029, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は空いた席が座り、本を開いた。", "corrected_sentence": "彼女は空いた席に座り、本を開いた。", "error_description": "誤: 席が座り / 正: 席に座り。座る場所は「に」で示す。「席が座る」は席を主語にできず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
