INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35030, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "作る対象を示す「を」。「動物を作らない」の目的語にあたり、ここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、作る対象を示せないので不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」だが、「動物で作らない」は動物を手段とする意味になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準の「より」で、「動物より作らない」は意味が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "作る対象を示す「を」。「動物を作らない」の目的語にあたり、ここに入る。", "へ": "方向を表す「へ」で、作る対象を示せないので不自然。", "で": "手段を表す「で」だが、「動物で作らない」は動物を手段とする意味になり不自然。", "より": "比較の基準の「より」で、「動物より作らない」は意味が成り立たない。"}, "error_tags": {"へ": "方向", "で": "手段・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35030, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "てや どうぐ などを つくる こと。", "primary_collocate": null, "pronunciation": "つくる", "ipa": "tsɯkɯɾɯ", "syllable_count": 3, "sentences": [{"text": "父は木を使って、子どもの机を作る。", "target_word": "作る", "complexity_tier": "T3", "furigana": "父[ちち]は木[き]を使[つか]って、子[こ]どもの机[つくえ]を作[つく]る。", "sentence_source": "generated"}, {"text": "店で売っていないので、兄は道具箱を自分で作った。", "target_word": "作った", "complexity_tier": "T3", "furigana": "店[みせ]で売[う]っていないので、兄[あに]は道具箱[どうぐばこ]を自分[じぶん]で作[つく]った。", "sentence_source": "generated"}, {"text": "毎年、祖母は私にセーターを作ってくれる。", "target_word": "作って", "complexity_tier": "T3", "furigana": "毎年[まいとし]、祖母[そぼ]は私[わたし]にセーターを作[つく]ってくれる。", "sentence_source": "generated"}, {"text": "紙で小さな箱を作りました。", "target_word": "作りました", "complexity_tier": "T3", "furigana": "紙[かみ]で小[ちい]さな箱[はこ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "工作の時間に、友だちと木の船を作ります。", "target_word": "作ります", "complexity_tier": "T3", "furigana": "工作[こうさく]の時間[じかん]に、友[とも]だちと木[き]の船[ふね]を作[つく]ります。", "sentence_source": "generated"}, {"text": "材料がそろったので、すぐに本棚を作ろう。", "target_word": "作ろう", "complexity_tier": "T3", "furigana": "材料[ざいりょう]がそろったので、すぐに本棚[ほんだな]を作[つく]ろう。", "sentence_source": "generated"}, {"text": "この椅子は職人が一つずつ手で作っています。", "target_word": "作って", "complexity_tier": "T3", "furigana": "この椅子[いす]は職人[しょくにん]が一[ひと]つずつ手[て]で作[つく]っています。", "sentence_source": "generated"}, {"text": "粘土で動物を作らないと、宿題が終わりません。", "target_word": "作らない", "complexity_tier": "T3", "furigana": "粘土[ねんど]で動物[どうぶつ]を作[つく]らないと、宿題[しゅくだい]が終[お]わりません。", "sentence_source": "generated"}, {"text": "母は古い布で上手にかばんを作れる。", "target_word": "作れる", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]い布[ぬの]で上手[じょうず]にかばんを作[つく]れる。", "sentence_source": "generated"}, {"text": "雨の日は家で紙の飛行機を作って遊んだ。", "target_word": "作って", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は家[いえ]で紙[かみ]の飛行機[ひこうき]を作[つく]って遊[あそ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作る", "label": "終止形"}, {"form": "作ります", "label": "丁寧形"}, {"form": "作った", "label": "過去形"}, {"form": "作って", "label": "て形"}, {"form": "作らない", "label": "否定形"}, {"form": "作れる", "label": "可能形"}, {"form": "作ろう", "label": "意志形"}, {"form": "作れば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "手や道具を使って物を形にして作り出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35030, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作る", "is_correct": true, "explanation": "辞書形で文末に入り、「子どもの机を作る」と動作を述べて文を完結させる。"}, {"text": "作って", "is_correct": false, "explanation": "て形は文を続ける形で、文末に置くと「作って。」となり文が完結しない。"}, {"text": "作れば", "is_correct": false, "explanation": "仮定形は「〜ば」の後件が必要で、この位置で文を終えることはできない。"}, {"text": "作ろうと", "is_correct": false, "explanation": "「〜しようと」の途中の形で、文を完結させられない。"}], "explanations": {"作る": "辞書形で文末に入り、「子どもの机を作る」と動作を述べて文を完結させる。", "作って": "て形は文を続ける形で、文末に置くと「作って。」となり文が完結しない。", "作れば": "仮定形は「〜ば」の後件が必要で、この位置で文を終えることはできない。", "作ろうと": "「〜しようと」の途中の形で、文を完結させられない。"}, "sentence_index": 0, "correct_answer": "作る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合に負けて、選手たちは悔しさの涙を作った。", "explanation": "ここは〈流す〉の意味。涙は流すもので、〈作る〉とは言わないので誤り。"}, {"text": "風邪をひいた父は、夜中に高い熱を作った。", "explanation": "ここは〈出す〉の意味。熱は出すものであり、〈作る〉とは言わないので誤り。"}, {"text": "会議で、彼は強い反対を作った。", "explanation": "ここは〈唱える・示す〉の意味。反対は唱えるもので、〈作る〉とは言わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35030, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作って", "is_correct": true, "explanation": "て形で、進行を表す「ています」に続く。「作っています」の前半にあたる。"}, {"text": "作る", "is_correct": false, "explanation": "辞書形は「ています」に直接続かず、「作るています」となって不自然。"}, {"text": "作った", "is_correct": false, "explanation": "過去形は「作ったています」となり、進行の形にならない。"}, {"text": "作らない", "is_correct": false, "explanation": "否定形は「ています」に続かず、「作らないています」となって成り立たない。"}], "explanations": {"作って": "て形で、進行を表す「ています」に続く。「作っています」の前半にあたる。", "作る": "辞書形は「ています」に直接続かず、「作るています」となって不自然。", "作った": "過去形は「作ったています」となり、進行の形にならない。", "作らない": "否定形は「ています」に続かず、「作らないています」となって成り立たない。"}, "sentence_index": 6, "correct_answer": "作って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議が終わると、彼は大きな拍手を作った。", "explanation": "ここは〈送る〉の意味。拍手は送るもので、〈作る〉とは言わないので誤り。"}, {"text": "私たちは昨日、新年を作って家族と過ごした。", "explanation": "ここは〈迎える〉の意味。新年は迎えるもので、〈作る〉とは言わないので誤り。"}, {"text": "昔は遠くの親戚に電報を作るしかなかった。", "explanation": "ここは〈打つ（送る）〉の意味。電報は作るのではなく打つものなので、〈作る〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35030, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は夏休みに、孫のために小さな船に作った。", "corrected_sentence": "祖父は夏休みに、孫のために小さな船を作った。", "error_description": "「作る」は作る対象を「を」で示すので「船に」は誤り。正しくは「船を作った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "作った", "is_correct": true, "explanation": "過去形で、「自分で作った」と既に行われた事柄を述べるので文脈に合う。"}, {"text": "作って", "is_correct": false, "explanation": "て形は文を続ける形で、ここでは文末にならず不完全になる。"}, {"text": "作れば", "is_correct": false, "explanation": "仮定形は後件が必要で、「売っていないので」の流れでは文を終えられない。"}, {"text": "作られた", "is_correct": false, "explanation": "受身の「作られた」は「兄は道具箱を自分で作られた」となり、「道具箱を」と両立せず不自然。"}], "correct_form": "作った", "base_form": "作る", "form_label": "過去形", "sentence_index": 1, "explanations": {"作った": "過去形で、「自分で作った」と既に行われた事柄を述べるので文脈に合う。", "作って": "て形は文を続ける形で、ここでは文末にならず不完全になる。", "作れば": "仮定形は後件が必要で、「売っていないので」の流れでは文を終えられない。", "作られた": "受身の「作られた」は「兄は道具箱を自分で作られた」となり、「道具箱を」と両立せず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35030, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は休日になると、庭で木の椅子を作りていた。", "corrected_sentence": "祖父は休日になると、庭で木の椅子を作っていた。", "error_description": "「作る」のて形は「作って」で、「作りて」は連用形に「て」を付けた誤り。正しくは「作っていた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "作らない", "is_correct": true, "explanation": "否定形で、「作らないと」の形で「作らなければ」の条件を表す。"}, {"text": "作らなかった", "is_correct": false, "explanation": "過去の否定は「〜なかったと」の条件として不自然で、現在の条件節に合わない。"}, {"text": "作らせ", "is_correct": false, "explanation": "使役の連用形「作らせ」は「〜と」に続かず、条件節として成立しない。"}, {"text": "作れ", "is_correct": false, "explanation": "命令形は文を終える形で、「〜と」の条件節にはならない。"}], "correct_form": "作らない", "base_form": "作る", "form_label": "否定形", "sentence_index": 7, "explanations": {"作らない": "否定形で、「作らないと」の形で「作らなければ」の条件を表す。", "作らなかった": "過去の否定は「〜なかったと」の条件として不自然で、現在の条件節に合わない。", "作らせ": "使役の連用形「作らせ」は「〜と」に続かず、条件節として成立しない。", "作れ": "命令形は文を終える形で、「〜と」の条件節にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "結果を表す「に」。「大きな問題に成った」で変化の結果を示し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「成る」は目的語を取らないので、「問題を成った」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」だが、「問題で成った」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞を修飾するもので、「問題の成った」は文として成立しない。"}], "correct_answer": "に", "explanations": {"に": "結果を表す「に」。「大きな問題に成った」で変化の結果を示し、ここに入る。", "を": "「成る」は目的語を取らないので、「問題を成った」は成立しない。", "で": "場所・手段の「で」だが、「問題で成った」は不自然。", "の": "連体の「の」は名詞を修飾するもので、「問題の成った」は文として成立しない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "結果を表す「に」。「夜に成ってしまった」で、夜という結果への変化を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だが、「夜が成ってしまった」は「〜に成る」の構文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「夜へ成る」は変化の結果を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、「夜から成る」は結果の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "結果を表す「に」。「夜に成ってしまった」で、夜という結果への変化を示す。", "が": "主語の「が」だが、「夜が成ってしまった」は「〜に成る」の構文に合わない。", "へ": "方向の「へ」で、「夜へ成る」は変化の結果を表せない。", "から": "起点の「から」で、「夜から成る」は結果の意味にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "できごとが、そうなる。", "primary_collocate": null, "pronunciation": "なる", "ipa": "naɾɯ", "syllable_count": 2, "sentences": [{"text": "長い話し合いの末、ようやく合意に成った。", "target_word": "成った", "complexity_tier": "T3", "furigana": "長[なが]い話[はな]し合[あ]いの末[すえ]、ようやく合意[ごうい]に成[な]った。", "sentence_source": "generated"}, {"text": "小さな嘘がきっかけで、大きな問題に成った。", "target_word": "成った", "complexity_tier": "T3", "furigana": "小[ちい]さな嘘[うそ]がきっかけで、大[おお]きな問題[もんだい]に成[な]った。", "sentence_source": "generated"}, {"text": "練習を重ねた結果、夢が現実に成った。", "target_word": "成った", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を重[かさ]ねた結果[けっか]、夢[ゆめ]が現実[げんじつ]に成[な]った。", "sentence_source": "generated"}, {"text": "雨が雪に成る季節が近づいている。", "target_word": "成る", "complexity_tier": "T3", "furigana": "雨[あめ]が雪[ゆき]に成[な]る季節[きせつ]が近[ちか]づいている。", "sentence_source": "generated"}, {"text": "計画が実を結び、町は観光地に成った。", "target_word": "成った", "complexity_tier": "T3", "furigana": "計画[けいかく]が実[み]を結[むす]び、町[まち]は観光地[かんこうち]に成[な]った。", "sentence_source": "generated"}, {"text": "試合は最後まで決まらず、引き分けに成った。", "target_word": "成った", "complexity_tier": "T3", "furigana": "試合[しあい]は最後[さいご]まで決[き]まらず、引[ひ]き分[わ]けに成[な]った。", "sentence_source": "generated"}, {"text": "春に成ると、公園に花が咲く。", "target_word": "成る", "complexity_tier": "T3", "furigana": "春[はる]に成[な]ると、公園[こうえん]に花[はな]が咲[さ]く。", "sentence_source": "generated"}, {"text": "話が長引いて、結局夜に成ってしまった。", "target_word": "成って", "complexity_tier": "T3", "furigana": "話[はなし]が長引[ながび]いて、結局[けっきょく]夜[よる]に成[な]ってしまった。", "sentence_source": "generated"}, {"text": "失敗が続いたので、会社は大変な状況に成っている。", "target_word": "成って", "complexity_tier": "T3", "furigana": "失敗[しっぱい]が続[つづ]いたので、会社[かいしゃ]は大変[たいへん]な状況[じょうきょう]に成[な]っている。", "sentence_source": "generated"}, {"text": "対策が遅れれば、被害はさらに大きく成る。", "target_word": "成る", "complexity_tier": "T3", "furigana": "対策[たいさく]が遅[おく]れれば、被害[ひがい]はさらに大[おお]きく成[な]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成る", "label": "終止形"}, {"form": "成ります", "label": "丁寧形"}, {"form": "成った", "label": "過去形"}, {"form": "成って", "label": "て形"}, {"form": "成らない", "label": "否定形"}, {"form": "成れば", "label": "仮定形"}], "register": "書き言葉", "sense_fingerprint": "物事や状況がある結果や状態に至る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成った", "is_correct": true, "explanation": "過去形で、話し合いの末に合意が生じたという既に起きた事柄を述べる。"}, {"text": "成って", "is_correct": false, "explanation": "て形は文を続ける形で、ここでは文が終わらない。"}, {"text": "成れば", "is_correct": false, "explanation": "仮定形は後件が必要で、文末には置けない。"}, {"text": "成ろうと", "is_correct": false, "explanation": "「〜しようと」の途中の形で、文を完結させられない。"}], "explanations": {"成った": "過去形で、話し合いの末に合意が生じたという既に起きた事柄を述べる。", "成って": "て形は文を続ける形で、ここでは文が終わらない。", "成れば": "仮定形は後件が必要で、文末には置けない。", "成ろうと": "「〜しようと」の途中の形で、文を完結させられない。"}, "sentence_index": 0, "correct_answer": "成った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月、私たちの家に赤ちゃんが成る予定だ。", "explanation": "ここは〈生まれる〉の意味。人の誕生には〈成る〉を使わないので不自然。"}, {"text": "この一年で、町の人口がずいぶん成った。", "explanation": "ここは〈増える〉の意味。人口の増加は〈成る〉ではなく〈増える〉で表すので誤り。"}, {"text": "登山隊はついに、標高三千メートルの頂上に成った。", "explanation": "ここは〈達する〉の意味。場所への到達には〈成る〉ではなく〈達する〉を使うので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成る", "is_correct": true, "explanation": "辞書形で「成ると」の条件を作り、春になるとという一般論を述べる。"}, {"text": "成れ", "is_correct": false, "explanation": "命令形は「〜と」の条件節に続かず、文として成立しない。"}, {"text": "成ります", "is_correct": false, "explanation": "丁寧形は「成りますと」と続きにくく、普通体の一般論の文に合わない。"}, {"text": "成りそう", "is_correct": false, "explanation": "様子を表す形で、「成りそうと」は一般論の条件として続かない。"}], "explanations": {"成る": "辞書形で「成ると」の条件を作り、春になるとという一般論を述べる。", "成れ": "命令形は「〜と」の条件節に続かず、文として成立しない。", "成ります": "丁寧形は「成りますと」と続きにくく、普通体の一般論の文に合わない。", "成りそう": "様子を表す形で、「成りそうと」は一般論の条件として続かない。"}, "sentence_index": 6, "correct_answer": "成る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、駅前で大きな事件が成った。", "explanation": "ここは〈起きる・発生する〉の意味。事件は起きるもので、〈成る〉とは言わないので誤り。"}, {"text": "午後二時に、会議が成った。", "explanation": "ここは〈始まる〉の意味。会議は始まるもので、〈成る〉では表せない。"}, {"text": "タンクの燃料が少しずつ成っていった。", "explanation": "ここは〈減る〉の意味。量が減っていく場合に〈成る〉は使わず、〈減る〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さな変化が積み重なって、大きな流れを成った。", "corrected_sentence": "小さな変化が積み重なって、大きな流れに成った。", "error_description": "「成る」は結果を「〜に成る」で示すので、「流れを」の「を」は誤り。正しくは「流れに成った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "成った", "is_correct": true, "explanation": "過去形で、「大きな問題に成った」と既に起きた結果を述べるので文脈に合う。"}, {"text": "成って", "is_correct": false, "explanation": "て形は文を続ける形で、ここでは文末にならず不完全になる。"}, {"text": "成れば", "is_correct": false, "explanation": "仮定形は後件が必要で、「きっかけで」の流れでは文を終えられない。"}, {"text": "成ろう", "is_correct": false, "explanation": "意志形は未来の意向を表し、既に起きた結果を述べる文脈に合わない。"}], "correct_form": "成った", "base_form": "成る", "form_label": "過去形", "sentence_index": 1, "explanations": {"成った": "過去形で、「大きな問題に成った」と既に起きた結果を述べるので文脈に合う。", "成って": "て形は文を続ける形で、ここでは文末にならず不完全になる。", "成れば": "仮定形は後件が必要で、「きっかけで」の流れでは文を終えられない。", "成ろう": "意志形は未来の意向を表し、既に起きた結果を述べる文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35032, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ようやく暖かい季節に成りてきた。", "corrected_sentence": "ようやく暖かい季節に成ってきた。", "error_description": "「成る」のて形は「成って」で、「成りて」は連用形に「て」を付けた誤り。正しくは「成ってきた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "成って", "is_correct": true, "explanation": "て形で「成ってしまった」に続き、完了して残った結果を表す。"}, {"text": "成った", "is_correct": false, "explanation": "「成ったしまった」となり、「〜てしまう」の形にならない。"}, {"text": "成る", "is_correct": false, "explanation": "辞書形は「成るてしまった」となり、後ろの「てしまった」に続かない。"}, {"text": "成ります", "is_correct": false, "explanation": "丁寧形は「成りますてしまった」となり、接続しない。"}], "correct_form": "成って", "base_form": "成る", "form_label": "て形", "sentence_index": 7, "explanations": {"成って": "て形で「成ってしまった」に続き、完了して残った結果を表す。", "成った": "「成ったしまった」となり、「〜てしまう」の形にならない。", "成る": "辞書形は「成るてしまった」となり、後ろの「てしまった」に続かない。", "成ります": "丁寧形は「成りますてしまった」となり、接続しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「日本人の多く」を主題として示す「は」。後ろで「毎朝ご飯を食べる」と続く。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示す。「日本人の多くに、毎朝ご飯を食べる」では主語が立たず意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「多くで毎朝ご飯を食べる」では意味がつながらない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「多くから」では起点の意味が合わず、主語も示せない。"}], "correct_answer": "は", "explanations": {"は": "「日本人の多く」を主題として示す「は」。後ろで「毎朝ご飯を食べる」と続く。", "に": "「に」は相手や位置を示す。「日本人の多くに、毎朝ご飯を食べる」では主語が立たず意味が通らない。", "で": "「で」は手段や場所を示す。「多くで毎朝ご飯を食べる」では意味がつながらない。", "から": "「から」は起点を示す。「多くから」では起点の意味が合わず、主語も示せない。"}, "error_tags": {"に": "dative", "で": "means", "から": "source"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少ない", "is_correct": true, "explanation": "「多い」の対義語で、数量が小さいことを表す。「多く」の対義語として辞書に並ぶ語。"}, {"text": "大きい", "is_correct": false, "explanation": "「大きい」は大きさを表す語で、「多い」の対義語ではない。"}, {"text": "高い", "is_correct": false, "explanation": "「高い」は高さや値段を表す語で、数量の対義語にはならない。"}, {"text": "重い", "is_correct": false, "explanation": "「重い」は重さを表す語で、数量の多い・少ないの対義語ではない。"}], "correct_answer": "少ない", "explanations": {"少ない": "「多い」の対義語で、数量が小さいことを表す。「多く」の対義語として辞書に並ぶ語。", "大きい": "「大きい」は大きさを表す語で、「多い」の対義語ではない。", "高い": "「高い」は高さや値段を表す語で、数量の対義語にはならない。", "重い": "「重い」は重さを表す語で、数量の多い・少ないの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この店の野菜の多く」を主題として示す「は」。後ろで「届く」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「多くを届く」では届く対象が合わず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「多くへ届く」では意味が通らず、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「多くより届く」は比較の相手がなく、意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「この店の野菜の多く」を主題として示す「は」。後ろで「届く」と続く。", "を": "「を」は目的語を示す。「多くを届く」では届く対象が合わず、文が成り立たない。", "へ": "「へ」は方向を示す。「多くへ届く」では意味が通らず、不自然になる。", "より": "「より」は比較を示す。「多くより届く」は比較の相手がなく、意味が通らない。"}, "error_tags": {"を": "object", "へ": "direction", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少ない", "is_correct": true, "explanation": "「多い」の対義語で、数量が小さいことを表す。「多く」の対義語として辞書に並ぶ語。"}, {"text": "早い", "is_correct": false, "explanation": "「早い」は時間や速さを表す語で、数量の対義語ではない。"}, {"text": "遠い", "is_correct": false, "explanation": "「遠い」は距離を表す語で、数量の多い・少ないとは対になっていない。"}, {"text": "明るい", "is_correct": false, "explanation": "「明るい」は光の強さや性格を表す語で、数量の対義語にはならない。"}], "correct_answer": "少ない", "explanations": {"少ない": "「多い」の対義語で、数量が小さいことを表す。「多く」の対義語として辞書に並ぶ語。", "早い": "「早い」は時間や速さを表す語で、数量の対義語ではない。", "遠い": "「遠い」は距離を表す語で、数量の多い・少ないとは対になっていない。", "明るい": "「明るい」は光の強さや性格を表す語で、数量の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数量や程度が大きいこと。たくさん。", "primary_collocate": null, "pronunciation": "おおく", "ipa": "oːkɯ", "syllable_count": 3, "sentences": [{"text": "彼は多くを語らないが、いつも優しい人だ。", "target_word": "多く", "complexity_tier": "T3", "furigana": "彼[かれ]は多[おお]くを語[かた]らないが、いつも優[やさ]しい人[ひと]だ。", "sentence_source": "generated"}, {"text": "日本人の多くは、毎朝ご飯を食べる。", "target_word": "多く", "complexity_tier": "T3", "furigana": "日本人[にほんじん]の多[おお]くは、毎朝[まいあさ]ご飯[はん]を食[た]べる。", "sentence_source": "generated"}, {"text": "この町の店の多くは、夜八時に閉まる。", "target_word": "多く", "complexity_tier": "T3", "furigana": "この町[まち]の店[みせ]の多[おお]くは、夜[よる]八時[はちじ]に閉[し]まる。", "sentence_source": "generated"}, {"text": "私は多くを望まない。毎日元気ならそれで十分だ。", "target_word": "多く", "complexity_tier": "T3", "furigana": "私[わたし]は多[おお]くを望[のぞ]まない。毎日[まいにち]元気[げんき]ならそれで十分[じゅうぶん]だ。", "sentence_source": "generated"}, {"text": "クラスの多くは、サッカーよりも野球が好きだ。", "target_word": "多く", "complexity_tier": "T3", "furigana": "クラスの多[おお]くは、サッカーよりも野球[やきゅう]が好[す]きだ。", "sentence_source": "generated"}, {"text": "会議で出た意見の多くは、費用に関するものだった。", "target_word": "多く", "complexity_tier": "T3", "furigana": "会議[かいぎ]で出[で]た意見[いけん]の多[おお]くは、費用[ひよう]に関[かん]するものだった。", "sentence_source": "generated"}, {"text": "生徒の多くが、その問題を正しく解けた。", "target_word": "多く", "complexity_tier": "T3", "furigana": "生徒[せいと]の多[おお]くが、その問題[もんだい]を正[ただ]しく解[と]けた。", "sentence_source": "generated"}, {"text": "この店の野菜の多くは、近くの農家から届く。", "target_word": "多く", "complexity_tier": "T3", "furigana": "この店[みせ]の野菜[やさい]の多[おお]くは、近[ちか]くの農家[のうか]から届[とど]く。", "sentence_source": "generated"}, {"text": "彼女は人生の多くを旅に使った。", "target_word": "多く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は人生[じんせい]の多[おお]くを旅[たび]に使[つか]った。", "sentence_source": "generated"}, {"text": "彼の作品の多くは、小さな町が舞台だ。", "target_word": "多く", "complexity_tier": "T3", "furigana": "彼[かれ]の作品[さくひん]の多[おお]くは、小[ちい]さな町[まち]が舞台[ぶたい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多く", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "全体のうちの大きな部分、または程度や量が大きいこと（「多くは」「多くを」の形）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多く", "is_correct": true, "explanation": "「多くを語らない」の形で、数量が大きい意味の「多く」が入る。"}, {"text": "深く", "is_correct": false, "explanation": "「深く」は副詞で、「を」の目的語にならない。「深くを語らない」では文が成り立たない。"}, {"text": "早く", "is_correct": false, "explanation": "「早く」は時間や速さを表す副詞。「早くを語らない」とは続かず、ここには入らない。"}, {"text": "広く", "is_correct": false, "explanation": "「広く」は範囲が大きいことを表す副詞。「を」と結びつかず、空欄に入らない。"}], "explanations": {"多く": "「多くを語らない」の形で、数量が大きい意味の「多く」が入る。", "深く": "「深く」は副詞で、「を」の目的語にならない。「深くを語らない」では文が成り立たない。", "早く": "「早く」は時間や速さを表す副詞。「早くを語らない」とは続かず、ここには入らない。", "広く": "「広く」は範囲が大きいことを表す副詞。「を」と結びつかず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "多く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は効き目が多く、すぐに頭痛が治った。", "explanation": "ここは「強い」（効き目の力が大きいこと）の意味。「多く」は数量の大きさを表すので、効き目の強さには使えない。"}, {"text": "この鉄は硬さが多く、曲げにくい。", "explanation": "ここは「硬い」（かたさの程度が大きいこと）の意味。「多く」は数の大きさを表すので、かたさの程度には使えない。"}, {"text": "この車は速さが多く、事故が心配だ。", "explanation": "ここは「速い」（速度が大きいこと）の意味。「多く」は数量の大きさを表すので、速さの程度には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多く", "is_correct": true, "explanation": "「生徒の多くが」の主語として、大部分の生徒という意味で入る。"}, {"text": "多い", "is_correct": false, "explanation": "形容詞「多い」は名詞の働きをせず、「生徒の多いが」とは続かない。"}, {"text": "強く", "is_correct": false, "explanation": "「強く」は副詞で、「生徒の強くが」と名詞の位置には入らない。"}, {"text": "細かく", "is_correct": false, "explanation": "「細かく」は副詞で、主語の位置に入る名詞の形にならないので合わない。"}], "explanations": {"多く": "「生徒の多くが」の主語として、大部分の生徒という意味で入る。", "多い": "形容詞「多い」は名詞の働きをせず、「生徒の多いが」とは続かない。", "強く": "「強く」は副詞で、「生徒の強くが」と名詞の位置には入らない。", "細かく": "「細かく」は副詞で、主語の位置に入る名詞の形にならないので合わない。"}, "sentence_index": 6, "correct_answer": "多く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この家の多くの窓は、ひとつしかない。", "explanation": "「多くの窓」と「ひとつしかない」が矛盾している。「多く」は数量の大きさを表すので、数の少なさとは結びつかない。"}, {"text": "彼の声は多くて、教室の後ろまで届く。", "explanation": "ここは「大きい」（音量が大きいこと）の意味。「多く」は数量の大きさを表すので、声の大きさには使えない。"}, {"text": "今年の夏は気温が多く、毎日暑い。", "explanation": "ここは「高い」（温度が大きいこと）の意味。「多く」は数量の大きさを表すので、気温の高さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "クラスの多くを、毎日宿題をやっている。", "corrected_sentence": "クラスの多くは、毎日宿題をやっている。", "error_description": "「多く」の直後の「を」が誤り。主題を示す「は」が正しく、「を」にすると目的語となり、文の主語が立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35037, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その学校の生徒の多くに、部活に入っている。", "corrected_sentence": "その学校の生徒の多くは、部活に入っている。", "error_description": "「多く」の後ろの「に」が誤り。「に」は相手や場所を示し、主題を立てる働きはない。正しくは主題を示す「は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "可能の対象を示す「が」。「結ぶことが出来ない」の形で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「ことを出来ない」は可能の対象の示し方として誤り。"}, {"text": "に", "is_correct": false, "explanation": "「ことに出来ない」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「ことへ出来ない」は不自然。"}], "correct_answer": "が", "explanations": {"が": "可能の対象を示す「が」。「結ぶことが出来ない」の形で、ここに入る。", "を": "「ことを出来ない」は可能の対象の示し方として誤り。", "に": "「ことに出来ない」は意味が通らない。", "へ": "方向を表す「へ」で、「ことへ出来ない」は不自然。"}, "error_tags": {"を": "目的語", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分の力や条件によって、そのことを行うことがかなう。", "primary_collocate": null, "pronunciation": "できる", "ipa": "dekiɾɯ", "syllable_count": 3, "sentences": [{"text": "私は一人で自転車に乗ることが出来る。", "target_word": "出来る", "complexity_tier": "T3", "furigana": "私[わたし]は一人[ひとり]で自転車[じてんしゃ]に乗[の]ることが出来[でき]る。", "sentence_source": "generated"}, {"text": "弟はまだ小さいので、靴ひもを結ぶことが出来ない。", "target_word": "出来ない", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ小[ちい]さいので、靴[くつ]ひもを結[むす]ぶことが出来[でき]ない。", "sentence_source": "generated"}, {"text": "姉は英語で電話の応対が出来ます。", "target_word": "出来ます", "complexity_tier": "T3", "furigana": "姉[あね]は英語[えいご]で電話[でんわ]の応対[おうたい]が出来[でき]ます。", "sentence_source": "generated"}, {"text": "先生が教えてくれたので、難しい問題も自分で解くことが出来た。", "target_word": "出来た", "complexity_tier": "T3", "furigana": "先生[せんせい]が教[おし]えてくれたので、難[むずか]しい問題[もんだい]も自分[じぶん]で解[と]くことが出来[でき]た。", "sentence_source": "generated"}, {"text": "毎日練習したので、速く泳ぐことが出来るようになった。", "target_word": "出来る", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したので、速[はや]く泳[およ]ぐことが出来[でき]るようになった。", "sentence_source": "generated"}, {"text": "足をけがして、今日は走ることが出来ません。", "target_word": "出来ません", "complexity_tier": "T3", "furigana": "足[あし]をけがして、今日[きょう]は走[はし]ることが出来[でき]ません。", "sentence_source": "generated"}, {"text": "母は料理が上手で、どんな魚でもさばくことが出来る。", "target_word": "出来る", "complexity_tier": "T3", "furigana": "母[はは]は料理[りょうり]が上手[じょうず]で、どんな魚[さかな]でもさばくことが出来[でき]る。", "sentence_source": "generated"}, {"text": "目が悪いので、遠くの文字を読むことが出来ない。", "target_word": "出来ない", "complexity_tier": "T3", "furigana": "目[め]が悪[わる]いので、遠[とお]くの文字[もじ]を読[よ]むことが出来[でき]ない。", "sentence_source": "generated"}, {"text": "兄は自分で車を修理することが出来て、いつも助かる。", "target_word": "出来て", "complexity_tier": "T3", "furigana": "兄[あに]は自分[じぶん]で車[くるま]を修理[しゅうり]することが出来[でき]て、いつも助[たす]かる。", "sentence_source": "generated"}, {"text": "泳げない私も、ここなら安心して水に入ることが出来た。", "target_word": "出来た", "complexity_tier": "T3", "furigana": "泳[およ]げない私[わたし]も、ここなら安心[あんしん]して水[みず]に入[はい]ることが出来[でき]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出来る", "label": "終止形"}, {"form": "出来ます", "label": "丁寧形"}, {"form": "出来た", "label": "過去形"}, {"form": "出来て", "label": "て形"}, {"form": "出来ない", "label": "否定形"}, {"form": "出来れば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "自分の力や条件でそのことをすることができる（可能）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: けがし (Zipf 2.18)']::text[], 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出来る", "is_correct": true, "explanation": "辞書形で文末に入り、「乗ることが出来る」と可能を述べて文を完結させる。"}, {"text": "出来て", "is_correct": false, "explanation": "て形は文を続ける形で、「乗ることが出来て。」は不完全になる。"}, {"text": "出来れば", "is_correct": false, "explanation": "仮定形は後件が必要で、この位置では文を終えられない。"}, {"text": "出来ず", "is_correct": false, "explanation": "否定の連用形で文を続ける形のため、ここでは文が終わらない。"}], "explanations": {"出来る": "辞書形で文末に入り、「乗ることが出来る」と可能を述べて文を完結させる。", "出来て": "て形は文を続ける形で、「乗ることが出来て。」は不完全になる。", "出来れば": "仮定形は後件が必要で、この位置では文を終えられない。", "出来ず": "否定の連用形で文を続ける形のため、ここでは文が終わらない。"}, "sentence_index": 0, "correct_answer": "出来る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の午後は、雨が降ることが出来るそうだ。", "explanation": "ここは〈可能性がある〉の意味。雨は人が「することができる」ものではないので、この語義には合わない。"}, {"text": "来週は、地震が起きることが出来ると言われている。", "explanation": "ここは〈起こりうる〉の意味。地震は人の能力の話ではないので、可能の〈出来る〉は使えない。"}, {"text": "妻に、待望の子どもが生まれることが出来た。", "explanation": "ここは〈生まれる〉の意味。出産は自分で「できる」ことではなく、〈生まれる〉を使うので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出来る", "is_correct": true, "explanation": "辞書形で文末に入り、「さばくことが出来る」と可能を述べて文を完結させる。"}, {"text": "出来なく", "is_correct": false, "explanation": "途中の形で、文を終えられない。"}, {"text": "出来たら", "is_correct": false, "explanation": "条件の形で、「さばくことが出来たら」だけでは文が終わらない。"}, {"text": "出来ると", "is_correct": false, "explanation": "条件・引用の形で、文末には置けず不完全になる。"}], "explanations": {"出来る": "辞書形で文末に入り、「さばくことが出来る」と可能を述べて文を完結させる。", "出来なく": "途中の形で、文を終えられない。", "出来たら": "条件の形で、「さばくことが出来たら」だけでは文が終わらない。", "出来ると": "条件・引用の形で、文末には置けず不完全になる。"}, "sentence_index": 6, "correct_answer": "出来る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この靴は一生出来る。", "explanation": "ここは〈もつ〉の意味。靴の耐久性には〈もつ〉を使い、〈出来る〉は合わないので誤り。"}, {"text": "夕方に家へ帰ると、部屋の電気が出来ていた。", "explanation": "ここは〈点く〉の意味。電気は点くもので、〈出来る〉とは言わないので誤り。"}, {"text": "昨夜は寒くて、一晩中、暖房が出来ていた。", "explanation": "ここは〈効く〉の意味。暖房には〈効く〉を使い、〈出来る〉は合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は一人で大きな箱を運ぶことを出来る。", "corrected_sentence": "彼女は一人で大きな箱を運ぶことが出来る。", "error_description": "可能の「出来る」は「〜ことが」で対象を示すので、「ことを」は誤り。正しくは「運ぶことが出来る」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "出来ない", "is_correct": true, "explanation": "否定形で、「まだ小さいので」という状況に合い、できないことを述べる。"}, {"text": "出来る", "is_correct": false, "explanation": "辞書形の肯定では、「まだ小さいので」という状況説明と合わない。"}, {"text": "出来た", "is_correct": false, "explanation": "過去の肯定で、「まだ小さい」という現在の状況と合わない。"}, {"text": "出来ます", "is_correct": false, "explanation": "丁寧な肯定で、否定の文脈と合わない。"}], "correct_form": "出来ない", "base_form": "出来る", "form_label": "否定形", "sentence_index": 1, "explanations": {"出来ない": "否定形で、「まだ小さいので」という状況に合い、できないことを述べる。", "出来る": "辞書形の肯定では、「まだ小さいので」という状況説明と合わない。", "出来た": "過去の肯定で、「まだ小さい」という現在の状況と合わない。", "出来ます": "丁寧な肯定で、否定の文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35038, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今では速く走ることが出来だ。", "corrected_sentence": "今では速く走ることが出来た。", "error_description": "「出来る」の過去形は「出来た」で、「出来だ」は誤り。正しくは「出来た」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "出来ない", "is_correct": true, "explanation": "否定形で、「目が悪いので」という状況に合い、できないことを述べる。"}, {"text": "出来ず", "is_correct": false, "explanation": "連用形「出来ず」は文を続ける形で、ここでは文が終わらない。"}, {"text": "出来なく", "is_correct": false, "explanation": "途中の形で、文を終えることができない。"}, {"text": "出来なくて", "is_correct": false, "explanation": "て形で文を続ける形なので、ここでは文末にならない。"}], "correct_form": "出来ない", "base_form": "出来る", "form_label": "否定形", "sentence_index": 7, "explanations": {"出来ない": "否定形で、「目が悪いので」という状況に合い、できないことを述べる。", "出来ず": "連用形「出来ず」は文を続ける形で、ここでは文が終わらない。", "出来なく": "途中の形で、文を終えることができない。", "出来なくて": "て形で文を続ける形なので、ここでは文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "方向を表す「へ」。「遠くへ歩く」と行き先を示し、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "帰着点の「に」は「歩く」の行き先に合わず、「遠くに歩く」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を示すので、「遠くと歩く」は距離の意味として通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」になるが、「遠く」は主語にならないので不自然。"}], "correct_answer": "へ", "explanations": {"へ": "方向を表す「へ」。「遠くへ歩く」と行き先を示し、ここに入る。", "に": "帰着点の「に」は「歩く」の行き先に合わず、「遠くに歩く」は不自然。", "と": "共同の相手を示すので、「遠くと歩く」は距離の意味として通らない。", "が": "主語を示す「が」になるが、「遠く」は主語にならないので不自然。"}, "error_tags": {"に": "帰着点", "と": "共同", "が": "主語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近く", "is_correct": true, "explanation": "「遠く」の対義語で、距離が短い意味。石を投げた距離の反対にあたる。"}, {"text": "深く", "is_correct": false, "explanation": "深さを表すので、距離の反対にはならない。"}, {"text": "広く", "is_correct": false, "explanation": "広さを表すので、距離の反対にはならない。"}, {"text": "高く", "is_correct": false, "explanation": "高さを表すので、距離の反対にはならない。"}], "correct_answer": "近く", "explanations": {"近く": "「遠く」の対義語で、距離が短い意味。石を投げた距離の反対にあたる。", "深く": "深さを表すので、距離の反対にはならない。", "広く": "広さを表すので、距離の反対にはならない。", "高く": "高さを表すので、距離の反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "到達点を示す「まで」。「遠くまで聞こえた」と音が届く果てを表し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」になるが、「聞こえる」は対象を取らないので「遠くを聞こえた」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞を修飾するもので、「遠くの聞こえた」は文が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だが、「遠くが聞こえた」は「聞こえる」の主語に合わず不自然。"}], "correct_answer": "まで", "explanations": {"まで": "到達点を示す「まで」。「遠くまで聞こえた」と音が届く果てを表し、ここに入る。", "を": "目的語の「を」になるが、「聞こえる」は対象を取らないので「遠くを聞こえた」は不自然。", "の": "連体の「の」は名詞を修飾するもので、「遠くの聞こえた」は文が成立しない。", "が": "主語の「が」だが、「遠くが聞こえた」は「聞こえる」の主語に合わず不自然。"}, "error_tags": {"を": "目的語", "の": "連体", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近く", "is_correct": true, "explanation": "「遠く」の対義語で、「近くへ運ぶ」に対して距離が短い意味になる。"}, {"text": "早く", "is_correct": false, "explanation": "速さを表すので、距離の反対にはならない。"}, {"text": "多く", "is_correct": false, "explanation": "数量の多さを表すので、距離の反対にはならない。"}, {"text": "長く", "is_correct": false, "explanation": "時間や長さを表すので、距離の反対にはならない。"}], "correct_answer": "近く", "explanations": {"近く": "「遠く」の対義語で、「近くへ運ぶ」に対して距離が短い意味になる。", "早く": "速さを表すので、距離の反対にはならない。", "多く": "数量の多さを表すので、距離の反対にはならない。", "長く": "時間や長さを表すので、距離の反対にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "ながい きょりを あらわす ことば。", "primary_collocate": null, "pronunciation": "とおく", "ipa": "toːkɯ", "syllable_count": 3, "sentences": [{"text": "朝早く出発して、遠くまで自転車で走った。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "朝早[あさはや]く出発[しゅっぱつ]して、遠[とお]くまで自転車[じてんしゃ]で走[はし]った。", "sentence_source": "generated"}, {"text": "荷物が重いので、遠くへ歩くのは大変だ。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "荷物[にもつ]が重[おも]いので、遠[とお]くへ歩[ある]くのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "山の上に立つと、遠くまで見わたせる。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に立[た]つと、遠[とお]くまで見[み]わたせる。", "sentence_source": "generated"}, {"text": "弟は力が強いので、遠くまで石を投げられる。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "弟[おとうと]は力[ちから]が強[つよ]いので、遠[とお]くまで石[いし]を投[な]げられる。", "sentence_source": "generated"}, {"text": "大きな声を出せば、遠くまで届く。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]を出[だ]せば、遠[とお]くまで届[とど]く。", "sentence_source": "generated"}, {"text": "犬は耳がいいので、遠くの音もよく聞こえる。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "犬[いぬ]は耳[みみ]がいいので、遠[とお]くの音[おと]もよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "家から遠くまで来たので、帰りの電車が心配だ。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "家[いえ]から遠[とお]くまで来[き]たので、帰[かえ]りの電車[でんしゃ]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "花火の音は、町の遠くまで聞こえた。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "花火[はなび]の音[おと]は、町[まち]の遠[とお]くまで聞[き]こえた。", "sentence_source": "generated"}, {"text": "遠くまで行く日は、朝からおにぎりを持っていく。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くまで行[い]く日[ひ]は、朝[あさ]からおにぎりを持[も]っていく。", "sentence_source": "generated"}, {"text": "飛行機は一度に大勢の人を遠くへ運ぶことができる。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は一度[いちど]に大勢[おおぜい]の人[ひと]を遠[とお]くへ運[はこ]ぶことができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠く", "label": "基本形"}, {"form": "遠くの", "label": "連体修飾"}, {"form": "遠くまで", "label": "到達点を表す形"}], "register": "中立", "sense_fingerprint": "長い距離そのもの（遠くまで・遠くへ）を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遠く", "is_correct": true, "explanation": "副詞として「遠くまで」と距離の果てを表し、ここに入る。"}, {"text": "遠い", "is_correct": false, "explanation": "形容詞の「遠い」は「まで」に直接続かず、「遠いまで」は成り立たない。"}, {"text": "速く", "is_correct": false, "explanation": "速さを表すので、距離を表す「まで」の文脈には合わない。"}, {"text": "強く", "is_correct": false, "explanation": "力の強さを表すので、距離の文脈には合わない。"}], "explanations": {"遠く": "副詞として「遠くまで」と距離の果てを表し、ここに入る。", "遠い": "形容詞の「遠い」は「まで」に直接続かず、「遠いまで」は成り立たない。", "速く": "速さを表すので、距離を表す「まで」の文脈には合わない。", "強く": "力の強さを表すので、距離の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "遠く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの争いは、五十年も遠く続いた。", "explanation": "ここは〈長く〉の意味。時間の長さには〈遠く〉を使わず〈長く〉を使うので誤り。"}, {"text": "私は犬を遠く抱きしめた。", "explanation": "ここは〈強く〉の意味。抱きしめる力の強さには〈遠く〉を使わず〈強く〉を使うので誤り。"}, {"text": "彼は問題の答えを遠く考え続けた。", "explanation": "ここは〈深く〉の意味。考えの程度を表す〈深く〉を使い、〈遠く〉は場所や距離に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遠く", "is_correct": true, "explanation": "副詞として「家から遠くまで来た」と距離を表し、ここに入る。"}, {"text": "深く", "is_correct": false, "explanation": "深さを表すので、「家から深くまで来た」は距離の文脈に合わない。"}, {"text": "高く", "is_correct": false, "explanation": "高さを表すので、距離を表す「まで」の文脈には合わない。"}, {"text": "軽く", "is_correct": false, "explanation": "軽さを表すので、距離の文脈には合わない。"}], "explanations": {"遠く": "副詞として「家から遠くまで来た」と距離を表し、ここに入る。", "深く": "深さを表すので、「家から深くまで来た」は距離の文脈に合わない。", "高く": "高さを表すので、距離を表す「まで」の文脈には合わない。", "軽く": "軽さを表すので、距離の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "遠く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町の人口は隣町より遠く多い。", "explanation": "ここは〈はるかに〉の意味。〈遠く〉は場所の距離を表す副詞で、数量の差は〈はるかに〉で言うので誤り。"}, {"text": "彼は遠く有名な歌手になった。", "explanation": "ここは〈広く〉の意味。知名度の広がりには〈広く〉を使い、〈遠く〉は距離に使うので誤り。"}, {"text": "朝、遠く起きて勉強した。", "explanation": "ここは〈早く〉の意味。時刻の早さには〈遠く〉を使わず、〈早く〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高台に登ると、遠くが海が見える。", "corrected_sentence": "高台に登ると、遠くまで海が見える。", "error_description": "「遠くまで」の「まで」は到達点を示すので、「遠くが」は誤り。正しくは「遠くまで海が見える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35040, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道は駅から遠いまで続いている。", "corrected_sentence": "この道は駅から遠くまで続いている。", "error_description": "「遠く」は副詞で「遠くまで」と使う。「遠い」は形容詞で「遠いまで」とは続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「遠くの町」の〈の〉で、〈遠く〉が〈町〉を修飾する形になる。"}, {"text": "が", "is_correct": false, "explanation": "「遠くが町から」は〈遠く〉を主語にしてしまい、〈町〉を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「遠くに町から」は場所を示す形になり、〈町〉の修飾が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「遠くへ町から」は方向の形になり、〈町〉の修飾が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「遠くの町」の〈の〉で、〈遠く〉が〈町〉を修飾する形になる。", "が": "「遠くが町から」は〈遠く〉を主語にしてしまい、〈町〉を修飾できない。", "に": "「遠くに町から」は場所を示す形になり、〈町〉の修飾が成り立たない。", "へ": "「遠くへ町から」は方向の形になり、〈町〉の修飾が成り立たない。"}, "error_tags": {"が": "主語の位置", "に": "場所の位置", "へ": "方向の位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「姉は遠くで働いて」の〈で〉は動作の場所を示し、〈働いている〉と合う。"}, {"text": "を", "is_correct": false, "explanation": "「遠くを働いて」は〈働く〉が目的語を取らないため成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「遠くと働いて」は並列や共同の形になり、場所を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「遠くより働いて」は比較の形になり、文の意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「姉は遠くで働いて」の〈で〉は動作の場所を示し、〈働いている〉と合う。", "を": "「遠くを働いて」は〈働く〉が目的語を取らないため成り立たない。", "と": "「遠くと働いて」は並列や共同の形になり、場所を示せない。", "より": "「遠くより働いて」は比較の形になり、文の意味が通らない。"}, "error_tags": {"を": "目的語の位置", "と": "並列・相手の位置", "より": "比較の位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "距離が大きいさま。遠いところ。", "primary_collocate": null, "pronunciation": "とおく", "ipa": "toːkɯ", "syllable_count": 3, "sentences": [{"text": "祖母は遠くに住んでいるので、めったに会えない。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "祖母[そぼ]は遠[とお]くに住[す]んでいるので、めったに会[あ]えない。", "sentence_source": "generated"}, {"text": "遠くの町から友だちが遊びに来た。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くの町[まち]から友[とも]だちが遊[あそ]びに来[き]た。", "sentence_source": "generated"}, {"text": "遠くに高い山が見えて、とてもきれいだった。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くに高[たか]い山[やま]が見[み]えて、とてもきれいだった。", "sentence_source": "generated"}, {"text": "父の転勤が決まり、遠くへ引っ越すことになった。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "父[ちち]の転勤[てんきん]が決[き]まり、遠[とお]くへ引[ひ]っ越[こ]すことになった。", "sentence_source": "generated"}, {"text": "遠くにいる家族に、毎週手紙を書いている。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くにいる家族[かぞく]に、毎週[まいしゅう]手紙[てがみ]を書[か]いている。", "sentence_source": "generated"}, {"text": "遠くの国の料理を、はじめて食べた。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くの国[くに]の料理[りょうり]を、はじめて食[た]べた。", "sentence_source": "generated"}, {"text": "夜の海の遠くに、船の灯りが小さく見える。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "夜[よる]の海[うみ]の遠[とお]くに、船[ふね]の灯[あか]りが小[ちい]さく見[み]える。", "sentence_source": "generated"}, {"text": "姉は遠くで働いているため、正月にしか帰らない。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "姉[あね]は遠[とお]くで働[はたら]いているため、正月[しょうがつ]にしか帰[かえ]らない。", "sentence_source": "generated"}, {"text": "遠くから見ると、あの建物は白い箱のようだ。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くから見[み]ると、あの建物[たてもの]は白[しろ]い箱[はこ]のようだ。", "sentence_source": "generated"}, {"text": "遠くで雷が鳴っているので、今日は外に出ない。", "target_word": "遠く", "complexity_tier": "T3", "furigana": "遠[とお]くで雷[かみなり]が鳴[な]っているので、今日[きょう]は外[そと]に出[で]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠く", "label": "基本形"}, {"form": "遠くの", "label": "名詞＋の（連体修飾）"}, {"form": "遠くに", "label": "場所を表す形"}], "register": "中立", "sense_fingerprint": "距離が大きく離れた場所（遠いところ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遠く", "is_correct": true, "explanation": "「遠くに住んでいる」で住む場所が離れていることを表し、「めったに会えない」と合う。"}, {"text": "距離", "is_correct": false, "explanation": "「距離に住んでいる」とは言えず、住んでいる場所を示せない。"}, {"text": "空間", "is_correct": false, "explanation": "「空間に住んでいる」は不自然で、場所を表す語として成り立たない。"}, {"text": "時間", "is_correct": false, "explanation": "時間は場所ではないので、「時間に住んでいる」は意味が通らない。"}], "explanations": {"遠く": "「遠くに住んでいる」で住む場所が離れていることを表し、「めったに会えない」と合う。", "距離": "「距離に住んでいる」とは言えず、住んでいる場所を示せない。", "空間": "「空間に住んでいる」は不自然で、場所を表す語として成り立たない。", "時間": "時間は場所ではないので、「時間に住んでいる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "遠く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "すぐ遠くにコンビニがあるので、とても便利だ。", "explanation": "「すぐ」は近さを表すので、距離が大きいという〈遠く〉の意味と矛盾する。近い場所には〈近く〉を使う。"}, {"text": "その出来事は遠く、今はあまり思い出せない。", "explanation": "〈遠く〉は場所の隔たりを表す。昔のことの古さは〈遠い昔〉のように形容詞で言うので、この意味では使えない。"}, {"text": "この会社の売り上げは去年から遠く伸びた。", "explanation": "ここは〈大きく〉（程度が大きい）の意味。〈遠く〉は距離の大きさを表すので、増加の程度には〈大きく〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遠く", "is_correct": true, "explanation": "「夜の海の遠く」は海の離れた場所を表し、船の灯りが見える位置に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は場所ではないので、「夜の海の季節に」では灯りの位置が示せない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は場所を表せず、「夜の海の時刻に」では船の位置が決まらない。"}, {"text": "距離", "is_correct": false, "explanation": "距離は場所ではなく、「夜の海の距離に」では船がどこにあるかを表せない。"}], "explanations": {"遠く": "「夜の海の遠く」は海の離れた場所を表し、船の灯りが見える位置に合う。", "季節": "季節は場所ではないので、「夜の海の季節に」では灯りの位置が示せない。", "時刻": "時刻は場所を表せず、「夜の海の時刻に」では船の位置が決まらない。", "距離": "距離は場所ではなく、「夜の海の距離に」では船がどこにあるかを表せない。"}, "sentence_index": 6, "correct_answer": "遠く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は遠く、とても辛い。", "explanation": "〈遠く〉を『程度がはなはだしい』の意味で使っている。〈遠く〉は距離の大きさだけを表すので、味の強さには〈ひどく〉を使う。"}, {"text": "足元の遠くに、小さな虫が歩いている。", "explanation": "〈足元〉と〈遠く〉が矛盾する。すぐ近くの場所には〈近く〉を使う。"}, {"text": "このアプリは遠く、ずっと使いやすい。", "explanation": "〈遠く〉を程度の副詞のように使っている。使いやすさの程度を言うなら〈はるかに〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔父は遠くを街に住んでいるので、年に一度しか会わない。", "corrected_sentence": "叔父は遠くの街に住んでいるので、年に一度しか会わない。", "error_description": "〈遠く〉に続く助詞が〈を〉になっている誤り。〈遠くの街〉と〈の〉で街を修飾するのが正しく、〈遠くを街に〉は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35041, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちは遠いの山へ登りに行った。", "corrected_sentence": "友だちは遠くの山へ登りに行った。", "error_description": "〈遠い〉の形が崩れた誤り。〈遠いの〉は形容詞として続かず、〈遠くの山〉と〈の〉で山を修飾するのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。掛かっている主語（飾り）を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に付くので、自動詞の「掛かっている」とは結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所や手段を示し、ものが引っかかっている位置は表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、ものが止まって掛かっている場所には使えない。"}], "correct_answer": "が", "explanations": {"が": "正解。掛かっている主語（飾り）を示す格助詞。", "を": "「を」は他動詞の目的語に付くので、自動詞の「掛かっている」とは結びつかない。", "で": "「で」は動作の場所や手段を示し、ものが引っかかっている位置は表せない。", "へ": "「へ」は移動の方向を示すので、ものが止まって掛かっている場所には使えない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。掛かっている場所（竿）を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に付くので、自動詞の「掛かっている」には使えない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、竿に掛かる位置関係を示せず、「竿の掛かっている」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すので、「竿と掛かっている」では位置関係が示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。掛かっている場所（竿）を示す格助詞。", "を": "「を」は他動詞の目的語に付くので、自動詞の「掛かっている」には使えない。", "の": "連体修飾の「の」では、竿に掛かる位置関係を示せず、「竿の掛かっている」は不自然。", "と": "「と」は並列を表すので、「竿と掛かっている」では位置関係が示せない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が壁・枝・釘などに引っかかって、上から下がった状態になること。", "primary_collocate": null, "pronunciation": "かかる", "ipa": "kakaɾɯ", "syllable_count": 3, "sentences": [{"text": "壁に大きな絵が掛かっています。", "target_word": "掛かっています", "complexity_tier": "T3", "furigana": "壁[かべ]に大[おお]きな絵[え]が掛[か]かっています。", "sentence_source": "generated"}, {"text": "玄関のドアに、かわいい飾りが掛かっている。", "target_word": "掛かっている", "complexity_tier": "T3", "furigana": "玄関[げんかん]のドアに、かわいい飾[かざ]りが掛[か]かっている。", "sentence_source": "generated"}, {"text": "木の枝に、風で飛んだ帽子が掛かってしまった。", "target_word": "掛かってしまった", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]に、風[かぜ]で飛[と]んだ帽子[ぼうし]が掛[か]かってしまった。", "sentence_source": "generated"}, {"text": "壁に時計が掛かっているので、時間がすぐ分かります。", "target_word": "掛かっている", "complexity_tier": "T3", "furigana": "壁[かべ]に時計[とけい]が掛[か]かっているので、時間[じかん]がすぐ分[わ]かります。", "sentence_source": "generated"}, {"text": "窓にカーテンが掛かっていて、部屋の中は見えません。", "target_word": "掛かっていて", "complexity_tier": "T3", "furigana": "窓[まど]にカーテンが掛[か]かっていて、部屋[へや]の中[なか]は見[み]えません。", "sentence_source": "generated"}, {"text": "ハンガーに上着が掛かっているから、それを着てください。", "target_word": "掛かっている", "complexity_tier": "T3", "furigana": "ハンガーに上着[うわぎ]が掛[か]かっているから、それを着[き]てください。", "sentence_source": "generated"}, {"text": "入り口には「休み」という札が掛かっていた。", "target_word": "掛かっていた", "complexity_tier": "T3", "furigana": "入[い]り口[ぐち]には「休[やす]み」という札[ふだ]が掛[か]かっていた。", "sentence_source": "generated"}, {"text": "洗濯物が竿に掛かっているのは、昨日の雨で乾かなかったからです。", "target_word": "掛かっている", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]が竿[さお]に掛[か]かっているのは、昨日[きのう]の雨[あめ]で乾[かわ]かなかったからです。", "sentence_source": "generated"}, {"text": "事務所の壁に、新しいポスターが掛かっています。", "target_word": "掛かっています", "complexity_tier": "T3", "furigana": "事務所[じむしょ]の壁[かべ]に、新[あたら]しいポスターが掛[か]かっています。", "sentence_source": "generated"}, {"text": "釘に鍵が掛かっているので、取って来てください。", "target_word": "掛かっている", "complexity_tier": "T3", "furigana": "釘[くぎ]に鍵[かぎ]が掛[か]かっているので、取[と]って来[き]てください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛かる", "label": "終止形"}, {"form": "掛かった", "label": "過去形"}, {"form": "掛かって", "label": "て形"}, {"form": "掛かっている", "label": "継続形"}, {"form": "掛からない", "label": "否定形"}, {"form": "掛かります", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "物が壁・枝・釘などに引っかかって下がっている（吊り下がる）意味の「掛かる」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛かっています", "is_correct": true, "explanation": "正解。壁に絵がぶら下がっている状態を表す自動詞の形で、文脈に合う。"}, {"text": "掛けています", "is_correct": false, "explanation": "「掛ける」は他動詞なので、「絵が」で受けると不自然になる。「絵を掛けています」なら成り立つ。"}, {"text": "置いています", "is_correct": false, "explanation": "「置く」は物を台などに据える動詞で、壁にぶら下がる絵の状態を表せず、「絵が」とも結びつかない。"}, {"text": "落としています", "is_correct": false, "explanation": "「落とす」は他動詞で、絵が壁から外れた状態を表せず、「絵が」で受けるのは不自然。"}], "explanations": {"掛かっています": "正解。壁に絵がぶら下がっている状態を表す自動詞の形で、文脈に合う。", "掛けています": "「掛ける」は他動詞なので、「絵が」で受けると不自然になる。「絵を掛けています」なら成り立つ。", "置いています": "「置く」は物を台などに据える動詞で、壁にぶら下がる絵の状態を表せず、「絵が」とも結びつかない。", "落としています": "「落とす」は他動詞で、絵が壁から外れた状態を表せず、「絵が」で受けるのは不自然。"}, "sentence_index": 0, "correct_answer": "掛かっています"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ここで椅子に掛かってお待ちください。", "explanation": "ここは〈腰掛ける〉の意味。人が座る動作には「掛かる」を使わず、物が引っかかって下がる意味にしか使えない。"}, {"text": "テーブルに皿が掛かっている。", "explanation": "ここは〈載る〉の意味。平らな台の上に置かれた皿には「掛かる」を使わない。"}, {"text": "棚に荷物が掛かっていて、取れなかった。", "explanation": "ここは〈載る・置く〉の意味。棚の上に乗せた物には「掛かる」を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛かっていた", "is_correct": true, "explanation": "正解。札が入り口にぶら下がっていた状態を表す。"}, {"text": "貼っていた", "is_correct": false, "explanation": "「貼る」は表面に付ける動詞で、札が自然に貼られている状態には言えず、「札が」で受けると不自然。"}, {"text": "留めていた", "is_correct": false, "explanation": "「留める」は他動詞なので、「札が」で受けると成り立たない。"}, {"text": "結んでいた", "is_correct": false, "explanation": "「結ぶ」は他動詞で、紐などで縛る動作を表し、札の状態には合わない。"}], "explanations": {"掛かっていた": "正解。札が入り口にぶら下がっていた状態を表す。", "貼っていた": "「貼る」は表面に付ける動詞で、札が自然に貼られている状態には言えず、「札が」で受けると不自然。", "留めていた": "「留める」は他動詞なので、「札が」で受けると成り立たない。", "結んでいた": "「結ぶ」は他動詞で、紐などで縛る動作を表し、札の状態には合わない。"}, "sentence_index": 6, "correct_answer": "掛かっていた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れて、ベッドに掛かって眠った。", "explanation": "ここは〈横になる〉の意味。体を横たえる動作には「掛かる」を使わない。"}, {"text": "書類のミスに掛かって、三時間直した。", "explanation": "ここは〈取りかかる〉の意味。仕事などに手を付ける用法で、この義項（吊り下がる）とは別。"}, {"text": "この壁には、昔の傷が掛かっている。", "explanation": "ここは〈付く〉の意味。掛かるは引っかかって下がる状態を表すので、傷のように表面にくっついたものには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玄関に鏡が掛けていて、少し暗い。", "corrected_sentence": "玄関に鏡が掛かっていて、少し暗い。", "error_description": "「掛けていて」は他動詞の形で、「鏡が」を主語にすると不自然。正しくは自動詞の「掛かっていて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掛かっている", "is_correct": true, "explanation": "正解。継続形で、ドアに飾りがぶら下がっている今の状態を表す。"}, {"text": "掛かった", "is_correct": false, "explanation": "過去形なので、掛かり終えた出来事になり、今掛かっている状態という文の意味と変わる。"}, {"text": "掛からない", "is_correct": false, "explanation": "否定形なので、飾りがぶら下がっていないことになり、文の内容と逆になる。"}, {"text": "掛かります", "is_correct": false, "explanation": "丁寧形で、ふつう体の文の中では文体が揃わない。"}], "correct_form": "掛かっている", "base_form": "掛かる", "form_label": "継続形", "sentence_index": 1, "explanations": {"掛かっている": "正解。継続形で、ドアに飾りがぶら下がっている今の状態を表す。", "掛かった": "過去形なので、掛かり終えた出来事になり、今掛かっている状態という文の意味と変わる。", "掛からない": "否定形なので、飾りがぶら下がっていないことになり、文の内容と逆になる。", "掛かります": "丁寧形で、ふつう体の文の中では文体が揃わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35044, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ハンガーに上着を掛かっていた。", "corrected_sentence": "ハンガーに上着が掛かっていた。", "error_description": "「掛かる」は自動詞なので、ものの主語は「が」で示す。「を」は他動詞の目的語に使うため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掛かっている", "is_correct": true, "explanation": "正解。継続形で、洗濯物が竿に掛かっている今の状態を表す。"}, {"text": "掛かれ", "is_correct": false, "explanation": "命令形で、「のは」の前に置けず、文が成り立たない。"}, {"text": "掛かって", "is_correct": false, "explanation": "て形は文を続ける途中の形で、「のは…からです」の文末に立てない。"}, {"text": "掛かっていて", "is_correct": false, "explanation": "て形で文を続ける途中の形なので、「のは」の前には立てず文が成り立たない。"}], "correct_form": "掛かっている", "base_form": "掛かる", "form_label": "継続形", "sentence_index": 7, "explanations": {"掛かっている": "正解。継続形で、洗濯物が竿に掛かっている今の状態を表す。", "掛かれ": "命令形で、「のは」の前に置けず、文が成り立たない。", "掛かって": "て形は文を続ける途中の形で、「のは…からです」の文末に立てない。", "掛かっていて": "て形で文を続ける途中の形なので、「のは」の前には立てず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35046, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大勢が球場へ来た」の〈が〉は主語を示し、〈大勢〉が来る主体になる。"}, {"text": "を", "is_correct": false, "explanation": "「大勢を球場へ来た」は〈来る〉が目的語を取れないため成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「大勢に球場へ来た」は相手や場所を示す形で、主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「大勢の球場へ来た」は連体修飾になり、〈来た〉の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「大勢が球場へ来た」の〈が〉は主語を示し、〈大勢〉が来る主体になる。", "を": "「大勢を球場へ来た」は〈来る〉が目的語を取れないため成り立たない。", "に": "「大勢に球場へ来た」は相手や場所を示す形で、主語にならない。", "の": "「大勢の球場へ来た」は連体修飾になり、〈来た〉の主語にならない。"}, "error_tags": {"を": "目的語の位置", "に": "相手・場所の位置", "の": "連体修飾の位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35046, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「大勢でゲームをする」の〈で〉は〈大勢〉を手段や人数の形で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「大勢へゲームをすると」は方向の形になり、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「大勢からゲームをすると」は起点の形になり、人数の意味が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「大勢よりゲームをすると」は比較の形になり、文の論理が合わない。"}], "correct_answer": "で", "explanations": {"で": "「大勢でゲームをする」の〈で〉は〈大勢〉を手段や人数の形で示す。", "へ": "「大勢へゲームをすると」は方向の形になり、意味が通らない。", "から": "「大勢からゲームをすると」は起点の形になり、人数の意味が成り立たない。", "より": "「大勢よりゲームをすると」は比較の形になり、文の論理が合わない。"}, "error_tags": {"へ": "方向の位置", "から": "起点の位置", "より": "比較の位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35046, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの 人。", "primary_collocate": null, "pronunciation": "おおぜい", "ipa": "oːzeː", "syllable_count": 4, "sentences": [{"text": "駅の前に大勢の人が集まっていた。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に大勢[おおぜい]の人[ひと]が集[あつ]まっていた。", "sentence_source": "generated"}, {"text": "試合を見るために、大勢が球場へ来た。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "試合[しあい]を見[み]るために、大勢[おおぜい]が球場[きゅうじょう]へ来[き]た。", "sentence_source": "generated"}, {"text": "一人で歌うより、大勢で歌うほうが楽しい。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "一人[ひとり]で歌[うた]うより、大勢[おおぜい]で歌[うた]うほうが楽[たの]しい。", "sentence_source": "generated"}, {"text": "祭りの日は、大勢の子どもが神社で遊ぶ。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、大勢[おおぜい]の子[こ]どもが神社[じんじゃ]で遊[あそ]ぶ。", "sentence_source": "generated"}, {"text": "大勢の客が来たので、店は忙しかった。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]の客[きゃく]が来[き]たので、店[みせ]は忙[いそが]しかった。", "sentence_source": "generated"}, {"text": "有名な先生の話を聞くために、大勢が教室に入った。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な先生[せんせい]の話[はなし]を聞[き]くために、大勢[おおぜい]が教室[きょうしつ]に入[はい]った。", "sentence_source": "generated"}, {"text": "大勢の前で話すのは、少し緊張する。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]の前[まえ]で話[はなし]すのは、少[すこ]し緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "大勢でゲームをすると、一人のときよりにぎやかだ。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]でゲームをすると、一人[ひとり]のときよりにぎやかだ。", "sentence_source": "generated"}, {"text": "事故のあと、大勢の人が助けに走った。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、大勢[おおぜい]の人[ひと]が助[たす]けに走[はし]った。", "sentence_source": "generated"}, {"text": "大勢の観客が、選手に大きな拍手を送った。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]の観客[かんきゃく]が、選手[せんしゅ]に大[おお]きな拍手[はくしゅ]を送[おく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大勢", "label": "基本形"}, {"form": "大勢の", "label": "名詞＋の（連体修飾）"}, {"form": "大勢で", "label": "手段・状態を表す形"}], "register": "中立", "sense_fingerprint": "たくさんの人、多人数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35046, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大勢", "is_correct": true, "explanation": "「駅の前に大勢の人が集まっていた」で、多くの人が集まる意味になり文脈に合う。"}, {"text": "寒気", "is_correct": false, "explanation": "「寒気の人」は成り立たず、人の集まりを表せない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉の人」は成り立たず、人が集まる文にならない。"}, {"text": "石", "is_correct": false, "explanation": "「石の人」は成り立たず、人の数を表せない。"}], "explanations": {"大勢": "「駅の前に大勢の人が集まっていた」で、多くの人が集まる意味になり文脈に合う。", "寒気": "「寒気の人」は成り立たず、人の集まりを表せない。", "落ち葉": "「落ち葉の人」は成り立たず、人が集まる文にならない。", "石": "「石の人」は成り立たず、人の数を表せない。"}, "sentence_index": 0, "correct_answer": "大勢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場で大勢の部品を作る。", "explanation": "〈大勢〉は人の多さを表す語。部品のような物の多さには〈大量〉を使う。"}, {"text": "大勢の友だちが、二人だけ遊びに来てくれた。", "explanation": "〈大勢〉を『多数』の意味で使っている。二人のような少数には〈数人〉を使う。"}, {"text": "机の上に大勢のペンが並んでいた。", "explanation": "〈大勢〉は人について使う語。ペンのような物の多さには〈たくさん〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35046, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大勢", "is_correct": true, "explanation": "「大勢の前で話す」で、多くの人の前という意味になり文に合う。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹の前で話す」は意味が通らず、場所を表せない。"}, {"text": "花びら", "is_correct": false, "explanation": "「花びらの前で話す」は不自然で、聞き手の位置を示せない。"}, {"text": "砂", "is_correct": false, "explanation": "「砂の前で話す」は不自然で、人の集まりを表せない。"}], "explanations": {"大勢": "「大勢の前で話す」で、多くの人の前という意味になり文に合う。", "空腹": "「空腹の前で話す」は意味が通らず、場所を表せない。", "花びら": "「花びらの前で話す」は不自然で、聞き手の位置を示せない。", "砂": "「砂の前で話す」は不自然で、人の集まりを表せない。"}, "sentence_index": 6, "correct_answer": "大勢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は大勢の物語を読んで、感動した。", "explanation": "〈大勢〉は人について使う語。物語の数には〈たくさん〉〈数多く〉を使う。"}, {"text": "彼女は大勢の内向的な性格だ。", "explanation": "〈大勢〉を『程度が大きい』の意味で使っている。性格の程度を言うなら〈非常に〉〈かなり〉を使う。"}, {"text": "大勢の本が一冊だけ残っていた。", "explanation": "〈大勢〉を本の数に使っている。本の多さには〈たくさん〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
