INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35047, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「大勢の子どもたち」の〈の〉で、〈大勢〉が〈子どもたち〉を修飾する。"}, {"text": "より", "is_correct": false, "explanation": "「大勢より子どもたちが」は比較の形になり、〈子どもたち〉の修飾にならない。"}, {"text": "から", "is_correct": false, "explanation": "「大勢から子どもたちが」は起点の形になり、人数の意味が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「大勢を子どもたちが」は目的語の形になり、〈遊ぶ〉の主語と合わない。"}], "correct_answer": "の", "explanations": {"の": "「大勢の子どもたち」の〈の〉で、〈大勢〉が〈子どもたち〉を修飾する。", "より": "「大勢より子どもたちが」は比較の形になり、〈子どもたち〉の修飾にならない。", "から": "「大勢から子どもたちが」は起点の形になり、人数の意味が成り立たない。", "を": "「大勢を子どもたちが」は目的語の形になり、〈遊ぶ〉の主語と合わない。"}, "error_tags": {"より": "比較の位置", "から": "起点の位置", "を": "目的語の位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35047, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの人々。大勢の人が集まる、などの形で使う。", "primary_collocate": null, "pronunciation": "おおぜい", "ipa": "oːdzeː", "syllable_count": 4, "sentences": [{"text": "駅の前に大勢の人が集まっていた。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に大勢[おおぜい]の人[ひと]が集[あつ]まっていた。", "sentence_source": "generated"}, {"text": "今日のパーティーには大勢の友達が来る。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "今日[きょう]のパーティーには大勢[おおぜい]の友達[ともだち]が来[く]る。", "sentence_source": "generated"}, {"text": "大勢の前で話すのは、とても緊張する。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]の前[まえ]で話[はな]すのは、とても緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "祭りの日は、大勢の観光客で町がにぎやかになる。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、大勢[おおぜい]の観光客[かんこうきゃく]で町[まち]がにぎやかになる。", "sentence_source": "generated"}, {"text": "大勢で食べると、料理がもっとおいしく感じられる。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]で食[た]べると、料理[りょうり]がもっとおいしく感[かん]じられる。", "sentence_source": "generated"}, {"text": "人気の店なので、昼には大勢の客が並んでいる。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "人気[にんき]の店[みせ]なので、昼[ひる]には大勢[おおぜい]の客[きゃく]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "試合を見に、大勢のファンがスタジアムへ行った。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "試合[しあい]を見[み]に、大勢[おおぜい]のファンがスタジアムへ行[い]った。", "sentence_source": "generated"}, {"text": "大勢の子どもたちが、公園で楽しそうに遊んでいる。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "大勢[おおぜい]の子[こ]どもたちが、公園[こうえん]で楽[たの]しそうに遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "先生は大勢の学生に向かって、ゆっくり説明した。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "先生[せんせい]は大勢[おおぜい]の学生[がくせい]に向[む]かって、ゆっくり説明[せつめい]した。", "sentence_source": "generated"}, {"text": "事故のあと、大勢の人が助けに駆けつけた。", "target_word": "大勢", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、大勢[おおぜい]の人[ひと]が助[たす]けに駆[か]けつけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大勢", "label": "基本形"}, {"form": "大勢の", "label": "名詞＋の（連体修飾）"}, {"form": "大勢で", "label": "で格"}], "register": "中立", "sense_fingerprint": "人が多数いること。大勢の人・大勢で、の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35047, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大勢", "is_correct": true, "explanation": "「駅の前に大勢の人が集まっていた」で、多くの人が集まる意味になり文脈に合う。"}, {"text": "寒気", "is_correct": false, "explanation": "「寒気の人」は成り立たず、人の集まりを表せない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉の人」は成り立たず、人が集まる文にならない。"}, {"text": "石", "is_correct": false, "explanation": "「石の人」は成り立たず、人の数を表せない。"}], "explanations": {"大勢": "「駅の前に大勢の人が集まっていた」で、多くの人が集まる意味になり文脈に合う。", "寒気": "「寒気の人」は成り立たず、人の集まりを表せない。", "落ち葉": "「落ち葉の人」は成り立たず、人が集まる文にならない。", "石": "「石の人」は成り立たず、人の数を表せない。"}, "sentence_index": 0, "correct_answer": "大勢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家の裏に大勢の木が生えている。", "explanation": "〈大勢〉を木の数に使っている。木の多さには〈たくさん〉を使う。"}, {"text": "大勢の観光客が、ほんの二人だけ来た。", "explanation": "〈大勢〉を『多数』の意味で使っている。二人のような少数には〈数人〉を使う。"}, {"text": "大勢の町は、なぜか人が一人もいない。", "explanation": "〈大勢〉を町の様子に使っている。町のにぎやかさを言うなら〈にぎやか〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35047, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大勢", "is_correct": true, "explanation": "「試合を見に、大勢のファンがスタジアムへ行った」で、多くのファンの意味になり文に合う。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹のファン」は意味が通らず、来場した人の集まりを表せない。"}, {"text": "花びら", "is_correct": false, "explanation": "「花びらのファン」は成り立たず、人を修飾できない。"}, {"text": "砂", "is_correct": false, "explanation": "「砂のファン」は成り立たず、人の数を表せない。"}], "explanations": {"大勢": "「試合を見に、大勢のファンがスタジアムへ行った」で、多くのファンの意味になり文に合う。", "空腹": "「空腹のファン」は意味が通らず、来場した人の集まりを表せない。", "花びら": "「花びらのファン」は成り立たず、人を修飾できない。", "砂": "「砂のファン」は成り立たず、人の数を表せない。"}, "sentence_index": 6, "correct_answer": "大勢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大勢の山が道を塞いでいた。", "explanation": "〈大勢〉を『たくさんの山』の意味で使っている。山の数には〈いくつも〉〈たくさん〉を使う。"}, {"text": "事故のあと、大勢の人が一人だけ駆けつけた。", "explanation": "〈大勢〉を『多数』の意味で使っている。少数には〈数人〉を使う。"}, {"text": "事故のあと、大勢の傷が走った。", "explanation": "〈大勢〉を傷の数に使っている。傷の多さには〈無数〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35047, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末の動物園は、大勢を家族連れでにぎわう。", "corrected_sentence": "週末の動物園は、大勢の家族連れでにぎわう。", "error_description": "〈大勢〉に続く〈の〉が〈を〉になっている誤り。〈大勢の家族連れ〉と連体修飾にするのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35047, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大勢だ子どもが、公園の池のそばで楽しそうに遊んでいる。", "corrected_sentence": "大勢の子どもが、公園の池のそばで楽しそうに遊んでいる。", "error_description": "〈大勢〉に〈だ〉が続いて〈大勢だ子ども〉となっている。名詞の連体修飾は〈大勢の〉とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「覚えるの」の〈の〉で動詞を名詞化し、「覚えること」の意味で〈が苦手〉につながる。"}, {"text": "を", "is_correct": false, "explanation": "「覚えるを」は名詞化せず、〈苦手〉の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「覚えるで」は手段や場所を示す形で、「覚えること」の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「覚えると」は条件や引用の形で、〈苦手〉の対象を示せない。"}], "correct_answer": "の", "explanations": {"の": "「覚えるの」の〈の〉で動詞を名詞化し、「覚えること」の意味で〈が苦手〉につながる。", "を": "「覚えるを」は名詞化せず、〈苦手〉の主語にならない。", "で": "「覚えるで」は手段や場所を示す形で、「覚えること」の意味にならない。", "と": "「覚えると」は条件や引用の形で、〈苦手〉の対象を示せない。"}, "error_tags": {"を": "目的語の位置", "で": "手段・場所の位置", "と": "条件・引用の位置"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘れる", "is_correct": true, "explanation": "「覚える」の対義語で、頭に入れた内容を失う意味になり、「覚えていない」と対応する。"}, {"text": "食べる", "is_correct": false, "explanation": "〈食べる〉は〈覚える〉の対義語ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "〈歩く〉は〈覚える〉の対義語ではない。"}, {"text": "教える", "is_correct": false, "explanation": "〈教える〉は〈覚える〉と反対の意味ではなく、覚えさせる側の動作を表す。"}], "correct_answer": "忘れる", "explanations": {"忘れる": "「覚える」の対義語で、頭に入れた内容を失う意味になり、「覚えていない」と対応する。", "食べる": "〈食べる〉は〈覚える〉の対義語ではない。", "歩く": "〈歩く〉は〈覚える〉の対義語ではない。", "教える": "〈教える〉は〈覚える〉と反対の意味ではなく、覚えさせる側の動作を表す。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘れる", "is_correct": true, "explanation": "「覚える」の対義語で、頭に入れた内容を失う意味になり、〈時間がかかった〉の文脈と対応する。"}, {"text": "書く", "is_correct": false, "explanation": "〈書く〉は〈覚える〉の対義語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "〈走る〉は〈覚える〉の対義語ではない。"}, {"text": "聞く", "is_correct": false, "explanation": "〈聞く〉は〈覚える〉の関連語だが、対義語ではない。"}], "correct_answer": "忘れる", "explanations": {"忘れる": "「覚える」の対義語で、頭に入れた内容を失う意味になり、〈時間がかかった〉の文脈と対応する。", "書く": "〈書く〉は〈覚える〉の対義語ではない。", "走る": "〈走る〉は〈覚える〉の対義語ではない。", "聞く": "〈聞く〉は〈覚える〉の関連語だが、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "おぼえる は、ものを あたまの なかに いれて、しって いる ように なる こと。", "primary_collocate": null, "pronunciation": "おぼえる", "ipa": "oboeɾɯ", "syllable_count": 4, "sentences": [{"text": "新しい友達の名前を、すぐに覚えた。", "target_word": "覚えた", "complexity_tier": "T3", "furigana": "新[あたら]しい友達[ともだち]の名前[なまえ]を、すぐに覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "電話番号を覚えるのが苦手だ。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "電話[でんわ]番号[ばんごう]を覚[おぼ]えるのが苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "毎日、英語の単語を十個ずつ覚える。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "毎日[まいにち]、英語[えいご]の単語[たんご]を十個[じっこ]ずつ覚[おぼ]える。", "sentence_source": "generated"}, {"text": "道を覚えていないので、地図を見ながら歩く。", "target_word": "覚えていない", "complexity_tier": "T3", "furigana": "道[みち]を覚[おぼ]えていないので、地図[ちず]を見[み]ながら歩[ある]く。", "sentence_source": "generated"}, {"text": "先生は学生全員の顔を覚えている。", "target_word": "覚えている", "complexity_tier": "T3", "furigana": "先生[せんせい]は学生[がくせい]全員[ぜんいん]の顔[かお]を覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "歌の言葉を覚えて、みんなで歌った。", "target_word": "覚えて", "complexity_tier": "T3", "furigana": "歌[うた]の言葉[ことば]を覚[おぼ]えて、みんなで歌[うた]った。", "sentence_source": "generated"}, {"text": "年表を覚えるために、何度も紙に書いた。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "年表[ねんぴょう]を覚[おぼ]えるために、何度[なんど]も紙[かみ]に書[か]いた。", "sentence_source": "generated"}, {"text": "子どもは一度聞いた歌をすぐに覚える。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "子[こ]どもは一度[いちど]聞[き]いた歌[うた]をすぐに覚[おぼ]える。", "sentence_source": "generated"}, {"text": "パスワードを覚えられなくて、紙に書いておいた。", "target_word": "覚えられなくて", "complexity_tier": "T3", "furigana": "パスワードを覚[おぼ]えられなくて、紙[かみ]に書[か]いておいた。", "sentence_source": "generated"}, {"text": "長い名前なので、覚えるのに時間がかかった。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "長[なが]い名前[なまえ]なので、覚[おぼ]えるのに時間[じかん]がかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覚える", "label": "辞書形"}, {"form": "覚えます", "label": "ます形"}, {"form": "覚えた", "label": "た形"}, {"form": "覚えて", "label": "て形"}, {"form": "覚えない", "label": "ない形"}, {"form": "覚えれば", "label": "ば形"}, {"form": "覚えよう", "label": "意向形"}, {"form": "覚えられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "名前・番号・言葉などを頭に入れて、忘れないようにする（暗記・記憶）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覚えた", "is_correct": true, "explanation": "「すぐに覚えた」の過去形で、文が完結して意味が通る。"}, {"text": "覚えて", "is_correct": false, "explanation": "て形は文末で止まらず、「すぐに覚えて。」では文が完結しない。"}, {"text": "覚え", "is_correct": false, "explanation": "語幹だけでは文が完結せず、「すぐに覚え。」は成り立たない。"}, {"text": "覚えられ", "is_correct": false, "explanation": "可能形の途中で文が完結せず、「すぐに覚えられ。」は成り立たない。"}], "explanations": {"覚えた": "「すぐに覚えた」の過去形で、文が完結して意味が通る。", "覚えて": "て形は文末で止まらず、「すぐに覚えて。」では文が完結しない。", "覚え": "語幹だけでは文が完結せず、「すぐに覚え。」は成り立たない。", "覚えられ": "可能形の途中で文が完結せず、「すぐに覚えられ。」は成り立たない。"}, "sentence_index": 0, "correct_answer": "覚えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんを覚えて、家を出た。", "explanation": "ここは〈食べる〉の意味。〈覚える〉は情報を頭に入れる動作なので、食事には使えない。"}, {"text": "財布を覚えてから、お金を払った。", "explanation": "〈覚える〉を『頭に入れる』の意味で使っているが、財布は覚える対象にならない。財布の場所なら〈確かめる〉を使う。"}, {"text": "白いカーテンを覚えて、窓を閉めた。", "explanation": "ここは〈選ぶ〉の意味。〈覚える〉は情報を頭に入れる動作で、物を選ぶことには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覚える", "is_correct": true, "explanation": "「年表を覚えるために」の辞書形で、目的を表す形として文に合う。"}, {"text": "覚えよう", "is_correct": false, "explanation": "「覚えようために」は接続が成り立たず、文の流れに合わない。"}, {"text": "覚えろ", "is_correct": false, "explanation": "命令形は「覚えろために」となり、目的の形にならない。"}, {"text": "覚えます", "is_correct": false, "explanation": "ます形は「覚えますために」となり、文に続かない。"}], "explanations": {"覚える": "「年表を覚えるために」の辞書形で、目的を表す形として文に合う。", "覚えよう": "「覚えようために」は接続が成り立たず、文の流れに合わない。", "覚えろ": "命令形は「覚えろために」となり、目的の形にならない。", "覚えます": "ます形は「覚えますために」となり、文に続かない。"}, "sentence_index": 6, "correct_answer": "覚える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い名前なので、窓を覚えるのに時間がかかった。", "explanation": "〈覚える〉は情報を頭に入れる動作で、窓そのものは覚える対象にならない。〈窓の位置〉のように情報に限定する。"}, {"text": "長い名前なので、椅子を覚えるのに時間がかかった。", "explanation": "〈覚える〉は情報を頭に入れる動作で、椅子そのものは覚える対象にならない。〈椅子の配置〉のように情報に限定する。"}, {"text": "長い名前なので、靴を覚えるのに時間がかかった。", "explanation": "〈覚える〉は情報を頭に入れる動作で、靴そのものは覚える対象にならない。〈靴の型〉のように情報に限定する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は料理の手順を覚えるている。", "corrected_sentence": "母は料理の手順を覚えている。", "error_description": "〈覚えている〉の形が誤り。〈覚える〉に〈ている〉が続くので、〈覚えるている〉は成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "覚える", "is_correct": true, "explanation": "「覚えるのが苦手」と名詞化する形で、辞書形が正しい。"}, {"text": "覚えた", "is_correct": false, "explanation": "過去形は「覚えたの」となり、一般的な苦手さの話に合わない。"}, {"text": "覚えない", "is_correct": false, "explanation": "否定形は「覚えないの」となり、覚えること自体の苦手さを表せない。"}, {"text": "覚えられる", "is_correct": false, "explanation": "可能形は「覚えられるの」となり、覚えることの苦手さに合わない。"}], "correct_form": "覚える", "base_form": "覚える", "form_label": "辞書形", "sentence_index": 1, "explanations": {"覚える": "「覚えるのが苦手」と名詞化する形で、辞書形が正しい。", "覚えた": "過去形は「覚えたの」となり、一般的な苦手さの話に合わない。", "覚えない": "否定形は「覚えないの」となり、覚えること自体の苦手さを表せない。", "覚えられる": "可能形は「覚えられるの」となり、覚えることの苦手さに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35048, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい体操を覚えるに、一週間かかった。", "corrected_sentence": "新しい体操を覚えるのに、一週間かかった。", "error_description": "〈覚える〉の後に〈の〉が抜けている。〈覚えるのに〉で「〜するのに時間がかかる」の形になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "覚える", "is_correct": true, "explanation": "文末で習慣や一般的な動作を表す辞書形で、「子どもは〜覚える」の文に合う。"}, {"text": "覚えて", "is_correct": false, "explanation": "て形は文末で止まらず、「すぐに覚えて。」では文が完結しない。"}, {"text": "覚えよう", "is_correct": false, "explanation": "意向形は意志を表すため、一般的な習慣を述べる文に合わない。"}, {"text": "覚えれば", "is_correct": false, "explanation": "ば形は条件を表し、「すぐに覚えれば。」では文が完結しない。"}], "correct_form": "覚える", "base_form": "覚える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"覚える": "文末で習慣や一般的な動作を表す辞書形で、「子どもは〜覚える」の文に合う。", "覚えて": "て形は文末で止まらず、「すぐに覚えて。」では文が完結しない。", "覚えよう": "意向形は意志を表すため、一般的な習慣を述べる文に合わない。", "覚えれば": "ば形は条件を表し、「すぐに覚えれば。」では文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘れる", "is_correct": true, "explanation": "覚える（記憶に留める）の対義語。記憶に留めることの反対の意味になる。"}, {"text": "作る", "is_correct": false, "explanation": "覚えることの反対語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "覚えることの反対語ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "覚えることの反対語ではない。"}], "correct_answer": "忘れる", "explanations": {"忘れる": "覚える（記憶に留める）の対義語。記憶に留めることの反対の意味になる。", "作る": "覚えることの反対語ではない。", "運ぶ": "覚えることの反対語ではない。", "洗う": "覚えることの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "動詞の辞書形に付けて「～すると」と条件を表し、「覚えると」で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を表すので、条件を作る位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、「覚えで」では条件の文が作れない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、条件を作る位置には入らない。"}], "correct_answer": "と", "explanations": {"と": "動詞の辞書形に付けて「～すると」と条件を表し、「覚えると」で文が成り立つ。", "を": "「を」は対象を表すので、条件を作る位置には入らない。", "で": "「で」は手段や場所を表すので、「覚えで」では条件の文が作れない。", "へ": "「へ」は方向を表すので、条件を作る位置には入らない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘れる", "is_correct": true, "explanation": "覚える（記憶に留める）の対義語。記憶に留めることの反対の意味になる。"}, {"text": "眠る", "is_correct": false, "explanation": "覚えることの反対語ではない。"}, {"text": "届ける", "is_correct": false, "explanation": "覚えることの反対語ではない。"}, {"text": "測る", "is_correct": false, "explanation": "覚えることの反対語ではない。"}], "correct_answer": "忘れる", "explanations": {"忘れる": "覚える（記憶に留める）の対義語。記憶に留めることの反対の意味になる。", "眠る": "覚えることの反対語ではない。", "届ける": "覚えることの反対語ではない。", "測る": "覚えることの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "情報や知識を記憶に留めること。また、習得すること。", "primary_collocate": null, "pronunciation": "おぼえる", "ipa": "oboeɾɯ", "syllable_count": 4, "sentences": [{"text": "新しい仕事を早く覚えたいと思っている。", "target_word": "覚えたい", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]を早[はや]く覚[おぼ]えたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "弟は自転車の乗り方をすぐに覚えた。", "target_word": "覚えた", "complexity_tier": "T3", "furigana": "弟[おとうと]は自転車[じてんしゃ]の乗[の]り方[かた]をすぐに覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "日本に来て、毎日使う言葉を少しずつ覚えた。", "target_word": "覚えた", "complexity_tier": "T3", "furigana": "日本[にほん]に来[き]て、毎日[まいにち]使[つか]う言葉[ことば]を少[すこ]しずつ覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "料理を覚えて、家族に作ってあげたい。", "target_word": "覚えて", "complexity_tier": "T3", "furigana": "料理[りょうり]を覚[おぼ]えて、家族[かぞく]に作[つく]ってあげたい。", "sentence_source": "generated"}, {"text": "彼女は新入社員なので、覚えることが多い。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新入[しんにゅう]社員[しゃいん]なので、覚[おぼ]えることが多[おお]い。", "sentence_source": "generated"}, {"text": "この機械の使い方は、一度見れば覚えられる。", "target_word": "覚えられる", "complexity_tier": "T3", "furigana": "この機械[きかい]の使[つか]い方[かた]は、一度[いちど]見[み]れば覚[おぼ]えられる。", "sentence_source": "generated"}, {"text": "犬に「お座り」を覚えさせるのは難しくない。", "target_word": "覚えさせる", "complexity_tier": "T3", "furigana": "犬[いぬ]に「お座[すわ]り」を覚[おぼ]えさせるのは難[むずか]しくない。", "sentence_source": "generated"}, {"text": "泳ぎは小さいころに覚えると、一生忘れない。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "泳[およ]ぎは小[ちい]さいころに覚[おぼ]えると、一生[いっしょう]忘[わす]れない。", "sentence_source": "generated"}, {"text": "ピアノの曲を覚えるまで、何度も練習した。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "ピアノの曲[きょく]を覚[おぼ]えるまで、何度[なんど]も練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "漢字は書きながら覚えると、忘れにくい。", "target_word": "覚える", "complexity_tier": "T3", "furigana": "漢字[かんじ]は書[か]きながら覚[おぼ]えると、忘[わす]れにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覚える", "label": "辞書形"}, {"form": "覚えます", "label": "ます形"}, {"form": "覚えた", "label": "た形"}, {"form": "覚えて", "label": "て形"}, {"form": "覚えない", "label": "ない形"}, {"form": "覚えれば", "label": "ば形"}, {"form": "覚えさせる", "label": "使役形"}, {"form": "覚えられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "知識・技能・やり方を身につける（習得）。仕事・使い方・言葉などを覚える。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覚えたい", "is_correct": true, "explanation": "「覚えたいと思っている」で、仕事を身につけたいという希望を表し、文に合う。"}, {"text": "食べたい", "is_correct": false, "explanation": "仕事は食べるものではないので、「食べたい」では文の意味が通らない。"}, {"text": "洗いたい", "is_correct": false, "explanation": "仕事は洗うものではないので、「洗いたい」は意味が合わない。"}, {"text": "焼きたい", "is_correct": false, "explanation": "仕事は焼くものではないので、「焼きたい」は文に合わない。"}], "explanations": {"覚えたい": "「覚えたいと思っている」で、仕事を身につけたいという希望を表し、文に合う。", "食べたい": "仕事は食べるものではないので、「食べたい」では文の意味が通らない。", "洗いたい": "仕事は洗うものではないので、「洗いたい」は意味が合わない。", "焼きたい": "仕事は焼くものではないので、「焼きたい」は文に合わない。"}, "sentence_index": 0, "correct_answer": "覚えたい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は生徒に計算を覚えた。", "explanation": "ここは〈教える〉の意味。覚えるは自分が記憶や技能を身につけることで、人に教える場面では「教える」を使う。"}, {"text": "朝、鳥の声で目を覚えた。", "explanation": "ここは〈覚ます〉の意味。「目を覚ます」と言い、覚えるは記憶や習得なので目には使わない。"}, {"text": "子どものころの夏休みを、ふと覚えた。", "explanation": "ここは〈思い出す〉の意味。覚えるは記憶に留めることで、ふと記憶がよみがえる場面では「思い出す」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覚えさせる", "is_correct": true, "explanation": "使役形で、犬に覚えさせるという意味になり、文に合う。"}, {"text": "食べさせる", "is_correct": false, "explanation": "「お座り」は食べさせるものではないので、意味が合わない。"}, {"text": "洗わせる", "is_correct": false, "explanation": "「お座り」は洗わせるものではないので、意味が合わない。"}, {"text": "運ばせる", "is_correct": false, "explanation": "「お座り」は運ばせるものではないので、意味が合わない。"}], "explanations": {"覚えさせる": "使役形で、犬に覚えさせるという意味になり、文に合う。", "食べさせる": "「お座り」は食べさせるものではないので、意味が合わない。", "洗わせる": "「お座り」は洗わせるものではないので、意味が合わない。", "運ばせる": "「お座り」は運ばせるものではないので、意味が合わない。"}, "sentence_index": 6, "correct_answer": "覚えさせる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夢から覚えて、汗をかいていた。", "explanation": "ここは〈覚める〉の意味。覚えるは記憶や習得なので、目が覚める意味には使わない。"}, {"text": "彼は本当の気持ちを覚えた。", "explanation": "ここは〈悟る〉の意味。覚えるは記憶することなので、相手の気持ちを察する場面では合わない。"}, {"text": "彼はついに、会社を辞める覚悟を覚えた。", "explanation": "ここは〈決める〉の意味。覚悟は「覚悟を決める」と言い、覚えるとは言わないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい漢字が覚えるのに、時間がかかった。", "corrected_sentence": "新しい漢字を覚えるのに、時間がかかった。", "error_description": "覚えるは他動詞なので、目的語には「を」を使う。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "覚えた", "is_correct": true, "explanation": "た形で、過去の完了を表す。文中の形と一致する。"}, {"text": "覚えて", "is_correct": false, "explanation": "て形は文を続ける形で、ここでは文末にならない。"}, {"text": "覚えない", "is_correct": false, "explanation": "ない形は否定を表し、「すぐに覚えた」という過去の出来事と合わない。"}, {"text": "覚えます", "is_correct": false, "explanation": "ます形は丁寧語で、普通体の文と合わない。"}], "correct_form": "覚えた", "base_form": "覚える", "form_label": "た形", "sentence_index": 1, "explanations": {"覚えた": "た形で、過去の完了を表す。文中の形と一致する。", "覚えて": "て形は文を続ける形で、ここでは文末にならない。", "覚えない": "ない形は否定を表し、「すぐに覚えた」という過去の出来事と合わない。", "覚えます": "ます形は丁寧語で、普通体の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35049, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験前に教科書を覚えたまで、何度も読んだ。", "corrected_sentence": "試験前に教科書を覚えるまで、何度も読んだ。", "error_description": "「まで」の前には辞書形を置く。「覚えたまで」は誤りで、正しくは「覚えるまで」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "覚える", "is_correct": true, "explanation": "辞書形で、「～と」の条件を作る形として文に合う。"}, {"text": "覚えて", "is_correct": false, "explanation": "て形は「と」の前に続かず、「覚えてと」は文が成り立たない。"}, {"text": "覚えた", "is_correct": false, "explanation": "た形は「と」の前に続かず、「覚えたと」は文として成り立たない。"}, {"text": "覚えろ", "is_correct": false, "explanation": "命令形で、「と」の条件文には続かず成り立たない。"}], "correct_form": "覚える", "base_form": "覚える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"覚える": "辞書形で、「～と」の条件を作る形として文に合う。", "覚えて": "て形は「と」の前に続かず、「覚えてと」は文が成り立たない。", "覚えた": "た形は「と」の前に続かず、「覚えたと」は文として成り立たない。", "覚えろ": "命令形で、「と」の条件文には続かず成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「自分で考えなさい」の「で」。独力で考えるよう求める意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「自分に考えなさい」は相手を示す「に」になり、考える様子を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「自分へ考えなさい」では考える内容が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「自分より考えなさい」となり、命令の意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "正解。「自分で考えなさい」の「で」。独力で考えるよう求める意味になる。", "に": "「自分に考えなさい」は相手を示す「に」になり、考える様子を表せない。", "へ": "「へ」は方向を示すため、「自分へ考えなさい」では考える内容が成り立たない。", "より": "比較の「より」では「自分より考えなさい」となり、命令の意味が通らない。"}, "error_tags": {"に": "相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、頭の中でうごかすことです。", "primary_collocate": null, "pronunciation": "かんがえる", "ipa": "kaŋɡaeɾɯ", "syllable_count": 5, "sentences": [{"text": "テストの答えを、静かに考えています。", "target_word": "考えています", "complexity_tier": "T3", "furigana": "テストの答[こた]えを、静[しず]かに考[かんが]えています。", "sentence_source": "generated"}, {"text": "わたしは夏休みに何をするか考えた。", "target_word": "考えた", "complexity_tier": "T3", "furigana": "わたしは夏休[なつやす]みに何[なに]をするか考[かんが]えた。", "sentence_source": "generated"}, {"text": "むずかしい算数の問題を、ゆっくり考える。", "target_word": "考える", "complexity_tier": "T3", "furigana": "むずかしい算数[さんすう]の問題[もんだい]を、ゆっくり考[かんが]える。", "sentence_source": "generated"}, {"text": "弟は、おもちゃの名前を考えて、紙に書いた。", "target_word": "考えて", "complexity_tier": "T3", "furigana": "弟[おとうと]は、おもちゃの名前[なまえ]を考[かんが]えて、紙[かみ]に書[か]いた。", "sentence_source": "generated"}, {"text": "よく考えてから、手をあげましょう。", "target_word": "考えて", "complexity_tier": "T3", "furigana": "よく考[かんが]えてから、手[て]をあげましょう。", "sentence_source": "generated"}, {"text": "母は、今日の晩ごはんを何にするか考えている。", "target_word": "考えている", "complexity_tier": "T3", "furigana": "母[はは]は、今日[きょう]の晩[ばん]ごはんを何[なに]にするか考[かんが]えている。", "sentence_source": "generated"}, {"text": "「どうしてだろう」と、空を見ながら考えた。", "target_word": "考えた", "complexity_tier": "T3", "furigana": "「どうしてだろう」と、空[そら]を見[み]ながら考[かんが]えた。", "sentence_source": "generated"}, {"text": "先生は、生徒に「自分で考えなさい」と言った。", "target_word": "考えなさい", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]に「自分[じぶん]で考[かんが]えなさい」と言[い]った。", "sentence_source": "generated"}, {"text": "かれはだまって考えていて、何も言わなかった。", "target_word": "考えて", "complexity_tier": "T3", "furigana": "かれはだまって考[かんが]えていて、何[なに]も言[い]わなかった。", "sentence_source": "generated"}, {"text": "人の話を聞いて、それについて自分なりに考えます。", "target_word": "考えます", "complexity_tier": "T3", "furigana": "人[ひと]の話[はなし]を聞[き]いて、それについて自分[じぶん]なりに考[かんが]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "考える", "label": "辞書形"}, {"form": "考えない", "label": "否定形"}, {"form": "考えます", "label": "丁寧形"}, {"form": "考えた", "label": "過去形"}, {"form": "考えて", "label": "て形"}, {"form": "考えれば", "label": "仮定形"}, {"form": "考えよう", "label": "意志形"}, {"form": "考えられる", "label": "可能・受身形"}], "register": "neutral", "sense_fingerprint": "頭の中でものごとをあれこれ動かして思う（答えや方法を考える）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考えています", "is_correct": true, "explanation": "「テストの答えを静かに考えています」は、答えを思案中という文脈に合う。"}, {"text": "壊しています", "is_correct": false, "explanation": "「テストの答えを壊しています」は意味が通らない。"}, {"text": "割っています", "is_correct": false, "explanation": "「答えを割っています」は動作として成り立たず、思案の意味にならない。"}, {"text": "洗っています", "is_correct": false, "explanation": "「答えを洗っています」は不自然で、思案の文脈に合わない。"}], "explanations": {"考えています": "「テストの答えを静かに考えています」は、答えを思案中という文脈に合う。", "壊しています": "「テストの答えを壊しています」は意味が通らない。", "割っています": "「答えを割っています」は動作として成り立たず、思案の意味にならない。", "洗っています": "「答えを洗っています」は不自然で、思案の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "考えています"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で濡れた靴を、よく考えて乾かした。", "explanation": "ここは濡れたものから水気を取る動作の意味。「考える」は思案の動詞なので、乾燥させる行為には使えない。"}, {"text": "窓ガラスの汚れを、布で考えて拭いた。", "explanation": "ここは布でこすって汚れを取る動作の意味。「考える」は思案の動詞で、こする行為には合わない。"}, {"text": "祖母の声が遠くから、考えて聞こえた。", "explanation": "ここは耳に音が届く感覚の意味。「考える」は思案の動詞で、音が伝わる現象には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考えた", "is_correct": true, "explanation": "「空を見ながら考えた」は、思案しながら空を見た様子を表し、文脈に合う。"}, {"text": "直した", "is_correct": false, "explanation": "「空を見ながら直した」は、動作として文脈に合わない。"}, {"text": "運んだ", "is_correct": false, "explanation": "「空を見ながら運んだ」は意味が通らない。"}, {"text": "磨いた", "is_correct": false, "explanation": "「空を磨いた」は不自然で、思案の文脈に合わない。"}], "explanations": {"考えた": "「空を見ながら考えた」は、思案しながら空を見た様子を表し、文脈に合う。", "直した": "「空を見ながら直した」は、動作として文脈に合わない。", "運んだ": "「空を見ながら運んだ」は意味が通らない。", "磨いた": "「空を磨いた」は不自然で、思案の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "考えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空の星が、考えて瞬いた。", "explanation": "ここは光を放つ様子の意味。「考える」は思案の動詞で、光る現象には使えない。"}, {"text": "久しぶりに会った友人の顔を、ふと考えた。", "explanation": "ここは〈思い出す〉の意味。記憶から呼び起こす行為を「考える」で言うのは誤り。"}, {"text": "その試合の結果を、大声で考えて喜んだ。", "explanation": "ここは歓声を上げて感情を表す意味。「考える」は思案の動詞で、感情を大声で表す行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい計画が、家族みんなで考えています。", "corrected_sentence": "新しい計画を、家族みんなで考えています。", "error_description": "「考える」の対象は「を」で示す。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "考えた", "is_correct": true, "explanation": "過去形で、何をするか思案した完了の動作に合う。"}, {"text": "考えない", "is_correct": false, "explanation": "否定形で、思案しなかったという逆の意味になる。"}, {"text": "考えれば", "is_correct": false, "explanation": "仮定形で、「何をするか考えれば」は文として止まり、過去の完了の文にならない。"}, {"text": "考えて", "is_correct": false, "explanation": "て形では文が終わらず、過去の完了の文として成り立たない。"}], "correct_form": "考えた", "base_form": "考える", "form_label": "過去形", "sentence_index": 1, "explanations": {"考えた": "過去形で、何をするか思案した完了の動作に合う。", "考えない": "否定形で、思案しなかったという逆の意味になる。", "考えれば": "仮定形で、「何をするか考えれば」は文として止まり、過去の完了の文にならない。", "考えて": "て形では文が終わらず、過去の完了の文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅先の宿を、自分で考え予約した。", "corrected_sentence": "旅先の宿を、自分で考えて予約した。", "error_description": "「考える」のて形「考えて」の「て」が抜けている。「考え」だけでは後に続かず、「考えて予約した」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "考えなさい", "is_correct": true, "explanation": "命令の形で、教師が生徒に自分で思案するよう求める文脈に合う。"}, {"text": "考えよう", "is_correct": false, "explanation": "勧誘の形で、命令の文脈に合わない。"}, {"text": "考えられる", "is_correct": false, "explanation": "可能の意味になり、命令の文脈に合わない。"}, {"text": "考えれば", "is_correct": false, "explanation": "仮定形で、引用の中の文が途中で止まり、命令として成立しない。"}], "correct_form": "考えなさい", "base_form": "考える", "form_label": "命令形", "sentence_index": 7, "explanations": {"考えなさい": "命令の形で、教師が生徒に自分で思案するよう求める文脈に合う。", "考えよう": "勧誘の形で、命令の文脈に合わない。", "考えられる": "可能の意味になり、命令の文脈に合わない。", "考えれば": "仮定形で、引用の中の文が途中で止まり、命令として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「家族みんなで」は、家族全員が一緒に考えるという様子を表す「で」。"}, {"text": "に", "is_correct": false, "explanation": "「家族みんなに考えている」では相手や方向の「に」になり、考える様子が示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「家族みんなへ考えている」は動作の様子を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「家族みんなから考えている」となり、一緒に考える意味が出ない。"}], "correct_answer": "で", "explanations": {"で": "正解。「家族みんなで」は、家族全員が一緒に考えるという様子を表す「で」。", "に": "「家族みんなに考えている」では相手や方向の「に」になり、考える様子が示せず文が成り立たない。", "へ": "「へ」は方向を示すため、「家族みんなへ考えている」は動作の様子を表せない。", "から": "起点の「から」では「家族みんなから考えている」となり、一緒に考える意味が出ない。"}, "error_tags": {"に": "相手・方向", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "頭を使って、何かについて思いをめぐらせたり、判断したりすること。", "primary_collocate": null, "pronunciation": "かんがえる", "ipa": "kaŋɡaeɾɯ", "syllable_count": 5, "sentences": [{"text": "単なる物置きではなく、創造性を刺激する空間にしたいと考えたのだ。", "target_word": "考えた", "complexity_tier": "T3", "furigana": "単[たん]なる物置[ものお]きではなく、創造性[そうぞうせい]を刺激[しげき]する空間[くうかん]にしたいと考[かんが]えたのだ。", "sentence_source": "mined"}, {"text": "来月の旅行の計画を、家族みんなで考えている。", "target_word": "考えている", "complexity_tier": "T3", "furigana": "来月[らいげつ]の旅行[りょこう]の計画[けいかく]を、家族[かぞく]みんなで考[かんが]えている。", "sentence_source": "generated"}, {"text": "彼女は将来のことを真剣に考えて、進路を決めた。", "target_word": "考えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は将来[しょうらい]のことを真剣[しんけん]に考[かんが]えて、進路[しんろ]を決[き]めた。", "sentence_source": "generated"}, {"text": "よく考えてから、返事をしてください。", "target_word": "考えて", "complexity_tier": "T3", "furigana": "よく考[かんが]えてから、返事[へんじ]をしてください。", "sentence_source": "generated"}, {"text": "私はこの問題には別の解決方法があると考える。", "target_word": "考える", "complexity_tier": "T3", "furigana": "私[わたし]はこの問題[もんだい]には別[べつ]の解決[かいけつ]方法[ほうほう]があると考[かんが]える。", "sentence_source": "generated"}, {"text": "友達の気持ちを考えずに話してしまい、後悔した。", "target_word": "考えず", "complexity_tier": "T3", "furigana": "友達[ともだち]の気持[きも]ちを考[かんが]えずに話[はな]してしまい、後悔[こうかい]した。", "sentence_source": "generated"}, {"text": "彼は転職するべきかどうか、一週間考えた。", "target_word": "考えた", "complexity_tier": "T3", "furigana": "彼[かれ]は転職[てんしょく]するべきかどうか、一週間[いっしゅうかん]考[かんが]えた。", "sentence_source": "generated"}, {"text": "新しい店の名前を、みんなで考えよう。", "target_word": "考えよう", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の名前[なまえ]を、みんなで考[かんが]えよう。", "sentence_source": "generated"}, {"text": "社長は海外に工場を作ることを考えているそうだ。", "target_word": "考えている", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は海外[かいがい]に工場[こうじょう]を作[つく]ることを考[かんが]えているそうだ。", "sentence_source": "generated"}, {"text": "もう少し考える時間をもらえませんか。", "target_word": "考える", "complexity_tier": "T3", "furigana": "もう少[すこ]し考[かんが]える時間[じかん]をもらえませんか。", "sentence_source": "generated"}], "morphological_forms": [{"form": "考える", "label": "辞書形"}, {"form": "考えない", "label": "否定形"}, {"form": "考えます", "label": "丁寧形"}, {"form": "考えた", "label": "過去形"}, {"form": "考えて", "label": "て形"}, {"form": "考えれば", "label": "仮定形"}, {"form": "考えよう", "label": "意志形"}, {"form": "考えられる", "label": "可能・受身形"}], "register": "neutral", "sense_fingerprint": "頭を使って思いをめぐらせ、判断や結論を出す（考えを持つ・思案する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考えた", "is_correct": true, "explanation": "「したいと考えたのだ」は、思案して思い至った内容を表し、文脈に合う。"}, {"text": "壊した", "is_correct": false, "explanation": "「空間にしたいと壊したのだ」は意味が通らず、思案の動詞ではない。"}, {"text": "忘れた", "is_correct": false, "explanation": "「したいと忘れたのだ」は文脈に合わず、後半の意図の説明にならない。"}, {"text": "買った", "is_correct": false, "explanation": "「したいと買ったのだ」は不自然で、目的の思いを表せない。"}], "explanations": {"考えた": "「したいと考えたのだ」は、思案して思い至った内容を表し、文脈に合う。", "壊した": "「空間にしたいと壊したのだ」は意味が通らず、思案の動詞ではない。", "忘れた": "「したいと忘れたのだ」は文脈に合わず、後半の意図の説明にならない。", "買った": "「したいと買ったのだ」は不自然で、目的の思いを表せない。"}, "sentence_index": 0, "correct_answer": "考えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "床に落ちた指輪を、考えてそっと拾い上げた。", "explanation": "ここは落ちた物を手で取り上げる動作の意味。「考える」は思案の動詞なので、物を手に取る行為には合わない。"}, {"text": "夕焼けを見て、胸が締めつけられるように考えた。", "explanation": "ここは〈感じる〉の意味。心に湧く感覚は「考える」では表せない。"}, {"text": "転んだ子どもを、すぐに考えて抱き起こした。", "explanation": "ここは〈助ける〉の意味。手を差し伸べる行為を「考える」で言うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考えた", "is_correct": true, "explanation": "「一週間考えた」は、転職について思案し続けた期間を表し、文脈に合う。"}, {"text": "直した", "is_correct": false, "explanation": "「一週間直した」は、転職の判断には使えず、意味が通らない。"}, {"text": "割った", "is_correct": false, "explanation": "「一週間割った」は動作として成り立たず、思案の意味にならない。"}, {"text": "運んだ", "is_correct": false, "explanation": "「一週間運んだ」は転職の判断を表す文脈に合わない。"}], "explanations": {"考えた": "「一週間考えた」は、転職について思案し続けた期間を表し、文脈に合う。", "直した": "「一週間直した」は、転職の判断には使えず、意味が通らない。", "割った": "「一週間割った」は動作として成り立たず、思案の意味にならない。", "運んだ": "「一週間運んだ」は転職の判断を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "考えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で濡れた床を、考えて乾いた布で拭いた。", "explanation": "ここは布でこすって汚れを取る動作の意味。「考える」は思案の動詞で、こする行為には使えない。"}, {"text": "ガラスの花瓶を、考えて割った。", "explanation": "ここは物を壊す動作の意味。「考える」は思案の動詞で、壊す行為には使えない。"}, {"text": "冷えた手を、考えてこすった。", "explanation": "ここは手を軽くなでて温める動作の意味。「考える」は思案の動詞で、なでる行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その問題に、もう一度考えてみよう。", "corrected_sentence": "その問題を、もう一度考えてみよう。", "error_description": "「考える」の対象は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "考えている", "is_correct": true, "explanation": "〜ている形で継続を表し、家族で計画を考え続けている文脈に合う。"}, {"text": "考えない", "is_correct": false, "explanation": "否定形で、計画を考えているという事実と逆の意味になる。"}, {"text": "考えれば", "is_correct": false, "explanation": "仮定形で、「家族みんなで考えれば」は文として止まり、継続の文として成り立たない。"}, {"text": "考えて", "is_correct": false, "explanation": "て形のままでは文を終えられず、「ている」の継続の意味が出ない。"}], "correct_form": "考えている", "base_form": "考える", "form_label": "〜ている形（継続）", "sentence_index": 1, "explanations": {"考えている": "〜ている形で継続を表し、家族で計画を考え続けている文脈に合う。", "考えない": "否定形で、計画を考えているという事実と逆の意味になる。", "考えれば": "仮定形で、「家族みんなで考えれば」は文として止まり、継続の文として成り立たない。", "考えて": "て形のままでは文を終えられず、「ている」の継続の意味が出ない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35051, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画を、今は考えるない。", "corrected_sentence": "その計画を、今は考えない。", "error_description": "「考える」の否定形は語幹「考え」に「ない」を続けて「考えない」。「考えるない」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "考えよう", "is_correct": true, "explanation": "意志・勧誘の形で、「みんなで考えよう」と誘う文脈に合う。"}, {"text": "考えた", "is_correct": false, "explanation": "過去形なので「みんなで考えた」は既に思案した事実を述べ、誘いの文脈に合わない。"}, {"text": "考えられる", "is_correct": false, "explanation": "可能の意味になり、勧誘の文脈に合わない。"}, {"text": "考えろ", "is_correct": false, "explanation": "命令形で相手に強く指示する形になり、一緒に誘う文脈に合わない。"}], "correct_form": "考えよう", "base_form": "考える", "form_label": "意志・勧誘形", "sentence_index": 7, "explanations": {"考えよう": "意志・勧誘の形で、「みんなで考えよう」と誘う文脈に合う。", "考えた": "過去形なので「みんなで考えた」は既に思案した事実を述べ、誘いの文脈に合わない。", "考えられる": "可能の意味になり、勧誘の文脈に合わない。", "考えろ": "命令形で相手に強く指示する形になり、一緒に誘う文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「世界の選手」で、世界が選手を修飾する関係を表し、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「世界が選手」と続けると修飾の関係にならず、文が不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や時を表すので、「世界に選手」では世界が選手を修飾する関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すので、「世界と選手」では世界を選手の修飾語として示せず、意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "「世界の選手」で、世界が選手を修飾する関係を表し、文に合う。", "が": "「が」は主語を表すが、「世界が選手」と続けると修飾の関係にならず、文が不自然になる。", "に": "「に」は到達点や時を表すので、「世界に選手」では世界が選手を修飾する関係が成り立たない。", "と": "「と」は並列を表すので、「世界と選手」では世界を選手の修飾語として示せず、意味が合わない。"}, "error_tags": {"が": "主格", "に": "到達点・時", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地球全体と、そこにいるすべての人々。", "primary_collocate": null, "pronunciation": "せかい", "ipa": "sekai", "syllable_count": 3, "sentences": [{"text": "世界には、たくさんの国と言葉がある。", "target_word": "世界", "complexity_tier": "T3", "furigana": "世界[せかい]には、たくさんの国[くに]と言葉[ことば]がある。", "sentence_source": "generated"}, {"text": "宇宙飛行士の話を聞いて、世界の見え方が変わった。", "target_word": "世界", "complexity_tier": "T3", "furigana": "宇宙飛行士[うちゅうひこうし]の話[はなし]を聞[き]いて、世界[せかい]の見[み]え方[かた]が変[か]わった。", "sentence_source": "generated"}, {"text": "世界で一番高い山は、エベレストだ。", "target_word": "世界", "complexity_tier": "T3", "furigana": "世界[せかい]で一番[いちばん]高[たか]い山[やま]は、エベレストだ。", "sentence_source": "generated"}, {"text": "この映画は、世界の多くの人に愛されている。", "target_word": "世界", "complexity_tier": "T3", "furigana": "この映画[えいが]は、世界[せかい]の多[おお]くの人[ひと]に愛[あい]されている。", "sentence_source": "generated"}, {"text": "日本の料理は、世界でも人気が高い。", "target_word": "世界", "complexity_tier": "T3", "furigana": "日本[にほん]の料理[りょうり]は、世界[せかい]でも人気[にんき]が高[たか]い。", "sentence_source": "generated"}, {"text": "地図を見ながら、世界の国の名前を覚えた。", "target_word": "世界", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ながら、世界[せかい]の国[くに]の名前[なまえ]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "世界の人口は、八十億人を超えている。", "target_word": "世界", "complexity_tier": "T3", "furigana": "世界[せかい]の人口[じんこう]は、八十億人[はちじゅうおくにん]を超[こ]えている。", "sentence_source": "generated"}, {"text": "オリンピックでは、世界の選手が一つの町に集まる。", "target_word": "世界", "complexity_tier": "T3", "furigana": "オリンピックでは、世界[せかい]の選手[せんしゅ]が一[ひと]つの町[まち]に集[あつ]まる。", "sentence_source": "generated"}, {"text": "インターネットで、世界の人と話せるようになった。", "target_word": "世界", "complexity_tier": "T3", "furigana": "インターネットで、世界[せかい]の人[ひと]と話[はな]せるようになった。", "sentence_source": "generated"}, {"text": "子どものころ、世界が広いことを知って驚いた。", "target_word": "世界", "complexity_tier": "T3", "furigana": "子[こ]どものころ、世界[せかい]が広[ひろ]いことを知[し]って驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "世界", "label": "基本形"}, {"form": "世界の", "label": "連体修飾（の）"}, {"form": "世界中", "label": "複合語"}], "register": "中立", "sense_fingerprint": "地球全体とそこにいる人々。世界中・世界の国々、の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a83c9026-1131-4ee0-b98b-f62e56181ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界", "is_correct": true, "explanation": "地球全体とそこにいる人々を指し、国と言葉が多くあるという文に合う。"}, {"text": "水", "is_correct": false, "explanation": "水に国や言葉があるとは言えず、文の意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "時計に国や言葉があるとは言えず、文の意味が通らない。"}, {"text": "電車", "is_correct": false, "explanation": "電車に国や言葉があるとは言えず、文の意味が通らない。"}], "explanations": {"世界": "地球全体とそこにいる人々を指し、国と言葉が多くあるという文に合う。", "水": "水に国や言葉があるとは言えず、文の意味が通らない。", "時計": "時計に国や言葉があるとは言えず、文の意味が通らない。", "電車": "電車に国や言葉があるとは言えず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "世界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その国の世界は、この一年で人口が倍になった。", "explanation": "ここは〈国〉の意味。世界は地球全体とそこにいる人々を指すので、一つの国を指す場面には使わない。"}, {"text": "この町の世界は、夜になると人がいなくなる。", "explanation": "ここは〈町〉の意味。世界は地球全体を指すので、町という範囲を言うときには使わない。"}, {"text": "この大陸の世界は、冬になると雪でおおわれる。", "explanation": "ここは〈大陸〉の意味。世界は地球全体を指すので、一つの大陸だけを指す場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界", "is_correct": true, "explanation": "地球全体とそこにいる人々を指し、人口が八十億人を超えるという文に合う。"}, {"text": "地図", "is_correct": false, "explanation": "地図には人口がないので、「地図の人口」では意味が通らない。"}, {"text": "花", "is_correct": false, "explanation": "花の人口とは言えず、文の意味が通らない。"}, {"text": "空", "is_correct": false, "explanation": "空の人口とは言えず、文の意味が通らない。"}], "explanations": {"世界": "地球全体とそこにいる人々を指し、人口が八十億人を超えるという文に合う。", "地図": "地図には人口がないので、「地図の人口」では意味が通らない。", "花": "花の人口とは言えず、文の意味が通らない。", "空": "空の人口とは言えず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "世界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この村の世界は、毎年夏に祭りを開く。", "explanation": "ここは〈村〉の意味。世界は地球全体を指すので、村という範囲を言うときには使わない。"}, {"text": "この駅の世界は、朝になると人でいっぱいになる。", "explanation": "ここは〈駅〉の意味。世界は地球全体を指すので、駅という場所を言うときには使わない。"}, {"text": "この工場の世界は、テストの前になると静かになる。", "explanation": "ここは〈工場〉の意味。世界は地球全体を指すので、工場という場所を言うときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世界が歴史を学んだ。", "corrected_sentence": "世界の歴史を学んだ。", "error_description": "「世界」と「歴史」は修飾の関係なので「の」を使う。「が」は誤りで、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世界間で、同じ歌が流行している。", "corrected_sentence": "世界中で、同じ歌が流行している。", "error_description": "「世界中」は一語の複合語で、「世界間」は誤り。正しくは「世界中」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b7d812-fd7d-4c56-a2b5-f84d48f625f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「面白い事があった」の「が」で、事が存在・発生することを示す。"}, {"text": "を", "is_correct": false, "explanation": "「面白い事をあった」では目的語の位置に合わず、文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「面白い事のあった」は動詞に続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「面白い事へあった」では方向の意味になり、存在を表す文として合わない。"}], "correct_answer": "が", "explanations": {"が": "「面白い事があった」の「が」で、事が存在・発生することを示す。", "を": "「面白い事をあった」では目的語の位置に合わず、文が成立しない。", "の": "連体の「の」。「面白い事のあった」は動詞に続かず不自然。", "へ": "「面白い事へあった」では方向の意味になり、存在を表す文として合わない。"}, "error_tags": {"を": "object", "の": "possessive", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事を黒板に書いた」の「を」で、書く対象である事柄を示す。"}, {"text": "が", "is_correct": false, "explanation": "「事が黒板に書いた」では書く動作の対象にならず、文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「事で黒板に書いた」では手段や場所の意味になり、書く対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「事へ黒板に書いた」では方向の意味になり、書く内容を示さない。"}], "correct_answer": "を", "explanations": {"を": "「事を黒板に書いた」の「を」で、書く対象である事柄を示す。", "が": "「事が黒板に書いた」では書く動作の対象にならず、文として不自然。", "で": "「事で黒板に書いた」では手段や場所の意味になり、書く対象を示せない。", "へ": "「事へ黒板に書いた」では方向の意味になり、書く内容を示さない。"}, "error_tags": {"が": "subject", "で": "location/means", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "おこったことや、できごと。", "primary_collocate": null, "pronunciation": "こと", "ipa": "koto", "syllable_count": 2, "sentences": [{"text": "昨日、駅の前で大変な事が起こった。", "target_word": "事", "complexity_tier": "T3", "furigana": "昨日[きのう]、駅[えき]の前[まえ]で大変[たいへん]な事[こと]が起[お]こった。", "sentence_source": "generated"}, {"text": "友達から、学校で面白い事があったと聞いた。", "target_word": "事", "complexity_tier": "T3", "furigana": "友達[ともだち]から、学校[がっこう]で面白[おもしろ]い事[こと]があったと聞[き]いた。", "sentence_source": "generated"}, {"text": "彼は去年の事をほとんど覚えていない。", "target_word": "事", "complexity_tier": "T3", "furigana": "彼[かれ]は去年[きょねん]の事[こと]をほとんど覚[おぼ]えていない。", "sentence_source": "generated"}, {"text": "悲しい事があった日は、早く寝ることにしている。", "target_word": "事", "complexity_tier": "T3", "furigana": "悲[かな]しい事[こと]があった日[ひ]は、早[はや]く寝[ね]ることにしている。", "sentence_source": "generated"}, {"text": "町で起きた事を、新聞が大きく伝えた。", "target_word": "事", "complexity_tier": "T3", "furigana": "町[まち]で起[お]きた事[こと]を、新聞[しんぶん]が大[おお]きく伝[つた]えた。", "sentence_source": "generated"}, {"text": "誰にも話さなかったが、本当は大きな事が起こっていた。", "target_word": "事", "complexity_tier": "T4", "furigana": "誰[だれ]にも話[はな]さなかったが、本当[ほんとう]は大[おお]きな事[こと]が起[お]こっていた。", "sentence_source": "generated"}, {"text": "子どものころの楽しい事を思い出して、笑ってしまった。", "target_word": "事", "complexity_tier": "T3", "furigana": "子[こ]どものころの楽[たの]しい事[こと]を思[おも]い出[だ]して、笑[わら]ってしまった。", "sentence_source": "generated"}, {"text": "先生は、その日に起きた事を黒板に書いた。", "target_word": "事", "complexity_tier": "T3", "furigana": "先生[せんせい]は、その日[ひ]に起[お]きた事[こと]を黒板[こくばん]に書[か]いた。", "sentence_source": "generated"}, {"text": "事の始まりは、小さな間違いだった。", "target_word": "事", "complexity_tier": "T4", "furigana": "事[こと]の始[はじ]まりは、小[ちい]さな間違[まちが]いだった。", "sentence_source": "generated"}, {"text": "旅行中にいろいろな事があって、忘れられない思い出になった。", "target_word": "事", "complexity_tier": "T4", "furigana": "旅行中[りょこうちゅう]にいろいろな事[こと]があって、忘[わす]れられない思[おも]い出[で]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事", "label": "基本形"}], "register": "plain", "sense_fingerprint": "起こった出来事・事柄（「事が起こる」「事がある」）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事", "is_correct": true, "explanation": "「大変な事が起こった」の「事」で、起きた出来事を表す。"}, {"text": "物", "is_correct": false, "explanation": "「大変な物が起こった」では物体の意味になり、出来事として合わない。"}, {"text": "人", "is_correct": false, "explanation": "「大変な人が起こった」では人物の意味になり、起きたことの説明にならない。"}, {"text": "声", "is_correct": false, "explanation": "「大変な声が起こった」では音声の意味になり、出来事を表さない。"}], "explanations": {"事": "「大変な事が起こった」の「事」で、起きた出来事を表す。", "物": "「大変な物が起こった」では物体の意味になり、出来事として合わない。", "人": "「大変な人が起こった」では人物の意味になり、起きたことの説明にならない。", "声": "「大変な声が起こった」では音声の意味になり、出来事を表さない。"}, "sentence_index": 0, "correct_answer": "事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、町で大きな事を買った。", "explanation": "「事」は出来事や用件の意味で、買える品物ではない。ここでは品物の意味と取り違えている。"}, {"text": "昨日、町で大きな事を始めた。", "explanation": "「事」は事業や仕事の意味で、始める対象になっている。出来事の意味ではない。"}, {"text": "昨日、町で大きな事を飲んだ。", "explanation": "「事」は出来事の意味で、飲めるものではない。ここでは飲み物と取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事", "is_correct": true, "explanation": "「楽しい事を思い出して」の「事」で、過去にあった出来事を指す。"}, {"text": "度", "is_correct": false, "explanation": "「楽しい度を思い出して」では程度の意味になり、思い出す対象として合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「楽しい窓を思い出して」では物の意味になり、思い出す出来事として合わない。"}, {"text": "紙", "is_correct": false, "explanation": "「楽しい紙を思い出して」では物の意味になり、思い出す出来事として合わない。"}], "explanations": {"事": "「楽しい事を思い出して」の「事」で、過去にあった出来事を指す。", "度": "「楽しい度を思い出して」では程度の意味になり、思い出す対象として合わない。", "窓": "「楽しい窓を思い出して」では物の意味になり、思い出す出来事として合わない。", "紙": "「楽しい紙を思い出して」では物の意味になり、思い出す出来事として合わない。"}, "sentence_index": 6, "correct_answer": "事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行中にいろいろな事を食べて、忘れられない思い出になった。", "explanation": "「事」は出来事の意味で、食べ物を表す語ではない。ここでは食品と取り違えている。"}, {"text": "旅行中にいろいろな事を眺めて、忘れられない思い出になった。", "explanation": "「事」は出来事の意味で、眺める景色を表す語ではない。ここでは景色と取り違えている。"}, {"text": "旅行中にいろいろな事を読んで、忘れられない思い出になった。", "explanation": "「事」は出来事の意味で、読む文章を表す語ではない。ここでは文章と取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、町で大きな事を起きた。", "corrected_sentence": "昨日、町で大きな事が起きた。", "error_description": "「起きる」は出来事が主語になるので「が」を使う。「事を」は誤りで、正しくは「事が」。誤りは目標語の直後の助詞だけ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35058, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、駅前で大きな事が起きる。", "corrected_sentence": "昨日、駅前で大きな事が起きた。", "error_description": "「昨日」と合う過去形が必要。「起きる」は現在形で誤りで、正しくは「起きた」。誤りは目標語の事に続く動詞の時制だけ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35060, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「古く」に続けて時代を区切る主題の「は」。「ずっと前は」の意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「古くが」は主語にならない。「が」は主語を示すので、時代を表す語には付かない。"}, {"text": "を", "is_correct": false, "explanation": "「古くを」は目的語にならない。「古く」は動作の対象ではないので「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「古くで」は場所や手段にならない。時を表す語には「で」は付かない。"}], "correct_answer": "は", "explanations": {"は": "「古く」に続けて時代を区切る主題の「は」。「ずっと前は」の意味になる。", "が": "「古くが」は主語にならない。「が」は主語を示すので、時代を表す語には付かない。", "を": "「古くを」は目的語にならない。「古く」は動作の対象ではないので「を」は合わない。", "で": "「古くで」は場所や手段にならない。時を表す語には「で」は付かない。"}, "error_tags": {"が": "主格（主語）", "を": "対格（目的語）", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
