INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35060, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっと前のこと。", "primary_collocate": null, "pronunciation": "ふるく", "ipa": "ɸɯɾɯkɯ", "syllable_count": 3, "sentences": [{"text": "古くは、この町は小さな漁村だった。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、この町(まち)は小(ちい)さな漁村(ぎょそん)だった。", "sentence_source": "generated"}, {"text": "古くは、米がお金の代わりに使われていた。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、米(こめ)がお金(かね)の代(か)わりに使(つか)われていた。", "sentence_source": "generated"}, {"text": "古くは、手紙が遠くの人に気持ちを伝える唯一の手段だった。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、手紙(てがみ)が遠(とお)くの人(ひと)に気持(きも)ちを伝(つた)える唯一(ゆいいつ)の手段(しゅだん)だった。", "sentence_source": "generated"}, {"text": "この神社の名前は、古くは「森の宮」と呼ばれていた。", "target_word": "古く", "complexity_tier": "T3", "furigana": "この神社(じんじゃ)の名前(なまえ)は、古(ふる)くは「森(もり)の宮(みや)」と呼(よ)ばれていた。", "sentence_source": "generated"}, {"text": "古くは、冬の食べ物を塩で保存したが、今は冷蔵庫を使う。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、冬(ふゆ)の食(た)べ物(もの)を塩(しお)で保存(ほぞん)したが、今(いま)は冷蔵庫(れいぞうこ)を使(つか)う。", "sentence_source": "generated"}, {"text": "古くは、この川で毎年大きな祭りが開かれていたそうだ。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、この川(かわ)で毎年(まいとし)大(おお)きな祭(まつ)りが開(ひら)かれていたそうだ。", "sentence_source": "generated"}, {"text": "古くは、井戸の水を毎日くんで使うのが普通だった。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、井戸(いど)の水(みず)を毎日(まいにち)くんで使(つか)うのが普通(ふつう)だった。", "sentence_source": "generated"}, {"text": "日本では古くは、お茶は薬として飲まれていた。", "target_word": "古く", "complexity_tier": "T3", "furigana": "日本(にほん)では古(ふる)くは、お茶(ちゃ)は薬(くすり)として飲(の)まれていた。", "sentence_source": "generated"}, {"text": "古くは、夜の道を月の明かりだけで歩いたものだ。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くは、夜(よる)の道(みち)を月(つき)の明(あ)かりだけで歩(ある)いたものだ。", "sentence_source": "generated"}, {"text": "この橋は古くは木でできていたが、今は石でできている。", "target_word": "古く", "complexity_tier": "T3", "furigana": "この橋(はし)は古(ふる)くは木(き)でできていたが、今(いま)は石(いし)でできている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "古く", "label": "基本形"}, {"form": "古くは", "label": "主題化"}, {"form": "古くに", "label": "時点"}], "register": "標準（普通体）", "sense_fingerprint": "古く（名詞）：ずっと前の時代。「古くは」の形で過去の状態を述べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35060, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古く", "is_correct": true, "explanation": "「ずっと前のこと」を指す名詞で、「古くは」の形で昔の状態を述べる。この空欄に入る。"}, {"text": "重く", "is_correct": false, "explanation": "「重く」は重さを表すので、昔の時代を示す主題にはならない。「重くは、この町は…」は意味が通らない。"}, {"text": "深く", "is_correct": false, "explanation": "「深く」は奥行きや程度を表すので、町の昔の姿を述べる主題にならない。"}, {"text": "強く", "is_correct": false, "explanation": "「強く」は力や程度の強さを表すので、昔の時代を示す文には入らない。"}], "explanations": {"古く": "「ずっと前のこと」を指す名詞で、「古くは」の形で昔の状態を述べる。この空欄に入る。", "重く": "「重く」は重さを表すので、昔の時代を示す主題にはならない。「重くは、この町は…」は意味が通らない。", "深く": "「深く」は奥行きや程度を表すので、町の昔の姿を述べる主題にならない。", "強く": "「強く」は力や程度の強さを表すので、昔の時代を示す文には入らない。"}, "sentence_index": 0, "correct_answer": "古く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くは、このあと五分で会議が始まる。", "explanation": "ここは〈これから〉の未来の意味。〈古く〉は過去の時点を指すので、これから始まる予定には合わない。"}, {"text": "古くは、試合の前にいつも頭が真っ白になる。", "explanation": "ここは〈直前〉の時間の意味。〈古く〉は「ずっと前」を表すので、試合の直前という時点には合わない。"}, {"text": "古くは、この町に大きな橋が架かるだろう。", "explanation": "ここは〈将来〉の意味を入れ替えた形。〈古く〉は過去の時代を指すので、未来の予測には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35060, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古く", "is_correct": true, "explanation": "「ずっと前」の時代を指す名詞で、「古くは」の形で過去の習慣を述べる。この空欄に入る。"}, {"text": "遠く", "is_correct": false, "explanation": "「遠く」は距離を表すので、井戸の水を使う習慣の時代を示せない。「遠くは」は意味が通らない。"}, {"text": "浅く", "is_correct": false, "explanation": "「浅く」は深さを表すので、時代の主題にはならない。"}, {"text": "高く", "is_correct": false, "explanation": "「高く」は高さや値段を表すので、昔の習慣を述べる文には入らない。"}], "explanations": {"古く": "「ずっと前」の時代を指す名詞で、「古くは」の形で過去の習慣を述べる。この空欄に入る。", "遠く": "「遠く」は距離を表すので、井戸の水を使う習慣の時代を示せない。「遠くは」は意味が通らない。", "浅く": "「浅く」は深さを表すので、時代の主題にはならない。", "高く": "「高く」は高さや値段を表すので、昔の習慣を述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "古く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古くは、この夏の暑さは例年より厳しかった。", "explanation": "ここは〈今年〉の意味。〈古く〉は遠い過去を指すので、この夏の出来事には合わない。"}, {"text": "古くは、さっき買ったばかりのパンがもう硬い。", "explanation": "ここは〈ごく最近〉の意味。〈古く〉は遠い過去を指すので、ついさっき買ったパンには合わない。"}, {"text": "古くは、ほんの数秒で答えが出た。", "explanation": "ここは〈短時間〉の意味。〈古く〉は遠い過去を指すので、数秒で済む出来事には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35060, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古くが、この村は小さな農村だった。", "corrected_sentence": "古くは、この村は小さな農村だった。", "error_description": "「古く」の後には主題の「は」が入る。「が」は主語を示すので、「ずっと前は」と時代を区切る文に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35060, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古くを、川の水を毎日くんで使うのが普通だった。", "corrected_sentence": "古くは、川の水を毎日くんで使うのが普通だった。", "error_description": "「古く」の後は主題の「は」が正しい。「を」は目的語を示すが、「古く」は目的語にならないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
