INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35061, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35061, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "昔から今まで、長い時間続いていることを表す。", "primary_collocate": null, "pronunciation": "ふるく", "ipa": "ɸɯɾɯkɯ", "syllable_count": 3, "sentences": [{"text": "この祭りは古くから、毎年秋に行われている。", "target_word": "古く", "complexity_tier": "T3", "furigana": "この祭(まつ)りは古(ふる)くから、毎年(まいとし)秋(あき)に行(おこな)われている。", "sentence_source": "generated"}, {"text": "古くから伝わる話を祖母が聞かせてくれた。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くから伝(つた)わる話(はなし)を祖母(そぼ)が聞(き)かせてくれた。", "sentence_source": "generated"}, {"text": "京都は古くから日本の文化の中心だった。", "target_word": "古く", "complexity_tier": "T3", "furigana": "京都(きょうと)は古(ふる)くから日本(にほん)の文化(ぶんか)の中心(ちゅうしん)だった。", "sentence_source": "generated"}, {"text": "この地方では古くから、米作りが盛んだ。", "target_word": "古く", "complexity_tier": "T3", "furigana": "この地方(ちほう)では古(ふる)くから、米作(こめづく)りが盛(さか)んだ。", "sentence_source": "generated"}, {"text": "古くからの友だちと、駅前の店で食事をした。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くからの友(とも)だちと、駅前(えきまえ)の店(みせ)で食事(しょくじ)をした。", "sentence_source": "generated"}, {"text": "古くから使われている道具は、今でも大切にされている。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くから使(つか)われている道具(どうぐ)は、今(いま)でも大切(たいせつ)にされている。", "sentence_source": "generated"}, {"text": "このお寺は古くから、町の人に親しまれてきた。", "target_word": "古く", "complexity_tier": "T3", "furigana": "このお寺(てら)は古(ふる)くから、町(まち)の人(ひと)に親(した)しまれてきた。", "sentence_source": "generated"}, {"text": "古くから、赤い色には悪いものを防ぐ力があると信じられている。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くから、赤(あか)い色(いろ)には悪(わる)いものを防(ふせ)ぐ力(ちから)があると信(しん)じられている。", "sentence_source": "generated"}, {"text": "この家には古くから、先祖の写真が飾られている。", "target_word": "古く", "complexity_tier": "T3", "furigana": "この家(いえ)には古(ふる)くから、先祖(せんぞ)の写真(しゃしん)が飾(かざ)られている。", "sentence_source": "generated"}, {"text": "古くからあるパン屋なので、近所の人はみんな知っている。", "target_word": "古く", "complexity_tier": "T3", "furigana": "古(ふる)くからあるパン屋(や)なので、近所(きんじょ)の人(ひと)はみんな知(し)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "古く", "label": "基本形"}, {"form": "古くから", "label": "起点"}, {"form": "古くからの", "label": "連体修飾"}], "register": "標準（普通体）", "sense_fingerprint": "古く（副詞的）：「古くから」の形で、昔から今まで長く続いていることを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35061, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古く", "is_correct": true, "explanation": "「昔から」の意味の副詞。「古くから」の形で、昔から今まで続く状態を表す。"}, {"text": "強く", "is_correct": false, "explanation": "「強く」は力の程度を表すので、「強くから」は起点として意味が通らない。"}, {"text": "厚く", "is_correct": false, "explanation": "「厚く」は厚さを表すので、「厚くから」は時間の起点にならない。"}, {"text": "深く", "is_correct": false, "explanation": "「深く」は深さや程度を表すので、「深くから」は時間の起点として使えない。"}], "explanations": {"古く": "「昔から」の意味の副詞。「古くから」の形で、昔から今まで続く状態を表す。", "強く": "「強く」は力の程度を表すので、「強くから」は起点として意味が通らない。", "厚く": "「厚く」は厚さを表すので、「厚くから」は時間の起点にならない。", "深く": "「深く」は深さや程度を表すので、「深くから」は時間の起点として使えない。"}, "sentence_index": 0, "correct_answer": "古く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くから、このカップは一度も使っていない新品だ。", "explanation": "ここは〈新しい状態〉の意味。〈古くから〉は昔から続く状態を表すので、使ったことのない新品の状態とは両立しない。"}, {"text": "古くから、明日の朝から走ることにした。", "explanation": "ここは〈これから〉の意味。〈古くから〉は昔から続く状態を表すので、明日始める決意には合わない。"}, {"text": "古くから、雨が降り出した。", "explanation": "ここは〈突然〉の意味を入れ替えた形。〈古くから〉は長く続く状態を表すので、急に始まった出来事には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35061, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古く", "is_correct": true, "explanation": "「昔から」の意味の副詞。「古くから」の形で、昔から続く状態を表す。"}, {"text": "浅く", "is_correct": false, "explanation": "「浅く」は深さを表すので、「浅くから」は時間の起点として意味が通らない。"}, {"text": "高く", "is_correct": false, "explanation": "「高く」は高さや値段を表すので、「高くから」は時間の起点にならない。"}, {"text": "赤く", "is_correct": false, "explanation": "「赤く」は色の状態を表すので、「赤くから」は時間の起点として使えない。"}], "explanations": {"古く": "「昔から」の意味の副詞。「古くから」の形で、昔から続く状態を表す。", "浅く": "「浅く」は深さを表すので、「浅くから」は時間の起点として意味が通らない。", "高く": "「高く」は高さや値段を表すので、「高くから」は時間の起点にならない。", "赤く": "「赤く」は色の状態を表すので、「赤くから」は時間の起点として使えない。"}, "sentence_index": 6, "correct_answer": "古く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古くから、この機械は今ちょうど動き始めたところだ。", "explanation": "ここは〈たった今〉の意味。〈古くから〉は昔から続く状態を表すので、今動き始めたばかりの状態には合わない。"}, {"text": "古くから、このパン屋は行列ができるようになった。", "explanation": "ここは〈最近〉の意味を入れ替えた形。〈古くから〉は昔から続く状態を表すので、最近始まった変化には合わない。"}, {"text": "古くから、店長が開店の挨拶をした。", "explanation": "ここは〈開店時の一時点〉の意味。〈古くから〉は長く続く状態を表すので、一度きりの挨拶の時点には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35061, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この神社では古くに、毎年祭りを行っている。", "corrected_sentence": "この神社では古くから、毎年祭りを行っている。", "error_description": "「古くに」は一つの時点を指す形。毎年続けている祭りには、起点を示す「古くから」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
