INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35062, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本を読むことにした」で、読む対象を示す目的語の格助詞として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「本に読む」は不自然で、読む対象を示すには合わない。"}, {"text": "が", "is_correct": false, "explanation": "「本が読む」では本が主語になり、読む主体として合わない。"}, {"text": "と", "is_correct": false, "explanation": "「本と読む」は並列や共同の意味になり、文の意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「本を読むことにした」で、読む対象を示す目的語の格助詞として正しい。", "に": "「本に読む」は不自然で、読む対象を示すには合わない。", "が": "「本が読む」では本が主語になり、読む主体として合わない。", "と": "「本と読む」は並列や共同の意味になり、文の意味が合わない。"}, "error_tags": {"に": "位置・方向", "が": "主語", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35062, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "本は、読んだり書いたりするためのものです。", "primary_collocate": null, "pronunciation": "ほん", "ipa": "hoɴ", "syllable_count": 2, "sentences": [{"text": "私は毎晩、寝る前に本を読みます。", "target_word": "本", "complexity_tier": "T3", "furigana": "私[わたし]は毎晩[まいばん]、寝[ね]る前[まえ]に本[ほん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "この本は漢字が少ないので、子どもにも読みやすい。", "target_word": "本", "complexity_tier": "T3", "furigana": "この本[ほん]は漢字[かんじ]が少[すく]ないので、子[こ]どもにも読[よ]みやすい。", "sentence_source": "generated"}, {"text": "図書館で本を三冊借りて、家に帰った。", "target_word": "本", "complexity_tier": "T3", "furigana": "図書館[としょかん]で本[ほん]を三冊[さんさつ]借[か]りて、家[いえ]に帰[かえ]った。", "sentence_source": "generated"}, {"text": "先生は「本を開いて十ページを見てください」と言った。", "target_word": "本", "complexity_tier": "T3", "furigana": "先生[せんせい]は「本[ほん]を開[ひら]いて十[じゅう]ページを見[み]てください」と言[い]った。", "sentence_source": "generated"}, {"text": "弟は本が好きで、休みの日は一日中読んでいる。", "target_word": "本", "complexity_tier": "T3", "furigana": "弟[おとうと]は本[ほん]が好[す]きで、休[やす]みの日[ひ]は一日中[いちにちじゅう]読[よ]んでいる。", "sentence_source": "generated"}, {"text": "本を忘れたので、隣の人に見せてもらった。", "target_word": "本", "complexity_tier": "T3", "furigana": "本[ほん]を忘[わす]れたので、隣[となり]の人[ひと]に見[み]せてもらった。", "sentence_source": "generated"}, {"text": "電車の中で本を読んでいたら、駅を乗り過ごした。", "target_word": "本", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で本[ほん]を読[よ]んでいたら、駅[えき]を乗[の]り過[す]ごした。", "sentence_source": "generated"}, {"text": "雨の日は外で遊べないから、家で本を読むことにした。", "target_word": "本", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]で遊[あそ]べないから、家[いえ]で本[ほん]を読[よ]むことにした。", "sentence_source": "generated"}, {"text": "この本には、世界のいろいろな動物の写真がのっている。", "target_word": "本", "complexity_tier": "T3", "furigana": "この本[ほん]には、世界[せかい]のいろいろな動物[どうぶつ]の写真[しゃしん]がのっている。", "sentence_source": "generated"}, {"text": "机の上に本とノートが置いてある。", "target_word": "本", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に本[ほん]とノートが置[お]いてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "基本形"}, {"form": "本を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "読むための、紙を綴じた日常的な物としての本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: 乗り過ごし (Zipf 2.09)']::text[], 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35062, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本", "is_correct": true, "explanation": "「寝る前に〜を読みます」の空所に入り、読むものとして自然に当てはまる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は読むものではないので、「窓を読みます」は不自然で合わない。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布は読めないものなので、「毛布を読みます」は成り立たない。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日は読むものではないので、「夕日を読みます」は意味が通らない。"}], "explanations": {"本": "「寝る前に〜を読みます」の空所に入り、読むものとして自然に当てはまる。", "窓": "窓は読むものではないので、「窓を読みます」は不自然で合わない。", "毛布": "毛布は読めないものなので、「毛布を読みます」は成り立たない。", "夕日": "夕日は読むものではないので、「夕日を読みます」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この川の本は、山の奥の湖から流れてくる。", "explanation": "〈源（みなもと）〉の意味で使っているが、「本」にはその意味がないので合わない。川の源は「源」と言う。"}, {"text": "この指輪は本の金でできている。", "explanation": "〈純金〉の意味で使っているが、「本」にはそれだけで「純粋な」を表す用法がないので合わない。"}, {"text": "毎晩、寝る前に日記を本に書いている。", "explanation": "〈日記帳〉や〈ノート〉の文。日記は帳面に書くもので、〈本〉に書くとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35062, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本", "is_correct": true, "explanation": "「電車の中で〜を読んでいた」に入り、読んでいたものとして自然に当てはまる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は読むものではないので、「窓を読んでいた」は成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は読めないものなので、「鍵を読んでいた」は不自然。"}, {"text": "雲", "is_correct": false, "explanation": "雲は読むものではないので、「雲を読んでいた」は意味が通らない。"}], "explanations": {"本": "「電車の中で〜を読んでいた」に入り、読んでいたものとして自然に当てはまる。", "窓": "窓は読むものではないので、「窓を読んでいた」は成り立たない。", "鍵": "鍵は読めないものなので、「鍵を読んでいた」は不自然。", "雲": "雲は読むものではないので、「雲を読んでいた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁のくぎに本を掛けた。", "explanation": "〈看板〉の文。くぎに掛けるのは看板で、本は掛けるものではないので合わない。"}, {"text": "彼の本音を突き止めないと、解決できない。", "explanation": "〈本音〉の語。「本」には単独で〈本音〉の意味はなく、この「本」は「本音」の一部で対象の義項とは合わない。"}, {"text": "道順を本に書いて、友人に渡した。", "explanation": "〈メモ〉や〈紙〉の文。道順は紙に書いて渡すもので、〈本〉に書くとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
