INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35063, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "書物。読み物として作られた、紙を綴じたもの。", "primary_collocate": null, "pronunciation": "ほん", "ipa": "hoɴ", "syllable_count": 2, "sentences": [{"text": "古い本のページをめくると、懐かしい匂いがした。", "target_word": "本", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]のページをめくると、懐[なつ]かしい匂[にお]いがした。", "sentence_source": "generated"}, {"text": "この本は十年かけて書かれた、歴史についての大作だ。", "target_word": "本", "complexity_tier": "T3", "furigana": "この本[ほん]は十年[じゅうねん]かけて書[か]かれた、歴史[れきし]についての大作[たいさく]だ。", "sentence_source": "generated"}, {"text": "彼は一冊の本との出会いで、将来の夢を決めた。", "target_word": "本", "complexity_tier": "T3", "furigana": "彼[かれ]は一冊[いっさつ]の本[ほん]との出会[であ]いで、将来[しょうらい]の夢[ゆめ]を決[き]めた。", "sentence_source": "generated"}, {"text": "著者のサイン入りの本を、友人が贈ってくれた。", "target_word": "本", "complexity_tier": "T3", "furigana": "著者[ちょしゃ]のサイン入[い]りの本[ほん]を、友人[ゆうじん]が贈[おく]ってくれた。", "sentence_source": "generated"}, {"text": "出版社は、来月その作家の新しい本を出す予定だ。", "target_word": "本", "complexity_tier": "T3", "furigana": "出版社[しゅっぱんしゃ]は、来月[らいげつ]その作家[さっか]の新[あたら]しい本[ほん]を出[だ]す予定[よてい]だ。", "sentence_source": "generated"}, {"text": "この本は紙が厚くて、持つとずっしり重い。", "target_word": "本", "complexity_tier": "T3", "furigana": "この本[ほん]は紙[かみ]が厚[あつ]くて、持[も]つとずっしり重[おも]い。", "sentence_source": "generated"}, {"text": "本を読むことで、知らない世界を知ることができる。", "target_word": "本", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]むことで、知[し]らない世界[せかい]を知[し]ることができる。", "sentence_source": "generated"}, {"text": "図書館の本は、二週間以内に返さなければならない。", "target_word": "本", "complexity_tier": "T3", "furigana": "図書館[としょかん]の本[ほん]は、二週間以内[にしゅうかんいない]に返[かえ]さなければならない。", "sentence_source": "generated"}, {"text": "新しい本を買ったが、まだ最初の数ページしか読んでいない。", "target_word": "本", "complexity_tier": "T3", "furigana": "新[あたら]しい本[ほん]を買[か]ったが、まだ最初[さいしょ]の数[すう]ページしか読[よ]んでいない。", "sentence_source": "generated"}, {"text": "祖父の本は、どれも丁寧に糸で綴じられている。", "target_word": "本", "complexity_tier": "T3", "furigana": "祖父[そふ]の本[ほん]は、どれも丁寧[ていねい]に糸[いと]で綴[と]じられている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "基本形"}, {"form": "本を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "著者が書き出版社が出す、読み物としての書物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35063, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本", "is_correct": true, "explanation": "「古い〜のページをめくる」に入り、ページのある書物として自然に当てはまる。"}, {"text": "窓", "is_correct": false, "explanation": "窓にはページがないので、「古い窓のページ」は成り立たない。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布にはページがないので、「古い毛布のページ」は不自然。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日にはページがないので、「古い夕日のページ」は意味が通らない。"}], "explanations": {"本": "「古い〜のページをめくる」に入り、ページのある書物として自然に当てはまる。", "窓": "窓にはページがないので、「古い窓のページ」は成り立たない。", "毛布": "毛布にはページがないので、「古い毛布のページ」は不自然。", "夕日": "夕日にはページがないので、「古い夕日のページ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の本は、駅前にある。", "explanation": "〈本店〉の意味で使っているが、「本」にはその意味がないので合わない。"}, {"text": "会社の本を金庫にしまった。", "explanation": "〈帳簿〉の意味で使っているが、「本」にはその意味がないので合わない。"}, {"text": "旅先で撮った写真を本に貼った。", "explanation": "〈アルバム〉の文。写真を貼るのはアルバムで、〈本〉には貼らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35063, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本", "is_correct": true, "explanation": "「〜を読むことで、知らない世界を知る」に入り、読むものとして自然に当てはまる。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は読むものではないので、「鍵を読むことで」は成り立たない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は読めないものなので、「靴下を読むことで」は意味が通らない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢は読むものではないので、「植木鉢を読むことで」は不自然。"}], "explanations": {"本": "「〜を読むことで、知らない世界を知る」に入り、読むものとして自然に当てはまる。", "鍵": "鍵は読むものではないので、「鍵を読むことで」は成り立たない。", "靴下": "靴下は読めないものなので、「靴下を読むことで」は意味が通らない。", "植木鉢": "植木鉢は読むものではないので、「植木鉢を読むことで」は不自然。"}, "sentence_index": 6, "correct_answer": "本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は本の気持ちを言えず、黙っていた。", "explanation": "〈本音〉の意味で使っているが、「本」にはその意味がないので合わない。"}, {"text": "この店では本の料理を出している。", "explanation": "〈本格〉の意味で使っているが、「本」一語にはそのような意味がないので合わない。"}, {"text": "家計の支出を本に書き込んだ。", "explanation": "〈家計簿〉の文。支出は家計簿に書くもので、〈本〉に書き込むとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35063, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新刊の本が書店で買いました。", "corrected_sentence": "新刊の本を書店で買いました。", "error_description": "「買う」の目的語は「を」で示す。「本が」は誤りで、正しくは「本を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35063, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図書館で本が借りて、二週間読みました。", "corrected_sentence": "図書館で本を借りて、二週間読みました。", "error_description": "「借りる」の目的語は「を」で示す。「本が」は誤りで、正しくは「本を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「手が痛くなりました」で、痛くなる主体を示す格助詞として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「手を痛くなる」は成り立たず、痛くなる主体には「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「手に痛くなる」は不自然で、主語を示すには合わない。"}, {"text": "で", "is_correct": false, "explanation": "「手で痛くなる」は手段の意味になり、文の意味が合わない。"}], "correct_answer": "が", "explanations": {"が": "「手が痛くなりました」で、痛くなる主体を示す格助詞として正しい。", "を": "「手を痛くなる」は成り立たず、痛くなる主体には「を」は使えない。", "に": "「手に痛くなる」は不自然で、主語を示すには合わない。", "で": "「手で痛くなる」は手段の意味になり、文の意味が合わない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「手にはまだ絵の具がついて」で、付着する場所を示す格助詞として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「手を絵の具がついて」は成り立たず、付着の場所には「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「手で絵の具がついて」は手段の意味になり、付着の場所として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「手へ絵の具がついて」は方向の意味になり、付着の場所として不自然。"}], "correct_answer": "に", "explanations": {"に": "「手にはまだ絵の具がついて」で、付着する場所を示す格助詞として正しい。", "を": "「手を絵の具がついて」は成り立たず、付着の場所には「を」は使えない。", "で": "「手で絵の具がついて」は手段の意味になり、付着の場所として合わない。", "へ": "「手へ絵の具がついて」は方向の意味になり、付着の場所として不自然。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の一部で、物をつかんだり、何かをするときに使うところです。", "primary_collocate": null, "pronunciation": "て", "ipa": "te", "syllable_count": 1, "sentences": [{"text": "外から帰ったら、まず手を洗います。", "target_word": "手", "complexity_tier": "T3", "furigana": "外[そと]から帰[かえ]ったら、まず手[て]を洗[あら]います。", "sentence_source": "generated"}, {"text": "重い荷物を持ちすぎて、手が痛くなりました。", "target_word": "手", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]ちすぎて、手[て]が痛[いた]くなりました。", "sentence_source": "generated"}, {"text": "質問がある人は、手を挙げてください。", "target_word": "手", "complexity_tier": "T3", "furigana": "質問[しつもん]がある人[ひと]は、手[て]を挙[あ]げてください。", "sentence_source": "generated"}, {"text": "子どもは道を渡るとき、母の手をしっかりにぎっていました。", "target_word": "手", "complexity_tier": "T3", "furigana": "子[こ]どもは道[みち]を渡[わた]るとき、母[はは]の手[て]をしっかりにぎっていました。", "sentence_source": "generated"}, {"text": "私は字を書くとき、右ではなく左の手を使います。", "target_word": "手", "complexity_tier": "T3", "furigana": "私[わたし]は字[じ]を書[か]くとき、右[みぎ]ではなく左[ひだり]の手[て]を使[つか]います。", "sentence_source": "generated"}, {"text": "料理をしていたら、熱いなべに手が当たってしまいました。", "target_word": "手", "complexity_tier": "T3", "furigana": "料理[りょうり]をしていたら、熱[あつ]いなべに手[て]が当[あ]たってしまいました。", "sentence_source": "generated"}, {"text": "友だちに手を振ると、笑って返事をしてくれました。", "target_word": "手", "complexity_tier": "T3", "furigana": "友[とも]だちに手[て]を振[ふ]ると、笑[わら]って返事[へんじ]をしてくれました。", "sentence_source": "generated"}, {"text": "手にはまだ絵の具がついていて、洗ってもなかなか落ちません。", "target_word": "手", "complexity_tier": "T3", "furigana": "手[て]にはまだ絵[え]の具[ぐ]がついていて、洗[あら]ってもなかなか落[お]ちません。", "sentence_source": "generated"}, {"text": "赤ちゃんの小さな手は、とてもやわらかいです。", "target_word": "手", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの小[ちい]さな手[て]は、とてもやわらかいです。", "sentence_source": "generated"}, {"text": "両方の手がふさがっていたので、ドアを開けられませんでした。", "target_word": "手", "complexity_tier": "T3", "furigana": "両方[りょうほう]の手[て]がふさがっていたので、ドアを開[あ]けられませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手", "label": "名詞基本形"}, {"form": "手を", "label": "を格"}, {"form": "手が", "label": "が格"}], "register": "丁寧", "sense_fingerprint": "人の体の一部である「手」。物を持つ、さわる、動作をするために使う部分。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: にぎっ (Zipf 2.25)']::text[], 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手", "is_correct": true, "explanation": "「まず〜を洗います」に入り、洗う体の部分として自然に当てはまる。"}, {"text": "歌", "is_correct": false, "explanation": "歌は洗うものではないので、「歌を洗います」は成り立たない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は洗うものではないので、「地図を洗います」は不自然。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日は洗うものではないので、「夕日を洗います」は意味が通らない。"}], "explanations": {"手": "「まず〜を洗います」に入り、洗う体の部分として自然に当てはまる。", "歌": "歌は洗うものではないので、「歌を洗います」は成り立たない。", "地図": "地図は洗うものではないので、「地図を洗います」は不自然。", "夕日": "夕日は洗うものではないので、「夕日を洗います」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の手を握って、重さを確かめた。", "explanation": "〈取っ手〉の意味で使っているが、「手」は体の部分で、箱の取っ手は〈取っ手〉と言うので合わない。"}, {"text": "時計の手を三時に合わせた。", "explanation": "〈針〉の意味で使っているが、体の部分の〈手〉にはその意味がないので合わない。"}, {"text": "彼は手で忙しく、テストの採点をやめた。", "explanation": "〈手〉を「忙しさ」の意味で使っているが、体の部分の〈手〉にはその意味がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手", "is_correct": true, "explanation": "「友だちに〜を振る」に入り、手を振る動作として自然に当てはまる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は振るものではないので、「窓を振る」は成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "机は振れないので、「机を振ると」は成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は振るものではないので、「雲を振る」は意味が通らない。"}], "explanations": {"手": "「友だちに〜を振る」に入り、手を振る動作として自然に当てはまる。", "窓": "窓は振るものではないので、「窓を振る」は成り立たない。", "机": "机は振れないので、「机を振ると」は成り立たない。", "雲": "雲は振るものではないので、「雲を振る」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は手が長くて、棚に入らない。", "explanation": "〈柄〉や〈長さ〉の文。箱の長さは「手」で表さないので、体の部分の〈手〉の意味では合わない。"}, {"text": "ペンの手が折れて、書けなくなった。", "explanation": "〈軸〉の意味で使っているが、体の部分の〈手〉にはその意味がないので合わない。"}, {"text": "弟のわがままに手を焼いて、困った。", "explanation": "〈手を焼く〉の慣用句で、体の部分の〈手〉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝起きたら、まず手が洗います。", "corrected_sentence": "朝起きたら、まず手を洗います。", "error_description": "「洗う」の目的語は「を」で示す。「手が洗います」は誤りで、正しくは「手を洗います」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35064, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "財布を手が持って、駅へ走った。", "corrected_sentence": "財布を手に持って、駅へ走った。", "error_description": "「手に持つ」の「手」に続く格助詞は「に」。「手が持って」は誤りで、正しくは「手に持って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大きな字を書いた」の目的語を示す格助詞。書いた対象は字。"}, {"text": "が", "is_correct": false, "explanation": "「字が書いた」は字が主語になり、人が書く文として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「字から書いた」は起点を表し、書く対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「字より書いた」は比較を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「大きな字を書いた」の目的語を示す格助詞。書いた対象は字。", "が": "「字が書いた」は字が主語になり、人が書く文として不自然。", "から": "「字から書いた」は起点を表し、書く対象を示せない。", "より": "「字より書いた」は比較を表し、目的語にならない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「字を書く」の目的語を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「字に書く」は目的語にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「字と書いて」は並列にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、目的語の位置に合わない。"}], "correct_answer": "を", "explanations": {"を": "「字を書く」の目的語を示す格助詞。", "に": "「字に書く」は目的語にならず、不自然。", "と": "「字と書いて」は並列にならず、不自然。", "へ": "「へ」は方向を示し、目的語の位置に合わない。"}, "error_tags": {"に": "場所・方向", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "えんぴつやペンで、字や絵を紙にのせること。", "primary_collocate": null, "pronunciation": "かく", "ipa": "kakɯ", "syllable_count": 2, "sentences": [{"text": "えんぴつで名前を書きます。", "target_word": "書きます", "complexity_tier": "T3", "furigana": "えんぴつで名前[なまえ]を書[か]きます。", "sentence_source": "generated"}, {"text": "先生はペンで、ノートに大きな字を書いた。", "target_word": "書いた", "complexity_tier": "T3", "furigana": "せんせいはペンで、ノートにおおきなじをかいた。", "sentence_source": "generated"}, {"text": "ペンで紙に自分の名前を書いてください。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "ペンで紙[かみ]に自分[じぶん]の名前[なまえ]を書[か]いてください。", "sentence_source": "generated"}, {"text": "ノートに今日の日付を書く。", "target_word": "書く", "complexity_tier": "T3", "furigana": "ノートに今日[きょう]の日付[ひづけ]を書[か]く。", "sentence_source": "generated"}, {"text": "間違えた字を消して、もう一度書きました。", "target_word": "書きました", "complexity_tier": "T3", "furigana": "間違[まちが]えた字[じ]を消[け]して、もう一度[いちど]書[か]きました。", "sentence_source": "generated"}, {"text": "赤いペンで丸い字を書くのが好きです。", "target_word": "書く", "complexity_tier": "T3", "furigana": "赤[あか]いペンで丸[まる]い字[じ]を書[か]くのが好[す]きです。", "sentence_source": "generated"}, {"text": "左手でも、ひらがなを書けるようになった。", "target_word": "書ける", "complexity_tier": "T3", "furigana": "左手[ひだりて]でも、ひらがなを書[か]けるようになった。", "sentence_source": "generated"}, {"text": "紙に絵と字を書いて、カードを作った。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "紙[かみ]に絵[え]と字[じ]を書[か]いて、カードを作[つく]った。", "sentence_source": "generated"}, {"text": "ゆっくり書けば、きれいな字になります。", "target_word": "書けば", "complexity_tier": "T3", "furigana": "ゆっくり書[か]けば、きれいな字[じ]になります。", "sentence_source": "generated"}, {"text": "字をならうために、毎日ノートに書いています。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "字[じ]をならうために、毎日[まいにち]ノートに書[か]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書く", "label": "辞書形"}, {"form": "書きます", "label": "ます形"}, {"form": "書いて", "label": "て形"}, {"form": "書いた", "label": "た形"}, {"form": "書かない", "label": "ない形"}, {"form": "書ける", "label": "可能形"}, {"form": "書こう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "えんぴつやペンで字や絵を紙の上に記す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書きます", "is_correct": true, "explanation": "丁寧語の現在形。文末として「書きます」で完結する。"}, {"text": "書いたら", "is_correct": false, "explanation": "たら形は文末に置けず、文が成立しない。"}, {"text": "書かず", "is_correct": false, "explanation": "否定の連用形は文末に置けず、文が成立しない。"}, {"text": "書き", "is_correct": false, "explanation": "連用形だけでは文末に置けず、文が成立しない。"}], "explanations": {"書きます": "丁寧語の現在形。文末として「書きます」で完結する。", "書いたら": "たら形は文末に置けず、文が成立しない。", "書かず": "否定の連用形は文末に置けず、文が成立しない。", "書き": "連用形だけでは文末に置けず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "書きます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関のチャイムを書いた。", "explanation": "〈鳴らす〉の場面。書くは紙に記す動作で、チャイムには使えない。"}, {"text": "セーターの糸を書いた。", "explanation": "〈編む〉の場面。書くは糸には使えず、編むが正しい。"}, {"text": "朝のシャワーを書いた。", "explanation": "〈浴びる〉の場面。書くはシャワーには使えず、シャワーは浴びるものなので浴びるが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書ける", "is_correct": true, "explanation": "可能形。「書けるようになった」で、ひらがなが書けるようになったことを表す。"}, {"text": "書こう", "is_correct": false, "explanation": "意向形は「ようになった」に続かず、文が成立しない。"}, {"text": "書けば", "is_correct": false, "explanation": "条件の「ば」形は「ようになった」に続かず、文が成立しない。"}, {"text": "書かなければ", "is_correct": false, "explanation": "「〜なければ」は条件・義務の形で、「ようになった」には続かず文が成立しない。"}], "explanations": {"書ける": "可能形。「書けるようになった」で、ひらがなが書けるようになったことを表す。", "書こう": "意向形は「ようになった」に続かず、文が成立しない。", "書けば": "条件の「ば」形は「ようになった」に続かず、文が成立しない。", "書かなければ": "「〜なければ」は条件・義務の形で、「ようになった」には続かず文が成立しない。"}, "sentence_index": 6, "correct_answer": "書ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "字をならうために、毎日ハサミを書いています。", "explanation": "〈切る〉の場面。書くは文字を記す動作で、ハサミには使えない。"}, {"text": "字をならうために、毎日お湯を書いています。", "explanation": "〈沸かす〉の場面。書くはお湯には使えず、沸かすが正しい。"}, {"text": "字をならうために、毎日キーボードを書いています。", "explanation": "〈打つ〉の場面。書くはキーボードには使えず、打つが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉛筆で丸い字を書きまた。", "corrected_sentence": "鉛筆で丸い字を書きました。", "error_description": "丁寧語の過去形は「書きました」。「書きまた」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "書いた", "is_correct": true, "explanation": "た形。文末で動作の完了を表す。"}, {"text": "書いたら", "is_correct": false, "explanation": "たら形は文末に置けず、文が成立しない。"}, {"text": "書かず", "is_correct": false, "explanation": "連用形の否定は文末に置けず、文が成立しない。"}, {"text": "書いたり", "is_correct": false, "explanation": "たり形は列挙の形で、文末に置けず文が成立しない。"}], "correct_form": "書いた", "base_form": "書く", "form_label": "た形", "sentence_index": 1, "explanations": {"書いた": "た形。文末で動作の完了を表す。", "書いたら": "たら形は文末に置けず、文が成立しない。", "書かず": "連用形の否定は文末に置けず、文が成立しない。", "書いたり": "たり形は列挙の形で、文末に置けず文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35066, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ペンを紙に名前を書いた。", "corrected_sentence": "ペンで紙に名前を書いた。", "error_description": "手段を表す「で」が正しい。「を」にすると目的語が二つになり不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "書いて", "is_correct": true, "explanation": "て形。「書いて、カードを作った」と動作を続けて述べる。"}, {"text": "書きます", "is_correct": false, "explanation": "ます形は文を終えてしまうため、「カードを作った」と続けられない。"}, {"text": "書ける", "is_correct": false, "explanation": "可能形は文を続けられず、「カードを作った」に続かない。"}, {"text": "書こう", "is_correct": false, "explanation": "意向形は「書こう」と意志を表し、「カードを作った」と続かない。"}], "correct_form": "書いて", "base_form": "書く", "form_label": "て形", "sentence_index": 7, "explanations": {"書いて": "て形。「書いて、カードを作った」と動作を続けて述べる。", "書きます": "ます形は文を終えてしまうため、「カードを作った」と続けられない。", "書ける": "可能形は文を続けられず、「カードを作った」に続かない。", "書こう": "意向形は「書こう」と意志を表し、「カードを作った」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「日記を書く」の目的語を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」にすると「日記で書く」となり、目的語が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「日記が書く」となって不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「日記と書く」は成立しない。"}], "correct_answer": "を", "explanations": {"を": "「日記を書く」の目的語を示す格助詞。", "で": "手段の「で」にすると「日記で書く」となり、目的語が成立しない。", "が": "「が」は主語を示し、「日記が書く」となって不自然。", "と": "「と」は並列や引用を示し、「日記と書く」は成立しない。"}, "error_tags": {"で": "手段", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電話番号を書いた」の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「電話番号が書いた」となって不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示し、「電話番号と書いた」は成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「電話番号へ書いた」は目的語の位置に合わず不自然。"}], "correct_answer": "を", "explanations": {"を": "「電話番号を書いた」の目的語を示す格助詞。", "が": "「が」は主語を示し、「電話番号が書いた」となって不自然。", "と": "「と」は並列を示し、「電話番号と書いた」は成立しない。", "へ": "「へ」は方向を示し、「電話番号へ書いた」は目的語の位置に合わず不自然。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "文字や記号を、手や道具を使って紙などに記すこと。", "primary_collocate": null, "pronunciation": "かく", "ipa": "kakɯ", "syllable_count": 2, "sentences": [{"text": "誰が、どこで、何を、なぜ、どのように書くか、その技法が進化します。", "target_word": "書く", "complexity_tier": "T3", "furigana": "誰[だれ]が、どこで、何[なに]を、なぜ、どのように書[か]くか、その技法[ぎほう]が進化[しんか]します。", "sentence_source": "mined"}, {"text": "彼女は毎晩、日記を書くのが習慣です。", "target_word": "書く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎晩[まいばん]、日記[にっき]を書[か]くのが習慣[しゅうかん]です。", "sentence_source": "generated"}, {"text": "住所と名前をここに書いてください。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "住所[じゅうしょ]と名前[なまえ]をここに書[か]いてください。", "sentence_source": "generated"}, {"text": "黒板に問題の答えを書いた。", "target_word": "書いた", "complexity_tier": "T3", "furigana": "黒板[こくばん]に問題[もんだい]の答[こた]えを書[か]いた。", "sentence_source": "generated"}, {"text": "忘れないように、予定をノートに書いておく。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "忘[わす]れないように、予定[よてい]をノートに書[か]いておく。", "sentence_source": "generated"}, {"text": "読みにくい字なので、もう少し大きく書いてほしい。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "読[よ]みにくい字[じ]なので、もう少[すこ]し大[おお]きく書[か]いてほしい。", "sentence_source": "generated"}, {"text": "作文では、自分の意見を最後まで書かなければならない。", "target_word": "書かなければ", "complexity_tier": "T3", "furigana": "作文[さくぶん]では、自分[じぶん]の意見[いけん]を最後[さいご]まで書[か]かなければならない。", "sentence_source": "generated"}, {"text": "用紙に電話番号を書いたが、一つ間違えた。", "target_word": "書いた", "complexity_tier": "T3", "furigana": "用紙[ようし]に電話番号[でんわばんごう]を書[か]いたが、一[ひと]つ間違[まちが]えた。", "sentence_source": "generated"}, {"text": "辞書で調べた漢字を、何度も紙に書いて覚えた。", "target_word": "書いて", "complexity_tier": "T3", "furigana": "辞書[じしょ]で調[しら]べた漢字[かんじ]を、何度[なんど]も紙[かみ]に書[か]いて覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "彼はカードにお礼の言葉を書き、先生に渡した。", "target_word": "書き", "complexity_tier": "T3", "furigana": "彼[かれ]はカードにお礼[れい]の言葉[ことば]を書[か]き、先生[せんせい]に渡[わた]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書く", "label": "辞書形"}, {"form": "書きます", "label": "ます形"}, {"form": "書いて", "label": "て形"}, {"form": "書いた", "label": "た形"}, {"form": "書かない", "label": "ない形"}, {"form": "書ける", "label": "可能形"}, {"form": "書こう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "文字や記号を手や道具で紙などに記す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書く", "is_correct": true, "explanation": "辞書形。〜か節の述語として「書く」動作を表し、文が成立する。"}, {"text": "書いて", "is_correct": false, "explanation": "て形は〜か節の述語になれず、文が完結しない。"}, {"text": "書き", "is_correct": false, "explanation": "連用形だけでは述語にならず、〜か節が成立しない。"}, {"text": "書かず", "is_correct": false, "explanation": "否定の連用形は〜か節の述語にならず、文が成立しない。"}], "explanations": {"書く": "辞書形。〜か節の述語として「書く」動作を表し、文が成立する。", "書いて": "て形は〜か節の述語になれず、文が完結しない。", "書き": "連用形だけでは述語にならず、〜か節が成立しない。", "書かず": "否定の連用形は〜か節の述語にならず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "書く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ため息を書いた。", "explanation": "〈吐く〉の場面。書くは文字や記号を紙などに記す意味で、ため息には使えない。"}, {"text": "呼び鈴のボタンを書いた。", "explanation": "〈押す〉の場面。書くは紙などに文字を記す動作で、ボタンには使えない。"}, {"text": "靴のひもを書いた。", "explanation": "〈結ぶ〉の場面。書くはひもに使えず、結ぶが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書かなければ", "is_correct": true, "explanation": "「〜なければならない」（義務）の前半。文が「ならない」で完結する。"}, {"text": "書けば", "is_correct": false, "explanation": "条件の「ば」形は「ならない」と続かず、義務の文が成立しない。"}, {"text": "書いたら", "is_correct": false, "explanation": "た形＋「ら」は義務の「ならない」の文に続かない。"}, {"text": "書きながら", "is_correct": false, "explanation": "同時進行の「ながら」は義務の「ならない」の文に続かない。"}], "explanations": {"書かなければ": "「〜なければならない」（義務）の前半。文が「ならない」で完結する。", "書けば": "条件の「ば」形は「ならない」と続かず、義務の文が成立しない。", "書いたら": "た形＋「ら」は義務の「ならない」の文に続かない。", "書きながら": "同時進行の「ながら」は義務の「ならない」の文に続かない。"}, "sentence_index": 6, "correct_answer": "書かなければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壇上で先生にお礼の言葉を書いた。", "explanation": "〈述べる〉の場面。口頭で伝えるお礼の言葉には書くは使えず、述べるが正しい。"}, {"text": "先生に花束を書いた。", "explanation": "〈贈る〉の場面。書くは文字を記す動作で、花束には使えない。"}, {"text": "先生に寝息を書いた。", "explanation": "〈立てる〉の場面。寝息は書けず、寝息を表すには立てるを使うのが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は手紙が丁寧に書いた。", "corrected_sentence": "彼は手紙を丁寧に書いた。", "error_description": "書くの目的語「手紙」には「を」が必要。「が」にすると手紙が主語になり、書くの目的語として成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "書く", "is_correct": true, "explanation": "辞書形。「書くのが習慣」の形で、動詞が名詞句を作り習慣を表す。"}, {"text": "書いたら", "is_correct": false, "explanation": "たら形は「のが習慣」に続かず、文が成立しない。"}, {"text": "書かず", "is_correct": false, "explanation": "連用形の否定は「のが習慣」に続かず、文が成立しない。"}, {"text": "書いて", "is_correct": false, "explanation": "て形は「のが習慣」に続かず、文が成立しない。"}], "correct_form": "書く", "base_form": "書く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"書く": "辞書形。「書くのが習慣」の形で、動詞が名詞句を作り習慣を表す。", "書いたら": "たら形は「のが習慣」に続かず、文が成立しない。", "書かず": "連用形の否定は「のが習慣」に続かず、文が成立しない。", "書いて": "て形は「のが習慣」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35067, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宿題のプリントに名前を書かた。", "corrected_sentence": "宿題のプリントに名前を書いた。", "error_description": "「書く」の過去形は「書いた」。「書かた」は活用の誤りで、正しくは「書いた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "書いた", "is_correct": true, "explanation": "た形。「書いたが」の形で、過去の動作を述べて後続の文に続ける。"}, {"text": "書いたり", "is_correct": false, "explanation": "「たり」は例示・並列の形で、「が」の前に置いて文を続ける述語にならず、文が成立しない。"}, {"text": "書くな", "is_correct": false, "explanation": "禁止の形は「が」に続く節を作れず、「用紙に電話番号を書くなが」となって文が成立しない。"}, {"text": "書こう", "is_correct": false, "explanation": "意向形は意志を表し、実際に書いた事実を述べる文に合わない。"}], "correct_form": "書いた", "base_form": "書く", "form_label": "た形", "sentence_index": 7, "explanations": {"書いた": "た形。「書いたが」の形で、過去の動作を述べて後続の文に続ける。", "書いたり": "「たり」は例示・並列の形で、「が」の前に置いて文を続ける述語にならず、文が成立しない。", "書くな": "禁止の形は「が」に続く節を作れず、「用紙に電話番号を書くなが」となって文が成立しない。", "書こう": "意向形は意志を表し、実際に書いた事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
