INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35068, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人がいるという意味。生きているものがどこかに存在すること。", "primary_collocate": null, "pronunciation": "いる", "ipa": "iɾɯ", "syllable_count": 2, "sentences": [{"text": "公園に子どもが三人居ます。", "target_word": "居ます", "complexity_tier": "T3", "furigana": "公園[こうえん]に子[こ]どもが三人[さんにん]居[い]ます。", "sentence_source": "generated"}, {"text": "部屋には誰も居ません。", "target_word": "居ません", "complexity_tier": "T3", "furigana": "部屋[へや]には誰[だれ]も居[い]ません。", "sentence_source": "generated"}, {"text": "兄は今、大阪に居ます。", "target_word": "居ます", "complexity_tier": "T3", "furigana": "兄[あに]は今[いま]、大阪[おおさか]に居[い]ます。", "sentence_source": "generated"}, {"text": "家に犬が居るので、毎朝散歩に行きます。", "target_word": "居る", "complexity_tier": "T3", "furigana": "家[いえ]に犬[いぬ]が居[い]るので、毎朝[まいあさ]散歩[さんぽ]に行[い]きます。", "sentence_source": "generated"}, {"text": "私が居ない間に、友だちが来ました。", "target_word": "居ない", "complexity_tier": "T3", "furigana": "私[わたし]が居[い]ない間[あいだ]に、友[とも]だちが来[き]ました。", "sentence_source": "generated"}, {"text": "教室に先生が居なかったので、廊下で待ちました。", "target_word": "居なかった", "complexity_tier": "T3", "furigana": "教室[きょうしつ]に先生[せんせい]が居[い]なかったので、廊下[ろうか]で待[ま]ちました。", "sentence_source": "generated"}, {"text": "昨日は一日中、家に居ました。", "target_word": "居ました", "complexity_tier": "T3", "furigana": "昨日[きのう]は一日中[いちにちじゅう]、家[いえ]に居[い]ました。", "sentence_source": "generated"}, {"text": "川の中に魚が居るかどうか、見てみましょう。", "target_word": "居る", "complexity_tier": "T3", "furigana": "川[かわ]の中[なか]に魚[さかな]が居[い]るかどうか、見[み]てみましょう。", "sentence_source": "generated"}, {"text": "弟は部屋に居て、ゲームをしています。", "target_word": "居て", "complexity_tier": "T3", "furigana": "弟[おとうと]は部屋[へや]に居[い]て、ゲームをしています。", "sentence_source": "generated"}, {"text": "山には熊が居るので、鈴を持って歩きます。", "target_word": "居る", "complexity_tier": "T3", "furigana": "山[やま]には熊[くま]が居[い]るので、鈴[すず]を持[も]って歩[ある]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "居る", "label": "基本形"}, {"form": "居ます", "label": "丁寧形"}, {"form": "居ない", "label": "否定形"}, {"form": "居て", "label": "て形"}, {"form": "居た", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "人や動物などの生き物がある場所に存在する（存在動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35068, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居ます", "is_correct": true, "explanation": "人や動物がその場所にいることを表す丁寧形で、子どもが公園にいる文に合う。"}, {"text": "売ります", "is_correct": false, "explanation": "商品を渡す意味で、子どもが公園にいることとは合わない。"}, {"text": "作ります", "is_correct": false, "explanation": "ものを作る意味で、子どもを主語にした存在の文には合わない。"}, {"text": "育ちます", "is_correct": false, "explanation": "成長する意味で、公園にいることを表せないので合わない。"}], "explanations": {"居ます": "人や動物がその場所にいることを表す丁寧形で、子どもが公園にいる文に合う。", "売ります": "商品を渡す意味で、子どもが公園にいることとは合わない。", "作ります": "ものを作る意味で、子どもを主語にした存在の文には合わない。", "育ちます": "成長する意味で、公園にいることを表せないので合わない。"}, "sentence_index": 0, "correct_answer": "居ます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の会議には、資料が居ます。", "explanation": "ここは〈要る〉（必要だ）の意味。必要なものには〈要る〉を使い、〈居る〉は人や動物の存在を表すので合わない。"}, {"text": "机の上に本が居ます。", "explanation": "ここは〈ある〉の意味。物が置かれている場合には〈ある〉を使い、〈居る〉は人や動物に使うので合わない。"}, {"text": "私は大きな家が居ます。", "explanation": "ここは〈持つ〉（持っている）の意味。持ち物には〈持つ〉を使い、〈居る〉は存在を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35068, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居ました", "is_correct": true, "explanation": "その場所にいたことを表す丁寧な過去形で、一日中家にいた文に合う。"}, {"text": "買いました", "is_correct": false, "explanation": "買う行為で、家にいたことを表せないので文に合わない。"}, {"text": "歩きました", "is_correct": false, "explanation": "移動する行為で、一日中家にいた文には合わない。"}, {"text": "書きました", "is_correct": false, "explanation": "文字を書く行為で、家にいたことを表せないので合わない。"}], "explanations": {"居ました": "その場所にいたことを表す丁寧な過去形で、一日中家にいた文に合う。", "買いました": "買う行為で、家にいたことを表せないので文に合わない。", "歩きました": "移動する行為で、一日中家にいた文には合わない。", "書きました": "文字を書く行為で、家にいたことを表せないので合わない。"}, "sentence_index": 6, "correct_answer": "居ました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜、町で大きな事故が居ました。", "explanation": "ここは〈起こる〉（出来事が起きる）の意味。出来事には〈起こる〉を使い、〈居る〉は人や動物に使うので合わない。"}, {"text": "庭の隅に、大きな木が居ました。", "explanation": "ここは〈生える〉（植物が育って現れる）の意味。植物には〈生える〉を使い、〈居る〉は人や動物に使うので合わない。"}, {"text": "朝から寒さが居ます。", "explanation": "ここは〈感じる〉の意味。感覚は〈感じる〉で表し、〈居る〉は存在を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35068, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭に猫を居ます。", "corrected_sentence": "庭に猫が居ます。", "error_description": "「居る」は存在するものを「が」で示す。「猫を」の「を」は誤り（正：猫が）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "居ません", "is_correct": true, "explanation": "丁寧形の否定で、「誰も」と合わせて使う正しい形。"}, {"text": "居ます", "is_correct": false, "explanation": "肯定の丁寧形なので、「誰も」の否定文には合わない。"}, {"text": "居た", "is_correct": false, "explanation": "肯定の過去形なので、「誰も」の否定文には合わない。"}, {"text": "居て", "is_correct": false, "explanation": "て形で文を終えられず、「誰も」の否定文にならない。"}], "correct_form": "居ません", "base_form": "居る", "form_label": "丁寧形・否定", "sentence_index": 1, "explanations": {"居ません": "丁寧形の否定で、「誰も」と合わせて使う正しい形。", "居ます": "肯定の丁寧形なので、「誰も」の否定文には合わない。", "居た": "肯定の過去形なので、「誰も」の否定文には合わない。", "居て": "て形で文を終えられず、「誰も」の否定文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35068, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は窓辺に居る、空を見ています。", "corrected_sentence": "彼女は窓辺に居て、空を見ています。", "error_description": "二つの動作を並べる「て形」が必要。「居る、」では文が続かず誤り（正：居て）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "居る", "is_correct": true, "explanation": "基本形で、「〜かどうか」の前に入る正しい形。"}, {"text": "居ません", "is_correct": false, "explanation": "丁寧形の否定なので、「〜かどうか」の前には入らない。"}, {"text": "居れば", "is_correct": false, "explanation": "仮定形で、「〜かどうか」につながらない。"}, {"text": "居ろ", "is_correct": false, "explanation": "命令形で、文の途中の「〜かどうか」には入らない。"}], "correct_form": "居る", "base_form": "居る", "form_label": "基本形", "sentence_index": 7, "explanations": {"居る": "基本形で、「〜かどうか」の前に入る正しい形。", "居ません": "丁寧形の否定なので、「〜かどうか」の前には入らない。", "居れば": "仮定形で、「〜かどうか」につながらない。", "居ろ": "命令形で、文の途中の「〜かどうか」には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
