INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35070, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "何かをするために、あることをすること。", "primary_collocate": null, "pronunciation": "ため", "ipa": "tame", "syllable_count": 2, "sentences": [{"text": "家族のために、毎朝早く起きて朝ごはんを作ります。", "target_word": "ため", "complexity_tier": "T3", "furigana": "家族[かぞく]のために、毎朝[まいあさ]早[はや]く起[お]きて朝[あさ]ごはんを作[つく]ります。", "sentence_source": "generated"}, {"text": "日本語を勉強するために、先月から教室に通っています。", "target_word": "ため", "complexity_tier": "T3", "furigana": "日本語[にほんご]を勉強[べんきょう]するために、先月[せんげつ]から教室[きょうしつ]に通[かよ]っています。", "sentence_source": "generated"}, {"text": "健康のために、エレベーターを使わず階段を上ります。", "target_word": "ため", "complexity_tier": "T3", "furigana": "健康[けんこう]のために、エレベーターを使[つか]わず階段[かいだん]を上[のぼ]ります。", "sentence_source": "generated"}, {"text": "友だちの誕生日プレゼントを買うために、アルバイトを始めました。", "target_word": "ため", "complexity_tier": "T3", "furigana": "友[とも]だちの誕生日[たんじょうび]プレゼントを買[か]うために、アルバイトを始[はじ]めました。", "sentence_source": "generated"}, {"text": "試験に合格するために、毎晩二時間勉強しています。", "target_word": "ため", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]するために、毎晩[まいばん]二時間[にじかん]勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "子どものために、休みの日は公園へ連れて行きます。", "target_word": "ため", "complexity_tier": "T3", "furigana": "子[こ]どものために、休[やす]みの日[ひ]は公園[こうえん]へ連[つ]れて行[い]きます。", "sentence_source": "generated"}, {"text": "来週の会議のために、資料を作っています。", "target_word": "ため", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の会議[かいぎ]のために、資料[しりょう]を作[つく]っています。", "sentence_source": "generated"}, {"text": "環境を守るために、買い物にはふくろを持って行きます。", "target_word": "ため", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]るために、買[か]い物[もの]にはふくろを持[も]って行[い]きます。", "sentence_source": "generated"}, {"text": "先生は生徒のために、わかりやすい説明を考えてくれました。", "target_word": "ため", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]のために、わかりやすい説明[せつめい]を考[かんが]えてくれました。", "sentence_source": "generated"}, {"text": "母は私のために、遅くまで待っていてくれました。", "target_word": "ため", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]のために、遅[おそ]くまで待[ま]っていてくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ため", "label": "名詞基本形"}, {"form": "ために", "label": "に格（目的）"}, {"form": "ための", "label": "連体形"}], "register": "丁寧", "sense_fingerprint": "形式名詞「ため」。目的や利益を表し、「〜のために」「〜するために」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35070, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ため", "is_correct": true, "explanation": "「家族の〜に、朝ごはんを作る」に入り、目的や利益を表す形式名詞として自然に当てはまる。"}, {"text": "最中", "is_correct": false, "explanation": "「家族の最中に」は出来事の途中を表し、目的の意味にならないので合わない。"}, {"text": "途中", "is_correct": false, "explanation": "「家族の途中に」は意味が通らず、目的を表す形にならない。"}, {"text": "直後", "is_correct": false, "explanation": "「家族の直後に」は時間の前後を表し、目的の文脈では合わない。"}], "explanations": {"ため": "「家族の〜に、朝ごはんを作る」に入り、目的や利益を表す形式名詞として自然に当てはまる。", "最中": "「家族の最中に」は出来事の途中を表し、目的の意味にならないので合わない。", "途中": "「家族の途中に」は意味が通らず、目的を表す形にならない。", "直後": "「家族の直後に」は時間の前後を表し、目的の文脈では合わない。"}, "sentence_index": 0, "correct_answer": "ため"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降るために、明日は傘を持った。", "explanation": "〈ように〉の文。「ために」は自分の意志でする行為の目的にだけ使うので、自然に降る雨は目的にならず、ここは「ように」を使う。"}, {"text": "電車に遅れるために、急いで走った。", "explanation": "〈ように〉の文（遅れないように）。「遅れる」は目的にできず、「ために」は合わない。"}, {"text": "春が来るために、庭に花を植えた。", "explanation": "〈ように〉の文の誤用例。自然に訪れる季節は目的にできないので、「ために」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35070, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ため", "is_correct": true, "explanation": "「来週の会議の〜に、資料を作る」に入り、目的を表す形式名詞として自然に当てはまる。"}, {"text": "戸棚", "is_correct": false, "explanation": "「会議の戸棚に」は意味が通らず、目的を表す形にならない。"}, {"text": "足音", "is_correct": false, "explanation": "「会議の足音に」は意味が通らず、目的の文脈では合わない。"}, {"text": "天井", "is_correct": false, "explanation": "「会議の天井に」は場所として不自然で、目的の意味にならない。"}], "explanations": {"ため": "「来週の会議の〜に、資料を作る」に入り、目的を表す形式名詞として自然に当てはまる。", "戸棚": "「会議の戸棚に」は意味が通らず、目的を表す形にならない。", "足音": "「会議の足音に」は意味が通らず、目的の文脈では合わない。", "天井": "「会議の天井に」は場所として不自然で、目的の意味にならない。"}, "sentence_index": 6, "correct_answer": "ため"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "話し声が聞こえるために、窓を閉めた。", "explanation": "〈ように〉の文（聞こえないように）。自然に聞こえてしまうことは目的にできないので、「ために」は合わない。"}, {"text": "ドアが開くために、鍵をかけた。", "explanation": "〈ように〉の文（開かないように）。「ために」は意志的な行為の目的にだけ使うので、ドアが開くことは目的にならない。"}, {"text": "雷が鳴るために、窓を閉めた。", "explanation": "〈ように〉の文（鳴らないように）。自然現象は目的にできないので、「ために」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅費を稼ぐための、夏はずっと働きました。", "corrected_sentence": "旅費を稼ぐために、夏はずっと働きました。", "error_description": "文末の読点の前は副詞的な「ために」が正しく、「ための」は連体形で後ろに名詞が必要。正しくは「稼ぐために」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35070, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年の受験にために、毎晩図書館で勉強しています。", "corrected_sentence": "来年の受験のために、毎晩図書館で勉強しています。", "error_description": "「ために」の前は名詞に続く「の」が正しく、「に」は誤り。正しくは「受験のために」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
