INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35072, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "とてもという意味です。何かの程度が大きいことを表します。", "primary_collocate": null, "pronunciation": "とても", "ipa": "totemo", "syllable_count": 3, "sentences": [{"text": "今日はとても暑いので、冷たい麦茶をたくさん飲みました。", "target_word": "とても", "complexity_tier": "T3", "furigana": "今日[きょう]はとても暑[あつ]いので、冷[つめ]たい麦茶[むぎちゃ]をたくさん飲[の]みました。", "sentence_source": "generated"}, {"text": "この本はとても面白くて、一晩で読み終えました。", "target_word": "とても", "complexity_tier": "T3", "furigana": "この本[ほん]はとても面白[おもしろ]くて、一晩[ひとばん]で読[よ]み終[お]えました。", "sentence_source": "generated"}, {"text": "京都の夏祭りはとてもにぎやかで、人が大勢いました。", "target_word": "とても", "complexity_tier": "T3", "furigana": "京都[きょうと]の夏祭[なつまつ]りはとてもにぎやかで、人[ひと]が大勢[おおぜい]いました。", "sentence_source": "generated"}, {"text": "祖母が作ってくれたスープは、とてもおいしかったです。", "target_word": "とても", "complexity_tier": "T3", "furigana": "祖母[そぼ]が作[つく]ってくれたスープは、とてもおいしかったです。", "sentence_source": "generated"}, {"text": "昨日の試験はとても難しくて、最後まで解けませんでした。", "target_word": "とても", "complexity_tier": "T3", "furigana": "昨日[きのう]の試験[しけん]はとても難[むずか]しくて、最後[さいご]まで解[と]けませんでした。", "sentence_source": "generated"}, {"text": "弟はとても背が高いので、バスケットボールが得意です。", "target_word": "とても", "complexity_tier": "T3", "furigana": "弟[おとうと]はとても背[せ]が高[たか]いので、バスケットボールが得意[とくい]です。", "sentence_source": "generated"}, {"text": "山の上から見た景色がとてもきれいで、写真を何枚も撮りました。", "target_word": "とても", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から見[み]た景色[けしき]がとてもきれいで、写真[しゃしん]を何枚[なんまい]も撮[と]りました。", "sentence_source": "generated"}, {"text": "駅から家までとても遠いので、毎朝自転車に乗ります。", "target_word": "とても", "complexity_tier": "T3", "furigana": "駅[えき]から家[いえ]までとても遠[とお]いので、毎朝[まいあさ]自転車[じてんしゃ]に乗[の]ります。", "sentence_source": "generated"}, {"text": "新しい先生はとても親切で、質問にていねいに答えてくれます。", "target_word": "とても", "complexity_tier": "T3", "furigana": "新[あたら]しい先生[せんせい]はとても親切[しんせつ]で、質問[しつもん]にていねいに答[こた]えてくれます。", "sentence_source": "generated"}, {"text": "疲れていたので、その日はとても早く寝ました。", "target_word": "とても", "complexity_tier": "T3", "furigana": "疲[つか]れていたので、その日[ひ]はとても早[はや]く寝[ね]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "とても", "label": "副詞基本形"}], "register": "丁寧", "sense_fingerprint": "程度副詞「とても」。肯定文で形容詞や状態を強め、程度が大きいことを表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35072, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "とても", "is_correct": true, "explanation": "「とても」は程度の大きさを表し、「暑い」を強めるので、ここに入ると文が自然になる。"}, {"text": "めったに", "is_correct": false, "explanation": "「めったに」は否定の文でしか使えないので、肯定の「暑いので」には合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで」は「〜のように」と比喩で結ぶ語で、ここでは文が成り立たない。"}, {"text": "ろくに", "is_correct": false, "explanation": "「ろくに」も否定を伴う副詞で、肯定の「暑い」を修飾できない。"}], "explanations": {"とても": "「とても」は程度の大きさを表し、「暑い」を強めるので、ここに入ると文が自然になる。", "めったに": "「めったに」は否定の文でしか使えないので、肯定の「暑いので」には合わない。", "まるで": "「まるで」は「〜のように」と比喩で結ぶ語で、ここでは文が成り立たない。", "ろくに": "「ろくに」も否定を伴う副詞で、肯定の「暑い」を修飾できない。"}, "sentence_index": 0, "correct_answer": "とても"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い間探して、とても見つかった。", "explanation": "「とても」は「やっと」の意味を持たないので、探して見つかったという結果は表せず、この文は成り立たない。"}, {"text": "彼は資料を、とても三日で仕上げました。", "explanation": "「とても」は「わずか」の意味を持たないので、期間が短いことは表せず、この文は成り立たない。"}, {"text": "宿題は、とても終わりました。", "explanation": "「とても」は「ほとんど」の意味を持たないので、完了の近さは表せず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35072, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "とても", "is_correct": true, "explanation": "「とても」は程度を強める語で、「きれいで」の度合いを表すので、ここに入ると文が自然になる。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "「ぜんぜん」は否定と一緒に使う語で、「景色がぜんぜんきれいで」は肯定と合わず意味が通らない。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は強い否定（決して〜ない）の副詞で、肯定の「きれいで」には合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで」は「〜のように」と比喩で結ぶ語で、「まるできれいで」は文が成り立たない。"}], "explanations": {"とても": "「とても」は程度を強める語で、「きれいで」の度合いを表すので、ここに入ると文が自然になる。", "ぜんぜん": "「ぜんぜん」は否定と一緒に使う語で、「景色がぜんぜんきれいで」は肯定と合わず意味が通らない。", "決して": "「決して」は強い否定（決して〜ない）の副詞で、肯定の「きれいで」には合わない。", "まるで": "「まるで」は「〜のように」と比喩で結ぶ語で、「まるできれいで」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "とても"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の結果は、とても出ます。", "explanation": "「とても」は「もうすぐ」の意味を持たないので、時間の近さは表せず、この文は成り立たない。"}, {"text": "電車は、とても十時に駅へ着きました。", "explanation": "「とても」は「ぴったり」の意味を持たないので、時刻のちょうどよさは表せず、この文は成り立たない。"}, {"text": "彼は、とても海を見ました。", "explanation": "「とても」は「初めて」の意味を持たないので、回数の最初であることは表せず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
