phological_forms": [{"form": "貴重だ", "label": "活用"}, {"form": "貴重な", "label": "活用"}, {"form": "貴重さ", "label": "派生"}, {"form": "貴重品", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | とても大切で特別なもののこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35074, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "貴重", "is_correct": true, "explanation": "見出し語「きちょう」そのものです。"}, {"text": "議長", "is_correct": false, "explanation": "「ぎちょう」で、最初の音が違います。"}, {"text": "気象", "is_correct": false, "explanation": "「きしょう」で、二番目の音が違います。"}, {"text": "机上", "is_correct": false, "explanation": "「きじょう」で、二番目の音が違います。"}, {"text": "区長", "is_correct": false, "explanation": "「くちょう」で、最初の音が違います。"}], "explanations": {"貴重": "見出し語「きちょう」そのものです。", "議長": "「ぎちょう」で、最初の音が違います。", "気象": "「きしょう」で、二番目の音が違います。", "机上": "「きじょう」で、二番目の音が違います。", "区長": "「くちょう」で、最初の音が違います。"}, "sentence_index": null, "correct_answer": "貴重"}, "level_3": {"options": [{"text": "貴重な", "is_correct": true, "explanation": "大切で特別な物という意味で文に合います。"}, {"text": "正直な", "is_correct": false, "explanation": "形は合うが、物を「正直」とは言わないので意味が合わない。"}, {"text": "元気な", "is_correct": false, "explanation": "形は合うが、物を「元気」とは言わないので意味が合わない。"}, {"text": "親切な", "is_correct": false, "explanation": "形は合うが、物を「親切」とは言わないので意味が合わない。"}], "explanations": {"貴重な": "大切で特別な物という意味で文に合います。", "正直な": "形は合うが、物を「正直」とは言わないので意味が合わない。", "元気な": "形は合うが、物を「元気」とは言わないので意味が合わない。", "親切な": "形は合うが、物を「親切」とは言わないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "貴重な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昔より貴重になって、背が高くなった。", "explanation": "人の成長を「貴重」で表していて、誤りです。"}, {"text": "毎日たくさん捨てるごみは貴重です。", "explanation": "たくさん捨てるものを「貴重」とは言えず、意味が合いません。"}, {"text": "貴重なおなかがすいたので、ご飯を食べた。", "explanation": "「貴重」を「とても」の意味で使っていて、誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_err