INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35074, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "貴重", "is_correct": true, "explanation": "見出し語「きちょう」そのものです。"}, {"text": "市長", "is_correct": false, "explanation": "「しちょう」で、最初の音が違います。"}, {"text": "胃腸", "is_correct": false, "explanation": "「いちょう」で、最初の音が違います。"}, {"text": "自重", "is_correct": false, "explanation": "「じちょう」で、最初の音が違います。"}], "explanations": {"貴重": "見出し語「きちょう」そのものです。", "市長": "「しちょう」で、最初の音が違います。", "胃腸": "「いちょう」で、最初の音が違います。", "自重": "「じちょう」で、最初の音が違います。"}, "sentence_index": null, "correct_answer": "貴重"}, "level_3": {"options": [{"text": "貴重だ", "is_correct": true, "explanation": "数が少ないから特別だ、という意味で文に合います。"}, {"text": "親切だ", "is_correct": false, "explanation": "形は合うが、鳥を「親切」とは言わないので意味が合わない。"}, {"text": "簡単だ", "is_correct": false, "explanation": "形は合うが、数が少ない理由と「簡単」では意味が合わない。"}, {"text": "退屈だ", "is_correct": false, "explanation": "形は合うが、数が少ない鳥を「退屈」とは言わないので意味が合わない。"}], "explanations": {"貴重だ": "数が少ないから特別だ、という意味で文に合います。", "親切だ": "形は合うが、鳥を「親切」とは言わないので意味が合わない。", "簡単だ": "形は合うが、数が少ない理由と「簡単」では意味が合わない。", "退屈だ": "形は合うが、数が少ない鳥を「退屈」とは言わないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "貴重だ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この石は貴重なので、道にたくさん落ちている。", "explanation": "「貴重」は数が少なく特別なことなのに、たくさん落ちている理由にしていて意味が合いません。"}, {"text": "彼は足が貴重で、百メートルを十秒で走る。", "explanation": "「貴重」を「速い」の意味で使っていて、誤りです。"}, {"text": "貴重な雨が毎日降って、洗濯物が乾かない。", "explanation": "毎日降る雨を「貴重」とは言えず、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35074, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その宝石は貴重くて高いです。", "corrected_sentence": "その宝石は貴重で高いです。", "error_description": "「貴重」は形状詞なので、「貴重くて」ではなく「貴重で」にします。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "貴重だ", "is_correct": true, "explanation": "文末で言い切る形で、空欄に合います。"}, {"text": "貴重な", "is_correct": false, "explanation": "連体形なので、文末には使えません。"}, {"text": "貴重に", "is_correct": false, "explanation": "連用形なので、文末には使えません。"}, {"text": "貴重で", "is_correct": false, "explanation": "中止形なので、ここで文を言い切れません。"}], "correct_form": "貴重だ", "base_form": "貴重だ", "form_label": "終止形", "sentence_index": 1, "explanations": {"貴重だ": "文末で言い切る形で、空欄に合います。", "貴重な": "連体形なので、文末には使えません。", "貴重に": "連用形なので、文末には使えません。", "貴重で": "中止形なので、ここで文を言い切れません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35074, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の手紙は貴重のです。", "corrected_sentence": "昔の手紙は貴重です。", "error_description": "「貴重」のあとに「の」は不要で、「貴重です」が正しいです。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "貴重な", "is_correct": true, "explanation": "名詞「資料」を修飾する連体形です。"}, {"text": "貴重だ", "is_correct": false, "explanation": "終止形なので、名詞の前には使えません。"}, {"text": "貴重に", "is_correct": false, "explanation": "連用形なので、名詞を修飾できません。"}, {"text": "貴重さ", "is_correct": false, "explanation": "名詞の形なので、「資料」を修飾できません。"}], "correct_form": "貴重な", "base_form": "貴重だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"貴重な": "名詞「資料」を修飾する連体形です。", "貴重だ": "終止形なので、名詞の前には使えません。", "貴重に": "連用形なので、名詞を修飾できません。", "貴重さ": "名詞の形なので、「資料」を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
