INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35075, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "価値が高く、めったにないこと。大切にすべきだと思うこと。", "primary_collocate": null, "pronunciation": "きちょう", "ipa": "kitɕoː", "syllable_count": 3, "sentences": [{"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "貴重な", "complexity_tier": "T6", "furigana": "この販売[はんばい]活動[かつどう]は、単[たん]にお金[かね]を稼[かせ]ぐためだけでなく、自分[じぶん]で計画[けいかく]を立[た]てて実行[じっこう]するという貴重[きちょう]な経験[けいけん]を積[つ]むことが目的[もくてき]だった。", "sentence_source": "mined"}, {"text": "水は貴重だ。", "target_word": "貴重だ", "complexity_tier": "T1", "furigana": "水[みず]は貴重[きちょう]だ。", "sentence_source": "generated"}, {"text": "これは貴重な切手です。", "target_word": "貴重な", "complexity_tier": "T2", "furigana": "これは貴重[きちょう]な切手[きって]です。", "sentence_source": "generated"}, {"text": "祖父の話は私にとって貴重だった。", "target_word": "貴重だった", "complexity_tier": "T3", "furigana": "祖父[そふ]の話[はなし]は私[わたし]にとって貴重[きちょう]だった。", "sentence_source": "generated"}, {"text": "貴重な時間をいただき、ありがとうございます。", "target_word": "貴重な", "complexity_tier": "T3", "furigana": "貴重[きちょう]な時間[じかん]をいただき、ありがとうございます。", "sentence_source": "generated"}, {"text": "この森には、世界でも貴重な植物が育っている。", "target_word": "貴重な", "complexity_tier": "T4", "furigana": "この森[もり]には、世界[せかい]でも貴重[きちょう]な植物[しょくぶつ]が育[そだ]っている。", "sentence_source": "generated"}, {"text": "古い写真は家族にとって貴重です。", "target_word": "貴重です", "complexity_tier": "T2", "furigana": "古[ふる]い写真[しゃしん]は家族[かぞく]にとって貴重[きちょう]です。", "sentence_source": "generated"}, {"text": "失敗から学んだことは、後から思えば何よりも貴重だったと感じる。", "target_word": "貴重だった", "complexity_tier": "T5", "furigana": "失敗[しっぱい]から学[まな]んだことは、後[あと]から思[おも]えば何[なに]よりも貴重[きちょう]だったと感[かん]じる。", "sentence_source": "generated"}, {"text": "一日一日を貴重に感じる。", "target_word": "貴重に", "complexity_tier": "T3", "furigana": "一日一日[いちにちいちにち]を貴重[きちょう]に感[かん]じる。", "sentence_source": "generated"}, {"text": "この本は貴重で、簡単には手に入らない。", "target_word": "貴重で", "complexity_tier": "T3", "furigana": "この本[ほん]は貴重[きちょう]で、簡単[かんたん]には手[て]に入[はい]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貴重だ", "label": "活用"}, {"form": "貴重な", "label": "活用"}, {"form": "貴重さ", "label": "派生"}, {"form": "貴重品", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 価値が高くめったにないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35075, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "貴重", "is_correct": true, "explanation": "見出し語「きちょう」そのものです。"}, {"text": "議長", "is_correct": false, "explanation": "「ぎちょう」で、最初の音が違います。"}, {"text": "気象", "is_correct": false, "explanation": "「きしょう」で、二番目の音が違います。"}, {"text": "机上", "is_correct": false, "explanation": "「きじょう」で、二番目の音が違います。"}, {"text": "区長", "is_correct": false, "explanation": "「くちょう」で、最初の音が違います。"}], "explanations": {"貴重": "見出し語「きちょう」そのものです。", "議長": "「ぎちょう」で、最初の音が違います。", "気象": "「きしょう」で、二番目の音が違います。", "机上": "「きじょう」で、二番目の音が違います。", "区長": "「くちょう」で、最初の音が違います。"}, "sentence_index": null, "correct_answer": "貴重"}, "level_3": {"options": [{"text": "貴重な", "is_correct": true, "explanation": "価値のある経験という意味で文に合います。"}, {"text": "豪華な", "is_correct": false, "explanation": "形は合うが、経験を「豪華」とは言わないので意味が合わない。"}, {"text": "頑丈な", "is_correct": false, "explanation": "形は合うが、経験を「頑丈」とは言わないので意味が合わない。"}, {"text": "派手な", "is_correct": false, "explanation": "形は合うが、計画を立てて実行する経験に「派手」は意味が合わない。"}], "explanations": {"貴重な": "価値のある経験という意味で文に合います。", "豪華な": "形は合うが、経験を「豪華」とは言わないので意味が合わない。", "頑丈な": "形は合うが、経験を「頑丈」とは言わないので意味が合わない。", "派手な": "形は合うが、計画を立てて実行する経験に「派手」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "貴重な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このかばんは貴重に重いので、持てません。", "explanation": "「貴重」を「とても」の意味で使っていて、誤りです。"}, {"text": "夏の暑い日は貴重で、毎日たくさんある。", "explanation": "「貴重」はめったにないことなのに、たくさんあると言っていて矛盾します。"}, {"text": "この水は貴重なので、毎日たくさん捨てています。", "explanation": "大切にすべきものを「貴重なので」捨てると言っていて、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
