INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35075, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の手紙は貴重に宝物です。", "corrected_sentence": "祖母の手紙は貴重な宝物です。", "error_description": "名詞「宝物」を修飾するので、「貴重に」ではなく「貴重な」にします。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "貴重だった", "is_correct": true, "explanation": "過去の形で、「と感じる」につながります。"}, {"text": "貴重な", "is_correct": false, "explanation": "連体形なので、「と」の前には使えません。"}, {"text": "貴重に", "is_correct": false, "explanation": "連用形なので、「と感じる」にはつながりません。"}, {"text": "貴重で", "is_correct": false, "explanation": "中止形なので、「と感じる」にはつながりません。"}], "correct_form": "貴重だった", "base_form": "貴重だ", "form_label": "過去形", "sentence_index": 7, "explanations": {"貴重だった": "過去の形で、「と感じる」につながります。", "貴重な": "連体形なので、「と」の前には使えません。", "貴重に": "連用形なので、「と感じる」にはつながりません。", "貴重で": "中止形なので、「と感じる」にはつながりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
