INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35080, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "紙に文字や絵をうつすこと。", "primary_collocate": null, "pronunciation": "いんさつ", "ipa": "insatsɯ", "syllable_count": 4, "sentences": [{"text": "先生は宿題のプリントを三十枚印刷した。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "先生[せんせい]は宿題[しゅくだい]のプリントを三十枚[さんじゅうまい]印刷[いんさつ]した。", "sentence_source": "generated"}, {"text": "コンビニで地図を印刷して、旅行に持っていった。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "コンビニで地図[ちず]を印刷[いんさつ]して、旅行[りょこう]に持[も]っていった。", "sentence_source": "generated"}, {"text": "印刷した紙が、まだ温かい。", "target_word": "印刷", "complexity_tier": "T2", "furigana": "印刷[いんさつ]した紙[かみ]が、まだ温[あたた]かい。", "sentence_source": "generated"}, {"text": "このインクは水に強く、印刷した文字が消えにくい。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "このインクは水[みず]に強[つよ]く、印刷[いんさつ]した文字[もじ]が消[き]えにくい。", "sentence_source": "generated"}, {"text": "写真を大きく印刷して、部屋の壁に飾った。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "写真[しゃしん]を大[おお]きく印刷[いんさつ]して、部屋[へや]の壁[かべ]に飾[かざ]った。", "sentence_source": "generated"}, {"text": "印刷の色が画面と違うので、設定を直した。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "印刷[いんさつ]の色[いろ]が画面[がめん]と違[ちが]うので、設定[せってい]を直[なお]した。", "sentence_source": "generated"}, {"text": "切符を印刷する機械が、駅の入り口にある。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "切符[きっぷ]を印刷[いんさつ]する機械[きかい]が、駅[えき]の入[い]り口[ぐち]にある。", "sentence_source": "generated"}, {"text": "新聞は夜のうちに印刷され、朝には家に届く。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "新聞[しんぶん]は夜[よる]のうちに印刷[いんさつ]され、朝[あさ]には家[いえ]に届[とど]く。", "sentence_source": "generated"}, {"text": "白黒で印刷すれば、インクを節約できる。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "白黒[しろくろ]で印刷[いんさつ]すれば、インクを節約[せつやく]できる。", "sentence_source": "generated"}, {"text": "宿題を印刷し忘れて、学校で先生に謝った。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を印刷[いんさつ]し忘[わす]れて、学校[がっこう]で先生[せんせい]に謝[あやま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "印刷", "label": "基本形"}, {"form": "印刷する", "label": "する動詞"}, {"form": "印刷した", "label": "過去形"}, {"form": "印刷される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "紙に文字や絵を写し出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35080, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷", "is_correct": true, "explanation": "「三十枚印刷した」で、同じプリントを三十枚作った意味になる。"}, {"text": "版木", "is_correct": false, "explanation": "版木は彫って版にする木の板で、枚数を数えて「した」と続けられない。"}, {"text": "紙質", "is_correct": false, "explanation": "紙質は紙の質を表す語で、動作の対象にならず「三十枚紙質した」とは言えない。"}, {"text": "用紙", "is_correct": false, "explanation": "用紙は紙そのものを指し、「三十枚用紙した」という動作にはならない。"}], "explanations": {"印刷": "「三十枚印刷した」で、同じプリントを三十枚作った意味になる。", "版木": "版木は彫って版にする木の板で、枚数を数えて「した」と続けられない。", "紙質": "紙質は紙の質を表す語で、動作の対象にならず「三十枚紙質した」とは言えない。", "用紙": "用紙は紙そのものを指し、「三十枚用紙した」という動作にはならない。"}, "sentence_index": 0, "correct_answer": "印刷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服の裾を、糸で印刷した。", "explanation": "ここは〈縫う〉の意味。糸で布を縫うことで、紙に写す印刷とは違う。"}, {"text": "先生の話を、スマホに印刷して残した。", "explanation": "ここは〈録音〉の意味。話を音として残す行為で、紙に写す印刷とは合わない。"}, {"text": "指輪に、二人の名前を印刷した。", "explanation": "ここは〈刻印〉の意味。金属に刻んで跡を付ける作業で、紙に写す印刷とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35080, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷", "is_correct": true, "explanation": "「切符を印刷する機械」で、切符に文字を写し出す機械という意味になる。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う券で、「切符を切手する」とは言えない。"}, {"text": "硬貨", "is_correct": false, "explanation": "硬貨は金属の貨幣で、「切符を硬貨する」という動作にはならない。"}, {"text": "券売機", "is_correct": false, "explanation": "券売機は切符を売る機械で、「切符を券売機する」とは言わない。"}], "explanations": {"印刷": "「切符を印刷する機械」で、切符に文字を写し出す機械という意味になる。", "切手": "切手は郵便に使う券で、「切符を切手する」とは言えない。", "硬貨": "硬貨は金属の貨幣で、「切符を硬貨する」という動作にはならない。", "券売機": "券売機は切符を売る機械で、「切符を券売機する」とは言わない。"}, "sentence_index": 6, "correct_answer": "印刷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "表計算の結果を、モニターに印刷して確認した。", "explanation": "ここは〈出力〉の意味。印刷は紙に写すことなので、画面に表示する結果には使わない。"}, {"text": "先生の話を、ボイスレコーダーに印刷して残した。", "explanation": "ここは〈録音〉の意味。話を音声として残す行為で、紙に写す印刷とは違う。"}, {"text": "会社は、古い社内制度を印刷した。", "explanation": "ここは〈刷新〉の意味。制度を新しくする意味で、紙に写す印刷とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35080, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "色の濃さは、印刷を設定で変えられる。", "corrected_sentence": "色の濃さは、印刷の設定で変えられる。", "error_description": "「印刷の設定」が正しい形。「印刷」と「設定」は「の」で結ぶ。「を」は動詞の目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35080, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この紙は、インクを使う印刷を向いている。", "corrected_sentence": "この紙は、インクを使う印刷に向いている。", "error_description": "「印刷に向いている」が正しい形。「向く」は適する対象を「に」で示すので、「印刷を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「多色印刷の場合」で、「印刷」と「場合」を名詞同士でつなぐ「の」。"}, {"text": "が", "is_correct": false, "explanation": "「印刷が場合」では主語を示す「が」になり、名詞同士をつなげない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「印刷を場合」と名詞に続けてもつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や時を示す助詞で、「印刷に場合」と名詞をつなぐ用法はない。"}], "correct_answer": "の", "explanations": {"の": "「多色印刷の場合」で、「印刷」と「場合」を名詞同士でつなぐ「の」。", "が": "「印刷が場合」では主語を示す「が」になり、名詞同士をつなげない。", "を": "「を」は目的語を示すので、「印刷を場合」と名詞に続けてもつながらない。", "に": "「に」は場所や時を示す助詞で、「印刷に場合」と名詞をつなぐ用法はない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所・時"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "文字や絵を紙などにたくさん同じ形で写すこと。", "primary_collocate": null, "pronunciation": "いんさつ", "ipa": "insatsɯ", "syllable_count": 4, "sentences": [{"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "印刷", "complexity_tier": "T4", "furigana": "絵師[えし]の描[えが]いた下絵[したえ]を彫師[ほりし]が版木[はんぎ]に彫[ほ]り、摺師[すりし]が紙[かみ]に印刷[いんさつ]するという複雑[ふくざつ]な工程[こうてい]を経[へ]ます。", "sentence_source": "mined"}, {"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "印刷", "complexity_tier": "T4", "furigana": "特[とく]に多色印刷[たしょくいんさつ]の場合[ばあい]、色[いろ]ごとに異[こと]なる版木[はんぎ]を使[つか]い分[わ]ける必要[ひつよう]があり、職人[しょくにん]たちの高度[こうど]な技術[ぎじゅつ]と協力[きょうりょく]が不可欠[ふかけつ]です。", "sentence_source": "mined"}, {"text": "会議の資料を二十部印刷してください。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "会議[かいぎ]の資料[しりょう]を二十部[にじゅうぶ]印刷[いんさつ]してください。", "sentence_source": "generated"}, {"text": "このプリンターは、写真をきれいに印刷できる。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "このプリンターは、写真[しゃしん]をきれいに印刷[いんさつ]できる。", "sentence_source": "generated"}, {"text": "印刷が終わったら、紙をホチキスで留めます。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "印刷[いんさつ]が終[お]わったら、紙[かみ]をホチキスで留[と]めます。", "sentence_source": "generated"}, {"text": "原稿を確認してから、印刷に回します。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "原稿[げんこう]を確認[かくにん]してから、印刷[いんさつ]に回[まわ]します。", "sentence_source": "generated"}, {"text": "両面に印刷すると、紙の量を減らせる。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "両面[りょうめん]に印刷[いんさつ]すると、紙[かみ]の量[りょう]を減[へ]らせる。", "sentence_source": "generated"}, {"text": "インクが切れて、印刷がかすれてしまった。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "インクが切[き]れて、印刷[いんさつ]がかすれてしまった。", "sentence_source": "generated"}, {"text": "卒業文集は、百冊だけ印刷することになった。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "卒業文集[そつぎょうぶんしゅう]は、百冊[ひゃくさつ]だけ印刷[いんさつ]することになった。", "sentence_source": "generated"}, {"text": "印刷の前に、誤字がないかもう一度確認した。", "target_word": "印刷", "complexity_tier": "T3", "furigana": "印刷[いんさつ]の前[まえ]に、誤字[ごじ]がないかもう一度[いちど]確認[かくにん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "印刷", "label": "基本形"}, {"form": "印刷する", "label": "する動詞"}, {"form": "印刷した", "label": "過去形"}, {"form": "印刷される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "同じ文字や絵を紙に多数写すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 版木 (Zipf 2.03)','sentence 1 above tier T2: contains vocabulary far above tier T2: 版木 (Zipf 2.03)']::text[], '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷", "is_correct": true, "explanation": "「紙に印刷する」で、版を使って紙に文字や絵を写す工程を指す。"}, {"text": "製本", "is_correct": false, "explanation": "製本は紙を綴じて本にする作業で、「紙に製本する」と続けると工程として不自然になる。"}, {"text": "下絵", "is_correct": false, "explanation": "下絵は写す前の下描きで、「紙に下絵する」という動作の形にはならない。"}, {"text": "版木", "is_correct": false, "explanation": "版木は彫って版にする木の板で、「紙に版木する」とは言えない。"}], "explanations": {"印刷": "「紙に印刷する」で、版を使って紙に文字や絵を写す工程を指す。", "製本": "製本は紙を綴じて本にする作業で、「紙に製本する」と続けると工程として不自然になる。", "下絵": "下絵は写す前の下描きで、「紙に下絵する」という動作の形にはならない。", "版木": "版木は彫って版にする木の板で、「紙に版木する」とは言えない。"}, "sentence_index": 0, "correct_answer": "印刷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "計算の結果を、パソコンの画面に印刷して確認した。", "explanation": "ここは〈出力〉の意味。印刷は紙に写すことなので、画面に表示する結果には使わない。"}, {"text": "黒板の文字を、ノートに手で印刷した。", "explanation": "ここは〈書き写す〉の意味。手で写す作業には、機械で同じものを作る印刷は使わない。"}, {"text": "この映画は、観客に強い印刷を残した。", "explanation": "ここは〈印象〉の意味。映画が観客に残すのは印象で、紙に写す印刷とは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷", "is_correct": true, "explanation": "「両面に印刷すると」で、紙の表と裏の両方に写す動作を表す。"}, {"text": "原稿", "is_correct": false, "explanation": "原稿は印刷する前の文章のことで、「両面に原稿すると」という動作にはならない。"}, {"text": "用紙", "is_correct": false, "explanation": "用紙は紙そのものを指し、「両面に用紙すると」と続けても動作を表さない。"}, {"text": "紙質", "is_correct": false, "explanation": "紙質は紙の質を表す語で、「両面に紙質すると」とは動作として言えない。"}], "explanations": {"印刷": "「両面に印刷すると」で、紙の表と裏の両方に写す動作を表す。", "原稿": "原稿は印刷する前の文章のことで、「両面に原稿すると」という動作にはならない。", "用紙": "用紙は紙そのものを指し、「両面に用紙すると」と続けても動作を表さない。", "紙質": "紙質は紙の質を表す語で、「両面に紙質すると」とは動作として言えない。"}, "sentence_index": 6, "correct_answer": "印刷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業を印刷して、後で聞き返した。", "explanation": "ここは〈録音〉の意味。印刷は紙に文字や絵を写すことなので、音声の授業には使わない。"}, {"text": "会社は、古い販売の仕組みを印刷した。", "explanation": "ここは〈刷新〉の意味。仕組みを新しくする意味で、紙に写す印刷とは違う。"}, {"text": "絵師は屏風に一点ずつ松を印刷した。", "explanation": "ここは〈描く〉の意味。一点ずつ手で描いた絵に、同じものを大量に刷る印刷は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校正が済んだので、データを印刷を回した。", "corrected_sentence": "校正が済んだので、データを印刷に回した。", "error_description": "「印刷に回す」が正しい形。「回す」は行き先を「に」で示すので、「印刷を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35081, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チラシを印刷で出して、週末までに配った。", "corrected_sentence": "チラシを印刷に出して、週末までに配った。", "error_description": "「印刷に出す」が正しい形。「出す」は送る先を「に」で示すので、「印刷で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35084, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少量", "is_correct": true, "explanation": "正解。「大量」の対義語で、量が少ないことを表す。"}, {"text": "適量", "is_correct": false, "explanation": "量が適切であることを表し、多い少ないの対立語ではない。"}, {"text": "平均", "is_correct": false, "explanation": "基準となる値を指し、量の多さと対になる語ではない。"}, {"text": "全体", "is_correct": false, "explanation": "まとまりの全部を指し、量の多さの反対語ではない。"}], "correct_answer": "少量", "explanations": {"少量": "正解。「大量」の対義語で、量が少ないことを表す。", "適量": "量が適切であることを表し、多い少ないの対立語ではない。", "平均": "基準となる値を指し、量の多さと対になる語ではない。", "全体": "まとまりの全部を指し、量の多さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35084, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少量", "is_correct": true, "explanation": "正解。量が少ないことを表し、「大量」の対義語になる。"}, {"text": "適当", "is_correct": false, "explanation": "程度がほどよいことを表し、量の少なさとは対にならない。"}, {"text": "通常", "is_correct": false, "explanation": "ふだんどおりという意味で、量の多少とは関係しない。"}, {"text": "中心", "is_correct": false, "explanation": "真ん中の位置を指し、量の対義語ではない。"}], "correct_answer": "少量", "explanations": {"少量": "正解。量が少ないことを表し、「大量」の対義語になる。", "適当": "程度がほどよいことを表し、量の少なさとは対にならない。", "通常": "ふだんどおりという意味で、量の多少とは関係しない。", "中心": "真ん中の位置を指し、量の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35084, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "とても多いこと。", "primary_collocate": null, "pronunciation": "たいりょう", "ipa": "taiɾʲoː", "syllable_count": 4, "sentences": [{"text": "祭りの日、屋台で大量のたこ焼きが売れた。", "target_word": "大量", "complexity_tier": "T2", "furigana": "祭[まつ]りの日[ひ]、屋台[やたい]で大量[たいりょう]のたこ焼[や]きが売[う]れた。", "sentence_source": "generated"}, {"text": "朝から大量の雪が降って、道が真っ白になった。", "target_word": "大量", "complexity_tier": "T2", "furigana": "朝[あさ]から大量[たいりょう]の雪[ゆき]が降[ふ]って、道[みち]が真[ま]っ白[しろ]になった。", "sentence_source": "generated"}, {"text": "母は大量のカレーを作って、近所にも分けた。", "target_word": "大量", "complexity_tier": "T2", "furigana": "母[はは]は大量[たいりょう]のカレーを作[つく]って、近所[きんじょ]にも分[わ]けた。", "sentence_source": "generated"}, {"text": "夏休みの宿題が大量に出て、遊ぶ時間がない。", "target_word": "大量", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの宿題[しゅくだい]が大量[たいりょう]に出[で]て、遊[あそ]ぶ時間[じかん]がない。", "sentence_source": "generated"}, {"text": "スーパーで大量に買うと、少し安くなる。", "target_word": "大量", "complexity_tier": "T2", "furigana": "スーパーで大量[たいりょう]に買[か]うと、少[すこ]し安[やす]くなる。", "sentence_source": "generated"}, {"text": "大量の本を運んだので、腕が痛くなった。", "target_word": "大量", "complexity_tier": "T2", "furigana": "大量[たいりょう]の本[ほん]を運[はこ]んだので、腕[うで]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "公園に大量のハトが集まって、とてもにぎやかだ。", "target_word": "大量", "complexity_tier": "T3", "furigana": "公園[こうえん]に大量[たいりょう]のハトが集[あつ]まって、とてもにぎやかだ。", "sentence_source": "generated"}, {"text": "海岸に大量のごみが流れ着いて、みんなで拾った。", "target_word": "大量", "complexity_tier": "T3", "furigana": "海岸[かいがん]に大量[たいりょう]のごみが流[なが]れ着[つ]いて、みんなで拾[ひろ]った。", "sentence_source": "generated"}, {"text": "工場の排水から大量の水が流れ出て、川が濁った。", "target_word": "大量", "complexity_tier": "T3", "furigana": "工場[こうじょう]の排水[はいすい]から大量[たいりょう]の水[みず]が流[なが]れ出[で]て、川[かわ]が濁[にご]った。", "sentence_source": "generated"}, {"text": "旅行のため大量の荷物を持って、駅まで歩いた。", "target_word": "大量", "complexity_tier": "T3", "furigana": "旅行[りょこう]のため大量[たいりょう]の荷物[にもつ]を持[も]って、駅[えき]まで歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大量", "label": "基本形"}, {"form": "大量の", "label": "連体形"}, {"form": "大量に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "ものの量がとても多いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35084, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大量", "is_correct": true, "explanation": "「大量の」の形で数の多さを表し、たこ焼きがたくさん売れた様子に合う。"}, {"text": "大量に", "is_correct": false, "explanation": "副詞形なので、名詞「たこ焼き」を直接修飾できない。"}, {"text": "大切", "is_correct": false, "explanation": "「大切な」の形で使い、「大切のたこ焼き」とは続かない。"}, {"text": "大丈夫", "is_correct": false, "explanation": "問題がないという意味の語で、数量を表す名詞の前には置けない。"}], "explanations": {"大量": "「大量の」の形で数の多さを表し、たこ焼きがたくさん売れた様子に合う。", "大量に": "副詞形なので、名詞「たこ焼き」を直接修飾できない。", "大切": "「大切な」の形で使い、「大切のたこ焼き」とは続かない。", "大丈夫": "問題がないという意味の語で、数量を表す名詞の前には置けない。"}, "sentence_index": 0, "correct_answer": "大量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その決定は会社に大量の影響を与えた。", "explanation": "ここは〈多大〉の場面。大量は物や数の多さに使い、影響のような抽象的な大きさには使わない。"}, {"text": "面白い映画だったので、みんな大量に笑った。", "explanation": "ここは〈大いに〉の場面。大量に は数や量を表すので、笑いの程度を表す語としては使わない。"}, {"text": "彼女はピアノが大量に上手だ。", "explanation": "ここは〈とても〉の場面。大量に は数量を表す副詞なので、上手さの程度を表す形容詞には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35084, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大量", "is_correct": true, "explanation": "「大量の」で数の多さを表し、ハトがたくさん集まった様子に合う。"}, {"text": "大変", "is_correct": false, "explanation": "程度の大きさを表す語で、「大変のハト」の形では続かない。"}, {"text": "大事", "is_correct": false, "explanation": "「大事な〜」の形で大切さを表し、「大事のハト」とは言わない。"}, {"text": "大胆", "is_correct": false, "explanation": "「大胆な」の形で振る舞いを表し、ハトの数には使えない。"}], "explanations": {"大量": "「大量の」で数の多さを表し、ハトがたくさん集まった様子に合う。", "大変": "程度の大きさを表す語で、「大変のハト」の形では続かない。", "大事": "「大事な〜」の形で大切さを表し、「大事のハト」とは言わない。", "大胆": "「大胆な」の形で振る舞いを表し、ハトの数には使えない。"}, "sentence_index": 6, "correct_answer": "大量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい法律の施行で、人々の暮らしは大量に変わった。", "explanation": "ここは〈大きく〉の場面。大量に は量の多さを表すので、変化の大きさを表す語としては使わない。"}, {"text": "その新製品は発売後、大量の成功を収めた。", "explanation": "ここは〈大成功〉の場面。大量 は数量の多さを表し、成功の度合いには使わない。"}, {"text": "彼は失敗を大量に反省し、二度と同じ過ちを繰り返さなかった。", "explanation": "ここは〈深く〉の場面。大量に は数の多さを示すので、反省の深さを表す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35084, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、祖父は魚を大量で釣って、家族に配った。", "corrected_sentence": "昨日、祖父は魚を大量に釣って、家族に配った。", "error_description": "「大量」を副詞として使うときは「大量に」の形になる。「大量で釣る」は誤りで、「で」を「に」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
