INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35085, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "数量や程度が非常に大きいこと。", "primary_collocate": null, "pronunciation": "たいりょう", "ipa": "taiɾʲoː", "syllable_count": 4, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "大量", "complexity_tier": "T4", "furigana": "しかし、産業[さんぎょう]革命[かくめい]以降[いこう]の急激[きゅうげき]な人間[にんげん]活動[かつどう]、とりわけ化石[かせき]燃料[ねんりょう]の大量[たいりょう]消費[しょうひ]と森林[しんりん]破壊[はかい]は、この循環[じゅんかん]に深刻[しんこく]な破綻[はたん]をもたらした。", "sentence_source": "mined"}, {"text": "工場から大量の廃水が川に流れ込み、魚が死んだ。", "target_word": "大量", "complexity_tier": "T3", "furigana": "工場[こうじょう]から大量[たいりょう]の廃水[はいすい]が川[かわ]に流[なが]れ込[こ]み、魚[さかな]が死[し]んだ。", "sentence_source": "generated"}, {"text": "この店では、毎日大量のパンを焼いて売っている。", "target_word": "大量", "complexity_tier": "T3", "furigana": "この店[みせ]では、毎日[まいにち]大量[たいりょう]のパンを焼[や]いて売[う]っている。", "sentence_source": "generated"}, {"text": "事故のあと、病院には大量の血液が必要になった。", "target_word": "大量", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、病院[びょういん]には大量[たいりょう]の血液[けつえき]が必要[ひつよう]になった。", "sentence_source": "generated"}, {"text": "台風で大量の雨が降り、川の水があふれた。", "target_word": "大量", "complexity_tier": "T3", "furigana": "台風[たいふう]で大量[たいりょう]の雨[あめ]が降[ふ]り、川[かわ]の水[みず]があふれた。", "sentence_source": "generated"}, {"text": "大量に生産すれば、一つあたりの値段を安くできる。", "target_word": "大量", "complexity_tier": "T3", "furigana": "大量[たいりょう]に生産[せいさん]すれば、一[ひと]つあたりの値段[ねだん]を安[やす]くできる。", "sentence_source": "generated"}, {"text": "引っ越しの日、大量のごみが出て、片づけるのが大変だった。", "target_word": "大量", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、大量[たいりょう]のごみが出[で]て、片[かた]づけるのが大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "彼は大量の資料を読み、三日でレポートを書き上げた。", "target_word": "大量", "complexity_tier": "T3", "furigana": "彼[かれ]は大量[たいりょう]の資料[しりょう]を読[よ]み、三日[みっか]でレポートを書[か]き上[あ]げた。", "sentence_source": "generated"}, {"text": "倉庫には、大量の商品が箱に入ったまま積まれている。", "target_word": "大量", "complexity_tier": "T3", "furigana": "倉庫[そうこ]には、大量[たいりょう]の商品[しょうひん]が箱[はこ]に入[はい]ったまま積[つ]まれている。", "sentence_source": "generated"}, {"text": "薬を大量に飲むと、体に害があるので危険だ。", "target_word": "大量", "complexity_tier": "T3", "furigana": "薬[くすり]を大量[たいりょう]に飲[の]むと、体[からだ]に害[がい]があるので危険[きけん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大量", "label": "基本形"}, {"form": "大量の", "label": "連体形"}, {"form": "大量に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "物の数量や規模が非常に多く大きいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 廃水 (Zipf 1.97)']::text[], '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35085, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大量", "is_correct": true, "explanation": "「大量消費」は消費する量の多さを表す定まった語で、化石燃料の文脈に合う。"}, {"text": "友情", "is_correct": false, "explanation": "「友情消費」という語は存在せず、化石燃料の文脈に合わない。"}, {"text": "寒冷", "is_correct": false, "explanation": "「寒冷消費」は意味が通らず、燃料を使う行為を表せない。"}, {"text": "平和", "is_correct": false, "explanation": "「平和消費」は意味をなさず、燃料の使い方を表せない。"}], "explanations": {"大量": "「大量消費」は消費する量の多さを表す定まった語で、化石燃料の文脈に合う。", "友情": "「友情消費」という語は存在せず、化石燃料の文脈に合わない。", "寒冷": "「寒冷消費」は意味が通らず、燃料を使う行為を表せない。", "平和": "「平和消費」は意味をなさず、燃料の使い方を表せない。"}, "sentence_index": 0, "correct_answer": "大量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の励ましに、大量に感謝した。", "explanation": "ここは〈大いに〉の意味。大量は数量の多さを表すので、感謝の程度を言う副詞としては使わない。"}, {"text": "この計画は大量の規模で進められた。", "explanation": "ここは〈大規模〉の意味。大量は数や量の多さを表すので、事業の規模を言うときには使わない。"}, {"text": "彼の握力は大量だ。", "explanation": "ここは〈強い〉の意味。大量は数量の多さを表すので、力の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35085, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大量", "is_correct": true, "explanation": "「大量のごみ」は数量の多さを表し、引っ越しで出たごみの量の文脈に合う。"}, {"text": "読書", "is_correct": false, "explanation": "「読書のごみ」は意味が通らず、引っ越しで出たごみを表せない。"}, {"text": "演奏", "is_correct": false, "explanation": "「演奏のごみ」は意味をなさず、片づけの大変さを説明できない。"}, {"text": "恋愛", "is_correct": false, "explanation": "「恋愛のごみ」は意味が通らず、引っ越しの場面に合わない。"}], "explanations": {"大量": "「大量のごみ」は数量の多さを表し、引っ越しで出たごみの量の文脈に合う。", "読書": "「読書のごみ」は意味が通らず、引っ越しで出たごみを表せない。", "演奏": "「演奏のごみ」は意味をなさず、片づけの大変さを説明できない。", "恋愛": "「恋愛のごみ」は意味が通らず、引っ越しの場面に合わない。"}, "sentence_index": 6, "correct_answer": "大量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日、大量に疲れていた。", "explanation": "ここは〈ひどく〉の意味。大量は数量の多さを表すので、疲れの程度を言うときには使わない。"}, {"text": "寒さが大量だ。", "explanation": "ここは〈厳しい〉の意味。大量は数量の多さを表すので、寒さの厳しさには使わない。"}, {"text": "この部屋は大量に暗い。", "explanation": "ここは〈暗い〉の意味。大量は数量の多さを表すので、部屋の明るさの度合いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35085, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の図書館には大量を本が並んでいる。", "corrected_sentence": "町の図書館には大量の本が並んでいる。", "error_description": "「大量」は後ろの名詞「本」を修飾するので「の」を使う。「大量を本が」は「を」が誤りで、目的語が二つ続いて文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35085, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "倉庫で大量を商品を注文した。", "corrected_sentence": "倉庫で大量の商品を注文した。", "error_description": "「大量」は商品の量を修飾するので、後の名詞に続けるには「の」を使う。「を」を置くと、目的語が二つ続いてしまい文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「中心から外まで」の起点を示し、範囲の始まりとして文に合う。"}, {"text": "で", "is_correct": false, "explanation": "「中心で外まで」では起点にならず、範囲の始まりを示せない。"}, {"text": "と", "is_correct": false, "explanation": "「中心と外まで」は並列の意味になり、起点と終点の関係が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「中心へ外まで」は方向の示し方として不自然で、起点を表せない。"}], "correct_answer": "から", "explanations": {"から": "「中心から外まで」の起点を示し、範囲の始まりとして文に合う。", "で": "「中心で外まで」では起点にならず、範囲の始まりを示せない。", "と": "「中心と外まで」は並列の意味になり、起点と終点の関係が合わない。", "へ": "「中心へ外まで」は方向の示し方として不自然で、起点を表せない。"}, "error_tags": {"で": "動作の場所", "と": "並列", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "周辺", "is_correct": true, "explanation": "中心の反対で、周りの部分を表す。類語辞典で対義語とされる。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面を指し、中心の対義語ではない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入口を指し、中心と反対の関係にはない。"}, {"text": "歴史", "is_correct": false, "explanation": "時間の積み重ねを指し、場所の中心と対になる語ではない。"}], "correct_answer": "周辺", "explanations": {"周辺": "中心の反対で、周りの部分を表す。類語辞典で対義語とされる。", "天井": "部屋の上の面を指し、中心の対義語ではない。", "玄関": "建物の出入口を指し、中心と反対の関係にはない。", "歴史": "時間の積み重ねを指し、場所の中心と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「池の中心には」は場所を示し、存在を表す「ある」と合う。"}, {"text": "を", "is_correct": false, "explanation": "「池の中心を小さな島がある」は場所を表せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「池の中心より」は比較の形になり、場所の説明にならない。"}, {"text": "が", "is_correct": false, "explanation": "「池の中心が小さな島がある」は場所を示す形にならない。"}], "correct_answer": "に", "explanations": {"に": "「池の中心には」は場所を示し、存在を表す「ある」と合う。", "を": "「池の中心を小さな島がある」は場所を表せず、文が成り立たない。", "より": "「池の中心より」は比較の形になり、場所の説明にならない。", "が": "「池の中心が小さな島がある」は場所を示す形にならない。"}, "error_tags": {"を": "対象", "より": "比較", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "周辺", "is_correct": true, "explanation": "中心の反対で、周りの部分を表す。類語辞典で対義語とされる。"}, {"text": "出口", "is_correct": false, "explanation": "通り抜けるための場所を指し、中心の対義語ではない。"}, {"text": "基礎", "is_correct": false, "explanation": "物事を支える土台を指し、中心と対になる語ではない。"}, {"text": "記録", "is_correct": false, "explanation": "記したものを指し、中心の反対の意味にはならない。"}], "correct_answer": "周辺", "explanations": {"周辺": "中心の反対で、周りの部分を表す。類語辞典で対義語とされる。", "出口": "通り抜けるための場所を指し、中心の対義語ではない。", "基礎": "物事を支える土台を指し、中心と対になる語ではない。", "記録": "記したものを指し、中心の反対の意味にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "真ん中の場所や、いちばん大事な人のことです。", "primary_collocate": null, "pronunciation": "ちゅうしん", "ipa": "tɕɯːɕiɴ", "syllable_count": 4, "sentences": [{"text": "町の中心に大きな公園があるので、休みの日はよく行く。", "target_word": "中心", "complexity_tier": "T3", "furigana": "町[まち]の中心[ちゅうしん]に大[おお]きな公園[こうえん]があるので、休[やす]みの日[ひ]はよく行[い]く。", "sentence_source": "generated"}, {"text": "円の中心から外までの長さを半径という。", "target_word": "中心", "complexity_tier": "T3", "furigana": "円[えん]の中心[ちゅうしん]から外[そと]までの長[なが]さを半径[はんけい]という。", "sentence_source": "generated"}, {"text": "彼はクラスの中心だから、みんな彼の話をよく聞く。", "target_word": "中心", "complexity_tier": "T3", "furigana": "彼[かれ]はクラスの中心[ちゅうしん]だから、みんな彼[かれ]の話[はなし]をよく聞[き]く。", "sentence_source": "generated"}, {"text": "部屋の中心にテーブルを置いたら、とても広く見えた。", "target_word": "中心", "complexity_tier": "T3", "furigana": "部屋[へや]の中心[ちゅうしん]にテーブルを置[お]いたら、とても広[ひろ]く見[み]えた。", "sentence_source": "generated"}, {"text": "庭の中心に大きな木が植えてあって、夏は日陰ができる。", "target_word": "中心", "complexity_tier": "T3", "furigana": "庭[にわ]の中心[ちゅうしん]に大[おお]きな木[き]が植[う]えてあって、夏[なつ]は日陰[ひかげ]ができる。", "sentence_source": "generated"}, {"text": "彼女は家族の中心で、何かあるとみんなが彼女に相談する。", "target_word": "中心", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は家族[かぞく]の中心[ちゅうしん]で、何[なに]かあるとみんなが彼女[かのじょ]に相談[そうだん]する。", "sentence_source": "generated"}, {"text": "地図の中心に赤い印があるので、そこが今いる場所だ。", "target_word": "中心", "complexity_tier": "T3", "furigana": "地図[ちず]の中心[ちゅうしん]に赤[あか]い印[しるし]があるので、そこが今[いま]いる場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "池の中心には小さな島があって、鳥が休んでいる。", "target_word": "中心", "complexity_tier": "T3", "furigana": "池[いけ]の中心[ちゅうしん]には小[ちい]さな島[しま]があって、鳥[とり]が休[やす]んでいる。", "sentence_source": "generated"}, {"text": "的の中心を狙って矢を放ったが、外れてしまった。", "target_word": "中心", "complexity_tier": "T3", "furigana": "的[まと]の中心[ちゅうしん]を狙[ねら]って矢[や]を放[はな]ったが、外[はず]れてしまった。", "sentence_source": "generated"}, {"text": "ボールを台の中心に置かないと、すぐに落ちてしまう。", "target_word": "中心", "complexity_tier": "T3", "furigana": "ボールを台[だい]の中心[ちゅうしん]に置[お]かないと、すぐに落[お]ちてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中心", "label": "基本形"}, {"form": "中心に", "label": "に格"}, {"form": "中心の", "label": "の格"}], "register": "普通体", "sense_fingerprint": "場所の真ん中、または集団でいちばん大事な人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "町の真ん中の場所を表し、「町の中心に大きな公園がある」として自然に通る。"}, {"text": "歴史", "is_correct": false, "explanation": "「町の歴史に大きな公園がある」は場所を示さず、文の意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「町の天気に大きな公園がある」は場所の語として成り立たない。"}, {"text": "料金", "is_correct": false, "explanation": "「町の料金に大きな公園がある」は場所を示せず、公園の所在を表せない。"}], "explanations": {"中心": "町の真ん中の場所を表し、「町の中心に大きな公園がある」として自然に通る。", "歴史": "「町の歴史に大きな公園がある」は場所を示さず、文の意味が通らない。", "天気": "「町の天気に大きな公園がある」は場所の語として成り立たない。", "料金": "「町の料金に大きな公園がある」は場所を示せず、公園の所在を表せない。"}, "sentence_index": 0, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マラソンは中心を過ぎたところで、足が止まった。", "explanation": "ここは〈中間〉の意味。中心は一点の真ん中を指すので、道のりの途中の段階には使えないため合わない。"}, {"text": "かばんの中心の値段を聞いて、思わず驚いた。", "explanation": "ここは〈値段〉の意味。中心は位置を指すので、値段の高さを表す用法にはならないため合わない。"}, {"text": "夏の中心に旅行へ行くことにした。", "explanation": "ここは〈中頃〉の意味。中心は場所の真ん中を指し、時期の途中には使わないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "地図の真ん中の位置を表し、「地図の中心に赤い印がある」として自然に通る。"}, {"text": "感情", "is_correct": false, "explanation": "「地図の感情に赤い印がある」は位置を示せず、意味が通らない。"}, {"text": "予算", "is_correct": false, "explanation": "「地図の予算に赤い印がある」は地図上の位置にならない。"}, {"text": "体重", "is_correct": false, "explanation": "「地図の体重に赤い印がある」は位置を示せず、文が成り立たない。"}], "explanations": {"中心": "地図の真ん中の位置を表し、「地図の中心に赤い印がある」として自然に通る。", "感情": "「地図の感情に赤い印がある」は位置を示せず、意味が通らない。", "予算": "「地図の予算に赤い印がある」は地図上の位置にならない。", "体重": "「地図の体重に赤い印がある」は位置を示せず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作業の中心で電話が鳴ったので、手を止めた。", "explanation": "ここは〈途中〉の意味。中心は位置の真ん中を指すので、作業が進んでいる時点は表せないため合わない。"}, {"text": "池の中心をぐるりと一周してから、家に帰った。", "explanation": "ここは〈周囲〉の意味。中心は一点の真ん中を指し、ぐるりと回る周りは表せないので合わない。"}, {"text": "コップの中心が欠けてしまったので、使わないことにした。", "explanation": "ここは〈縁〉の意味。中心は真ん中を指し、欠けるのは外側の縁なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の中心で大きな病院がある。", "corrected_sentence": "町の中心に大きな病院がある。", "error_description": "「ある」は存在を表すので、場所は「に」で示す。「で」は動作の場所を表すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35086, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボールを台の中心を置くと、安定する。", "corrected_sentence": "ボールを台の中心に置くと、安定する。", "error_description": "「置く」は置く先を「に」で表す。「を」は対象につくため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「を中心に」の形で、野菜を中心にした販売を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「野菜を中心を」は中心の後ろに対象を置く形になり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「野菜を中心が」は主語の形にならず、販売の内容を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「野菜を中心より」は比較の形になり、販売の内容の説明にならない。"}], "correct_answer": "に", "explanations": {"に": "「を中心に」の形で、野菜を中心にした販売を表し、文に合う。", "を": "「野菜を中心を」は中心の後ろに対象を置く形になり、文が成り立たない。", "が": "「野菜を中心が」は主語の形にならず、販売の内容を表せない。", "より": "「野菜を中心より」は比較の形になり、販売の内容の説明にならない。"}, "error_tags": {"を": "対象", "が": "主語", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "周辺", "is_correct": true, "explanation": "中心の反対で、物事の周りの部分を表す。類語辞典で対義語とされる。"}, {"text": "単位", "is_correct": false, "explanation": "物の大きさを測る基準を指し、中心の対義語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "物事を進める順序を指し、中心と対になる語ではない。"}, {"text": "感想", "is_correct": false, "explanation": "受けた印象を指し、中心の反対の意味にはならない。"}], "correct_answer": "周辺", "explanations": {"周辺": "中心の反対で、物事の周りの部分を表す。類語辞典で対義語とされる。", "単位": "物の大きさを測る基準を指し、中心の対義語ではない。", "手順": "物事を進める順序を指し、中心と対になる語ではない。", "感想": "受けた印象を指し、中心の反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中心になって」の形で、役割として中心になることを表し、文に合う。"}, {"text": "で", "is_correct": false, "explanation": "「若い人が中心で、なって活動」は役割の形にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「中心へなって」は方向を表す形になり、役割の説明にならない。"}, {"text": "から", "is_correct": false, "explanation": "「中心からなって」は起点を表す形になり、役割を示せない。"}], "correct_answer": "に", "explanations": {"に": "「中心になって」の形で、役割として中心になることを表し、文に合う。", "で": "「若い人が中心で、なって活動」は役割の形にならず、文が成り立たない。", "へ": "「中心へなって」は方向を表す形になり、役割の説明にならない。", "から": "「中心からなって」は起点を表す形になり、役割を示せない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "周辺", "is_correct": true, "explanation": "中心の反対で、物事の周りの部分を表す。類語辞典で対義語とされる。"}, {"text": "出口", "is_correct": false, "explanation": "通り抜けるための場所を指し、中心の対義語ではない。"}, {"text": "基礎", "is_correct": false, "explanation": "物事を支える土台を指し、中心と対になる語ではない。"}, {"text": "記録", "is_correct": false, "explanation": "記したものを指し、中心の反対の意味にはならない。"}], "correct_answer": "周辺", "explanations": {"周辺": "中心の反対で、物事の周りの部分を表す。類語辞典で対義語とされる。", "出口": "通り抜けるための場所を指し、中心の対義語ではない。", "基礎": "物事を支える土台を指し、中心と対になる語ではない。", "記録": "記したものを指し、中心の反対の意味にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の真ん中の部分や、活動などでいちばん重要な役割を果たすものや人のこと。", "primary_collocate": null, "pronunciation": "ちゅうしん", "ipa": "tɕɯːɕiɴ", "syllable_count": 4, "sentences": [{"text": "今日の会議は、新しい商品の話が中心だった。", "target_word": "中心", "complexity_tier": "T3", "furigana": "今日[きょう]の会議[かいぎ]は、新[あたら]しい商品[しょうひん]の話[はなし]が中心[ちゅうしん]だった。", "sentence_source": "generated"}, {"text": "この店は、野菜を中心に安い物をたくさん売っている。", "target_word": "中心", "complexity_tier": "T3", "furigana": "この店[みせ]は、野菜[やさい]を中心[ちゅうしん]に安[やす]い物[もの]をたくさん売[う]っている。", "sentence_source": "generated"}, {"text": "大阪を中心に、関西では雨が強くなるそうだ。", "target_word": "中心", "complexity_tier": "T3", "furigana": "大阪[おおさか]を中心[ちゅうしん]に、関西[かんさい]では雨[あめ]が強[つよ]くなるそうだ。", "sentence_source": "generated"}, {"text": "彼女は研究の中心として、毎日遅くまで働いている。", "target_word": "中心", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は研究[けんきゅう]の中心[ちゅうしん]として、毎日[まいにち]遅[おそ]くまで働[はたら]いている。", "sentence_source": "generated"}, {"text": "問題の中心がわからないと、答えは見つからない。", "target_word": "中心", "complexity_tier": "T3", "furigana": "問題[もんだい]の中心[ちゅうしん]がわからないと、答[こた]えは見[み]つからない。", "sentence_source": "generated"}, {"text": "私の食事は魚が中心で、肉はあまり食べない。", "target_word": "中心", "complexity_tier": "T3", "furigana": "私[わたし]の食事[しょくじ]は魚[さかな]が中心[ちゅうしん]で、肉[にく]はあまり食[た]べない。", "sentence_source": "generated"}, {"text": "台風の中心が近づくと、風がさらに強くなる。", "target_word": "中心", "complexity_tier": "T3", "furigana": "台風[たいふう]の中心[ちゅうしん]が近[ちか]づくと、風[かぜ]がさらに強[つよ]くなる。", "sentence_source": "generated"}, {"text": "このクラブは、若い人が中心になって活動している。", "target_word": "中心", "complexity_tier": "T3", "furigana": "このクラブは、若[わか]い人[ひと]が中心[ちゅうしん]になって活動[かつどう]している。", "sentence_source": "generated"}, {"text": "話の中心をはっきりさせてから、短くまとめて書こう。", "target_word": "中心", "complexity_tier": "T3", "furigana": "話[はなし]の中心[ちゅうしん]をはっきりさせてから、短[みじか]くまとめて書[か]こう。", "sentence_source": "generated"}, {"text": "日本の経済は、東京を中心に動いている。", "target_word": "中心", "complexity_tier": "T3", "furigana": "日本[にほん]の経済[けいざい]は、東京[とうきょう]を中心[ちゅうしん]に動[うご]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中心", "label": "基本形"}, {"form": "中心に", "label": "に格"}, {"form": "中心が", "label": "が格"}], "register": "普通体", "sense_fingerprint": "物事の核となる部分、活動の主な内容や中心となる人・地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "話の主な内容を表し、「新しい商品の話が中心だった」として自然に通る。"}, {"text": "天気", "is_correct": false, "explanation": "「新しい商品の話が天気だった」は意味が通らず、話の内容を示せない。"}, {"text": "機嫌", "is_correct": false, "explanation": "「新しい商品の話が機嫌だった」は話の内容を表せず、文が成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "「新しい商品の話が体重だった」は話の内容として成り立たない。"}], "explanations": {"中心": "話の主な内容を表し、「新しい商品の話が中心だった」として自然に通る。", "天気": "「新しい商品の話が天気だった」は意味が通らず、話の内容を示せない。", "機嫌": "「新しい商品の話が機嫌だった」は話の内容を表せず、文が成り立たない。", "体重": "「新しい商品の話が体重だった」は話の内容として成り立たない。"}, "sentence_index": 0, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は長引いたが、やっと中心を出すことができた。", "explanation": "ここは〈結論〉の意味。中心は話の要点を指すので、結論を出すとは言わないため合わない。"}, {"text": "彼は中心の車を安く買った。", "explanation": "ここは〈中古〉の意味。中心は位置や重要な部分を指すので、使われた車には使えないため合わない。"}, {"text": "妹は来年、中心に入学する予定だ。", "explanation": "ここは〈中学〉の意味。中心は学校の種類を表さないので、中学校への入学には使えないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "台風の真ん中の部分を表し、「台風の中心が近づく」として自然に通る。"}, {"text": "評判", "is_correct": false, "explanation": "「台風の評判が近づく」は意味が通らず、台風の部分を示せない。"}, {"text": "予算", "is_correct": false, "explanation": "「台風の予算が近づく」は台風の一部を表さず、文が成り立たない。"}, {"text": "年齢", "is_correct": false, "explanation": "「台風の年齢が近づく」は台風に対して意味を持たず、文が成り立たない。"}], "explanations": {"中心": "台風の真ん中の部分を表し、「台風の中心が近づく」として自然に通る。", "評判": "「台風の評判が近づく」は意味が通らず、台風の部分を示せない。", "予算": "「台風の予算が近づく」は台風の一部を表さず、文が成り立たない。", "年齢": "「台風の年齢が近づく」は台風に対して意味を持たず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "目的を果たすため、中心を一つ選んで実行した。", "explanation": "ここは〈手段〉の意味。中心は物事の核を指し、目的を果たす方法は表さないため合わない。"}, {"text": "締め切りを過ぎたので、中心を過ぎたことになった。", "explanation": "ここは〈期限〉の意味。中心は時点を表さないので、締め切りの時間には使えないため合わない。"}, {"text": "夜になって、中心が下がってきた。", "explanation": "ここは〈気温〉の意味。中心は温度や数値を表さないので、下がる対象にならないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は果物を中心で、新鮮な食品を売っている。", "corrected_sentence": "この店は果物を中心に、新鮮な食品を売っている。", "error_description": "「〜を中心に」の形で「に」が必要。「で」は場所や手段を表すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35087, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の中心を入ると、とても危ない。", "corrected_sentence": "台風の中心に入ると、とても危ない。", "error_description": "「入る」は行き先を「に」で表す。「を」は対象につくため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黙る", "is_correct": true, "explanation": "言うの反対で、口を閉じて話さないことを表す。類語辞典で対義語とされる。"}, {"text": "歌う", "is_correct": false, "explanation": "節をつけて声を出すことを指し、言うの反対の意味にはならない。"}, {"text": "書く", "is_correct": false, "explanation": "文字で表すことを指し、言うの対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "寝て休むことを指し、言うと対になる語ではない。"}], "correct_answer": "黙る", "explanations": {"黙る": "言うの反対で、口を閉じて話さないことを表す。類語辞典で対義語とされる。", "歌う": "節をつけて声を出すことを指し、言うの反対の意味にはならない。", "書く": "文字で表すことを指し、言うの対義語ではない。", "眠る": "寝て休むことを指し、言うと対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黙る", "is_correct": true, "explanation": "言うの反対で、口を閉じて話さないことを表す。類語辞典で対義語とされる。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出すことを指し、言うの反対の意味にはならない。"}, {"text": "食べる", "is_correct": false, "explanation": "食物を口に入れることを指し、言うと対になる語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "足で移動することを指し、言うの対義語ではない。"}], "correct_answer": "黙る", "explanations": {"黙る": "言うの反対で、口を閉じて話さないことを表す。類語辞典で対義語とされる。", "叫ぶ": "大きな声を出すことを指し、言うの反対の意味にはならない。", "食べる": "食物を口に入れることを指し、言うと対になる語ではない。", "走る": "足で移動することを指し、言うの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "口（くち）から言葉（ことば）を出（だ）すこと。", "primary_collocate": null, "pronunciation": "ゆう", "ipa": "jɯː", "syllable_count": 2, "sentences": [{"text": "友だちは「ありがとう」と言って、笑顔で手を振った。", "target_word": "言って", "complexity_tier": "T3", "furigana": "友[とも]だちは「ありがとう」と言[ゆ]って、笑顔[えがお]で手[て]を振[ふ]った。", "sentence_source": "generated"}, {"text": "先生は大きな声で言うので、後ろの席でもよく聞こえる。", "target_word": "言う", "complexity_tier": "T3", "furigana": "先生[せんせい]は大[おお]きな声[こえ]で言[ゆ]うので、後[うし]ろの席[せき]でもよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "弟は何も言わないで、部屋から出ていった。", "target_word": "言わないで", "complexity_tier": "T3", "furigana": "弟[おとうと]は何[なに]も言[ゆ]わないで、部屋[へや]から出[で]ていった。", "sentence_source": "generated"}, {"text": "彼は「あした来る」と言ったのに、来なかった。", "target_word": "言った", "complexity_tier": "T3", "furigana": "彼[かれ]は「あした来[く]る」と言[ゆ]ったのに、来[こ]なかった。", "sentence_source": "generated"}, {"text": "思ったことははっきり言うほうが、相手に伝わりやすい。", "target_word": "言う", "complexity_tier": "T3", "furigana": "思[おも]ったことははっきり言[ゆ]うほうが、相手[あいて]に伝[つた]わりやすい。", "sentence_source": "generated"}, {"text": "父は小さな声で何か言ったが、聞き取れなかった。", "target_word": "言った", "complexity_tier": "T3", "furigana": "父[ちち]は小[ちい]さな声[こえ]で何[なに]か言[ゆ]ったが、聞[き]き取[と]れなかった。", "sentence_source": "generated"}, {"text": "母に「早く寝なさい」と言われて、電気を消した。", "target_word": "言われて", "complexity_tier": "T3", "furigana": "母[はは]に「早[はや]く寝[ね]なさい」と言[ゆ]われて、電気[でんき]を消[け]した。", "sentence_source": "generated"}, {"text": "彼女は怒っていたので、「帰って」とだけ言った。", "target_word": "言った", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は怒[おこ]っていたので、「帰[かえ]って」とだけ言[ゆ]った。", "sentence_source": "generated"}, {"text": "赤ちゃんが初めて「ママ」と言って、家族みんなが喜んだ。", "target_word": "言って", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが初[はじ]めて「ママ」と言[ゆ]って、家族[かぞく]みんなが喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "外国の人にも分かるように、ゆっくり言うことにしている。", "target_word": "言う", "complexity_tier": "T3", "furigana": "外国[がいこく]の人[ひと]にも分[わ]かるように、ゆっくり言[ゆ]うことにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言う", "label": "辞書形"}, {"form": "言った", "label": "過去形"}, {"form": "言って", "label": "て形"}, {"form": "言わない", "label": "否定形"}, {"form": "言われる", "label": "受身形"}], "register": "普通体", "sense_fingerprint": "口から言葉を出して話す、声に出して伝える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言って", "is_correct": true, "explanation": "「と言って」で、言葉を口に出したことを表し、文の流れに合う。"}, {"text": "食べて", "is_correct": false, "explanation": "「ありがとうと食べて」は引用の形に合わず、文が成り立たない。"}, {"text": "寝て", "is_correct": false, "explanation": "「ありがとうと寝て」は引用の形に合わず、文が成り立たない。"}, {"text": "走って", "is_correct": false, "explanation": "「ありがとうと走って」は引用の形に合わず、文が成り立たない。"}], "explanations": {"言って": "「と言って」で、言葉を口に出したことを表し、文の流れに合う。", "食べて": "「ありがとうと食べて」は引用の形に合わず、文が成り立たない。", "寝て": "「ありがとうと寝て」は引用の形に合わず、文が成り立たない。", "走って": "「ありがとうと走って」は引用の形に合わず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "言って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中に犬が言ったので、目が覚めた。", "explanation": "ここは〈鳴く〉の意味。動物の声には〈鳴く〉を使い、〈言う〉は人の言葉を口に出す場合に限るため合わない。"}, {"text": "その思いを手紙に言って送った。", "explanation": "ここは〈書く〉の意味。思いを文字にする場合は〈書く〉を使い、〈言う〉は話す行為なので合わない。"}, {"text": "その曲をピアノで言った。", "explanation": "ここは〈弾く〉の意味。楽器で音楽を出す場合は〈弾く〉を使い、〈言う〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言われて", "is_correct": true, "explanation": "「と言われて」で、人から言葉をかけられたことを表し、文の流れに合う。"}, {"text": "座って", "is_correct": false, "explanation": "「早く寝なさいと座って」は引用の形に合わず、文が成り立たない。"}, {"text": "眠って", "is_correct": false, "explanation": "「早く寝なさいと眠って」は引用の形に合わず、文が成り立たない。"}, {"text": "振って", "is_correct": false, "explanation": "「早く寝なさいと振って」は引用の形に合わず、文が成り立たない。"}], "explanations": {"言われて": "「と言われて」で、人から言葉をかけられたことを表し、文の流れに合う。", "座って": "「早く寝なさいと座って」は引用の形に合わず、文が成り立たない。", "眠って": "「早く寝なさいと眠って」は引用の形に合わず、文が成り立たない。", "振って": "「早く寝なさいと振って」は引用の形に合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "言われて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は仕事で疲れて、ため息を言った。", "explanation": "ここは〈ため息をつく〉の意味。ため息は〈つく〉で表し、〈言う〉は言葉を口に出す行為なので合わない。"}, {"text": "赤ちゃんが夜中に言い続けて、家族は眠れなかった。", "explanation": "ここは〈泣く〉の意味。赤ちゃんの泣き声は〈泣く〉で表し、〈言う〉は話す行為なので合わない。"}, {"text": "庭の花が朝に言った。", "explanation": "ここは〈咲く〉の意味。花が開く様子は〈咲く〉で表し、〈言う〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は「もう帰る」と言いったので、みんなが驚いた。", "corrected_sentence": "彼は「もう帰る」と言ったので、みんなが驚いた。", "error_description": "「言う」の過去形は「言った」。「言いった」は活用の形が誤りなので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "言う", "is_correct": true, "explanation": "辞書形で、「言うので」と後ろにつながる形として文に合う。"}, {"text": "言いて", "is_correct": false, "explanation": "「言う」のて形は「言って」なので、「言いて」は活用の形が誤りで文が成り立たない。"}, {"text": "言いない", "is_correct": false, "explanation": "「ない」は未然形につくので、「言いない」は活用が誤りで文が成り立たない。"}, {"text": "言いので", "is_correct": false, "explanation": "連用形のままでは「ので」に続かず、文が成り立たない。"}], "correct_form": "言う", "base_form": "言う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"言う": "辞書形で、「言うので」と後ろにつながる形として文に合う。", "言いて": "「言う」のて形は「言って」なので、「言いて」は活用の形が誤りで文が成り立たない。", "言いない": "「ない」は未然形につくので、「言いない」は活用が誤りで文が成り立たない。", "言いので": "連用形のままでは「ので」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35090, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は「行こう」と言わて、先に出た。", "corrected_sentence": "彼は「行こう」と言って、先に出た。", "error_description": "「言う」のて形は「言って」。「言わて」は活用の形が誤りなので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "言った", "is_correct": true, "explanation": "過去形で、「とだけ言った」と過去の出来事として文に合う。"}, {"text": "言って", "is_correct": false, "explanation": "て形なので、後ろに続けて動作を並べる形になり、過去の出来事を言い切れない。"}, {"text": "言いかった", "is_correct": false, "explanation": "形容詞のような活用の形で、動詞「言う」の過去形ではないため、文が成り立たない。"}, {"text": "言いた", "is_correct": false, "explanation": "「言いた」は動詞の活用形として成り立たず、文が成り立たない。"}], "correct_form": "言った", "base_form": "言う", "form_label": "過去形", "sentence_index": 7, "explanations": {"言った": "過去形で、「とだけ言った」と過去の出来事として文に合う。", "言って": "て形なので、後ろに続けて動作を並べる形になり、過去の出来事を言い切れない。", "言いかった": "形容詞のような活用の形で、動詞「言う」の過去形ではないため、文が成り立たない。", "言いた": "「言いた」は動詞の活用形として成り立たず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35092, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「技術を身につける」で、身につける対象を示し、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「技術に身につける」は対象の示し方として不自然で、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「技術が身につける」は主語として成り立たず、身につける人が必要なので文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「技術へ身につける」は方向の形になり、身につける対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「技術を身につける」で、身につける対象を示し、文に合う。", "に": "「技術に身につける」は対象の示し方として不自然で、文が成り立たない。", "が": "「技術が身につける」は主語として成り立たず、身につける人が必要なので文が不自然になる。", "へ": "「技術へ身につける」は方向の形になり、身につける対象を示せない。"}, "error_tags": {"に": "相手・対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
