INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35092, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うための特別な方法やわざ。", "primary_collocate": null, "pronunciation": "ぎじゅつ", "ipa": "ɡiʑɯtsɯ", "syllable_count": 3, "sentences": [{"text": "彼は料理の技術が高いので、店はいつも客でいっぱいだ。", "target_word": "技術", "complexity_tier": "T3", "furigana": "彼[かれ]は料理[りょうり]の技術[ぎじゅつ]が高[たか]いので、店[みせ]はいつも客[きゃく]でいっぱいだ。", "sentence_source": "generated"}, {"text": "新しい技術を身につけるために、毎晩練習している。", "target_word": "技術", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]を身[み]につけるために、毎晩[まいばん]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "この職人の技術は、長い経験から生まれたものだ。", "target_word": "技術", "complexity_tier": "T3", "furigana": "この職人[しょくにん]の技術[ぎじゅつ]は、長[なが]い経験[けいけん]から生[う]まれたものだ。", "sentence_source": "generated"}, {"text": "技術が足りなくて、速い球を打ち返せなかった。", "target_word": "技術", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]が足[た]りなくて、速[はや]い球[たま]を打[う]ち返[かえ]せなかった。", "sentence_source": "generated"}, {"text": "絵の技術を磨いたおかげで、コンクールで賞をもらった。", "target_word": "技術", "complexity_tier": "T3", "furigana": "絵[え]の技術[ぎじゅつ]を磨[みが]いたおかげで、コンクールで賞[しょう]をもらった。", "sentence_source": "generated"}, {"text": "兄は車を直す技術を学ぶため、専門学校に入った。", "target_word": "技術", "complexity_tier": "T3", "furigana": "兄[あに]は車[くるま]を直[なお]す技術[ぎじゅつ]を学[まな]ぶため、専門学校[せんもんがっこう]に入[はい]った。", "sentence_source": "generated"}, {"text": "姉は写真の技術には自信があるが、色の選び方はまだ苦手だ。", "target_word": "技術", "complexity_tier": "T3", "furigana": "姉[あね]は写真[しゃしん]の技術[ぎじゅつ]には自信[じしん]があるが、色[いろ]の選[えら]び方[かた]はまだ苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "泳ぎの技術は、何度も練習しないと身につかない。", "target_word": "技術", "complexity_tier": "T3", "furigana": "泳[およ]ぎの技術[ぎじゅつ]は、何度[なんど]も練習[れんしゅう]しないと身[み]につかない。", "sentence_source": "generated"}, {"text": "彼のピアノは技術だけでなく、気持ちもこもっている。", "target_word": "技術", "complexity_tier": "T3", "furigana": "彼[かれ]のピアノは技術[ぎじゅつ]だけでなく、気持[きも]ちもこもっている。", "sentence_source": "generated"}, {"text": "古い技術を守る人が減って、この町の伝統工芸は危ない。", "target_word": "技術", "complexity_tier": "T3", "furigana": "古[ふる]い技術[ぎじゅつ]を守[まも]る人[ひと]が減[へ]って、この町[まち]の伝統工芸[でんとうこうげい]は危[あぶ]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "技術", "label": "基本形"}, {"form": "技術を", "label": "を格"}, {"form": "技術が", "label": "が格"}], "register": "普通体", "sense_fingerprint": "物事をうまく行うための腕前や方法、身につけるわざ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: 打ち返せ (Zipf 1.59)']::text[], '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35092, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技術", "is_correct": true, "explanation": "物事をうまく行う腕前を表し、「料理の技術が高い」として自然に通る。"}, {"text": "天気", "is_correct": false, "explanation": "「料理の天気が高い」は意味が通らず、腕前を示せない。"}, {"text": "体重", "is_correct": false, "explanation": "「料理の体重が高い」は腕前を表さず、文が成り立たない。"}, {"text": "月", "is_correct": false, "explanation": "「料理の月が高い」は意味が通らず、文が成り立たない。"}], "explanations": {"技術": "物事をうまく行う腕前を表し、「料理の技術が高い」として自然に通る。", "天気": "「料理の天気が高い」は意味が通らず、腕前を示せない。", "体重": "「料理の体重が高い」は腕前を表さず、文が成り立たない。", "月": "「料理の月が高い」は意味が通らず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "技術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は技術が明るくて、いつもみんなを笑わせる。", "explanation": "ここは〈性格〉の意味。明るいのは人の性格で、腕前や方法を表す技術には使えないため合わない。"}, {"text": "来週の旅行の技術を立てることにした。", "explanation": "ここは〈計画〉の意味。計画は立てるものだが、技術は立てる対象にならないため合わない。"}, {"text": "店の奥で大きな技術が鳴った。", "explanation": "ここは〈音〉の意味。鳴るのは音で、技術は鳴るものではないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35092, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技術", "is_correct": true, "explanation": "腕前や方法を表し、「写真の技術には自信がある」として自然に通る。"}, {"text": "予算", "is_correct": false, "explanation": "「写真の予算には自信がある」は意味が通らず、腕前を示せない。"}, {"text": "年齢", "is_correct": false, "explanation": "「写真の年齢には自信がある」は意味が通らず、文が成り立たない。"}, {"text": "方角", "is_correct": false, "explanation": "「写真の方角には自信がある」は腕前を表さず、文が成り立たない。"}], "explanations": {"技術": "腕前や方法を表し、「写真の技術には自信がある」として自然に通る。", "予算": "「写真の予算には自信がある」は意味が通らず、腕前を示せない。", "年齢": "「写真の年齢には自信がある」は意味が通らず、文が成り立たない。", "方角": "「写真の方角には自信がある」は腕前を表さず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "技術"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紅茶は技術がよく香る。", "explanation": "ここは〈香り〉の意味。香るのは物の匂いで、技術は香らないため合わない。"}, {"text": "このスープは技術がとても濃い。", "explanation": "ここは〈味〉の意味。濃いのは味で、腕前を表す技術には使わないため合わない。"}, {"text": "この箱は技術が大きい。", "explanation": "ここは〈大きさ〉の意味。大きさは物の寸法を指すので、技術の大小とは言わないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35092, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この職人は、木を削る技術を優れている。", "corrected_sentence": "この職人は、木を削る技術に優れている。", "error_description": "「優れる」は対象を「に」で示す。「を」は誤りなので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35092, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は技術を磨いために、毎日ピアノを弾いている。", "corrected_sentence": "彼女は技術を磨くために、毎日ピアノを弾いている。", "error_description": "「ために」の前は辞書形が必要。「磨いため」は活用の形が誤りなので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。活字を主題にして、その性質（小さい）を後で述べる文なので自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だと「活字を小さいので」となり、小さいという状態の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "方向や帰着を示す格で、「小さい」の主題にはならず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す格で、活字の性質を述べる文の主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。活字を主題にして、その性質（小さい）を後で述べる文なので自然。", "を": "目的語の「を」だと「活字を小さいので」となり、小さいという状態の主語にならない。", "に": "方向や帰着を示す格で、「小さい」の主題にはならず文が成り立たない。", "で": "手段や場所を示す格で、活字の性質を述べる文の主題にはならない。"}, "error_tags": {"を": "目的語", "に": "方向・帰着", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りない」の主語を示す格。不足しているのは活字なので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「足りない」は「〜が足りない」の形を取り、目的語の「を」は取れないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、足りないという状態の主語にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す格で、足りないの主語にはならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「足りない」の主語を示す格。不足しているのは活字なので正しい。", "を": "「足りない」は「〜が足りない」の形を取り、目的語の「を」は取れないので合わない。", "へ": "方向を示す格で、足りないという状態の主語にはならないので合わない。", "と": "相手や並列を示す格で、足りないの主語にはならないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もじをうつためのかた。", "primary_collocate": null, "pronunciation": "かつじ", "ipa": "katsɯʑi", "syllable_count": 3, "sentences": [{"text": "昔の印刷所では、一つずつ活字を並べて文章を作っていた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "昔[むかし]の印刷所[いんさつじょ]では、一[ひと]つずつ活字[かつじ]を並[なら]べて文章[ぶんしょう]を作[つく]っていた。", "sentence_source": "generated"}, {"text": "活字は小さいので、落とすと探すのが大変だ。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]は小[ちい]さいので、落[お]とすと探[さが]すのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "職人は活字を箱から取り出して、順番に並べた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "職人[しょくにん]は活字[かつじ]を箱[はこ]から取[と]り出[だ]して、順番[じゅんばん]に並[なら]べた。", "sentence_source": "generated"}, {"text": "この博物館には、古い活字が千本以上も展示されている。", "target_word": "活字", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]には、古[ふる]い活字[かつじ]が千本[せんぼん]以上[いじょう]も展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "活字の底には文字が逆向きに彫られていて、紙に押すと正しく読める。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]の底[そこ]には文字[もじ]が逆向[ぎゃくむ]きに彫[ほ]られていて、紙[かみ]に押[お]すと正[ただ]しく読[よ]める。", "sentence_source": "generated"}, {"text": "活字にインクをつけてから、紙に強く押した。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]にインクをつけてから、紙[かみ]に強[つよ]く押[お]した。", "sentence_source": "generated"}, {"text": "祖父は印刷所で働いていた頃、毎日活字を拾っていた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "祖父[そふ]は印刷所[いんさつじょ]で働[はたら]いていた頃[ころ]、毎日[まいにち]活字[かつじ]を拾[ひろ]っていた。", "sentence_source": "generated"}, {"text": "活字が一つ足りなくて、ページを完成させられなかった。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]が一[ひと]つ足[た]りなくて、ページを完成[かんせい]させられなかった。", "sentence_source": "generated"}, {"text": "子どもたちは、活字を使ってスタンプのように名前を押した。", "target_word": "活字", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、活字[かつじ]を使[つか]ってスタンプのように名前[なまえ]を押[お]した。", "sentence_source": "generated"}, {"text": "活字は何度も使えるので、印刷が終わったら元の場所に戻す。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]は何度[なんど]も使[つか]えるので、印刷[いんさつ]が終[お]わったら元[もと]の場所[ばしょ]に戻[もど]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活字", "label": "基本形"}, {"form": "活字を", "label": "を格"}, {"form": "活字が", "label": "が格"}], "register": "普通体", "sense_fingerprint": "印刷で文字を紙に写すための、一文字ずつの型（印刷用の部品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活字", "is_correct": true, "explanation": "一つずつ並べて文章を作る、印刷用の型。文脈に合う唯一の語。"}, {"text": "印刷機", "is_correct": false, "explanation": "印刷を行う機械で、一つずつ並べて文章を作るための部品ではないので合わない。"}, {"text": "植字機", "is_correct": false, "explanation": "文字を組む機械で、並べる対象として一つずつ置く物ではないので合わない。"}, {"text": "紙型", "is_correct": false, "explanation": "活字を鋳造するための紙の型で、文章を作るために並べる部品ではないので合わない。"}], "explanations": {"活字": "一つずつ並べて文章を作る、印刷用の型。文脈に合う唯一の語。", "印刷機": "印刷を行う機械で、一つずつ並べて文章を作るための部品ではないので合わない。", "植字機": "文字を組む機械で、並べる対象として一つずつ置く物ではないので合わない。", "紙型": "活字を鋳造するための紙の型で、文章を作るために並べる部品ではないので合わない。"}, "sentence_index": 0, "correct_answer": "活字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "溶かした金を活字に流し込んで、指輪を作った。", "explanation": "ここは〈鋳型〉の意味。活字は印刷用の文字の型で、指輪を作る鋳型とは違う。"}, {"text": "町は活字にあふれ、朝から大勢の人でにぎわった。", "explanation": "ここは〈活気〉の意味。活字は印刷用の型なので、町の勢いやにぎわいは表せない。"}, {"text": "この映画は、外国語の台詞を画面の下に活字で出している。", "explanation": "ここは〈字幕〉の意味。活字は印刷用の型で、映画の画面に映す文字ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活字", "is_correct": true, "explanation": "祖父が印刷所で毎日拾っていた、印刷用の型。文脈に合う唯一の語。"}, {"text": "挿絵", "is_correct": false, "explanation": "本に入る絵で、拾い集める対象ではないので合わない。"}, {"text": "組版", "is_correct": false, "explanation": "組み上げた版の状態を指し、毎日拾うものではないので合わない。"}, {"text": "版木", "is_correct": false, "explanation": "木に文字を彫った版で、毎日拾い集めるものではないので合わない。"}], "explanations": {"活字": "祖父が印刷所で毎日拾っていた、印刷用の型。文脈に合う唯一の語。", "挿絵": "本に入る絵で、拾い集める対象ではないので合わない。", "組版": "組み上げた版の状態を指し、毎日拾うものではないので合わない。", "版木": "木に文字を彫った版で、毎日拾い集めるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "活字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この活字は持ち帰らず、受付に返してください。", "explanation": "ここは〈印刷物〉の意味（配られる紙）。活字は印刷用の型なので、持ち帰って返す紙の代わりにはならない。"}, {"text": "この活字は、紙に刷るために一枚ずつ彫った版画だ。", "explanation": "ここは〈版画〉の意味（彫った版で刷った作品）。活字は金属の文字の型で、刷り上がった絵ではない。"}, {"text": "この活字は、字を触って読むために作られている。", "explanation": "ここは〈点字〉の意味。活字は印刷用の型で、触って読むための文字ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "印刷所の職人は、一つずつ活字に拾って版を組んだ。", "corrected_sentence": "印刷所の職人は、一つずつ活字を拾って版を組んだ。", "error_description": "誤った形は「活字に拾って」、正しい形は「活字を拾って」。拾う動作の対象なので目的格の「を」が必要で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35096, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は夜遅くまで活字を拾いていた。", "corrected_sentence": "彼は夜遅くまで活字を拾っていた。", "error_description": "誤った形は「拾いていた」、正しい形は「拾っていた」。「拾う」は促音便で、て形は「拾って」になるので、「拾いて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "並んでいる状態の主語を示す格。活字が並んでいるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「並ぶ」は自動詞で目的語を取れないので、「を」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、並んでいるという状態の主語にはならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す格で、並んでいる状態の主語にはならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "並んでいる状態の主語を示す格。活字が並んでいるので正しい。", "を": "「並ぶ」は自動詞で目的語を取れないので、「を」では文が成り立たない。", "へ": "方向を示す格で、並んでいるという状態の主語にはならないので合わない。", "より": "比較の基準を示す格で、並んでいる状態の主語にはならないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使った」の対象を示す目的語。金属の活字を使って印刷した、という正しい文になる。"}, {"text": "に", "is_correct": false, "explanation": "相手や帰着を示す格で、「使った」の対象にはできないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、使うの対象にはならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点や材料を示す格で、使うの対象を表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「使った」の対象を示す目的語。金属の活字を使って印刷した、という正しい文になる。", "に": "相手や帰着を示す格で、「使った」の対象にはできないので合わない。", "へ": "方向を示す格で、使うの対象にはならないので合わない。", "から": "起点や材料を示す格で、使うの対象を表せないので合わない。"}, "error_tags": {"に": "相手・帰着", "へ": "方向", "から": "起点・材料"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "印刷に使う、文字が浮き彫りにされた金属などのブロック。", "primary_collocate": null, "pronunciation": "かつじ", "ipa": "katsɯʑi", "syllable_count": 3, "sentences": [{"text": "活字は鉛などの金属で作られていて、手に持つとずっしり重い。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]は鉛[なまり]などの金属[きんぞく]で作[つく]られていて、手[て]に持[も]つとずっしり重[おも]い。", "sentence_source": "generated"}, {"text": "印刷所の棚には、大きさの違う活字がずらりと並んでいた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "印刷所[いんさつじょ]の棚[たな]には、大[おお]きさの違[ちが]う活字[かつじ]がずらりと並[なら]んでいた。", "sentence_source": "generated"}, {"text": "古い本は、金属の活字を組み合わせて印刷されたものだ。", "target_word": "活字", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]は、金属[きんぞく]の活字[かつじ]を組[く]み合[あ]わせて印刷[いんさつ]されたものだ。", "sentence_source": "generated"}, {"text": "活字が古くなって欠けたので、新しい物に取りかえた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]が古[ふる]くなって欠[か]けたので、新[あたら]しい物[もの]に取[と]りかえた。", "sentence_source": "generated"}, {"text": "彼は小さな活字をピンセットでつまみ、一文字ずつ枠に入れた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "彼[かれ]は小[ちい]さな活字[かつじ]をピンセットでつまみ、一文字[ひともじ]ずつ枠[わく]に入[い]れた。", "sentence_source": "generated"}, {"text": "活字の表面は文字が盛り上がっているため、インクがきれいにつく。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]の表面[ひょうめん]は文字[もじ]が盛[も]り上[あ]がっているため、インクがきれいにつく。", "sentence_source": "generated"}, {"text": "活字を一つずつ並べる作業には、とても時間がかかった。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]を一[ひと]つずつ並[なら]べる作業[さぎょう]には、とても時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "グーテンベルクは、金属の活字を使った印刷を広めた人だ。", "target_word": "活字", "complexity_tier": "T3", "furigana": "グーテンベルクは、金属[きんぞく]の活字[かつじ]を使[つか]った印刷[いんさつ]を広[ひろ]めた人[ひと]だ。", "sentence_source": "generated"}, {"text": "活字は文字が逆さに作られているので、見た目では読みにくい。", "target_word": "活字", "complexity_tier": "T3", "furigana": "活字[かつじ]は文字[もじ]が逆[さか]さに作[つく]られているので、見[み]た目[め]では読[よ]みにくい。", "sentence_source": "generated"}, {"text": "展示室で、実際に活字を手に取って重さを確かめた。", "target_word": "活字", "complexity_tier": "T3", "furigana": "展示室[てんじしつ]で、実際[じっさい]に活字[かつじ]を手[て]に取[と]って重[おも]さを確[たし]かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活字", "label": "基本形"}, {"form": "活字を", "label": "を格"}, {"form": "活字は", "label": "は格"}], "register": "普通体", "sense_fingerprint": "印刷に使う、文字が盛り上がった金属などの小さなブロック", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T4: contains vocabulary far above tier T4: 取りかえ (Zipf 1.48)']::text[], '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活字", "is_correct": true, "explanation": "鉛などの金属で作られた、手に持つと重い印刷用のブロック。文脈に合う唯一の語。"}, {"text": "原稿", "is_correct": false, "explanation": "紙に書かれた文章で、金属製ではなく手に持ってずっしり重いものでもないので合わない。"}, {"text": "印刷物", "is_correct": false, "explanation": "紙に刷られたもので、金属製ではなく軽いので合わない。"}, {"text": "紙型", "is_correct": false, "explanation": "紙で作られた鋳造用の型で、金属製ではないので合わない。"}], "explanations": {"活字": "鉛などの金属で作られた、手に持つと重い印刷用のブロック。文脈に合う唯一の語。", "原稿": "紙に書かれた文章で、金属製ではなく手に持ってずっしり重いものでもないので合わない。", "印刷物": "紙に刷られたもので、金属製ではなく軽いので合わない。", "紙型": "紙で作られた鋳造用の型で、金属製ではないので合わない。"}, "sentence_index": 0, "correct_answer": "活字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この活字に生地を詰めて焼くと、星の形のクッキーができる。", "explanation": "ここは〈抜き型〉の意味。活字は印刷に使う金属の文字ブロックで、生地を抜いて菓子の形を作る道具ではない。"}, {"text": "市場は活字にあふれ、朝から大勢の客でにぎわった。", "explanation": "ここは〈活気〉の意味。活字は印刷用の金属ブロックなので、市場の勢いやにぎわいは表せない。"}, {"text": "この活字は、一枚ずつ彫って紙に刷った版画の一つだ。", "explanation": "ここは〈版画〉の意味（彫った版で刷った作品）。活字は金属の文字ブロックで、刷り上がった絵ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活字", "is_correct": true, "explanation": "一つずつ並べて文字を組む、金属の小さなブロック。文脈に合う唯一の語。"}, {"text": "印刷機", "is_correct": false, "explanation": "印刷を行う機械で、一つずつ並べる対象ではないので合わない。"}, {"text": "感想", "is_correct": false, "explanation": "心に抱く思いで、一つずつ並べて作業する物ではないので合わない。"}, {"text": "印刷所", "is_correct": false, "explanation": "印刷を行う場所で、並べる物ではないので合わない。"}], "explanations": {"活字": "一つずつ並べて文字を組む、金属の小さなブロック。文脈に合う唯一の語。", "印刷機": "印刷を行う機械で、一つずつ並べる対象ではないので合わない。", "感想": "心に抱く思いで、一つずつ並べて作業する物ではないので合わない。", "印刷所": "印刷を行う場所で、並べる物ではないので合わない。"}, "sentence_index": 6, "correct_answer": "活字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下書きは活字で書いてから、ペンで清書した。", "explanation": "ここは〈鉛筆〉の意味（下書きに使う道具）。活字は印刷用の型で、ものを書く道具ではない。"}, {"text": "活字はゴムでできていて、とても軽い。", "explanation": "ここは〈ゴム印〉の意味。活字は鉛などの金属で作るので、ゴム製で軽いものではない。"}, {"text": "活字は薄くて、ペンで書き込める。", "explanation": "ここは〈コピー用紙〉の意味。活字は金属の型で、薄くペンで書き込める紙ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金属の活字を、印刷のたびに少しずつすり減った。", "corrected_sentence": "金属の活字が、印刷のたびに少しずつすり減った。", "error_description": "「すり減る」は活字が主語になる自動詞。主語の「活字」は「が」で示すので、「を」は誤り（誤りは「活字を」、正しくは「活字が」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35097, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "印刷所では、一つずつ活字を編んで版を作った。", "corrected_sentence": "印刷所では、一つずつ活字を組んで版を作った。", "error_description": "誤った動詞は「編んで」、正しい動詞は「組んで」。活字には「組む」が結びつくので、「編む」（糸などを扱う動詞）は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ハサミを使う」の〈を〉。「使う」は道具を目的語にとる。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すため、「ハサミへ使う」は道具を目的語にできない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は共同を表すため、「ハサミと使う」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すため、「ハサミから使う」は目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ハサミを使う」の〈を〉。「使う」は道具を目的語にとる。", "へ": "〈へ〉は方向を表すため、「ハサミへ使う」は道具を目的語にできない。", "と": "〈と〉は共同を表すため、「ハサミと使う」は成り立たない。", "から": "〈から〉は起点を表すため、「ハサミから使う」は目的語を示せない。"}, "error_tags": {"へ": "方向", "と": "共同", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ミシンを使っています」の〈を〉。「使う」は道具を目的語にとる。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は帰着や相手を表すため、「ミシンに使っています」は目的語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は連体修飾を表すため、「ミシンの使っています」は文として続かない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を表すため、「ミシンより使っています」は「使う」の目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ミシンを使っています」の〈を〉。「使う」は道具を目的語にとる。", "に": "〈に〉は帰着や相手を表すため、「ミシンに使っています」は目的語を示せない。", "の": "〈の〉は連体修飾を表すため、「ミシンの使っています」は文として続かない。", "より": "〈より〉は比較を表すため、「ミシンより使っています」は「使う」の目的語を示せない。"}, "error_tags": {"に": "方向・対象", "の": "連体", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをするときに道具などを使うこと。", "primary_collocate": null, "pronunciation": "つかう", "ipa": "tsɯkaɯ", "syllable_count": 3, "sentences": [{"text": "木を切るときは、のこぎりを使います。", "target_word": "使います", "complexity_tier": "T3", "furigana": "木[き]を切[き]るときは、のこぎりを使[つか]います。", "sentence_source": "generated"}, {"text": "彼は左手でハサミを使うのが上手です。", "target_word": "使う", "complexity_tier": "T3", "furigana": "彼[かれ]は左手[ひだりて]でハサミを使[つか]うのが上手[じょうず]です。", "sentence_source": "generated"}, {"text": "字がうまく書けないので、新しいペンを使ってみました。", "target_word": "使って", "complexity_tier": "T3", "furigana": "字[じ]がうまく書[か]けないので、新[あたら]しいペンを使[つか]ってみました。", "sentence_source": "generated"}, {"text": "包丁を使うときは、手を切らないように気をつけてください。", "target_word": "使う", "complexity_tier": "T3", "furigana": "包丁[ほうちょう]を使[つか]うときは、手[て]を切[き]らないように気[き]をつけてください。", "sentence_source": "generated"}, {"text": "子どもが粘土を使って、かわいい動物を作りました。", "target_word": "使って", "complexity_tier": "T3", "furigana": "子[こ]どもが粘土[ねんど]を使[つか]って、かわいい動物[どうぶつ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "このスプーンは大きすぎて、小さい子には使えません。", "target_word": "使え", "complexity_tier": "T3", "furigana": "このスプーンは大[おお]きすぎて、小[ちい]さい子[こ]には使[つか]えません。", "sentence_source": "generated"}, {"text": "暗くなってきたので、懐中電灯を使って道を照らしました。", "target_word": "使って", "complexity_tier": "T4", "furigana": "暗[くら]くなってきたので、懐中電灯[かいちゅうでんとう]を使[つか]って道[みち]を照[て]らしました。", "sentence_source": "generated"}, {"text": "祖母は今も昔のミシンを使っています。", "target_word": "使って", "complexity_tier": "T3", "furigana": "祖母[そぼ]は今[いま]も昔[むかし]のミシンを使[つか]っています。", "sentence_source": "generated"}, {"text": "石けんを使って、手をていねいに洗いましょう。", "target_word": "使って", "complexity_tier": "T3", "furigana": "石[せっ]けんを使[つか]って、手[て]をていねいに洗[あら]いましょう。", "sentence_source": "generated"}, {"text": "工作の授業で、はさみとのりを使いました。", "target_word": "使い", "complexity_tier": "T3", "furigana": "工作[こうさく]の授業[じゅぎょう]で、はさみとのりを使[つか]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使う", "label": "終止形"}, {"form": "使わ", "label": "未然形"}, {"form": "使い", "label": "連用形"}, {"form": "使って", "label": "連用形（音便）"}, {"form": "使えば", "label": "仮定形"}, {"form": "使える", "label": "可能形"}], "register": "中立", "sense_fingerprint": "作業の際に手に取って道具・器具を用いる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 4 words above tier T1 (max 2): 暗く (Zipf 3.91), 懐中 (Zipf 3.23), 電灯 (Zipf 3.58), 照らし (Zipf 3.72)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 石けん (Zipf 3.32), ていねい (Zipf 2.59), 洗い (Zipf 3.74)']::text[], 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使います", "is_correct": true, "explanation": "丁寧形。「のこぎりを使います」で、道具を用いる習慣を述べる正しい形。"}, {"text": "使い", "is_correct": false, "explanation": "連用形で文を終えられず、「のこぎりを使い。」は文として不完全。"}, {"text": "使わ", "is_correct": false, "explanation": "未然形で文を終えられず、「のこぎりを使わ。」は非文になる。"}, {"text": "使って", "is_correct": false, "explanation": "音便形で文を終えられず、「のこぎりを使って。」は未完成の文になる。"}], "explanations": {"使います": "丁寧形。「のこぎりを使います」で、道具を用いる習慣を述べる正しい形。", "使い": "連用形で文を終えられず、「のこぎりを使い。」は文として不完全。", "使わ": "未然形で文を終えられず、「のこぎりを使わ。」は非文になる。", "使って": "音便形で文を終えられず、「のこぎりを使って。」は未完成の文になる。"}, "sentence_index": 0, "correct_answer": "使います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は親に深い感謝を使った。", "explanation": "ここは〈示す〉の意味。感謝は道具や手段ではないので、〈使う〉では気持ちを表す場面に合わない。"}, {"text": "彼はすぐに返事を使った。", "explanation": "ここは〈する〉（返事をする）の意味。返事は道具や手段ではないので、〈使う〉では返答する場面に合わない。"}, {"text": "彼は初対面の人にも礼儀を使った。", "explanation": "ここは〈守る〉の意味。礼儀は道具や手段ではないので、〈使う〉では礼儀を守る場面に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使って", "is_correct": true, "explanation": "連用形（音便）。「懐中電灯を使って道を照らす」の手段を表す正しい形。"}, {"text": "使え", "is_correct": false, "explanation": "命令形のため、「懐中電灯を使え道を照らしました」は文として続かない。"}, {"text": "使おう", "is_correct": false, "explanation": "意向形のため、「懐中電灯を使おう道を照らしました」は成り立たない。"}, {"text": "使わせ", "is_correct": false, "explanation": "使役の語幹のため、「懐中電灯を使わせ道を照らしました」は意味も文法も合わない。"}], "explanations": {"使って": "連用形（音便）。「懐中電灯を使って道を照らす」の手段を表す正しい形。", "使え": "命令形のため、「懐中電灯を使え道を照らしました」は文として続かない。", "使おう": "意向形のため、「懐中電灯を使おう道を照らしました」は成り立たない。", "使わせ": "使役の語幹のため、「懐中電灯を使わせ道を照らしました」は意味も文法も合わない。"}, "sentence_index": 6, "correct_answer": "使って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "係の人は、お客さんの苦情を丁寧に使っている。", "explanation": "ここは〈扱う〉の意味。苦情は道具ではないので、〈使う〉では苦情を取り扱う場面に合わない。"}, {"text": "まず計画の見通しを使ってから、予算を決めた。", "explanation": "ここは〈立てる〉の意味。見通しは道具や手段ではないので、〈使う〉では見通しを立てる場面に合わない。"}, {"text": "彼は新人の教育を使っている。", "explanation": "ここは〈担当する〉の意味。教育は道具ではないので、〈使う〉では担当の意味が伝わらず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドライバーを使え、ねじを締めました。", "corrected_sentence": "ドライバーを使って、ねじを締めました。", "error_description": "「使え」は命令形で、「、」で続けて文を並べることはできない。正しくは「ドライバーを使って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "使う", "is_correct": true, "explanation": "連体形。「ハサミを使うのが上手」の「の」に続く正しい形。"}, {"text": "使い", "is_correct": false, "explanation": "連用形は「のが」に続かず、「使いのが上手」は成り立たない。"}, {"text": "使わ", "is_correct": false, "explanation": "未然形は「のが」に続かず、「使わのが上手」は非文になる。"}, {"text": "使って", "is_correct": false, "explanation": "音便形は「のが」に続かず、「使ってのが上手」は成り立たない。"}], "correct_form": "使う", "base_form": "使う", "form_label": "連体形", "sentence_index": 1, "explanations": {"使う": "連体形。「ハサミを使うのが上手」の「の」に続く正しい形。", "使い": "連用形は「のが」に続かず、「使いのが上手」は成り立たない。", "使わ": "未然形は「のが」に続かず、「使わのが上手」は非文になる。", "使って": "音便形は「のが」に続かず、「使ってのが上手」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35098, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、ハサミを使いて工作をしました。", "corrected_sentence": "夏休みに、ハサミを使って工作をしました。", "error_description": "「使う」の連用形の音便は「使って」。「使いて」は誤った形で、接続の「て」とは続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "使って", "is_correct": true, "explanation": "連用形（音便）。「使っています」の進行を表す正しい形。"}, {"text": "使い", "is_correct": false, "explanation": "連用形（音便なし）のため、「使いています」は標準的な文法では成り立たない（正しくは「使っています」）。"}, {"text": "使おう", "is_correct": false, "explanation": "意向形のため、「使おうています」は非文になる。"}, {"text": "使えば", "is_correct": false, "explanation": "仮定形のため、「使えばています」は文法的に続かない。"}], "correct_form": "使って", "base_form": "使う", "form_label": "連用形（音便）", "sentence_index": 7, "explanations": {"使って": "連用形（音便）。「使っています」の進行を表す正しい形。", "使い": "連用形（音便なし）のため、「使いています」は標準的な文法では成り立たない（正しくは「使っています」）。", "使おう": "意向形のため、「使おうています」は非文になる。", "使えば": "仮定形のため、「使えばています」は文法的に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
