INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35099, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目的のために、道具や手段を利用する。", "primary_collocate": null, "pronunciation": "つかう", "ipa": "tsɯkaɯ", "syllable_count": 3, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "使わ", "complexity_tier": "T4", "furigana": "しかし、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てるという仕事[しごと]を通[つう]じて、彼[かれ]は自然[しぜん]の厳[きび]しさと、土[つち]が命[いのち]を育[はぐく]むという壮大[そうだい]な仕組[しく]みを、自[みずか]らの肌[はだ]で実感[じっかん]していくことになります。", "sentence_source": "mined"}, {"text": "問題を解くときは、図を使って考えると分かりやすくなります。", "target_word": "使って", "complexity_tier": "T3", "furigana": "問題[もんだい]を解[と]くときは、図[ず]を使[つか]って考[かんが]えると分[わ]かりやすくなります。", "sentence_source": "generated"}, {"text": "日本語がわからないので、辞書を使って調べました。", "target_word": "使って", "complexity_tier": "T3", "furigana": "日本語[にほんご]がわからないので、辞書[じしょ]を使[つか]って調[しら]べました。", "sentence_source": "generated"}, {"text": "この机は場所を取るので、使わないときは壁に立てかけておきます。", "target_word": "使わ", "complexity_tier": "T3", "furigana": "この机[つくえ]は場所[ばしょ]を取[と]るので、使[つか]わないときは壁[かべ]に立[た]てかけておきます。", "sentence_source": "generated"}, {"text": "電気をたくさん使ったので、今月は料金が高くなりました。", "target_word": "使った", "complexity_tier": "T3", "furigana": "電気[でんき]をたくさん使[つか]ったので、今月[こんげつ]は料金[りょうきん]が高[たか]くなりました。", "sentence_source": "generated"}, {"text": "彼女はいつも丁寧な言葉を使うので、誰からも好かれています。", "target_word": "使う", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はいつも丁寧[ていねい]な言葉[ことば]を使[つか]うので、誰[だれ]からも好[す]かれています。", "sentence_source": "generated"}, {"text": "会議では、この資料を使って説明するつもりです。", "target_word": "使って", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、この資料[しりょう]を使[つか]って説明[せつめい]するつもりです。", "sentence_source": "generated"}, {"text": "この道具は、使うたびに手入れをしてください。", "target_word": "使う", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は、使[つか]うたびに手入[ていれ]れをしてください。", "sentence_source": "generated"}, {"text": "地図アプリを使えば、初めての町でも迷いません。", "target_word": "使えば", "complexity_tier": "T3", "furigana": "地図[ちず]アプリを使[つか]えば、初[はじ]めての町[まち]でも迷[まよ]いません。", "sentence_source": "generated"}, {"text": "明日の試験では、電卓を使ってもいいそうです。", "target_word": "使って", "complexity_tier": "T3", "furigana": "明日[あした]の試験[しけん]では、電卓[でんたく]を使[つか]ってもいいそうです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使う", "label": "終止形"}, {"form": "使わ", "label": "未然形"}, {"form": "使い", "label": "連用形"}, {"form": "使って", "label": "連用形（音便）"}, {"form": "使えば", "label": "仮定形"}, {"form": "使える", "label": "可能形"}], "register": "中立", "sense_fingerprint": "目的を果たすために道具・手段・資料などを利用する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 農薬 (Zipf 3.66), 厳し (Zipf 3.6), 育む (Zipf 3.02), 壮大 (Zipf 3.84)','sentence 3 above tier T1: contains vocabulary far above tier T1: 立てかけ (Zipf 2.34)']::text[], 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35099, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使わ", "is_correct": true, "explanation": "未然形。「農薬を使わずに」の「ずに」に続く形で、この文脈の正しい形。"}, {"text": "使い", "is_correct": false, "explanation": "連用形は「ずに」と続かないため、「農薬を使いずに」は成り立たない。"}, {"text": "使う", "is_correct": false, "explanation": "終止形に「ずに」は付かないため、「農薬を使うずに」は非文になる。"}, {"text": "使って", "is_correct": false, "explanation": "音便形に「ずに」は続かず、「使ってずに」は文として成り立たない。"}], "explanations": {"使わ": "未然形。「農薬を使わずに」の「ずに」に続く形で、この文脈の正しい形。", "使い": "連用形は「ずに」と続かないため、「農薬を使いずに」は成り立たない。", "使う": "終止形に「ずに」は付かないため、「農薬を使うずに」は非文になる。", "使って": "音便形に「ずに」は続かず、「使ってずに」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "使わ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その批判を、彼は冷静に使った。", "explanation": "ここは〈受け止める〉の意味。批判は道具や手段ではないので、〈使う〉では批判を受け止める場面に合わない。"}, {"text": "彼は罪を使うため、毎日、奉仕活動を続けている。", "explanation": "ここは〈償う〉の意味。罪は道具や手段ではないので、〈使う〉では罪を償う場面に合わない。"}, {"text": "彼は失敗の責任を、すべて自分で使った。", "explanation": "ここは〈負う〉の意味。責任は道具や手段ではないので、〈使う〉では責任を引き受ける場面に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35099, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使って", "is_correct": true, "explanation": "連用形（音便）。「資料を使って説明する」の手段を表す形で、この文脈の正しい形。"}, {"text": "使え", "is_correct": false, "explanation": "命令形のため、「資料を使え説明する」は文として続かない。"}, {"text": "使おう", "is_correct": false, "explanation": "意向形のため、「資料を使おう説明する」は成り立たない。"}, {"text": "使わせ", "is_correct": false, "explanation": "使役の語幹のため、「資料を使わせ説明する」は意味も文法も合わない。"}], "explanations": {"使って": "連用形（音便）。「資料を使って説明する」の手段を表す形で、この文脈の正しい形。", "使え": "命令形のため、「資料を使え説明する」は文として続かない。", "使おう": "意向形のため、「資料を使おう説明する」は成り立たない。", "使わせ": "使役の語幹のため、「資料を使わせ説明する」は意味も文法も合わない。"}, "sentence_index": 6, "correct_answer": "使って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は子どもを優しく使うので、保育士に向いている。", "explanation": "ここは〈扱う〉の意味。子どもを道具のように使うと聞こえ、接し方を表す〈扱う〉の場面には合わない。"}, {"text": "失敗を認めて、なんとか面目を使った。", "explanation": "ここは〈保つ〉の意味。面目は道具や手段ではないので、〈使う〉では面目を守る場面に合わない。"}, {"text": "届いた注文を、順番に使っていく。", "explanation": "ここは〈処理する〉の意味。注文は道具ではないので、〈使う〉では処理の場面に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35099, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハサミを使わて、紙を切りました。", "corrected_sentence": "ハサミを使って、紙を切りました。", "error_description": "「使う」の未然形「使わ」には「て」が続かない。正しくは連用形（音便）「使って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "使って", "is_correct": true, "explanation": "連用形（音便）。「図を使って考える」の手段を表す「て」に続く正しい形。"}, {"text": "使わ", "is_correct": false, "explanation": "未然形のため、「図を使わて考える」は「て」に続かず成り立たない。"}, {"text": "使い", "is_correct": false, "explanation": "連用形（音便なし）のため、「図を使いて考える」は「て」に直接続けられず文として誤り。"}, {"text": "使おう", "is_correct": false, "explanation": "意向形のため、「図を使おうて考える」は「て」に続けられず非文になる。"}], "correct_form": "使って", "base_form": "使う", "form_label": "連用形（音便）", "sentence_index": 1, "explanations": {"使って": "連用形（音便）。「図を使って考える」の手段を表す「て」に続く正しい形。", "使わ": "未然形のため、「図を使わて考える」は「て」に続かず成り立たない。", "使い": "連用形（音便なし）のため、「図を使いて考える」は「て」に直接続けられず文として誤り。", "使おう": "意向形のため、「図を使おうて考える」は「て」に続けられず非文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35099, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パソコンを使いて、資料を作りました。", "corrected_sentence": "パソコンを使って、資料を作りました。", "error_description": "「使う」の連用形の音便は「使って」。「使いて」は誤った形で、接続の「て」とは続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "使う", "is_correct": true, "explanation": "連体形。「使うたびに」の「たび」を修飾する正しい形。"}, {"text": "使え", "is_correct": false, "explanation": "命令形のため、「使えたびに」は「たびに」に続かず文法的に誤り。"}, {"text": "使えば", "is_correct": false, "explanation": "仮定形のため、「使えばたびに」は「たびに」に続かず文として成り立たない。"}, {"text": "使うな", "is_correct": false, "explanation": "禁止形（終止形に「な」が付いた形）のため、「使うなたびに」は文として成り立たない。"}], "correct_form": "使う", "base_form": "使う", "form_label": "連体形", "sentence_index": 7, "explanations": {"使う": "連体形。「使うたびに」の「たび」を修飾する正しい形。", "使え": "命令形のため、「使えたびに」は「たびに」に続かず文法的に誤り。", "使えば": "仮定形のため、「使えばたびに」は「たびに」に続かず文として成り立たない。", "使うな": "禁止形（終止形に「な」が付いた形）のため、「使うなたびに」は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
