INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35102, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "わからないことをたずねるときに使う言葉です。", "primary_collocate": null, "pronunciation": "なん", "ipa": "naɴ", "syllable_count": 2, "sentences": [{"text": "これは何ですか。", "target_word": "何", "complexity_tier": "T1", "furigana": "これは何[なん]ですか。", "sentence_source": "generated"}, {"text": "机の上に置いてあるこれは何という道具ですか。", "target_word": "何", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に置[お]いてあるこれは何[なん]という道具[どうぐ]ですか。", "sentence_source": "generated"}, {"text": "今、何の音が聞こえましたか。", "target_word": "何", "complexity_tier": "T2", "furigana": "今[いま]、何[なん]の音[おと]が聞[き]こえましたか。", "sentence_source": "generated"}, {"text": "好きな食べ物は何ですか。", "target_word": "何", "complexity_tier": "T1", "furigana": "好[す]きな食[た]べ物[もの]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "窓の外で光っているのは何だろうと、子どもが首をかしげた。", "target_word": "何", "complexity_tier": "T4", "furigana": "窓[まど]の外[そと]で光[ひか]っているのは何[なん]だろうと、子[こ]どもが首[くび]をかしげた。", "sentence_source": "generated"}, {"text": "「ありがとう」は英語で何と言いますか。", "target_word": "何", "complexity_tier": "T2", "furigana": "「ありがとう」は英語[えいご]で何[なん]と言[い]いますか。", "sentence_source": "generated"}, {"text": "今日の宿題は何ですか。", "target_word": "何", "complexity_tier": "T2", "furigana": "今日[きょう]の宿題[しゅくだい]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "彼が持っているのは何の道具ですか。", "target_word": "何", "complexity_tier": "T3", "furigana": "彼[かれ]が持[も]っているのは何[なん]の道具[どうぐ]ですか。", "sentence_source": "generated"}, {"text": "この漢字の意味は何ですか。", "target_word": "何", "complexity_tier": "T2", "furigana": "この漢字[かんじ]の意味[いみ]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "何の用事で来たのか、先に教えてください。", "target_word": "何", "complexity_tier": "T3", "furigana": "何[なん]の用事[ようじ]で来[き]たのか、先[さき]に教[おし]えてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "何", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "知らない物事をたずねる疑問語(なん)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35102, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何", "is_correct": true, "explanation": "「これは何ですか」の『何』。物の正体を尋ねるので空欄に入る。"}, {"text": "誰", "is_correct": false, "explanation": "人を尋ねる語。「これは誰ですか」は人物を聞く文になり、物の正体を尋ねる空欄には合わない。"}, {"text": "何時", "is_correct": false, "explanation": "時刻を尋ねる語（なんじ）。物の正体を尋ねる文にはならず、合わない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を尋ねる語。物が何かを聞く空欄には入らない。"}], "explanations": {"何": "「これは何ですか」の『何』。物の正体を尋ねるので空欄に入る。", "誰": "人を尋ねる語。「これは誰ですか」は人物を聞く文になり、物の正体を尋ねる空欄には合わない。", "何時": "時刻を尋ねる語（なんじ）。物の正体を尋ねる文にはならず、合わない。", "なぜ": "理由を尋ねる語。物が何かを聞く空欄には入らない。"}, "sentence_index": 0, "correct_answer": "何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場は何時ですか。", "explanation": "ここは〈何時〉（時刻を問う語）と混同している。会場は時刻ではないので合わない。"}, {"text": "田中さんは何ですか。", "explanation": "ここは〈誰〉の意味。人を尋ねるときは誰を使い、何は物事に使うので合わない。"}, {"text": "会議は何からですか。", "explanation": "ここは〈何時〉の意味。開始の時刻を聞くときは何時からを使う。何からでは時刻を尋ねられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35102, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何", "is_correct": true, "explanation": "「今日の宿題は何ですか」の『何』。宿題の内容を尋ねるので空欄に入る。"}, {"text": "何人", "is_correct": false, "explanation": "人数を数える語。宿題は人ではないので、内容を尋ねる空欄には合わない。"}, {"text": "何歳", "is_correct": false, "explanation": "年齢を尋ねる語。宿題には年齢がないので合わない。"}, {"text": "何回", "is_correct": false, "explanation": "回数を尋ねる語。宿題の内容を尋ねる空欄には入らない。"}], "explanations": {"何": "「今日の宿題は何ですか」の『何』。宿題の内容を尋ねるので空欄に入る。", "何人": "人数を数える語。宿題は人ではないので、内容を尋ねる空欄には合わない。", "何歳": "年齢を尋ねる語。宿題には年齢がないので合わない。", "何回": "回数を尋ねる語。宿題の内容を尋ねる空欄には入らない。"}, "sentence_index": 6, "correct_answer": "何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "気分は何ですか。", "explanation": "ここは〈どんな〉の意味。気分の様子を尋ねるときはどんなを使い、何では気分の答えにならないので合わない。"}, {"text": "明日の天気は何時ですか。", "explanation": "ここは〈何時〉（時刻を問う語）と混同している。天気は時刻ではないので、〈何時〉では問えない。"}, {"text": "雨が止むのは何ですか。", "explanation": "ここは〈いつ〉の意味。時期を尋ねるときはいつを使う。何では時期の答えにならず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35102, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日の予定は何だですか。", "corrected_sentence": "明日の予定は何ですか。", "error_description": "『何だですか』は誤り。対象語『何』に丁寧な『です』を続けるので、間に『だ』は入らない。誤りは『何』に付く語の『だ』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35102, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鞄の中に入っているのは何が本ですか。", "corrected_sentence": "鞄の中に入っているのは何の本ですか。", "error_description": "『何が本』は誤り。名詞『本』を修飾するには『何の本』と『の』が必要で、対象語『何』に続く助詞『が』が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
