INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35103, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "疑問を表す語。数量や程度、理由などを問うときに用いる。", "primary_collocate": null, "pronunciation": "なん", "ipa": "naɴ", "syllable_count": 2, "sentences": [{"text": "何度練習しましたか。", "target_word": "何", "complexity_tier": "T3", "furigana": "何度[なんど]練習[れんしゅう]しましたか。", "sentence_source": "generated"}, {"text": "今日の会議には何人が参加しますか。", "target_word": "何", "complexity_tier": "T3", "furigana": "今日[きょう]の会議[かいぎ]には何人[なんにん]が参加[さんか]しますか。", "sentence_source": "generated"}, {"text": "この箱の中に、りんごが何個入っていますか。", "target_word": "何", "complexity_tier": "T3", "furigana": "この箱[はこ]の中[なか]に、りんごが何個[なんこ]入[はい]っていますか。", "sentence_source": "generated"}, {"text": "明日は何曜日ですか。", "target_word": "何", "complexity_tier": "T2", "furigana": "明日[あした]は何曜日[なんようび]ですか。", "sentence_source": "generated"}, {"text": "何時間かかるのか、先に教えてください。", "target_word": "何", "complexity_tier": "T3", "furigana": "何時間[なんじかん]かかるのか、先[さき]に教[おし]えてください。", "sentence_source": "generated"}, {"text": "あなたは何歳のときに日本へ来ましたか。", "target_word": "何", "complexity_tier": "T3", "furigana": "あなたは何歳[なんさい]のときに日本[にほん]へ来[き]ましたか。", "sentence_source": "generated"}, {"text": "旅行の準備には何日かかりますか。", "target_word": "何", "complexity_tier": "T3", "furigana": "旅行[りょこう]の準備[じゅんび]には何[なん]日[にち]かかりますか。", "sentence_source": "generated"}, {"text": "駅から学校まで、歩いて何分ですか。", "target_word": "何", "complexity_tier": "T3", "furigana": "駅[えき]から学校[がっこう]まで、歩[ある]いて何分[なんぷん]ですか。", "sentence_source": "generated"}, {"text": "何でこんなに遅くなったのか、理由を聞かせてください。", "target_word": "何", "complexity_tier": "T4", "furigana": "何[なん]でこんなに遅[おそ]くなったのか、理由[りゆう]を聞[き]かせてください。", "sentence_source": "generated"}, {"text": "このクラスの生徒は全部で何人いますか。", "target_word": "何", "complexity_tier": "T3", "furigana": "このクラスの生徒[せいと]は全部[ぜんぶ]で何人[なんにん]いますか。", "sentence_source": "generated"}], "morphological_forms": [{"form": "何", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数量・程度・理由を問う疑問語(なん)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35103, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何", "is_correct": true, "explanation": "代名詞。「何度練習しましたか」の「何」。回数を問う疑問語なので空欄に入る。"}, {"text": "毎", "is_correct": false, "explanation": "「毎度」は「いつも」の意で回数を問わず、「何度」の空欄には入らない。"}, {"text": "全", "is_correct": false, "explanation": "「全度」という語はなく、ここでは入らない。"}, {"text": "新", "is_correct": false, "explanation": "「新度」は成り立たず、文に合わない。"}], "explanations": {"何": "代名詞。「何度練習しましたか」の「何」。回数を問う疑問語なので空欄に入る。", "毎": "「毎度」は「いつも」の意で回数を問わず、「何度」の空欄には入らない。", "全": "「全度」という語はなく、ここでは入らない。", "新": "「新度」は成り立たず、文に合わない。"}, "sentence_index": 0, "correct_answer": "何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の会議には何さんが参加しますか。", "explanation": "ここは〈誰〉（人を問う語）の代わりに〈何〉を使った誤用。人を問うには〈誰〉を使うので、〈何〉は合わない。"}, {"text": "明日は何年ですか。", "explanation": "ここは〈何日〉（日付を問う語）と混同している。日付を問うには〈何日〉を使い、〈何年〉は年を問うので合わない。"}, {"text": "明日は何分ですか。", "explanation": "ここは〈何時〉（時刻を問う語）と混同している。時刻や日付を問うには〈何時〉や〈何日〉を使い、〈何分〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35103, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何", "is_correct": true, "explanation": "代名詞。「何日」の一部で、日数を問う疑問語として文の意味に合う。"}, {"text": "誰", "is_correct": false, "explanation": "人を問う語で、「誰日かかる」は成り立たない。"}, {"text": "先", "is_correct": false, "explanation": "「先日」は別の語で、ここでは日数を問う意味にならない。"}, {"text": "余", "is_correct": false, "explanation": "「余日」は別の語で、「余日かかる」は文に合わない。"}], "explanations": {"何": "代名詞。「何日」の一部で、日数を問う疑問語として文の意味に合う。", "誰": "人を問う語で、「誰日かかる」は成り立たない。", "先": "「先日」は別の語で、ここでは日数を問う意味にならない。", "余": "「余日」は別の語で、「余日かかる」は文に合わない。"}, "sentence_index": 6, "correct_answer": "何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議は何人に始まりますか。", "explanation": "ここは〈何人〉（人数を問う語）を誤用している。会議の開始は人数ではないので合わない。"}, {"text": "彼女は何人の時に、日本へ来ましたか。", "explanation": "ここは〈何歳〉（年齢を問う語）と混同している。年齢を問うには〈何歳〉を使い、〈何人〉は人数を数えるので合わない。"}, {"text": "明日の天気は何時ですか。", "explanation": "ここは〈何時〉（時刻を問う語）と混同している。天気は時刻ではないので、〈何時〉では問えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35103, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この袋の中に、みかんが何個を入っていますか。", "corrected_sentence": "この袋の中に、みかんが何個入っていますか。", "error_description": "「入っています」には「を」は不要。「何個」の後に助詞を付けず、「何個入っていますか」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35103, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい教室には椅子が何人並んでいますか。", "corrected_sentence": "新しい教室には椅子が何脚並んでいますか。", "error_description": "椅子は「脚」で数えるので、「人」は誤り。「何脚」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
