INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35104, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "真似する対象を示す目的語。方法を真似したという正しい文になる。"}, {"text": "に", "is_correct": false, "explanation": "相手を示す格で、真似する対象にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、真似の対象にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す格で、真似の対象は表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "真似する対象を示す目的語。方法を真似したという正しい文になる。", "に": "相手を示す格で、真似する対象にはならないので合わない。", "へ": "方向を示す格で、真似の対象にはならないので合わない。", "と": "相手や並列を示す格で、真似の対象は表せないので合わない。"}, "error_tags": {"に": "相手", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35104, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、やり方。", "primary_collocate": null, "pronunciation": "ほうほう", "ipa": "hoːhoː", "syllable_count": 4, "sentences": [{"text": "漢字を覚える方法は、人によって違います。", "target_word": "方法", "complexity_tier": "T3", "furigana": "漢字[かんじ]を覚[おぼ]える方法[ほうほう]は、人[ひと]によって違[ちが]います。", "sentence_source": "generated"}, {"text": "母に魚を長く保存する方法を教えてもらった。", "target_word": "方法", "complexity_tier": "T3", "furigana": "母[はは]に魚[さかな]を長[なが]く保存[ほぞん]する方法[ほうほう]を教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "この方法なら、初心者でも三十分でケーキが作れます。", "target_word": "方法", "complexity_tier": "T3", "furigana": "この方法[ほうほう]なら、初心者[しょしんしゃ]でも三十分[さんじゅっぷん]でケーキが作[つく]れます。", "sentence_source": "generated"}, {"text": "先生は、英語の発音を直す方法を丁寧に説明してくれた。", "target_word": "方法", "complexity_tier": "T3", "furigana": "先生[せんせい]は、英語[えいご]の発音[はつおん]を直[なお]す方法[ほうほう]を丁寧[ていねい]に説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "同じ料理でも、作る方法が国によってずいぶん違う。", "target_word": "方法", "complexity_tier": "T3", "furigana": "同[おな]じ料理[りょうり]でも、作[つく]る方法[ほうほう]が国[くに]によってずいぶん違[ちが]う。", "sentence_source": "generated"}, {"text": "毎朝の運動を続ける方法を、友達に聞いてみた。", "target_word": "方法", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]の運動[うんどう]を続[つづ]ける方法[ほうほう]を、友達[ともだち]に聞[き]いてみた。", "sentence_source": "generated"}, {"text": "洗濯機を使う方法が分からなかったので、説明書を読んだ。", "target_word": "方法", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]を使[つか]う方法[ほうほう]が分[わ]からなかったので、説明書[せつめいしょ]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "彼の勉強の方法を真似したら、成績が少し上がった。", "target_word": "方法", "complexity_tier": "T3", "furigana": "彼[かれ]の勉強[べんきょう]の方法[ほうほう]を真似[まね]したら、成績[せいせき]が少[すこ]し上[あ]がった。", "sentence_source": "generated"}, {"text": "道に迷わない方法を、父が地図を広げて教えてくれた。", "target_word": "方法", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]わない方法[ほうほう]を、父[ちち]が地図[ちず]を広[ひろ]げて教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "一つの方法がだめでも、別の方法を試せばいい。", "target_word": "方法", "complexity_tier": "T3", "furigana": "一[ひと]つの方法[ほうほう]がだめでも、別[べつ]の方法[ほうほう]を試[ため]せばいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方法", "label": "基本形"}, {"form": "方法が", "label": "主語形"}, {"form": "方法を", "label": "目的語形"}], "register": "neutral", "sense_fingerprint": "何かを行うときの手順やしかた（やり方）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35104, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法", "is_correct": true, "explanation": "漢字を覚えるやり方を指す。文脈に合う唯一の語。"}, {"text": "重さ", "is_correct": false, "explanation": "量を表す語で、覚える仕方を表せないので合わない。"}, {"text": "高さ", "is_correct": false, "explanation": "物の高低を表す語で、覚え方の説明にはならないので合わない。"}, {"text": "温度", "is_correct": false, "explanation": "温かさの度合いを表す語で、覚え方の代わりにはならないので合わない。"}], "explanations": {"方法": "漢字を覚えるやり方を指す。文脈に合う唯一の語。", "重さ": "量を表す語で、覚える仕方を表せないので合わない。", "高さ": "物の高低を表す語で、覚え方の説明にはならないので合わない。", "温度": "温かさの度合いを表す語で、覚え方の代わりにはならないので合わない。"}, "sentence_index": 0, "correct_answer": "方法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行の方法は、来月の十日だ。", "explanation": "ここは〈日程〉の意味。方法はやり方を表すので、いつ行うかという日付は表さない。"}, {"text": "船は、南の方法へ進んでいった。", "explanation": "ここは〈方角〉の意味。方法はやり方で、進む向きは表さないので合わない。"}, {"text": "遅刻した方法は、電車が止まったためだ。", "explanation": "ここは〈理由〉の意味。方法はやり方で、なぜそうなったかの説明には〈理由〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35104, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法", "is_correct": true, "explanation": "洗濯機の使い方を指す。文脈に合う唯一の語。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表す語で、使うやり方の代わりにはならないので合わない。"}, {"text": "明るさ", "is_correct": false, "explanation": "明暗の度合いを表す語で、使い方の説明にはならないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色彩を表す語で、洗濯機を使うやり方を表せないので合わない。"}], "explanations": {"方法": "洗濯機の使い方を指す。文脈に合う唯一の語。", "音量": "音の大きさを表す語で、使うやり方の代わりにはならないので合わない。", "明るさ": "明暗の度合いを表す語で、使い方の説明にはならないので合わない。", "色": "色彩を表す語で、洗濯機を使うやり方を表せないので合わない。"}, "sentence_index": 6, "correct_answer": "方法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は方法が十畳あって、広々としている。", "explanation": "ここは〈広さ〉の意味。方法はやり方で、面積を表す文には使えないので合わない。"}, {"text": "雨が続く方法は、台風が来たことだ。", "explanation": "ここは〈原因〉の意味。方法は「どうやるか」を表し、なぜ起きたかは〈原因〉で表す。"}, {"text": "店の方法を棚に並べた。", "explanation": "ここは〈商品〉の意味。方法は形のないやり方なので、棚に並べる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35104, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この方法を、雑用の時間を大きく減らせる。", "corrected_sentence": "この方法で、雑用の時間を大きく減らせる。", "error_description": "誤った形は「方法を」、正しい形は「方法で」。手段を表すには「で」が必要で、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35104, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、新しい方法を開いて、部屋を片付けた。", "corrected_sentence": "父は、新しい方法を考えて、部屋を片付けた。", "error_description": "誤った動詞は「開いて」、正しい動詞は「考えて」。方法は考え出すものなので、「開く」（扉や道などに使う動詞）は結びつかず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ない」の主語を示す格。連絡する方法がないという正しい文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格。「〜がない」の形になるので「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示す格で、「ない」の主語にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、存在しないという状態の主語にはならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「ない」の主語を示す格。連絡する方法がないという正しい文になる。", "を": "目的語を示す格。「〜がない」の形になるので「を」は合わない。", "に": "帰着点を示す格で、「ない」の主語にはならないので合わない。", "へ": "方向を示す格で、存在しないという状態の主語にはならないので合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "考える対象を示す目的語。方法を考えていたという正しい文になる。"}, {"text": "に", "is_correct": false, "explanation": "相手や帰着を示す格で、考える対象にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、考える内容にはならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す格で、考える対象は表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "考える対象を示す目的語。方法を考えていたという正しい文になる。", "に": "相手や帰着を示す格で、考える対象にはならないので合わない。", "へ": "方向を示す格で、考える内容にはならないので合わない。", "より": "比較の基準を示す格で、考える対象は表せないので合わない。"}, "error_tags": {"に": "相手・帰着", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うためのやり方や手段。", "primary_collocate": null, "pronunciation": "ほうほう", "ipa": "hoːhoː", "syllable_count": 4, "sentences": [{"text": "問題を解決する方法が、やっと見つかった。", "target_word": "方法", "complexity_tier": "T3", "furigana": "問題[もんだい]を解決[かいけつ]する方法[ほうほう]が、やっと見[み]つかった。", "sentence_source": "generated"}, {"text": "連絡する方法がないので、直接会いに行くしかない。", "target_word": "方法", "complexity_tier": "T3", "furigana": "連絡[れんらく]する方法[ほうほう]がないので、直接[ちょくせつ]会[あ]いに行[い]くしかない。", "sentence_source": "generated"}, {"text": "会議で、費用を減らす方法をみんなで考えた。", "target_word": "方法", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、費用[ひよう]を減[へ]らす方法[ほうほう]をみんなで考[かんが]えた。", "sentence_source": "generated"}, {"text": "駅まで行く一番安い方法は、バスに乗ることです。", "target_word": "方法", "complexity_tier": "T3", "furigana": "駅[えき]まで行[い]く一番[いちばん]安[やす]い方法[ほうほう]は、バスに乗[の]ることです。", "sentence_source": "generated"}, {"text": "医者は、病気を治す方法はいくつかあると言った。", "target_word": "方法", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、病気[びょうき]を治[なお]す方法[ほうほう]はいくつかあると言[い]った。", "sentence_source": "generated"}, {"text": "電話がつながらないため、別の方法で知らせることにした。", "target_word": "方法", "complexity_tier": "T3", "furigana": "電話[でんわ]がつながらないため、別[べつ]の方法[ほうほう]で知[し]らせることにした。", "sentence_source": "generated"}, {"text": "荷物を早く届ける方法を、会社が探している。", "target_word": "方法", "complexity_tier": "T3", "furigana": "荷物[にもつ]を早[はや]く届[とど]ける方法[ほうほう]を、会社[かいしゃ]が探[さが]している。", "sentence_source": "generated"}, {"text": "彼女は、泣かずに気持ちを伝える方法を考えていた。", "target_word": "方法", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、泣[な]かずに気持[きも]ちを伝[つた]える方法[ほうほう]を考[かんが]えていた。", "sentence_source": "generated"}, {"text": "目標を達成するには、正しい方法で努力することが大切だ。", "target_word": "方法", "complexity_tier": "T3", "furigana": "目標[もくひょう]を達成[たっせい]するには、正[ただ]しい方法[ほうほう]で努力[どりょく]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "雪で道が閉ざされ、山を下りる方法がなくなった。", "target_word": "方法", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]が閉[と]ざされ、山[やま]を下[お]りる方法[ほうほう]がなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方法", "label": "基本形"}, {"form": "方法で", "label": "手段を表す形"}, {"form": "方法が", "label": "主語形"}], "register": "neutral", "sense_fingerprint": "目的を達成するための手段・方策", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法", "is_correct": true, "explanation": "問題を解決するやり方を指す。文脈に合う唯一の語。"}, {"text": "色", "is_correct": false, "explanation": "見た目の特徴を表す語で、問題を解決するやり方の代わりにはならないので合わない。"}, {"text": "音", "is_correct": false, "explanation": "音声を表す語で、解決の手段を表せないので合わない。"}, {"text": "味", "is_correct": false, "explanation": "味覚の性質を表す語で、解決のやり方を表せないので合わない。"}], "explanations": {"方法": "問題を解決するやり方を指す。文脈に合う唯一の語。", "色": "見た目の特徴を表す語で、問題を解決するやり方の代わりにはならないので合わない。", "音": "音声を表す語で、解決の手段を表せないので合わない。", "味": "味覚の性質を表す語で、解決のやり方を表せないので合わない。"}, "sentence_index": 0, "correct_answer": "方法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の方法は、一つ百円です。", "explanation": "ここは〈値段〉の意味。方法はやり方なので、金額は表さないので合わない。"}, {"text": "会議の方法は、来月に延期することになった。", "explanation": "ここは〈結論〉の意味。方法は手順のやり方で、会議の結果は表さないので合わない。"}, {"text": "駅までの方法は、およそ二キロだ。", "explanation": "ここは〈距離〉の意味。方法は道のりの長さを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法", "is_correct": true, "explanation": "荷物を早く届けるやり方を指す。文脈に合う唯一の語。"}, {"text": "重さ", "is_correct": false, "explanation": "物の重量を表す語で、届けるやり方の代わりにはならないので合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "香りを表す語で、届けるやり方を説明しないので合わない。"}, {"text": "温度", "is_correct": false, "explanation": "温かさの度合いを表す語で、届けるやり方の代わりにはならないので合わない。"}], "explanations": {"方法": "荷物を早く届けるやり方を指す。文脈に合う唯一の語。", "重さ": "物の重量を表す語で、届けるやり方の代わりにはならないので合わない。", "匂い": "香りを表す語で、届けるやり方を説明しないので合わない。", "温度": "温かさの度合いを表す語で、届けるやり方の代わりにはならないので合わない。"}, "sentence_index": 6, "correct_answer": "方法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の方法は、雪が降るらしい。", "explanation": "ここは〈天気〉の意味。方法はやり方なので、明日の空模様は表さないので合わない。"}, {"text": "次の方法は、山の麓の町だ。", "explanation": "ここは〈行き先〉の意味。方法は手順を表し、行き先の場所は表さないので合わない。"}, {"text": "参加する方法は十人だ。", "explanation": "ここは〈人数〉の意味。方法は人の数を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "よい方法を運んで、準備を進めた。", "corrected_sentence": "よい方法を探して、準備を進めた。", "error_description": "誤った動詞は「運んで」、正しい動詞は「探して」。「方法」は探すものなので、「運ぶ」（物に使う動詞）は結びつかず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35105, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この方法を、荷物の準備を一時間で終えられる。", "corrected_sentence": "この方法で、荷物の準備を一時間で終えられる。", "error_description": "誤った形は「方法を」、正しい形は「方法で」。手段を表すには「で」が必要で、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「開発する」の目的語を示す格助詞。新しい味のソースを作り出した、の意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「ソースに開発した」は開発の対象を示す形として不自然。目的語には「を」を使う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「開発する」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では、開発の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「開発する」の目的語を示す格助詞。新しい味のソースを作り出した、の意味になる。", "に": "「ソースに開発した」は開発の対象を示す形として不自然。目的語には「を」を使う。", "へ": "方向を示す「へ」は「開発する」の目的語にならない。", "で": "手段や場所を示す「で」では、開発の対象を表せない。"}, "error_tags": {"に": "対象の格", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「品種を開発して」の目的語。作り出す対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「品種が開発して」では主語になり、人が開発したという文意に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「品種の開発」は名詞句になり、動詞「開発して」とつながらない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「品種を開発して」の目的語。作り出す対象を示す。", "が": "「品種が開発して」では主語になり、人が開発したという文意に合わない。", "の": "「品種の開発」は名詞句になり、動詞「開発して」とつながらない。", "より": "比較を示す「より」は目的語にならない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しいものをつくること。", "primary_collocate": null, "pronunciation": "かいはつ", "ipa": "kaihatsɯ", "syllable_count": 4, "sentences": [{"text": "会社は、子ども向けの新しいおもちゃの開発に力を入れている。", "target_word": "開発", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、子[こ]ども向[む]けの新[あたら]しいおもちゃの開発[かいはつ]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "兄は料理が好きで、自分で新しい味のソースを開発した。", "target_word": "開発", "complexity_tier": "T3", "furigana": "兄[あに]は料理[りょうり]が好[す]きで、自分[じぶん]で新[あたら]しい味[あじ]のソースを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "研究チームは、体にやさしい薬の開発を目指している。", "target_word": "開発", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは、体[からだ]にやさしい薬[くすり]の開発[かいはつ]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "その研究所は、子どもが安全に使える新しい家庭用ロボットを開発した。", "target_word": "開発", "complexity_tier": "T3", "furigana": "その研究所[けんきゅうじょ]は、子[こ]どもが安全[あんぜん]に使[つか]える新[あたら]しい家庭用[かてい よう]ロボットを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "町のパン屋は、米粉を使った新商品の開発に半年かけた。", "target_word": "開発", "complexity_tier": "T3", "furigana": "町[まち]のパン屋[や]は、米粉[こめこ]を使[つか]った新商品[しんしょうひん]の開発[かいはつ]に半年[はんとし]かけた。", "sentence_source": "generated"}, {"text": "このおもちゃは、小さな工場が長い時間をかけて開発したものだ。", "target_word": "開発", "complexity_tier": "T3", "furigana": "このおもちゃは、小[ちい]さな工場[こうじょう]が長[なが]い時間[じかん]をかけて開発[かいはつ]したものだ。", "sentence_source": "generated"}, {"text": "開発に失敗が続いても、彼らはあきらめなかった。", "target_word": "開発", "complexity_tier": "T3", "furigana": "開発[かいはつ]に失敗[しっぱい]が続[つづ]いても、彼[かれ]らはあきらめなかった。", "sentence_source": "generated"}, {"text": "農家の人が、寒さに強い品種を開発して、地域で評判になった。", "target_word": "開発", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]が、寒[さむ]さに強[つよ]い品種[ひんしゅ]を開発[かいはつ]して、地域[ちいき]で評判[ひょうばん]になった。", "sentence_source": "generated"}, {"text": "道具の開発には、現場で働く人の意見が欠かせない。", "target_word": "開発", "complexity_tier": "T3", "furigana": "道具[どうぐ]の開発[かいはつ]には、現場[げんば]で働[はたら]く人[ひと]の意見[いけん]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "その学校では、生徒が自分で教材を開発する授業がある。", "target_word": "開発", "complexity_tier": "T3", "furigana": "その学校[がっこう]では、生徒[せいと]が自分[じぶん]で教材[きょうざい]を開発[かいはつ]する授業[じゅぎょう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開発", "label": "基本形"}, {"form": "開発する", "label": "終止形"}, {"form": "開発した", "label": "過去形"}, {"form": "開発して", "label": "て形"}, {"form": "開発される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "これまでになかった物や品種・味などを新しくつくり出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開発", "is_correct": true, "explanation": "「おもちゃの開発に力を入れる」の「開発」。力を入れる対象として自然な名詞。"}, {"text": "返信", "is_correct": false, "explanation": "返事を出すこと。おもちゃを対象に「力を入れる」とは結びつかない。"}, {"text": "通院", "is_correct": false, "explanation": "病院に通うこと。おもちゃの文脈で「力を入れる」対象にならない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかけること。「おもちゃの施錠に力を入れる」は意味が通らない。"}], "explanations": {"開発": "「おもちゃの開発に力を入れる」の「開発」。力を入れる対象として自然な名詞。", "返信": "返事を出すこと。おもちゃを対象に「力を入れる」とは結びつかない。", "通院": "病院に通うこと。おもちゃの文脈で「力を入れる」対象にならない。", "施錠": "鍵をかけること。「おもちゃの施錠に力を入れる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "開発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大学で、古代の文字を開発している。", "explanation": "ここは〈研究〉の意味。開発は新しいものを作り出すことで、既にある古代の文字を調べる場面には使わない。"}, {"text": "古い機械を開発して、もっと長く使えるようにした。", "explanation": "ここは〈改良〉の意味。開発は新しいものをつくることで、古い機械を直して性能を上げる場面には合わない。"}, {"text": "その会議で、来年の予算を開発した。", "explanation": "ここは〈立案〉の意味。開発は新しい技術や製品を考え出して作ることで、予算を組んで計画を立てる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開発", "is_correct": true, "explanation": "「開発に失敗が続く」の「開発」。失敗の対象として自然な名詞。"}, {"text": "眠気", "is_correct": false, "explanation": "眠ろうとする感覚。「眠気に失敗が続く」は意味が通らない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様のこと。失敗が続く対象にはならない。"}, {"text": "日没", "is_correct": false, "explanation": "太陽が沈むこと。失敗の対象にはならない。"}], "explanations": {"開発": "「開発に失敗が続く」の「開発」。失敗の対象として自然な名詞。", "眠気": "眠ろうとする感覚。「眠気に失敗が続く」は意味が通らない。", "天候": "空模様のこと。失敗が続く対象にはならない。", "日没": "太陽が沈むこと。失敗の対象にはならない。"}, "sentence_index": 6, "correct_answer": "開発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この工場では毎日、同じ部品を開発している。", "explanation": "ここは〈生産〉の意味。開発は新しいものを考え出して作ることで、毎日同じ部品を量産する場面には合わない。"}, {"text": "壊れた掃除機を開発して、また使えるようにした。", "explanation": "ここは〈修理〉の意味。開発は新しいものをつくることで、壊れたものを直す場面には合わない。"}, {"text": "新しい書類を開発して、課長に提出した。", "explanation": "ここは〈作成〉の意味。開発は新しい技術や製品を考え出して作り上げることで、書類を書いて仕上げる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は新しい薬の開発を力を入れている。", "corrected_sentence": "会社は新しい薬の開発に力を入れている。", "error_description": "「開発に力を入れる」が正しい。「力を入れる」の対象は「に」で示すので、「開発を」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35106, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その農家は、寒さに強い品種を開発られた。", "corrected_sentence": "その農家は、寒さに強い品種を開発した。", "error_description": "「開発した」が正しい。「開発られた」は「開発する」の語形として誤りで、受身にしたいなら「開発される」になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35107, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アプリを開発する」の目的語。作り出す対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「アプリに開発する」は開発の対象を示す形として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は開発の目的語にならない。"}, {"text": "が", "is_correct": false, "explanation": "「アプリが開発する」ではアプリ自身が作る文意になり、不自然。"}], "correct_answer": "を", "explanations": {"を": "「アプリを開発する」の目的語。作り出す対象を示す。", "に": "「アプリに開発する」は開発の対象を示す形として不自然。", "へ": "方向を示す「へ」は開発の目的語にならない。", "が": "「アプリが開発する」ではアプリ自身が作る文意になり、不自然。"}, "error_tags": {"に": "対象の格", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
