INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35107, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい技術や製品などを考え出して作り上げること。", "primary_collocate": null, "pronunciation": "かいはつ", "ipa": "kaihatsɯ", "syllable_count": 4, "sentences": [{"text": "この会社は、電気自動車の新しいバッテリーを開発した。", "target_word": "開発", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、電気自動車[でんきじどうしゃ]の新[あたら]しいバッテリーを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "スマートフォンのアプリを開発するために、彼は毎日プログラムを書いている。", "target_word": "開発", "complexity_tier": "T4", "furigana": "スマートフォンのアプリを開発[かいはつ]するために、彼[かれ]は毎日[まいにち]プログラムを書[か]いている。", "sentence_source": "generated"}, {"text": "新型エンジンの開発には、五年以上かかったそうだ。", "target_word": "開発", "complexity_tier": "T3", "furigana": "新型[しんがた]エンジンの開発[かいはつ]には、五年[ごねん]以上[いじょう]かかったそうだ。", "sentence_source": "generated"}, {"text": "大学と企業が協力して、新しい素材を開発している。", "target_word": "開発", "complexity_tier": "T3", "furigana": "大学[だいがく]と企業[きぎょう]が協力[きょうりょく]して、新[あたら]しい素材[そざい]を開発[かいはつ]している。", "sentence_source": "generated"}, {"text": "開発したばかりの技術を、展示会で初めて公開した。", "target_word": "開発", "complexity_tier": "T4", "furigana": "開発[かいはつ]したばかりの技術[ぎじゅつ]を、展示会[てんじかい]で初[はじ]めて公開[こうかい]した。", "sentence_source": "generated"}, {"text": "彼女は、目の不自由な人のための地図アプリを開発した。", "target_word": "開発", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、目[め]の不自由[ふじゆう]な人[ひと]のための地図[ちず]アプリを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "人工知能の開発が進み、翻訳の精度が上がった。", "target_word": "開発", "complexity_tier": "T4", "furigana": "人工知能[じんこうちのう]の開発[かいはつ]が進[すす]み、翻訳[ほんやく]の精度[せいど]が上[あ]がった。", "sentence_source": "generated"}, {"text": "発売前に、開発した製品の安全性を何度も確認する。", "target_word": "開発", "complexity_tier": "T4", "furigana": "発売[はつばい]前[まえ]に、開発[かいはつ]した製品[せいひん]の安全性[あんぜんせい]を何度[なんど]も確認[かくにん]する。", "sentence_source": "generated"}, {"text": "この会社の強みは、独自の技術を開発する力だ。", "target_word": "開発", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の強[つよ]みは、独自[どくじ]の技術[ぎじゅつ]を開発[かいはつ]する力[ちから]だ。", "sentence_source": "generated"}, {"text": "ロボットを開発した学生たちが、全国大会で優勝した。", "target_word": "開発", "complexity_tier": "T3", "furigana": "ロボットを開発[かいはつ]した学生[がくせい]たちが、全国[ぜんこく]大会[たいかい]で優勝[ゆうしょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開発", "label": "基本形"}, {"form": "開発する", "label": "終止形"}, {"form": "開発した", "label": "過去形"}, {"form": "開発して", "label": "て形"}, {"form": "開発される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "新しい技術・製品・ソフトウェアなどを考案して完成させること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35107, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開発", "is_correct": true, "explanation": "「新しいバッテリーを開発した」の「開発」。製品を目的語に取る自然な動詞句。"}, {"text": "離婚", "is_correct": false, "explanation": "夫婦が婚姻関係を解消すること。バッテリーを対象にできない。"}, {"text": "返信", "is_correct": false, "explanation": "返事を出すこと。バッテリーを対象にすると意味が通らない。"}, {"text": "脱走", "is_correct": false, "explanation": "逃げ出すこと。バッテリーを対象にした文として成り立たない。"}], "explanations": {"開発": "「新しいバッテリーを開発した」の「開発」。製品を目的語に取る自然な動詞句。", "離婚": "夫婦が婚姻関係を解消すること。バッテリーを対象にできない。", "返信": "返事を出すこと。バッテリーを対象にすると意味が通らない。", "脱走": "逃げ出すこと。バッテリーを対象にした文として成り立たない。"}, "sentence_index": 0, "correct_answer": "開発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では毎日、同じ型のねじを開発している。", "explanation": "ここは〈製造〉の意味。開発は新しい技術や製品を考え出して完成させることで、毎日同じ型のものを作る場面には合わない。"}, {"text": "この手紙を開発して、英語版にした。", "explanation": "ここは〈翻訳〉の意味。開発は新しい技術や製品を考え出すことで、既にある手紙を別の言語に訳す場面には合わない。"}, {"text": "出荷前に、完成した製品を開発して確かめる。", "explanation": "ここは〈点検〉の意味。開発は新しいものを考案して完成させることで、既に完成した製品を確かめる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35107, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開発", "is_correct": true, "explanation": "「人工知能の開発が進む」の「開発」。進む対象として自然な名詞。"}, {"text": "結婚", "is_correct": false, "explanation": "夫婦になること。「人工知能の結婚が進む」は意味が通らない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様のこと。人工知能の文脈で「進む」対象にならない。"}, {"text": "早起き", "is_correct": false, "explanation": "朝早く起きること。人工知能の進みには結びつかない。"}], "explanations": {"開発": "「人工知能の開発が進む」の「開発」。進む対象として自然な名詞。", "結婚": "夫婦になること。「人工知能の結婚が進む」は意味が通らない。", "天候": "空模様のこと。人工知能の文脈で「進む」対象にならない。", "早起き": "朝早く起きること。人工知能の進みには結びつかない。"}, "sentence_index": 6, "correct_answer": "開発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いエンジンを開発して、燃費を良くした。", "explanation": "ここは〈改良〉の意味。開発は新しいものをつくることで、既にある古いエンジンを手直しする場面には合わない。"}, {"text": "壊れた古い絵画を開発して、元の姿に戻した。", "explanation": "ここは〈修復〉の意味。開発は新しいものを考え出すことで、壊れた絵画を元の姿に戻す場面には合わない。"}, {"text": "研究者は、夜空に新しい惑星を開発した。", "explanation": "ここは〈発見〉の意味。開発は新しい技術や製品を考え出して作ることで、既に存在する天体を見つけ出す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35107, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は、電気自動車の新しい充電器に開発した。", "corrected_sentence": "この会社は、電気自動車の新しい充電器を開発した。", "error_description": "「充電器を開発した」が正しい。「開発」の目的語は「を」で示すので、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35107, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、人工知能の開発で三年間取り組んだ。", "corrected_sentence": "彼女は、人工知能の開発に三年間取り組んだ。", "error_description": "「開発に取り組む」が正しい。「取り組む」の対象は「に」で示すので、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古い", "is_correct": true, "explanation": "「新しい」の対義語として辞典に載る語。以前からあるものを表し、今までと違うという意味の対になる。"}, {"text": "狭い", "is_correct": false, "explanation": "空間の広さを表す語で、「新しい」の対義語にはならない。"}, {"text": "遅い", "is_correct": false, "explanation": "時間や速度の遅さを表す語で、「新しい」の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、「新しい」の対義語ではない。"}], "correct_answer": "古い", "explanations": {"古い": "「新しい」の対義語として辞典に載る語。以前からあるものを表し、今までと違うという意味の対になる。", "狭い": "空間の広さを表す語で、「新しい」の対義語にはならない。", "遅い": "時間や速度の遅さを表す語で、「新しい」の対義語ではない。", "重い": "重さを表す語で、「新しい」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古い", "is_correct": true, "explanation": "「新しい」の対義語として辞典に載る語。「新しく」は同じ語の連用形で、対義関係は変わらない。"}, {"text": "硬い", "is_correct": false, "explanation": "固さを表す語で、「新しい」の対義語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さを表す語で、「新しい」の対義語ではない。"}, {"text": "低い", "is_correct": false, "explanation": "高さや位置を表す語で、「新しい」の対義語ではない。"}], "correct_answer": "古い", "explanations": {"古い": "「新しい」の対義語として辞典に載る語。「新しく」は同じ語の連用形で、対義関係は変わらない。", "硬い": "固さを表す語で、「新しい」の対義語ではない。", "軽い": "重さを表す語で、「新しい」の対義語ではない。", "低い": "高さや位置を表す語で、「新しい」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "今までと違って新しい。", "primary_collocate": null, "pronunciation": "あたらしい", "ipa": "atarashiː", "syllable_count": 5, "sentences": [{"text": "新しい方法を試したら、仕事が早く終わった。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "新[あたら]しい方法[ほうほう]を試[ため]したら、仕事[しごと]が早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "先生は、今までと違う新しい考え方を教えてくれた。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "先生[せんせい]は、今[いま]までと違[ちが]う新[あたら]しい考[かんが]え方[かた]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "引っ越して、新しい生活が始まった。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]して、新[あたら]しい生活[せいかつ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "去年と違って、今年は新しい練習を取り入れている。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "去年[きょねん]と違[ちが]って、今年[ことし]は新[あたら]しい練習[れんしゅう]を取[と]り入[い]れている。", "sentence_source": "generated"}, {"text": "この映画は、今までにない新しい表現で話題になった。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "この映画[えいが]は、今[いま]までにない新[あたら]しい表現[ひょうげん]で話題[わだい]になった。", "sentence_source": "generated"}, {"text": "新しい駅ができて、町の様子が変わった。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ができて、町[まち]の様子[ようす]が変[か]わった。", "sentence_source": "generated"}, {"text": "彼のアイデアは新しくて、会議の空気が変わった。", "target_word": "新しくて", "complexity_tier": "T3", "furigana": "彼[かれ]のアイデアは新[あたら]しくて、会議[かいぎ]の空気[くうき]が変[か]わった。", "sentence_source": "generated"}, {"text": "古い習慣をやめて、新しく始めたことがある。", "target_word": "新しく", "complexity_tier": "T3", "furigana": "古[ふる]い習慣[しゅうかん]をやめて、新[あたら]しく始[はじ]めたことがある。", "sentence_source": "generated"}, {"text": "その歌手は、昔とは違う新しい音楽に挑戦している。", "target_word": "新しい", "complexity_tier": "T3", "furigana": "その歌手[かしゅ]は、昔[むかし]とは違[ちが]う新[あたら]しい音楽[おんがく]に挑戦[ちょうせん]している。", "sentence_source": "generated"}, {"text": "新しくなった店は、前よりずっと明るい。", "target_word": "新しく", "complexity_tier": "T3", "furigana": "新[あたら]しくなった店[みせ]は、前[まえ]よりずっと明[あか]るい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "新しい", "label": "終止形・連体形"}, {"form": "新しく", "label": "連用形"}, {"form": "新しくて", "label": "て形"}, {"form": "新しかった", "label": "過去形"}, {"form": "新しくない", "label": "否定形"}, {"form": "新しければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "以前のものとは違う、これまでにない新たな状態や内容であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新しい", "is_correct": true, "explanation": "「新しい方法」の連体形。方法を修飾して、今までと違う方法という意味になる。"}, {"text": "赤い", "is_correct": false, "explanation": "色を表す語。「赤い方法」では今までと違う方法の意味にならない。"}, {"text": "丸い", "is_correct": false, "explanation": "形を表す語。「丸い方法」は文脈に合わない。"}, {"text": "白い", "is_correct": false, "explanation": "色を表す語。「白い方法」は意味が通らない。"}], "explanations": {"新しい": "「新しい方法」の連体形。方法を修飾して、今までと違う方法という意味になる。", "赤い": "色を表す語。「赤い方法」では今までと違う方法の意味にならない。", "丸い": "形を表す語。「丸い方法」は文脈に合わない。", "白い": "色を表す語。「白い方法」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "新しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は百年前の新しい道具を毎日使っている。", "explanation": "ここは〈新品〉の意味。今までと違うという定義の「新しい」は、百年前の道具には合わない。"}, {"text": "祖母が若い頃から大切にしてきた、新しい着物だ。", "explanation": "ここは〈新品〉の意味。長く大切にしてきた着物には、今までと違うという意味の「新しい」は合わない。"}, {"text": "築百年の老舗なのに、新しい店として話題になった。", "explanation": "ここは〈新規開店〉の意味。百年続く老舗には、今までと違うという意味の「新しい」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新しくて", "is_correct": true, "explanation": "「アイデアは新しくて」のて形。アイデアの性質を述べ、会議の空気が変わった理由になる。"}, {"text": "濡れて", "is_correct": false, "explanation": "水にぬれること。アイデアを主語にすると意味が通らない。"}, {"text": "腫れて", "is_correct": false, "explanation": "皮膚などが膨らむこと。アイデアを主語にすると意味が通らない。"}, {"text": "眠くて", "is_correct": false, "explanation": "眠気を表す語。アイデアを主語にすると意味が通らない。"}], "explanations": {"新しくて": "「アイデアは新しくて」のて形。アイデアの性質を述べ、会議の空気が変わった理由になる。", "濡れて": "水にぬれること。アイデアを主語にすると意味が通らない。", "腫れて": "皮膚などが膨らむこと。アイデアを主語にすると意味が通らない。", "眠くて": "眠気を表す語。アイデアを主語にすると意味が通らない。"}, "sentence_index": 6, "correct_answer": "新しくて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は、五十年前の新しい茶碗を毎日使っている。", "explanation": "ここは〈新品〉の意味。今までと違うという定義の「新しい」は、五十年前の茶碗には合わない。"}, {"text": "市場で新しい魚を買って、刺身にした。", "explanation": "ここは〈新鮮〉の意味。今までと違うという定義の「新しい」は、鮮度の良さを表す場面には合わない。"}, {"text": "この神社は千年前に建てられた、新しい建物だ。", "explanation": "ここは〈新築〉の意味。千年前に建てられた建物には、今までと違うという意味の「新しい」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週から、新しいな習慣を始めた。", "corrected_sentence": "先週から、新しい習慣を始めた。", "error_description": "「新しい習慣」が正しい。「新しい」は形容詞なので、名詞に続くときに「な」は付けられず、「新しいな」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "新しい", "is_correct": true, "explanation": "連体形で「考え方」を直接修飾する。今までと違う考え方という意味に合う。"}, {"text": "新しく", "is_correct": false, "explanation": "連用形は名詞を直接修飾できないので、「新しく考え方」は成り立たない。"}, {"text": "新しくて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「新しくて考え方」は文が成り立たない。"}, {"text": "新しければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、ここでは使えない。"}], "correct_form": "新しい", "base_form": "新しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"新しい": "連体形で「考え方」を直接修飾する。今までと違う考え方という意味に合う。", "新しく": "連用形は名詞を直接修飾できないので、「新しく考え方」は成り立たない。", "新しくて": "て形は名詞を修飾できず、「新しくて考え方」は文が成り立たない。", "新しければ": "仮定形は名詞を修飾できず、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35108, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は、外観を新しいした。", "corrected_sentence": "この店は、外観を新しくした。", "error_description": "「外観を新しくした」が正しい。「する」に続けるには連用形「新しく」が必要で、「新しいした」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "新しく", "is_correct": true, "explanation": "連用形で「始めた」を修飾する。「新しく始めた」は成り立つ。"}, {"text": "新しい", "is_correct": false, "explanation": "連体形は動詞「始めた」を修飾できず、「新しい始めた」は不自然。"}, {"text": "新しかった", "is_correct": false, "explanation": "過去形は「始めた」に直接かからず、文の形が崩れる。"}, {"text": "新しくない", "is_correct": false, "explanation": "否定の形で「始めた」と続かず、「新しくない始めた」は成り立たない。"}], "correct_form": "新しく", "base_form": "新しい", "form_label": "連用形", "sentence_index": 7, "explanations": {"新しく": "連用形で「始めた」を修飾する。「新しく始めた」は成り立つ。", "新しい": "連体形は動詞「始めた」を修飾できず、「新しい始めた」は不自然。", "新しかった": "過去形は「始めた」に直接かからず、文の形が崩れる。", "新しくない": "否定の形で「始めた」と続かず、「新しくない始めた」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
