INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35110, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "function", "definition": "「原因」という意味で、「～によって」と使う言葉です。", "primary_collocate": null, "pronunciation": "よる", "ipa": "joɾɯ", "syllable_count": 2, "sentences": [{"text": "今回の遅れは、大雪に因るものです。", "target_word": "因る", "complexity_tier": "T3", "furigana": "今回[こんかい]の遅[おく]れは、大雪[おおゆき]に因[よ]るものです。", "sentence_source": "generated"}, {"text": "火事の原因は、たばこの火の不始末に因ると考えられる。", "target_word": "因る", "complexity_tier": "T4", "furigana": "火事[かじ]の原因[げんいん]は、たばこの火[ひ]の不始末[ふしまつ]に因[よ]ると考[かんが]えられる。", "sentence_source": "generated"}, {"text": "電車の遅れは、信号の故障に因って起きた。", "target_word": "因って", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の遅[おく]れは、信号[しんごう]の故障[こしょう]に因[よ]って起[お]きた。", "sentence_source": "generated"}, {"text": "この病気は、ウイルスに因るものではなく、生活習慣に因るものだ。", "target_word": "因る", "complexity_tier": "T4", "furigana": "この病気[びょうき]は、ウイルスに因[よ]るものではなく、生活習慣[せいかつしゅうかん]に因[よ]るものだ。", "sentence_source": "generated"}, {"text": "事故は、運転手の居眠りに因って起こった。", "target_word": "因って", "complexity_tier": "T3", "furigana": "事故[じこ]は、運転手[うんてんしゅ]の居眠[いねむ]りに因[よ]って起[お]こった。", "sentence_source": "generated"}, {"text": "彼の失敗は、準備不足に因ります。", "target_word": "因ります", "complexity_tier": "T3", "furigana": "彼[かれ]の失敗[しっぱい]は、準備不足[じゅんびぶそく]に因[よ]ります。", "sentence_source": "generated"}, {"text": "強い雨に因って、試合は中止になった。", "target_word": "因って", "complexity_tier": "T3", "furigana": "強[つよ]い雨[あめ]に因[よ]って、試合[しあい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "作物の被害は、長く続いた干ばつに因る。", "target_word": "因る", "complexity_tier": "T3", "furigana": "作物[さくもつ]の被害[ひがい]は、長[なが]く続[つづ]いた干[ひ]ばつに因[よ]る。", "sentence_source": "generated"}, {"text": "停電は、雷に因って起こったと発表された。", "target_word": "因って", "complexity_tier": "T4", "furigana": "停電[ていでん]は、雷[かみなり]に因[よ]って起[お]こったと発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "川の水があふれたのは、大雨に因るものだった。", "target_word": "因る", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]があふれたのは、大雨[おおあめ]に因[よ]るものだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "因る", "label": "終止形・連体形"}, {"form": "因って", "label": "て形"}, {"form": "因った", "label": "過去形"}, {"form": "因ります", "label": "丁寧形"}, {"form": "因らない", "label": "否定形"}], "register": "formal-written", "sense_fingerprint": "「〜に因る」の形で、ある結果の原因・理由を示す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53cbea69-d3e7-450d-a7a2-d101bb9bdab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35110, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因る", "is_correct": true, "explanation": "「大雪に因るもの」の連体形。大雪を原因として示す文脈に合う。"}, {"text": "眠る", "is_correct": false, "explanation": "眠ることを表す語で、大雪を原因とする文脈に合わない。"}, {"text": "転ぶ", "is_correct": false, "explanation": "倒れる意味の語で、「大雪に転ぶもの」は成り立たない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を出す意味の語で、原因を示す文脈に合わない。"}], "explanations": {"因る": "「大雪に因るもの」の連体形。大雪を原因として示す文脈に合う。", "眠る": "眠ることを表す語で、大雪を原因とする文脈に合わない。", "転ぶ": "倒れる意味の語で、「大雪に転ぶもの」は成り立たない。", "叫ぶ": "声を出す意味の語で、原因を示す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "因る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の名前は、祖父の名前に因っている。", "explanation": "ここは「因む」の意味。名前の由来を言うなら「名前に因んでいる」と言うべきで、「因っている」では合わない。"}, {"text": "環境問題に因る本を読んだ。", "explanation": "ここは〈関する〉の意味。「因る」は原因を示すので、話題を示す場面には合わない。"}, {"text": "この菓子の名は、古い町の名に因っている。", "explanation": "ここは〈名の由来〉の意味。原因を示す「因る」とは扱いが異なり、ここでは名づけの由来の文脈になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35110, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因って", "is_correct": true, "explanation": "「強い雨に因って」のて形。雨を原因として試合が中止になった文脈に合う。"}, {"text": "笑って", "is_correct": false, "explanation": "笑う意味の語で、雨を原因とする文脈に合わない。"}, {"text": "光って", "is_correct": false, "explanation": "光る意味の語で、試合中止の原因を示せない。"}, {"text": "踊って", "is_correct": false, "explanation": "踊る意味の語で、「強い雨に踊って」は成り立たない。"}], "explanations": {"因って": "「強い雨に因って」のて形。雨を原因として試合が中止になった文脈に合う。", "笑って": "笑う意味の語で、雨を原因とする文脈に合わない。", "光って": "光る意味の語で、試合中止の原因を示せない。", "踊って": "踊る意味の語で、「強い雨に踊って」は成り立たない。"}, "sentence_index": 6, "correct_answer": "因って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この祭りの名前は、昔の武将の名に因っている。", "explanation": "ここは「因む」の意味。名前の由来を言うなら「名に因んでいる」と言うべきで、「因っている」では合わない。"}, {"text": "この町の名前は、昔の武将の名に因っている。", "explanation": "ここは〈名の由来〉の意味。原因の「因る」として読むと、名づけの文脈に合わない。"}, {"text": "この店の名前は、亡くなった友人の名に因っている。", "explanation": "ここは〈名の由来〉の意味。原因の「因る」として読むと、名づけの文脈に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35110, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風の被害は、強風を因るものだ。", "corrected_sentence": "台風の被害は、強風に因るものだ。", "error_description": "「強風に因る」が正しい。「因る」が示す原因には「に」を使うので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35110, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その遅れは、事故に因るて起きた。", "corrected_sentence": "その遅れは、事故に因って起きた。", "error_description": "「事故に因って」が正しい。「因る」のて形は「因って」で、「因るて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305ec81c-fd5d-473f-8f39-90c94495047f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
