INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35114, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "「ずっと」は、前とくらべて、とてもちがうことをあらわすことばです。", "primary_collocate": null, "pronunciation": "ずっと", "ipa": "zɯtto", "syllable_count": 3, "sentences": [{"text": "去年より、今年の冬はずっと寒い。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "去年[きょねん]より、今年[ことし]の冬[ふゆ]はずっと寒[さむ]い。", "sentence_source": "generated"}, {"text": "引っ越してから、通勤がずっと楽になった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してから、通勤[つうきん]がずっと楽[らく]になった。", "sentence_source": "generated"}, {"text": "薬を飲んだら、昨日よりずっと元気になった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら、昨日[きのう]よりずっと元気[げんき]になった。", "sentence_source": "generated"}, {"text": "新しい眼鏡にしたら、字がずっと読みやすくなった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "新[あたら]しい眼鏡[めがね]にしたら、字[じ]がずっと読[よ]みやすくなった。", "sentence_source": "generated"}, {"text": "練習を続けたので、前よりずっと上手に泳げる。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を続[つづ]けたので、前[まえ]よりずっと上手[じょうず]に泳[およ]げる。", "sentence_source": "generated"}, {"text": "部屋を片づけたら、前とはずっと違う雰囲気になった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "部屋[へや]を片[かた]づけたら、前[まえ]とはずっと違[ちが]う雰囲気[ふんいき]になった。", "sentence_source": "generated"}, {"text": "兄は結婚してから、ずっと優しくなった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "兄[あに]は結婚[けっこん]してから、ずっと優[やさ]しくなった。", "sentence_source": "generated"}, {"text": "新しい駅ができて、街はずっと便利になった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ができて、街[まち]はずっと便利[べんり]になった。", "sentence_source": "generated"}, {"text": "先月と比べて、この店はずっと混んでいる。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "先月[せんげつ]と比[くら]べて、この店[みせ]はずっと混[こ]んでいる。", "sentence_source": "generated"}, {"text": "髪を切ったので、頭がずっと軽く感じる。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "髪[かみ]を切[き]ったので、頭[あたま]がずっと軽[かる]く感[かん]じる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ずっと", "label": "基本形"}], "register": "口語・中立(常体)", "sense_fingerprint": "以前の状態と比べて変化の程度が大きいことを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35114, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ずっと", "is_correct": true, "explanation": "去年との比較で、今年の冬の寒さの差が大きいことを表し、ここに入る。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "打ち消しの形と結ぶ副詞なので、肯定の「寒い」とは合わない。"}, {"text": "ふと", "is_correct": false, "explanation": "不意に、思いがけずという意味で、程度の差を表す文には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "打ち消しと結ぶ語で、肯定の「寒い」の前には置けない。"}], "explanations": {"ずっと": "去年との比較で、今年の冬の寒さの差が大きいことを表し、ここに入る。", "ぜんぜん": "打ち消しの形と結ぶ副詞なので、肯定の「寒い」とは合わない。", "ふと": "不意に、思いがけずという意味で、程度の差を表す文には合わない。", "決して": "打ち消しと結ぶ語で、肯定の「寒い」の前には置けない。"}, "sentence_index": 0, "correct_answer": "ずっと"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題はずっと終わった。", "explanation": "ずっとには〈ほとんど〉の意味がなく、この文は不自然。ずっとは前との程度の差を表す。"}, {"text": "ずっと十時に、電話がかかってきた。", "explanation": "ずっとには〈ちょうど〉の意味がなく、時刻をぴったり指す文には使えない。"}, {"text": "準備はずっと一時間で終わった。", "explanation": "ずっとには〈たった〉の意味がなく、少なさを強調する文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35114, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ずっと", "is_correct": true, "explanation": "結婚の前後で性格が変わった程度の差を表し、ここに入る。"}, {"text": "必ず", "is_correct": false, "explanation": "確実にという意味の副詞で、少しずつ変わった程度の差を表す文には合わない。"}, {"text": "そっと", "is_correct": false, "explanation": "静かに、こっそりという意味で、性格の変化を述べるここには合わない。"}, {"text": "少しも", "is_correct": false, "explanation": "打ち消しと結ぶ語で、過去の変化を述べる肯定文には使えない。"}], "explanations": {"ずっと": "結婚の前後で性格が変わった程度の差を表し、ここに入る。", "必ず": "確実にという意味の副詞で、少しずつ変わった程度の差を表す文には合わない。", "そっと": "静かに、こっそりという意味で、性格の変化を述べるここには合わない。", "少しも": "打ち消しと結ぶ語で、過去の変化を述べる肯定文には使えない。"}, "sentence_index": 6, "correct_answer": "ずっと"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ずっと雨がやんだ。", "explanation": "ずっとには〈ようやく〉の意味がなく、一点の出来事を表す文とは合わない。"}, {"text": "荷物を頼んだら、ずっと届いた。", "explanation": "ずっとには〈すぐに〉の意味がなく、即座の到着を表す文には使えない。"}, {"text": "薬を飲んだら、ずっと少し楽になった。", "explanation": "ずっとには〈やや〉の意味がなく、わずかな変化を表す文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35114, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日より、今日の朝はずっとの寒い。", "corrected_sentence": "昨日より、今日の朝はずっと寒い。", "error_description": "副詞「ずっと」に助詞「の」が付き、「寒い」に続けられない形になっている。副詞は助詞を付けず、そのまま「寒い」を修飾する。正しくは「ずっと寒い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35114, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は進学してから、ずっとが優しくなった。", "corrected_sentence": "兄は進学してから、ずっと優しくなった。", "error_description": "副詞「ずっと」に格助詞「が」が付き、主語のように扱われている。副詞は助詞を付けず、そのまま「優しくなった」を修飾する。正しくは「ずっと優しくなった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
