INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35115, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "副詞。比較の基準よりも程度がはるかに大きいことを表す。", "primary_collocate": null, "pronunciation": "ずっと", "ipa": "zɯtto", "syllable_count": 3, "sentences": [{"text": "弟は私よりずっと背が高い。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "弟[おとうと]は私[わたし]よりずっと背[せ]が高[たか]い。", "sentence_source": "generated"}, {"text": "電車で行くより、バスのほうがずっと安い。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で行[い]くより、バスのほうがずっと安[やす]い。", "sentence_source": "generated"}, {"text": "東京は私の町よりずっと人が多い。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "東京[とうきょう]は私[わたし]の町[まち]よりずっと人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "この本はあの本よりずっとおもしろい。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "この本[ほん]はあの本[ほん]よりずっとおもしろい。", "sentence_source": "generated"}, {"text": "歩くより自転車のほうがずっと速い。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "歩[ある]くより自転車[じてんしゃ]のほうがずっと速[はや]い。", "sentence_source": "generated"}, {"text": "去年の試験は、今年よりずっとむずかしかった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "去年[きょねん]の試験[しけん]は、今年[ことし]よりずっとむずかしかった。", "sentence_source": "generated"}, {"text": "姉は母よりずっと料理が上手だ。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "姉[あね]は母[はは]よりずっと料理[りょうり]が上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "駅から近い部屋のほうが、ずっといい。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "駅[えき]から近[ちか]い部屋[へや]のほうが、ずっといい。", "sentence_source": "generated"}, {"text": "夏の北海道は、東京よりずっとすずしい。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "夏[なつ]の北海道[ほっかいどう]は、東京[とうきょう]よりずっとすずしい。", "sentence_source": "generated"}, {"text": "想像していたより、実物はずっと小さかった。", "target_word": "ずっと", "complexity_tier": "T3", "furigana": "想像[そうぞう]していたより、実物[じつぶつ]はずっと小[ちい]さかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ずっと", "label": "基本形"}], "register": "口語・中立(常体)", "sense_fingerprint": "比較の基準(〜より)に対して程度の差がはるかに大きいことを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: むずかしかっ (Zipf 1.93)','sentence 8 above tier T1: contains vocabulary far above tier T1: すずしい (Zipf 2.04)']::text[], 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35115, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ずっと", "is_correct": true, "explanation": "比べる基準（私）より背の差がはるかに大きいことを表し、ここに入る。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "打ち消しと結ぶ副詞なので、肯定の「背が高い」とは合わない。"}, {"text": "ふと", "is_correct": false, "explanation": "不意に、思いがけずという意味で、背の高さの比較とは合わない。"}, {"text": "決して", "is_correct": false, "explanation": "打ち消しと結ぶ語で、肯定の「背が高い」の前には置けない。"}], "explanations": {"ずっと": "比べる基準（私）より背の差がはるかに大きいことを表し、ここに入る。", "ぜんぜん": "打ち消しと結ぶ副詞なので、肯定の「背が高い」とは合わない。", "ふと": "不意に、思いがけずという意味で、背の高さの比較とは合わない。", "決して": "打ち消しと結ぶ語で、肯定の「背が高い」の前には置けない。"}, "sentence_index": 0, "correct_answer": "ずっと"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ずっと正午に、アラームが鳴った。", "explanation": "ずっとには〈ちょうど〉の意味がなく、時刻を指す文には使えない。"}, {"text": "ずっと一人分の料理で、家族が満足した。", "explanation": "ずっとには〈たった〉の意味がなく、少ない量を強調する文には使えない。"}, {"text": "報告書はずっと完成した。", "explanation": "ずっとには〈ほとんど〉の意味がなく、完成直前の状態を表す文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35115, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ずっと", "is_correct": true, "explanation": "比べる基準（母）より上手さの差がはるかに大きいことを表し、ここに入る。"}, {"text": "必ず", "is_correct": false, "explanation": "「必ず」は確実にという意味の副詞で、料理の上手さの程度の差を表すここには合わない。"}, {"text": "そっと", "is_correct": false, "explanation": "「そっと」は静かに、こっそりという意味で、料理の上手さの比較とは合わない。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも」は打ち消しと結ぶ語で、肯定の「上手だ」の前には置けない。"}], "explanations": {"ずっと": "比べる基準（母）より上手さの差がはるかに大きいことを表し、ここに入る。", "必ず": "「必ず」は確実にという意味の副詞で、料理の上手さの程度の差を表すここには合わない。", "そっと": "「そっと」は静かに、こっそりという意味で、料理の上手さの比較とは合わない。", "少しも": "「少しも」は打ち消しと結ぶ語で、肯定の「上手だ」の前には置けない。"}, "sentence_index": 6, "correct_answer": "ずっと"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ずっと試験が終わった。", "explanation": "ずっとには〈やっと〉の意味がなく、一点の出来事を表す文とは合わない。"}, {"text": "注文したら、ずっと商品が届いた。", "explanation": "ずっとには〈すぐに〉の意味がなく、即座の到着を表す文には使えない。"}, {"text": "雨が止んだら、ずっと少し涼しくなった。", "explanation": "ずっとには〈やや〉の意味がなく、わずかな変化を表す文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35115, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この机は隣の机よりずっとの広い。", "corrected_sentence": "この机は隣の机よりずっと広い。", "error_description": "「ずっと」に助詞「の」が付き、形容詞「広い」を直接修飾できない形になっている。副詞はそのまま「広い」に続ける。正しくは「ずっと広い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
