INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35116, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ねだんがひくいこと。", "primary_collocate": null, "pronunciation": "やすい", "ipa": "jasɯi", "syllable_count": 3, "sentences": [{"text": "このりんごは一つ百円で、とても安い。", "target_word": "安い", "complexity_tier": "T3", "furigana": "このりんごは一[ひと]つ百円[ひゃくえん]で、とても安[やす]い。", "sentence_source": "generated"}, {"text": "昨日は野菜が安かったので、たくさん買った。", "target_word": "安かった", "complexity_tier": "T3", "furigana": "昨日[きのう]は野菜[やさい]が安[やす]かったので、たくさん買[か]った。", "sentence_source": "generated"}, {"text": "もっと安い店を探して、駅の反対側まで歩いた。", "target_word": "安い", "complexity_tier": "T3", "furigana": "もっと安[やす]い店[みせ]を探[さが]して、駅[えき]の反対側[はんたいがわ]まで歩[ある]いた。", "sentence_source": "generated"}, {"text": "安くて味もいい店を友だちが教えてくれた。", "target_word": "安くて", "complexity_tier": "T3", "furigana": "安[やす]くて味[あじ]もいい店[みせ]を友[とも]だちが教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "セールの日は、服が半分の値段で安く買える。", "target_word": "安く", "complexity_tier": "T3", "furigana": "セールの日[ひ]は、服[ふく]が半分[はんぶん]の値段[ねだん]で安[やす]く買[か]える。", "sentence_source": "generated"}, {"text": "この靴は安いけれど、すぐにこわれてしまった。", "target_word": "安い", "complexity_tier": "T3", "furigana": "この靴[くつ]は安[やす]いけれど、すぐにこわれてしまった。", "sentence_source": "generated"}, {"text": "夜に行くと、パンが安くなる。", "target_word": "安く", "complexity_tier": "T3", "furigana": "夜[よる]に行[い]くと、パンが安[やす]くなる。", "sentence_source": "generated"}, {"text": "値段が安ければ、二つ買うつもりだ。", "target_word": "安ければ", "complexity_tier": "T3", "furigana": "値段[ねだん]が安[やす]ければ、二[ふた]つ買[か]うつもりだ。", "sentence_source": "generated"}, {"text": "先週の航空券は、今週より安かった。", "target_word": "安かった", "complexity_tier": "T3", "furigana": "先週[せんしゅう]の航空券[こうくうけん]は、今週[こんしゅう]より安[やす]かった。", "sentence_source": "generated"}, {"text": "安い切符を買うために、早めに予約した。", "target_word": "安い", "complexity_tier": "T3", "furigana": "安[やす]い切符[きっぷ]を買[か]うために、早[はや]めに予約[よやく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安い", "label": "基本形"}, {"form": "安く", "label": "連用形"}, {"form": "安かった", "label": "過去形"}, {"form": "安くない", "label": "否定形"}, {"form": "安ければ", "label": "仮定形"}], "register": "口語・中立(常体)", "sense_fingerprint": "商品やサービスの値段が低いことを表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35116, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安い", "is_correct": true, "explanation": "一つ百円という値段の低さを表し、ここに入る。"}, {"text": "早い", "is_correct": false, "explanation": "速さや時刻を表す語で、値段の話には合わない。"}, {"text": "遅い", "is_correct": false, "explanation": "時間や速度が遅いことを表し、値段の高低とは関係しない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す語で、りんごの値段の説明には合わない。"}], "explanations": {"安い": "一つ百円という値段の低さを表し、ここに入る。", "早い": "速さや時刻を表す語で、値段の話には合わない。", "遅い": "時間や速度が遅いことを表し、値段の高低とは関係しない。", "細い": "太さを表す語で、りんごの値段の説明には合わない。"}, "sentence_index": 0, "correct_answer": "安い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事の手間が安いので、作業は一時間で終わった。", "explanation": "安いには〈省ける〉（手間が少ない）の意味がなく、手間の少なさには使えない。"}, {"text": "テストの問題が安くて、全員が満点を取った。", "explanation": "安いには〈簡単〉（やさしい）の意味がなく、問題の難しさには使えない。"}, {"text": "店の評判が一度安くなると、取り戻すのは難しい。", "explanation": "安いには〈落ちる〉（評判が下がる）の意味がなく、評判の低下には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35116, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安く", "is_correct": true, "explanation": "値段が下がる意味で、「なる」と結びつき、ここに入る。"}, {"text": "早く", "is_correct": false, "explanation": "時間の早さを表し、パンの値段の変化とは合わない。"}, {"text": "遅く", "is_correct": false, "explanation": "時間の遅さを表し、値段の変化とは合わない。"}, {"text": "近く", "is_correct": false, "explanation": "距離を表す語で、「パンが近くなる」では文が成り立たない。"}], "explanations": {"安く": "値段が下がる意味で、「なる」と結びつき、ここに入る。", "早く": "時間の早さを表し、パンの値段の変化とは合わない。", "遅く": "時間の遅さを表し、値段の変化とは合わない。", "近く": "距離を表す語で、「パンが近くなる」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "安く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会社で地位が安い。", "explanation": "安いには〈低い〉（地位が低い）の意味がなく、地位の高低には使えない。"}, {"text": "一仕事終えて、気持ちが安い。", "explanation": "安いには〈軽い〉（気持ちが軽い）の意味がなく、心の状態には使えない。"}, {"text": "その会社は経営が安くて、心配だ。", "explanation": "安いには〈安定〉（経営が安定している）の意味がなく、経営の状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35116, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "値段がとても安いで、みんな買う。", "corrected_sentence": "値段がとても安いので、みんな買う。", "error_description": "「安い」の後に助詞「で」が付き、理由をつなぐ「ので」になっていない。正しくは「安いので」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安かった", "is_correct": true, "explanation": "過去形で、「昨日」の値段の低さを表し、ここに入る。"}, {"text": "安く", "is_correct": false, "explanation": "連用形で、「ので」に続く理由の形にならない。"}, {"text": "安ければ", "is_correct": false, "explanation": "仮定形で、「ので」の理由を表す文には合わない。"}, {"text": "安かったら", "is_correct": false, "explanation": "仮定の過去形で、「ので」と続けると文が崩れる。"}], "correct_form": "安かった", "base_form": "安い", "form_label": "過去形", "sentence_index": 1, "explanations": {"安かった": "過去形で、「昨日」の値段の低さを表し、ここに入る。", "安く": "連用形で、「ので」に続く理由の形にならない。", "安ければ": "仮定形で、「ので」の理由を表す文には合わない。", "安かったら": "仮定の過去形で、「ので」と続けると文が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35116, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "安いの席を取るために、早めに並んだ。", "corrected_sentence": "安い席を取るために、早めに並んだ。", "error_description": "「安い」の直後に助詞「の」が付き、名詞「席」を直接修飾できない形になっている。正しくは「安い席」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "安ければ", "is_correct": true, "explanation": "仮定形で、値段が低い場合という条件を表し、ここに入る。"}, {"text": "安かった", "is_correct": false, "explanation": "過去形で、条件を表せず文が崩れる。"}, {"text": "安い", "is_correct": false, "explanation": "基本形で、「、」の前では文が切れ、並列の形にならない。"}, {"text": "安くない", "is_correct": false, "explanation": "否定形で、条件節としての形にならない。"}], "correct_form": "安ければ", "base_form": "安い", "form_label": "仮定形", "sentence_index": 7, "explanations": {"安ければ": "仮定形で、値段が低い場合という条件を表し、ここに入る。", "安かった": "過去形で、条件を表せず文が崩れる。", "安い": "基本形で、「、」の前では文が切れ、並列の形にならない。", "安くない": "否定形で、条件節としての形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35117, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高い", "is_correct": true, "explanation": "「安い」の対義語で、値段が高いという意味。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞で、値段の対義語ではない。"}, {"text": "狭い", "is_correct": false, "explanation": "空間の狭さを表す語で、「安い」の対義語ではない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さや時間の遅さを表す語で、「安い」の対義語ではない。"}], "correct_answer": "高い", "explanations": {"高い": "「安い」の対義語で、値段が高いという意味。", "重い": "重さを表す形容詞で、値段の対義語ではない。", "狭い": "空間の狭さを表す語で、「安い」の対義語ではない。", "遅い": "速さや時間の遅さを表す語で、「安い」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
