INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35117, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "値段が低く、買いやすいこと。", "primary_collocate": null, "pronunciation": "やすい", "ipa": "jasɯi", "syllable_count": 3, "sentences": [{"text": "学生にも買える安い値段なので、よく売れている。", "target_word": "安い", "complexity_tier": "T3", "furigana": "学生[がくせい]にも買[か]える安[やす]い値段[ねだん]なので、よく売[う]れている。", "sentence_source": "generated"}, {"text": "この店のお弁当は安くて、毎日買いやすい。", "target_word": "安くて", "complexity_tier": "T3", "furigana": "この店[みせ]のお弁当[べんとう]は安[やす]くて、毎日[まいにち]買[か]いやすい。", "sentence_source": "generated"}, {"text": "安いスマホなら、私のおこづかいでも買える。", "target_word": "安い", "complexity_tier": "T3", "furigana": "安[やす]いスマホなら、私[わたし]のおこづかいでも買[か]える。", "sentence_source": "generated"}, {"text": "給料が少ないので、安い家具から買いそろえた。", "target_word": "安い", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が少[すく]ないので、安[やす]い家具[かぐ]から買[か]いそろえた。", "sentence_source": "generated"}, {"text": "安く買えるように、まとめて注文した。", "target_word": "安く", "complexity_tier": "T3", "furigana": "安[やす]く買[か]えるように、まとめて注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "値段が安いから、子どもでも自分で買える。", "target_word": "安い", "complexity_tier": "T3", "furigana": "値段[ねだん]が安[やす]いから、子[こ]どもでも自分[じぶん]で買[か]える。", "sentence_source": "generated"}, {"text": "家から近くて安い店なので、毎週通っている。", "target_word": "安い", "complexity_tier": "T3", "furigana": "家[いえ]から近[ちか]くて安[やす]い店[みせ]なので、毎週[まいしゅう]通[かよ]っている。", "sentence_source": "generated"}, {"text": "安くなかったら、この車は買わなかった。", "target_word": "安くなかったら", "complexity_tier": "T3", "furigana": "安[やす]くなかったら、この車[くるま]は買[か]わなかった。", "sentence_source": "generated"}, {"text": "冬のあいだに使う安い手袋を、二つ買った。", "target_word": "安い", "complexity_tier": "T3", "furigana": "冬[ふゆ]のあいだに使[つか]う安[やす]い手袋[てぶくろ]を、二[ふた]つ買[か]った。", "sentence_source": "generated"}, {"text": "学校の近くには、安い食堂が多くて助かる。", "target_word": "安い", "complexity_tier": "T3", "furigana": "学校[がっこう]の近[ちか]くには、安[やす]い食堂[しょくどう]が多[おお]くて助[たす]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安い", "label": "基本形"}, {"form": "安く", "label": "連用形"}, {"form": "安くて", "label": "て形"}, {"form": "安くなかったら", "label": "否定仮定形"}], "register": "口語・中立(常体)", "sense_fingerprint": "値段が低くて手が届きやすく、気軽に買えることを表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35117, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安い", "is_correct": true, "explanation": "値段が低く買いやすいという意味で、ここに入る。"}, {"text": "早い", "is_correct": false, "explanation": "時間の早さを表し、値段の話には合わない。"}, {"text": "遅い", "is_correct": false, "explanation": "時間の遅さを表し、値段の話には合わない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す語で、値段の説明には合わない。"}], "explanations": {"安い": "値段が低く買いやすいという意味で、ここに入る。", "早い": "時間の早さを表し、値段の話には合わない。", "遅い": "時間の遅さを表し、値段の話には合わない。", "細い": "太さを表す語で、値段の説明には合わない。"}, "sentence_index": 0, "correct_answer": "安い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍵を閉めたので、もう安い。", "explanation": "安いには〈安心〉（ほっとする）の意味がなく、気持ちの安らぎには使えない。"}, {"text": "会社の評判が安くなり、客が減った。", "explanation": "安いには〈落ちる〉（評判が下がる）の意味がなく、評判の低下には使えない。"}, {"text": "この課題は安いので、すぐに終わった。", "explanation": "安いには〈簡単〉の意味がなく、課題の難しさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35117, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安い", "is_correct": true, "explanation": "家の近くで値段が低く、通いやすい店という意味で、ここに入る。"}, {"text": "軽い", "is_correct": false, "explanation": "重さが少ないことを表す語で、店の説明には合わない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表す語で、店の説明には合わない。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気があることを表す語で、店の説明には合わない。"}], "explanations": {"安い": "家の近くで値段が低く、通いやすい店という意味で、ここに入る。", "軽い": "重さが少ないことを表す語で、店の説明には合わない。", "太い": "太さを表す語で、店の説明には合わない。", "眠い": "眠気があることを表す語で、店の説明には合わない。"}, "sentence_index": 6, "correct_answer": "安い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その選手は評価が安いので、試合に出られない。", "explanation": "安いには〈低い〉（評価が低い）の意味がなく、評価の高低には使えない。"}, {"text": "穏やかな海が、今日は安い。", "explanation": "安いには〈穏やか〉の意味がなく、海の状態には使えない。"}, {"text": "夜の道は安いので、一人では歩かないほうがいい。", "explanation": "安いには〈安全〉の意味がなく、危険の有無は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35117, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新入生にも買える安いの値段なので、よく売れている。", "corrected_sentence": "新入生にも買える安い値段なので、よく売れている。", "error_description": "「安い」の後に助詞「の」が付き、名詞「値段」を直接修飾できない形になっている。正しくは「安い値段」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安くて", "is_correct": true, "explanation": "て形で、「安い」と「買いやすい」を並べる役割があり、ここに入る。"}, {"text": "安い", "is_correct": false, "explanation": "基本形で、「、」の前では文が切れ、並べる形にならない。"}, {"text": "安かった", "is_correct": false, "explanation": "過去形で、並列の文の形に合わない。"}, {"text": "安くない", "is_correct": false, "explanation": "否定形で、並べる形にならず文が崩れる。"}], "correct_form": "安くて", "base_form": "安い", "form_label": "て形", "sentence_index": 1, "explanations": {"安くて": "て形で、「安い」と「買いやすい」を並べる役割があり、ここに入る。", "安い": "基本形で、「、」の前では文が切れ、並べる形にならない。", "安かった": "過去形で、並列の文の形に合わない。", "安くない": "否定形で、並べる形にならず文が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35117, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校の近くには、安いが店が多くて助かる。", "corrected_sentence": "学校の近くには、安い店が多くて助かる。", "error_description": "「安い」の直後に格助詞「が」が付き、名詞「店」を修飾できなくなっている。正しくは「安い店」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "安くなかったら", "is_correct": true, "explanation": "否定の仮定形で、「なかったら」の条件を表し、文頭の条件節に合う。"}, {"text": "安くなる", "is_correct": false, "explanation": "変化を表す形で、「なかったら」の条件節にはならず、文が成り立たない。"}, {"text": "安くなかった", "is_correct": false, "explanation": "否定の過去形で、「たら」がないため条件節が完結せず、文が途切れる。"}, {"text": "安くありません", "is_correct": false, "explanation": "丁寧な否定形で、文頭の条件節（「なかったら」）の形にならない。"}], "correct_form": "安くなかったら", "base_form": "安い", "form_label": "否定の仮定形", "sentence_index": 7, "explanations": {"安くなかったら": "否定の仮定形で、「なかったら」の条件を表し、文頭の条件節に合う。", "安くなる": "変化を表す形で、「なかったら」の条件節にはならず、文が成り立たない。", "安くなかった": "否定の過去形で、「たら」がないため条件節が完結せず、文が途切れる。", "安くありません": "丁寧な否定形で、文頭の条件節（「なかったら」）の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "速さの反対語で、作業にかかる時間が長い意味になる。"}, {"text": "高い", "is_correct": false, "explanation": "値段や位置の高さの反対語で、速さには対応しない。"}, {"text": "重い", "is_correct": false, "explanation": "重さの反対語は軽い。速さとは関係ない。"}, {"text": "細い", "is_correct": false, "explanation": "太さの反対語は太い。速さには対応しない。"}], "correct_answer": "遅い", "explanations": {"遅い": "速さの反対語で、作業にかかる時間が長い意味になる。", "高い": "値段や位置の高さの反対語で、速さには対応しない。", "重い": "重さの反対語は軽い。速さとは関係ない。", "細い": "太さの反対語は太い。速さには対応しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "速さの反対語で、作業にかかる時間が長い意味になる。"}, {"text": "狭い", "is_correct": false, "explanation": "広さの反対語で、速さとは無関係。"}, {"text": "深い", "is_correct": false, "explanation": "深さを表す語で、速さとは無関係。"}, {"text": "柔らかい", "is_correct": false, "explanation": "硬さの反対語で、速さには対応しない。"}], "correct_answer": "遅い", "explanations": {"遅い": "速さの反対語で、作業にかかる時間が長い意味になる。", "狭い": "広さの反対語で、速さとは無関係。", "深い": "深さを表す語で、速さとは無関係。", "柔らかい": "硬さの反対語で、速さには対応しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "何かをするのにかかる時間が少ないこと。", "primary_collocate": null, "pronunciation": "はやい", "ipa": "hajai", "syllable_count": 3, "sentences": [{"text": "兄は食べるのが早いので、いつも先に終わる。", "target_word": "早い", "complexity_tier": "T3", "furigana": "兄[あに]は食[た]べるのが早[はや]いので、いつも先[さき]に終[お]わる。", "sentence_source": "generated"}, {"text": "彼女は仕事が早くて、頼むとすぐ終わらせてくれる。", "target_word": "早くて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕事[しごと]が早[はや]くて、頼[たの]むとすぐ終[お]わらせてくれる。", "sentence_source": "generated"}, {"text": "この店は料理が出てくるのが早い。", "target_word": "早い", "complexity_tier": "T3", "furigana": "この店[みせ]は料理[りょうり]が出[で]てくるのが早[はや]い。", "sentence_source": "generated"}, {"text": "返事が早かったので、予定を決めやすかった。", "target_word": "早かった", "complexity_tier": "T3", "furigana": "返事[へんじ]が早[はや]かったので、予定[よてい]を決[き]めやすかった。", "sentence_source": "generated"}, {"text": "手を洗うのが早いと、よく先生にほめられる。", "target_word": "早い", "complexity_tier": "T3", "furigana": "手[て]を洗[あら]うのが早[はや]いと、よく先生[せんせい]にほめられる。", "sentence_source": "generated"}, {"text": "計算の早い人は、暗算も得意だ。", "target_word": "早い", "complexity_tier": "T3", "furigana": "計算[けいさん]の早[はや]い人[ひと]は、暗算[あんざん]も得意[とくい]だ。", "sentence_source": "generated"}, {"text": "この方法のほうが早いから、先に試してみよう。", "target_word": "早い", "complexity_tier": "T3", "furigana": "この方法[ほうほう]のほうが早[はや]いから、先[さき]に試[ため]してみよう。", "sentence_source": "generated"}, {"text": "準備が早ければ、そのぶん休む時間も増える。", "target_word": "早ければ", "complexity_tier": "T3", "furigana": "準備[じゅんび]が早[はや]ければ、そのぶん休[やす]む時間[じかん]も増[ふ]える。", "sentence_source": "generated"}, {"text": "彼は着替えが早く、三分で家を出る。", "target_word": "早く", "complexity_tier": "T3", "furigana": "彼[かれ]は着替[きが]えが早[はや]く、三分[さんぷん]で家[いえ]を出[で]る。", "sentence_source": "generated"}, {"text": "注文から届くまでが早くて、助かった。", "target_word": "早くて", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]から届[とど]くまでが早[はや]くて、助[たす]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "早い", "label": "基本形"}, {"form": "早く", "label": "連用形"}, {"form": "早くて", "label": "て形"}, {"form": "早かった", "label": "過去形"}, {"form": "早ければ", "label": "仮定形"}], "register": "口語・中立(常体)", "sense_fingerprint": "作業や行動を済ませるのに要する時間が短いこと(手早い)を表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早い", "is_correct": true, "explanation": "食べ終えるまでの時間が短いという意味で、「先に終わる」と合う。"}, {"text": "遅い", "is_correct": false, "explanation": "食べるのが遅ければ先に終わらないので、「いつも先に終わる」と矛盾する。"}, {"text": "重い", "is_correct": false, "explanation": "食べ方の速さは「重い」では表せず、文として意味が通らない。"}, {"text": "細い", "is_correct": false, "explanation": "「細い」は太さの語で、食べる速さを表せない。"}], "explanations": {"早い": "食べ終えるまでの時間が短いという意味で、「先に終わる」と合う。", "遅い": "食べるのが遅ければ先に終わらないので、「いつも先に終わる」と矛盾する。", "重い": "食べ方の速さは「重い」では表せず、文として意味が通らない。", "細い": "「細い」は太さの語で、食べる速さを表せない。"}, "sentence_index": 0, "correct_answer": "早い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道は距離が早いので、近道として使える。", "explanation": "距離の長さは〈短い〉で表す。ここは〈短い〉の意味で、〈早い〉は時間の短さに使うので合わない。"}, {"text": "このかばんは重さが早いので、持ち運びにくい。", "explanation": "重さは〈重い〉〈軽い〉で表す。ここは〈重い〉の意味で、〈早い〉は時間の短さに使うので合わない。"}, {"text": "この部屋は広さが早いので、家具を置きやすい。", "explanation": "広さは〈広い〉〈狭い〉で表す。ここは〈広い〉の意味で、〈早い〉は時間の短さに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早い", "is_correct": true, "explanation": "この方法なら時間が短く済むので、先に試す理由に合う。"}, {"text": "広い", "is_correct": false, "explanation": "「方法」の広さは理由にならず、文が通らない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さは方法の速さとは無関係で、理由として成り立たない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さは方法の速さとは無関係で、理由として成り立たない。"}], "explanations": {"早い": "この方法なら時間が短く済むので、先に試す理由に合う。", "広い": "「方法」の広さは理由にならず、文が通らない。", "厚い": "厚さは方法の速さとは無関係で、理由として成り立たない。", "硬い": "硬さは方法の速さとは無関係で、理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "早い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題は難易度が早いので、解くのに時間がかかる。", "explanation": "難しさは〈難しい〉で表す。ここは〈難しい〉の意味で、〈早い〉は時間の短さに使うので合わない。"}, {"text": "この箱は高さが早いので、棚に入らない。", "explanation": "高さは〈高い〉で表す。ここは〈高い〉の意味で、〈早い〉は時間の短さに使うので合わない。"}, {"text": "この店は値段が早いので、学生も助かる。", "explanation": "値段の高さ・安さは〈高い〉〈安い〉で表す。ここは〈安い〉の意味で、〈早い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "料理の準備が早いくて、客を待たせない。", "corrected_sentence": "料理の準備が早くて、客を待たせない。", "error_description": "形容詞「早い」のて形は「早くて」。「早いくて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "早くて", "is_correct": true, "explanation": "て形で、「仕事が早くて、頼むと…」と続けられる。"}, {"text": "早い", "is_correct": false, "explanation": "終止形で、「、頼むと」と続けられず文がつながらない。"}, {"text": "早かった", "is_correct": false, "explanation": "過去形で、現在の話の流れと時制が合わない。"}, {"text": "早かろう", "is_correct": false, "explanation": "推量形で「だろう」の意味になり、「仕事が」の後に「、頼むと」と続けられない。"}], "correct_form": "早くて", "base_form": "早い", "form_label": "て形", "sentence_index": 1, "explanations": {"早くて": "て形で、「仕事が早くて、頼むと…」と続けられる。", "早い": "終止形で、「、頼むと」と続けられず文がつながらない。", "早かった": "過去形で、現在の話の流れと時制が合わない。", "早かろう": "推量形で「だろう」の意味になり、「仕事が」の後に「、頼むと」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35118, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬は効き目を早くて、すぐ楽になった。", "corrected_sentence": "この薬は効き目が早くて、すぐ楽になった。", "error_description": "「効き目が早い」の主語は「が」。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "早ければ", "is_correct": true, "explanation": "仮定形で「早ければ〜」と条件を示し、後ろの文に続く。"}, {"text": "早くない", "is_correct": false, "explanation": "否定形で、準備が早いことを否定して文の意味が逆になる。"}, {"text": "早かろう", "is_correct": false, "explanation": "推量形で「だろう」の意味になり、条件の文として続かない。"}, {"text": "早く", "is_correct": false, "explanation": "連用形では「準備が早く、そのぶん」と言い切れず、「そのぶん」と続く自然な文にならない。"}], "correct_form": "早ければ", "base_form": "早い", "form_label": "仮定形", "sentence_index": 7, "explanations": {"早ければ": "仮定形で「早ければ〜」と条件を示し、後ろの文に続く。", "早くない": "否定形で、準備が早いことを否定して文の意味が逆になる。", "早かろう": "推量形で「だろう」の意味になり、条件の文として続かない。", "早く": "連用形では「準備が早く、そのぶん」と言い切れず、「そのぶん」と続く自然な文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "時期が前であることの反対語で、時期が後である意味になる。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さを表す語で、時期の前後とは関係ない。"}, {"text": "深い", "is_correct": false, "explanation": "深さを表す語で、時期の前後とは関係ない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さの反対語で、時期の前後とは関係ない。"}], "correct_answer": "遅い", "explanations": {"遅い": "時期が前であることの反対語で、時期が後である意味になる。", "厚い": "厚さを表す語で、時期の前後とは関係ない。", "深い": "深さを表す語で、時期の前後とは関係ない。", "軽い": "重さの反対語で、時期の前後とは関係ない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "時期が前であることの反対語で、時期が後である意味になる。"}, {"text": "狭い", "is_correct": false, "explanation": "広さの反対語で、時期の前後とは関係ない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "硬さの反対語で、時期の前後とは関係ない。"}, {"text": "硬い", "is_correct": false, "explanation": "柔らかいの反対語で、時期の前後とは関係ない。"}], "correct_answer": "遅い", "explanations": {"遅い": "時期が前であることの反対語で、時期が後である意味になる。", "狭い": "広さの反対語で、時期の前後とは関係ない。", "柔らかい": "硬さの反対語で、時期の前後とは関係ない。", "硬い": "柔らかいの反対語で、時期の前後とは関係ない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "基準となる時間よりも前に起こる様子。また、時間の経過が短いさま。", "primary_collocate": null, "pronunciation": "はやい", "ipa": "hajai", "syllable_count": 3, "sentences": [{"text": "明日は試験なので、今夜は早い時間にねる。", "target_word": "早い", "complexity_tier": "T3", "furigana": "明日[あした]は試験[しけん]なので、今夜[こんや]は早[はや]い時間[じかん]にねる。", "sentence_source": "generated"}, {"text": "今朝は早く起きて、公園を散歩した。", "target_word": "早く", "complexity_tier": "T3", "furigana": "今朝[けさ]は早[はや]く起[お]きて、公園[こうえん]を散歩[さんぽ]した。", "sentence_source": "generated"}, {"text": "約束の時間より早く着いてしまった。", "target_word": "早く", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]より早[はや]く着[つ]いてしまった。", "sentence_source": "generated"}, {"text": "桜が咲くのが、今年は例年より早い。", "target_word": "早い", "complexity_tier": "T3", "furigana": "桜[さくら]が咲[さ]くのが、今年[ことし]は例年[れいねん]より早[はや]い。", "sentence_source": "generated"}, {"text": "あきらめるのはまだ早い。", "target_word": "早い", "complexity_tier": "T3", "furigana": "あきらめるのはまだ早[はや]い。", "sentence_source": "generated"}, {"text": "父は朝が早いので、夜は九時にねる。", "target_word": "早い", "complexity_tier": "T3", "furigana": "父[ちち]は朝[あさ]が早[はや]いので、夜[よる]は九時[くじ]にねる。", "sentence_source": "generated"}, {"text": "早く着きすぎて、店はまだ開いていなかった。", "target_word": "早く", "complexity_tier": "T3", "furigana": "早[はや]く着[つ]きすぎて、店[みせ]はまだ開[あ]いていなかった。", "sentence_source": "generated"}, {"text": "冬は日がしずむのが早い。", "target_word": "早い", "complexity_tier": "T3", "furigana": "冬[ふゆ]は日[ひ]がしずむのが早[はや]い。", "sentence_source": "generated"}, {"text": "結果を判断するには、まだ早い時期だ。", "target_word": "早い", "complexity_tier": "T3", "furigana": "結果[けっか]を判断[はんだん]するには、まだ早[はや]い時期[じき]だ。", "sentence_source": "generated"}, {"text": "早い電車に乗ったので、座ることができた。", "target_word": "早い", "complexity_tier": "T3", "furigana": "早[はや]い電車[でんしゃ]に乗[の]ったので、座[すわ]ることができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "早い", "label": "基本形"}, {"form": "早く", "label": "連用形"}, {"form": "早かった", "label": "過去形"}, {"form": "早くない", "label": "否定形"}], "register": "口語・中立(常体)", "sense_fingerprint": "基準の時刻や時期より前であること、時期がまだ来ていないことを表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: しずむ (Zipf 1.41)']::text[], 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早い", "is_correct": true, "explanation": "時刻が前であるという意味で、試験に備えて夜早くねる文に合う。"}, {"text": "重い", "is_correct": false, "explanation": "時間を重いと言うのは不自然で、文が通らない。"}, {"text": "太い", "is_correct": false, "explanation": "時間の太さは意味をなさない。"}, {"text": "広い", "is_correct": false, "explanation": "時間の広さを言うのは不自然で、文が通らない。"}], "explanations": {"早い": "時刻が前であるという意味で、試験に備えて夜早くねる文に合う。", "重い": "時間を重いと言うのは不自然で、文が通らない。", "太い": "時間の太さは意味をなさない。", "広い": "時間の広さを言うのは不自然で、文が通らない。"}, "sentence_index": 0, "correct_answer": "早い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は重さが早いので、一人では持ち上げられない。", "explanation": "重さは〈重い〉で表す。ここは〈重い〉の意味で、〈早い〉は時期や時間の前後に使うので合わない。"}, {"text": "この店は値段が早いので、学生にも手が届く。", "explanation": "値段の高さ・安さは〈高い〉〈安い〉で表す。ここは〈安い〉の意味で、〈早い〉は時期の前後に使うので合わない。"}, {"text": "この問題は難しさが早いので、解けるか心配だ。", "explanation": "難しさは〈難しい〉で表す。ここは〈難しい〉の意味で、〈早い〉は時期の前後の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早く", "is_correct": true, "explanation": "時間より前に着いたという意味で、「着きすぎて」と自然に続く。"}, {"text": "厚く", "is_correct": false, "explanation": "厚さの語で、着く時間とは関係ない。"}, {"text": "強く", "is_correct": false, "explanation": "強さの語で、着く時間とは関係なく文が通らない。"}, {"text": "細く", "is_correct": false, "explanation": "細さの語で、時間には対応しない。"}], "explanations": {"早く": "時間より前に着いたという意味で、「着きすぎて」と自然に続く。", "厚く": "厚さの語で、着く時間とは関係ない。", "強く": "強さの語で、着く時間とは関係なく文が通らない。", "細く": "細さの語で、時間には対応しない。"}, "sentence_index": 6, "correct_answer": "早く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は速度が早いので、高速道路で目立つ。", "explanation": "速さは〈速い〉で表す。ここは〈速い〉の意味で、〈早い〉は時期や時間の前後に使うので合わない。"}, {"text": "この道は長さが早いので、歩くのが大変だ。", "explanation": "長さは〈長い〉で表す。ここは〈長い〉の意味で、〈早い〉は時期や時間の前後に使うので合わない。"}, {"text": "この木は背が早いので、遠くからでも目立つ。", "explanation": "高さは〈高い〉で表す。ここは〈高い〉の意味で、〈早い〉は時期や時間に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今朝は早いく起きたので、遅刻しなかった。", "corrected_sentence": "今朝は早く起きたので、遅刻しなかった。", "error_description": "「早い」の連用形は「早く」。「早いく」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "早く", "is_correct": true, "explanation": "連用形で、「起きて」を修飾する形として自然。"}, {"text": "早い", "is_correct": false, "explanation": "終止形で、「起きて」を修飾できない。"}, {"text": "早かった", "is_correct": false, "explanation": "過去形で、「起きて」とつながらない。"}, {"text": "早ければ", "is_correct": false, "explanation": "仮定形で「もし早ければ」の意味になり、文の意味が変わる。"}], "correct_form": "早く", "base_form": "早い", "form_label": "連用形", "sentence_index": 1, "explanations": {"早く": "連用形で、「起きて」を修飾する形として自然。", "早い": "終止形で、「起きて」を修飾できない。", "早かった": "過去形で、「起きて」とつながらない。", "早ければ": "仮定形で「もし早ければ」の意味になり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35119, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予定の時間で早く着いたので、店の前で待った。", "corrected_sentence": "予定の時間より早く着いたので、店の前で待った。", "error_description": "時間を比べる基準は「より」。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "早い", "is_correct": true, "explanation": "終止形で、「冬は日がしずむのが早い」と文末で自然に言い切れる。"}, {"text": "早く", "is_correct": false, "explanation": "連用形で、文末に置くと言い切れず文が完結しない。"}, {"text": "早ければ", "is_correct": false, "explanation": "仮定形で、文末に置くと条件の節のまま文が完結しない。"}, {"text": "早くて", "is_correct": false, "explanation": "て形のままでは文が終わらず、文末として不自然。"}], "correct_form": "早い", "base_form": "早い", "form_label": "終止形", "sentence_index": 7, "explanations": {"早い": "終止形で、「冬は日がしずむのが早い」と文末で自然に言い切れる。", "早く": "連用形で、文末に置くと言い切れず文が完結しない。", "早ければ": "仮定形で、文末に置くと条件の節のまま文が完結しない。", "早くて": "て形のままでは文が終わらず、文末として不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「登場」は「待つ」の対象なので「を」。「主人公の登場を待っていた」で成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「登場へ待っていた」と待つ対象が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や引用を表すので、「登場と待っていた」では待つ対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するので、「登場の、待っていた」と文が切れて合わない。"}], "correct_answer": "を", "explanations": {"を": "「登場」は「待つ」の対象なので「を」。「主人公の登場を待っていた」で成り立つ。", "へ": "「へ」は方向を表すので、「登場へ待っていた」と待つ対象が合わない。", "と": "「と」は相手や引用を表すので、「登場と待っていた」では待つ対象にならない。", "の": "「の」は名詞を修飾するので、「登場の、待っていた」と文が切れて合わない。"}, "error_tags": {"へ": "方向", "と": "相手・引用", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「登場」は「祝う」の対象なので「を」。「登場を祝って」で文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「登場が祝って」では祝う主体が合わず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「登場より祝って」では比べる内容がない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を表すので、「登場から祝って」では祝う対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「登場」は「祝う」の対象なので「を」。「登場を祝って」で文が成り立つ。", "が": "「が」は主語を示すので、「登場が祝って」では祝う主体が合わず文が成り立たない。", "より": "「より」は比較を表すので、「登場より祝って」では比べる内容がない。", "から": "「から」は起点や理由を表すので、「登場から祝って」では祝う対象にならない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や人が、初めて現れること。", "primary_collocate": null, "pronunciation": "とうじょう", "ipa": "toːd͡ʑoː", "syllable_count": 4, "sentences": [{"text": "新しい携帯電話の登場で、生活が便利になった。", "target_word": "登場", "complexity_tier": "T3", "furigana": "新[あたら]しい携帯電話[けいたいでんわ]の登場[とうじょう]で、生活[せいかつ]が便利[べんり]になった。", "sentence_source": "generated"}, {"text": "主人公の登場を、観客は静かに待っていた。", "target_word": "登場", "complexity_tier": "T3", "furigana": "主人公[しゅじんこう]の登場[とうじょう]を、観客[かんきゃく]は静[しず]かに待[ま]っていた。", "sentence_source": "generated"}, {"text": "物語の後半になって、謎の男が登場する。", "target_word": "登場", "complexity_tier": "T3", "furigana": "物語[ものがたり]の後半[こうはん]になって、謎[なぞ]の男[おとこ]が登場[とうじょう]する。", "sentence_source": "generated"}, {"text": "電気自動車の登場は、街の音を変えた。", "target_word": "登場", "complexity_tier": "T3", "furigana": "電気自動車[でんきじどうしゃ]の登場[とうじょう]は、街[まち]の音[おと]を変[か]えた。", "sentence_source": "generated"}, {"text": "彼女の登場に、会場はいっせいに拍手をした。", "target_word": "登場", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の登場[とうじょう]に、会場[かいじょう]はいっせいに拍手[はくしゅ]をした。", "sentence_source": "generated"}, {"text": "今月号から、新しい犬のキャラクターが登場する。", "target_word": "登場", "complexity_tier": "T3", "furigana": "今月号[こんげつごう]から、新[あたら]しい犬[いぬ]のキャラクターが登場[とうじょう]する。", "sentence_source": "generated"}, {"text": "新型の機械が登場してから、仕事が早くなった。", "target_word": "登場", "complexity_tier": "T3", "furigana": "新型[しんがた]の機械[きかい]が登場[とうじょう]してから、仕事[しごと]が早[はや]くなった。", "sentence_source": "generated"}, {"text": "新人歌手の登場を祝って、司会者は大きな花束を渡した。", "target_word": "登場", "complexity_tier": "T3", "furigana": "新人歌手[しんじんかしゅ]の登場[とうじょう]を祝[いわ]って、司会者[しかいしゃ]は大[おお]きな花束[はなたば]を渡[わた]した。", "sentence_source": "generated"}, {"text": "インターネットの登場によって、情報が集めやすくなった。", "target_word": "登場", "complexity_tier": "T3", "furigana": "インターネットの登場[とうじょう]によって、情報[じょうほう]が集[あつ]めやすくなった。", "sentence_source": "generated"}, {"text": "劇では、王様が最初に登場する。", "target_word": "登場", "complexity_tier": "T3", "furigana": "劇[げき]では、王様[おうさま]が最初[さいしょ]に登場[とうじょう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "登場する", "label": "辞書形"}, {"form": "登場した", "label": "過去形"}, {"form": "登場して", "label": "て形"}, {"form": "登場しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "物や人が初めて姿を現すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 祝っ (Zipf 3.63), 司会 (Zipf 3.99), 花束 (Zipf 3.64)']::text[], '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登場", "is_correct": true, "explanation": "〈登場〉は新しい物が世に現れることで、「登場で生活が便利になった」と因果がつながる。"}, {"text": "故障", "is_correct": false, "explanation": "故障は使えなくなることなので、便利になった理由にならず文の意味が合わない。"}, {"text": "紛失", "is_correct": false, "explanation": "なくすことは便利さにつながらず、「紛失で便利になった」は意味が通らない。"}, {"text": "盗難", "is_correct": false, "explanation": "盗まれることで生活が便利になることはなく、文の意味と合わない。"}], "explanations": {"登場": "〈登場〉は新しい物が世に現れることで、「登場で生活が便利になった」と因果がつながる。", "故障": "故障は使えなくなることなので、便利になった理由にならず文の意味が合わない。", "紛失": "なくすことは便利さにつながらず、「紛失で便利になった」は意味が通らない。", "盗難": "盗まれることで生活が便利になることはなく、文の意味と合わない。"}, "sentence_index": 0, "correct_answer": "登場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乗客は定刻どおりに、飛行機へ登場を始めた。", "explanation": "ここは〈搭乗〉（乗り物に乗り込むこと）の意味。同じ読みの〈登場〉は物や人が世に現れることなので、乗り込む動作には使えない。"}, {"text": "会社の登場を役所に届けた。", "explanation": "ここは〈登記〉（会社などを法務局に記録してもらうこと）の意味。登場は現れることなので、役所への届け出には使えない。"}, {"text": "彼らは朝早く、富士山の頂上に登場した。", "explanation": "ここは〈登頂〉（山の頂上に到達すること）の意味。登場は現れることで、頂上に達する意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登場", "is_correct": true, "explanation": "新型機が世に現れ、その後で仕事が早くなったという流れになる。"}, {"text": "故障", "is_correct": false, "explanation": "故障すると仕事は早くならないので、文の結果と合わない。"}, {"text": "誤作動", "is_correct": false, "explanation": "誤作動では仕事が早くならず、「誤作動してから仕事が早くなった」は成り立たない。"}, {"text": "停電", "is_correct": false, "explanation": "停電すると仕事は止まるので、早くなるという結果に合わない。"}], "explanations": {"登場": "新型機が世に現れ、その後で仕事が早くなったという流れになる。", "故障": "故障すると仕事は早くならないので、文の結果と合わない。", "誤作動": "誤作動では仕事が早くならず、「誤作動してから仕事が早くなった」は成り立たない。", "停電": "停電すると仕事は止まるので、早くなるという結果に合わない。"}, "sentence_index": 6, "correct_answer": "登場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町で大きな事故が登場した。", "explanation": "ここは〈発生〉（出来事が起こること）の意味。事故は世に現れる物や人ではないので、〈登場〉とは言わない。"}, {"text": "体に発疹が登場した。", "explanation": "ここは〈出現〉（症状などが現れること）の意味。発疹は世に出るものではないので、〈登場〉は合わない。"}, {"text": "A社は来月、東京証券取引所に登場する。", "explanation": "ここは〈上場〉（株式を市場で売買できるようにすること）の意味。登場は現れることなので、株式を取引所に加える意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい携帯電話の登場を、駅前の店が混雑した。", "corrected_sentence": "新しい携帯電話の登場で、駅前の店が混雑した。", "error_description": "原因を表す文では「登場」に「で」を付ける。誤りは「を」、正しくは「で」。「を」だと文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35120, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新型の機器が登場たので、工場の仕事が早くなった。", "corrected_sentence": "新型の機器が登場したので、工場の仕事が早くなった。", "error_description": "「登場」は「する」と活用する動詞なので、過去形は「登場した」。「し」を抜いた「登場た」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退場", "is_correct": true, "explanation": "「その場に現れる」の反対で、その場から去ること。〈登場〉の対義語として辞書にも挙がる。"}, {"text": "出発", "is_correct": false, "explanation": "出発は場所を離れることだが、〈登場〉の対義語ではない（反対語は到着）。"}, {"text": "発見", "is_correct": false, "explanation": "発見は見つけることで、現れることの反対ではない。"}, {"text": "交換", "is_correct": false, "explanation": "交換は取り替えることで、〈登場〉の反対の意味にはならない。"}], "correct_answer": "退場", "explanations": {"退場": "「その場に現れる」の反対で、その場から去ること。〈登場〉の対義語として辞書にも挙がる。", "出発": "出発は場所を離れることだが、〈登場〉の対義語ではない（反対語は到着）。", "発見": "発見は見つけることで、現れることの反対ではない。", "交換": "交換は取り替えることで、〈登場〉の反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退場", "is_correct": true, "explanation": "「その場に現れる」の反対で、その場から去ること。〈登場〉の対義語として辞書にも挙がる。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれることで、〈登場〉の反対の意味ではない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作ることで、〈登場〉の反対の意味ではない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集団が別れることで、〈登場〉の対義語ではない。"}], "correct_answer": "退場", "explanations": {"退場": "「その場に現れる」の反対で、その場から去ること。〈登場〉の対義語として辞書にも挙がる。", "誕生": "誕生は生まれることで、〈登場〉の反対の意味ではない。", "製造": "製造は物を作ることで、〈登場〉の反対の意味ではない。", "解散": "解散は集団が別れることで、〈登場〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい物や人物が、初めて世の中に現れること。また、その場に現れること。", "primary_collocate": null, "pronunciation": "とうじょう", "ipa": "toːd͡ʑoː", "syllable_count": 4, "sentences": [{"text": "新人選手の登場に、ファンの期待が高まった。", "target_word": "登場", "complexity_tier": "T3", "furigana": "新人選手[しんじんせんしゅ]の登場[とうじょう]に、ファンの期待[きたい]が高[たか]まった。", "sentence_source": "generated"}, {"text": "新型スマートフォンが登場し、店の前に行列ができた。", "target_word": "登場", "complexity_tier": "T3", "furigana": "新型[しんがた]スマートフォンが登場[とうじょう]し、店[みせ]の前[まえ]に行列[ぎょうれつ]ができた。", "sentence_source": "generated"}, {"text": "大会に彼が登場すると、空気が一気に変わった。", "target_word": "登場", "complexity_tier": "T3", "furigana": "大会[たいかい]に彼[かれ]が登場[とうじょう]すると、空気[くうき]が一気[いっき]に変[か]わった。", "sentence_source": "generated"}, {"text": "映画にはかつての人気俳優が登場する。", "target_word": "登場", "complexity_tier": "T3", "furigana": "映画[えいが]にはかつての人気俳優[にんきはいゆう]が登場[とうじょう]する。", "sentence_source": "generated"}, {"text": "登場したばかりの商品は、値段が高い。", "target_word": "登場", "complexity_tier": "T3", "furigana": "登場[とうじょう]したばかりの商品[しょうひん]は、値段[ねだん]が高[たか]い。", "sentence_source": "generated"}, {"text": "彼女は舞台の右側から登場した。", "target_word": "登場", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は舞台[ぶたい]の右側[みぎがわ]から登場[とうじょう]した。", "sentence_source": "generated"}, {"text": "ゲームの新キャラクターが、今日の放送で登場する。", "target_word": "登場", "complexity_tier": "T3", "furigana": "ゲームの新[しん]キャラクターが、今日[きょう]の放送[ほうそう]で登場[とうじょう]する。", "sentence_source": "generated"}, {"text": "蒸気機関の登場は、社会を大きく変えた。", "target_word": "登場", "complexity_tier": "T3", "furigana": "蒸気機関[じょうききかん]の登場[とうじょう]は、社会[しゃかい]を大[おお]きく変[か]えた。", "sentence_source": "generated"}, {"text": "主役の登場まで、客席はざわついていた。", "target_word": "登場", "complexity_tier": "T3", "furigana": "主役[しゅやく]の登場[とうじょう]まで、客席[きゃくせき]はざわついていた。", "sentence_source": "generated"}, {"text": "新しい歌手が登場するたびに、音楽の流行は変わる。", "target_word": "登場", "complexity_tier": "T3", "furigana": "新[あたら]しい歌手[かしゅ]が登場[とうじょう]するたびに、音楽[おんがく]の流行[りゅうこう]は変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "登場する", "label": "辞書形"}, {"form": "登場した", "label": "過去形"}, {"form": "登場して", "label": "て形"}, {"form": "登場しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "新しい物や人物が世に出ること、またその場に現れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: ざわつい (Zipf 2.35)']::text[], '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登場", "is_correct": true, "explanation": "〈登場〉は選手が現れることで、「登場に期待が高まった」と文が通る。"}, {"text": "引退", "is_correct": false, "explanation": "引退は選手が去ることなので、ファンの期待が高まる理由にならない。"}, {"text": "怪我", "is_correct": false, "explanation": "怪我は期待を高めるものではなく、「怪我に期待が高まった」は意味が通らない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は契約を打ち切ることなので、期待が高まるという文の意味と合わない。"}], "explanations": {"登場": "〈登場〉は選手が現れることで、「登場に期待が高まった」と文が通る。", "引退": "引退は選手が去ることなので、ファンの期待が高まる理由にならない。", "怪我": "怪我は期待を高めるものではなく、「怪我に期待が高まった」は意味が通らない。", "解雇": "解雇は契約を打ち切ることなので、期待が高まるという文の意味と合わない。"}, "sentence_index": 0, "correct_answer": "登場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乗客は搭乗口で順番に、飛行機へ登場を始めた。", "explanation": "ここは〈搭乗〉（乗り物に乗り込むこと）の意味。同じ読みの〈登場〉は現れることなので、乗り込む動作には使えない。"}, {"text": "A社は来月、東京証券取引所に登場する。", "explanation": "ここは〈上場〉（株式を市場で売買できるようにすること）の意味。登場は現れることなので、株式市場への上場の意味では使えない。"}, {"text": "週末に友人と、山へ登場した。", "explanation": "ここは〈登山〉（山に登ること）の意味。〈登場〉は山に登る意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登場", "is_correct": true, "explanation": "キャラクターが放送で現れる、という文の意味に合う。"}, {"text": "故障", "is_correct": false, "explanation": "キャラクターが故障するという文は、放送の内容として意味が通らない。"}, {"text": "感謝", "is_correct": false, "explanation": "キャラクターが放送で感謝するという文は、意味が通らない。"}, {"text": "退職", "is_correct": false, "explanation": "キャラクターが退職するという文は、新キャラクターの話として合わない。"}], "explanations": {"登場": "キャラクターが放送で現れる、という文の意味に合う。", "故障": "キャラクターが故障するという文は、放送の内容として意味が通らない。", "感謝": "キャラクターが放送で感謝するという文は、意味が通らない。", "退職": "キャラクターが退職するという文は、新キャラクターの話として合わない。"}, "sentence_index": 6, "correct_answer": "登場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜、この地域で大規模な停電が登場した。", "explanation": "ここは〈発生〉（出来事が起こること）の意味。停電は世に現れる物や人ではないので、〈登場〉とは言わない。"}, {"text": "皮膚に赤いしみが登場した。", "explanation": "ここは〈出現〉（症状などが現れること）の意味。しみは世に出るものではないので、〈登場〉は合わない。"}, {"text": "先月、株価が大きく登場した。", "explanation": "ここは〈変動〉（数値が上下に変わること）の意味。株価の上下は現れることではないので、〈登場〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新型スマートフォンが登場ったので、店の前に行列ができた。", "corrected_sentence": "新型スマートフォンが登場したので、店の前に行列ができた。", "error_description": "「登場」は「する」と活用する動詞なので、過去形は「登場した」。「し」を「っ」に変えた「登場った」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35121, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい店が登場たびに、町の人が集まる。", "corrected_sentence": "新しい店が登場するたびに、町の人が集まる。", "error_description": "「たびに」の前は動詞の連体形が必要なので「登場するたびに」。「する」を抜いた「登場たびに」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35122, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普通", "is_correct": true, "explanation": "正解。「ふつうではない」に対して「ふつう」を表す、対義関係にある語。"}, {"text": "簡単", "is_correct": false, "explanation": "形状詞だが、「特別」と対義関係にはない。「手間がかからない」の意味。"}, {"text": "静か", "is_correct": false, "explanation": "形状詞だが、「にぎやかではない」様子を表し、「特別」との対義関係はない。"}, {"text": "大切", "is_correct": false, "explanation": "形状詞だが、「重要で大事にすべき」の意味で、「特別」の対義語ではない。"}], "correct_answer": "普通", "explanations": {"普通": "正解。「ふつうではない」に対して「ふつう」を表す、対義関係にある語。", "簡単": "形状詞だが、「特別」と対義関係にはない。「手間がかからない」の意味。", "静か": "形状詞だが、「にぎやかではない」様子を表し、「特別」との対義関係はない。", "大切": "形状詞だが、「重要で大事にすべき」の意味で、「特別」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
