INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35122, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ふつうではない、とてもめずらしいこと。", "primary_collocate": null, "pronunciation": "とくべつ", "ipa": "tokɯbetsɯ", "syllable_count": 4, "sentences": [{"text": "今日は母の誕生日なので、特別な料理を作りました。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "今日[きょう]は母[はは]の誕生日[たんじょうび]なので、特別[とくべつ]な料理[りょうり]を作[つく]りました。", "sentence_source": "generated"}, {"text": "年に一度だけ見られる特別な花が、山の上で咲いた。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "年[とし]に一度[いちど]だけ見[み]られる特別[とくべつ]な花[はな]が、山[やま]の上[うえ]で咲[さ]いた。", "sentence_source": "generated"}, {"text": "この切手はとても古くて、特別な価値がある。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "この切手[きって]はとても古[ふる]くて、特別[とくべつ]な価値[かち]がある。", "sentence_source": "generated"}, {"text": "雪がめったに降らない町なので、雪の日は特別だ。", "target_word": "特別だ", "complexity_tier": "T3", "furigana": "雪[ゆき]がめったに降[ふ]らない町[まち]なので、雪[ゆき]の日[ひ]は特別[とくべつ]だ。", "sentence_source": "generated"}, {"text": "結婚式の日は、二人にとって特別な一日だった。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の日[ひ]は、二人[ふたり]にとって特別[とくべつ]な一日[いちにち]だった。", "sentence_source": "generated"}, {"text": "ふだんは入れない部屋を、特別に見せてもらった。", "target_word": "特別に", "complexity_tier": "T3", "furigana": "ふだんは入[はい]れない部屋[へや]を、特別[とくべつ]に見[み]せてもらった。", "sentence_source": "generated"}, {"text": "彼女にとって、あの夏の旅行は特別な思い出です。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "彼女[かのじょ]にとって、あの夏[なつ]の旅行[りょこう]は特別[とくべつ]な思[おも]い出[で]です。", "sentence_source": "generated"}, {"text": "一年に一回の祭りは、町の人には特別なものだ。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "一年[いちねん]に一回[いっかい]の祭[まつ]りは、町[まち]の人[ひと]には特別[とくべつ]なものだ。", "sentence_source": "generated"}, {"text": "この宝石は特別なので、ふだんは箱の中にしまってある。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "この宝石[ほうせき]は特別[とくべつ]なので、ふだんは箱[はこ]の中[なか]にしまってある。", "sentence_source": "generated"}, {"text": "雨の日に虹を見るなんて、特別なことが起きた気がした。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]に虹[にじ]を見[み]るなんて、特別[とくべつ]なことが起[お]きた気[き]がした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特別だ", "label": "終止形"}, {"form": "特別な", "label": "連体形"}, {"form": "特別に", "label": "連用形"}, {"form": "特別で", "label": "て形"}, {"form": "特別だった", "label": "過去形"}, {"form": "特別ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "ふだんとは違う、めったにない・めずらしい様子を表す「特別」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35122, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特別な", "is_correct": true, "explanation": "正解。後ろの名詞「料理」を修飾する連体形。"}, {"text": "特別だ", "is_correct": false, "explanation": "終止形は名詞を直接修飾できず、「料理」に続けられない。"}, {"text": "特別で", "is_correct": false, "explanation": "て形は文の途中の形で、名詞の前には使えない。"}, {"text": "特別だった", "is_correct": false, "explanation": "過去形は名詞修飾に使えず、「特別だった料理」は成り立たない。"}], "explanations": {"特別な": "正解。後ろの名詞「料理」を修飾する連体形。", "特別だ": "終止形は名詞を直接修飾できず、「料理」に続けられない。", "特別で": "て形は文の途中の形で、名詞の前には使えない。", "特別だった": "過去形は名詞修飾に使えず、「特別だった料理」は成り立たない。"}, "sentence_index": 0, "correct_answer": "特別な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "どの家にも同じ特別な飾りがあって、珍しくない。", "explanation": "「珍しくない」と矛盾する。「特別」はふつうではないほどめずらしい意味で、ありふれたものには使えない。"}, {"text": "毎日食べるふつうのご飯を、特別な料理と呼んでいる。", "explanation": "ふつうの食事を指すので、「ふつうではない」の意味と逆になる。この義項では使えない。"}, {"text": "どこにでも見かける特別な看板で、目立たない。", "explanation": "「目立たない」と矛盾する。「特別」はめずらしさを表し、ありふれた物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35122, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特別な", "is_correct": true, "explanation": "正解。後ろの名詞「思い出」を修飾する連体形。"}, {"text": "特別に", "is_correct": false, "explanation": "「特別に」は副詞なので、名詞「思い出」の前に置けない。"}, {"text": "特別では", "is_correct": false, "explanation": "「では」は述語を作る形で、名詞「思い出」を修飾できない。"}, {"text": "特別なら", "is_correct": false, "explanation": "仮定形で、名詞「思い出」を修飾する形として成り立たない。"}], "explanations": {"特別な": "正解。後ろの名詞「思い出」を修飾する連体形。", "特別に": "「特別に」は副詞なので、名詞「思い出」の前に置けない。", "特別では": "「では」は述語を作る形で、名詞「思い出」を修飾できない。", "特別なら": "仮定形で、名詞「思い出」を修飾する形として成り立たない。"}, "sentence_index": 6, "correct_answer": "特別な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "どの店にも売っている特別な菓子で、珍しさはない。", "explanation": "「珍しさはない」と矛盾する。ふつうの菓子に「特別」は使えない。"}, {"text": "毎日見かける特別な景色で、めずらしくも何ともない。", "explanation": "めずらしくないことを述べており、この義項の「ふつうではない」と逆になる。"}, {"text": "どこにでもある特別な石ころだ。", "explanation": "「どこにでもある」はふつうのものを表し、特別な（めずらしい）意味と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35122, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その花は、年に一度だけ咲く特別花だ。", "corrected_sentence": "その花は、年に一度だけ咲く特別な花だ。", "error_description": "「特別」は形状詞なので、名詞の前では「な」が要る。「特別花」は誤りで、「特別な花」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "特別な", "is_correct": true, "explanation": "正解。名詞「花」を修飾する連体形。"}, {"text": "特別だ", "is_correct": false, "explanation": "終止形で、名詞「花」を修飾できない。"}, {"text": "特別で", "is_correct": false, "explanation": "て形で、名詞の前には立たない。"}, {"text": "特別だった", "is_correct": false, "explanation": "過去形は名詞修飾に使えず、この文の説明語としてまとまらない。"}], "correct_form": "特別な", "base_form": "特別", "form_label": "連体形", "sentence_index": 1, "explanations": {"特別な": "正解。名詞「花」を修飾する連体形。", "特別だ": "終止形で、名詞「花」を修飾できない。", "特別で": "て形で、名詞の前には立たない。", "特別だった": "過去形は名詞修飾に使えず、この文の説明語としてまとまらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35122, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今回の旅行は、私にとって特別だ思い出になった。", "corrected_sentence": "今回の旅行は、私にとって特別な思い出になった。", "error_description": "「特別」は形状詞なので、名詞「思い出」の前では「な」にする。「特別だ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "特別な", "is_correct": true, "explanation": "正解。連体形で、後ろの「もの」を修飾している。"}, {"text": "特別ではない", "is_correct": false, "explanation": "否定形で、「特別なもの」の反対の意味になり、祭りの説明と逆になる。"}, {"text": "特別ではなかった", "is_correct": false, "explanation": "過去の否定形で、今の祭りの説明と時制が合わない。"}, {"text": "特別だろう", "is_correct": false, "explanation": "推量形で、断定している文の内容と合わない。"}], "correct_form": "特別な", "base_form": "特別", "form_label": "連体形", "sentence_index": 7, "explanations": {"特別な": "正解。連体形で、後ろの「もの」を修飾している。", "特別ではない": "否定形で、「特別なもの」の反対の意味になり、祭りの説明と逆になる。", "特別ではなかった": "過去の否定形で、今の祭りの説明と時制が合わない。", "特別だろう": "推量形で、断定している文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
