INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35123, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "他と比べて、特にすぐれていたり、変わっていたりするさま。", "primary_collocate": null, "pronunciation": "とくべつ", "ipa": "tokɯbetsɯ", "syllable_count": 4, "sentences": [{"text": "彼は特別な才能があって、五歳でピアノが上手だった。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "彼[かれ]は特別[とくべつ]な才能[さいのう]があって、五歳[ごさい]でピアノが上手[じょうず]だった。", "sentence_source": "generated"}, {"text": "このカレーは、特別な香辛料を使っているので味が違う。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "このカレーは、特別[とくべつ]な香辛料[こうしんりょう]を使[つか]っているので味[あじ]が違[ちが]う。", "sentence_source": "generated"}, {"text": "特別に変わった味ではないが、毎日食べても飽きない。", "target_word": "特別に", "complexity_tier": "T3", "furigana": "特別[とくべつ]に変[か]わった味[あじ]ではないが、毎日[まいにち]食[た]べても飽[あ]きない。", "sentence_source": "generated"}, {"text": "今年の夏は特別に暑くて、外に出られなかった。", "target_word": "特別に", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は特別[とくべつ]に暑[あつ]くて、外[そと]に出[で]られなかった。", "sentence_source": "generated"}, {"text": "あの先生は生徒に特別なやり方で教えている。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "あの先生[せんせい]は生徒[せいと]に特別[とくべつ]なやり方[かた]で教[おし]えている。", "sentence_source": "generated"}, {"text": "彼女の歌声は、他の人と比べて特別だと思う。", "target_word": "特別だ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌声[うたごえ]は、他[ほか]の人[ひと]と比[くら]べて特別[とくべつ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "この店のケーキは特別においしいので、いつも行列ができる。", "target_word": "特別に", "complexity_tier": "T3", "furigana": "この店[みせ]のケーキは特別[とくべつ]においしいので、いつも行列[ぎょうれつ]ができる。", "sentence_source": "generated"}, {"text": "私は犬が特別に好きというわけではありません。", "target_word": "特別に", "complexity_tier": "T3", "furigana": "私[わたし]は犬[いぬ]が特別[とくべつ]に好[す]きというわけではありません。", "sentence_source": "generated"}, {"text": "特別な訓練を受けた犬だけが、この仕事ができる。", "target_word": "特別な", "complexity_tier": "T3", "furigana": "特別[とくべつ]な訓練[くんれん]を受[う]けた犬[いぬ]だけが、この仕事[しごと]ができる。", "sentence_source": "generated"}, {"text": "兄は料理が特別に上手で、プロのようだ。", "target_word": "特別に", "complexity_tier": "T3", "furigana": "兄[あに]は料理[りょうり]が特別[とくべつ]に上手[じょうず]で、プロのようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特別だ", "label": "終止形"}, {"form": "特別な", "label": "連体形"}, {"form": "特別に", "label": "連用形"}, {"form": "特別で", "label": "て形"}, {"form": "特別だった", "label": "過去形"}, {"form": "特別ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "他と比べて特にすぐれている・変わっている程度や性質を表す「特別」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35123, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特別な", "is_correct": true, "explanation": "正解。後ろの「才能」を修飾する連体形。"}, {"text": "特別だ", "is_correct": false, "explanation": "終止形は名詞を直接修飾できず、「才能」に続けられない。"}, {"text": "特別だった", "is_correct": false, "explanation": "過去形は名詞修飾に使えず、「才能があって」の前に置けない。"}, {"text": "特別なら", "is_correct": false, "explanation": "仮定形で、「才能」を修飾する形として成り立たない。"}], "explanations": {"特別な": "正解。後ろの「才能」を修飾する連体形。", "特別だ": "終止形は名詞を直接修飾できず、「才能」に続けられない。", "特別だった": "過去形は名詞修飾に使えず、「才能があって」の前に置けない。", "特別なら": "仮定形で、「才能」を修飾する形として成り立たない。"}, "sentence_index": 0, "correct_answer": "特別な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会員の特別として、無料の入場券がもらえる。", "explanation": "「特別」を名詞の〈特典〉の意味で使う用法は標準的でなく、この文は義項の混同例として適切ではない。"}, {"text": "彼女の特別は、ピアノを弾くことだ。", "explanation": "「特別」を名詞の〈特技〉の意味で使う用法は標準的でなく、この文は義項の混同例として適切ではない。"}, {"text": "この技術は去年、特別を取った。", "explanation": "「特別」を名詞の〈特許〉の意味で使う用法は標準的でなく、この文は義項の混同例として適切ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35123, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特別に", "is_correct": true, "explanation": "正解。後ろの「おいしい」を修飾する副詞。"}, {"text": "特別では", "is_correct": false, "explanation": "「では」は述語を作る形で、「おいしい」を修飾できない。"}, {"text": "特別ではない", "is_correct": false, "explanation": "否定の述語になり、「おいしい」を修飾する副詞として置けない。"}, {"text": "特別だろう", "is_correct": false, "explanation": "推量形で、「おいしい」を修飾できない。"}], "explanations": {"特別に": "正解。後ろの「おいしい」を修飾する副詞。", "特別では": "「では」は述語を作る形で、「おいしい」を修飾できない。", "特別ではない": "否定の述語になり、「おいしい」を修飾する副詞として置けない。", "特別だろう": "推量形で、「おいしい」を修飾できない。"}, "sentence_index": 6, "correct_answer": "特別に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は今週、特別をしていて、ほとんどの商品が安い。", "explanation": "「特別」を名詞の〈特売〉の意味で使う用法は標準的でなく、この文は義項の混同例として適切ではない。"}, {"text": "この鉱石の特別は、軽くて丈夫なことだ。", "explanation": "「特別」を名詞の〈特質〉の意味で使う用法は標準的でなく、この文は義項の混同例として適切ではない。"}, {"text": "この町の特別は、大きな川が流れていることだ。", "explanation": "「特別」を名詞の〈特色〉の意味で使う用法は標準的でなく、この文は義項の混同例として適切ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35123, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部品は、他の品と比べて特別丈夫だ。", "corrected_sentence": "この部品は、他の品と比べて特別に丈夫だ。", "error_description": "「特別」を「丈夫」の前で副詞として使うときは「特別に」が必要。「特別丈夫」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "特別な", "is_correct": true, "explanation": "正解。後ろの「香辛料」を修飾する連体形。"}, {"text": "特別だ", "is_correct": false, "explanation": "終止形で、名詞「香辛料」を修飾できない。"}, {"text": "特別で", "is_correct": false, "explanation": "て形で、名詞の前には立たない。"}, {"text": "特別なら", "is_correct": false, "explanation": "仮定形で、名詞を修飾する形として成り立たない。"}], "correct_form": "特別な", "base_form": "特別", "form_label": "連体形", "sentence_index": 1, "explanations": {"特別な": "正解。後ろの「香辛料」を修飾する連体形。", "特別だ": "終止形で、名詞「香辛料」を修飾できない。", "特別で": "て形で、名詞の前には立たない。", "特別なら": "仮定形で、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35123, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は書道が特別な上手で、賞を取った。", "corrected_sentence": "父は書道が特別に上手で、賞を取った。", "error_description": "「上手」を修飾する「特別」は副詞なので「特別に」にする。「特別な上手」は名詞修飾の形で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "特別に", "is_correct": true, "explanation": "正解。後ろの「好き」を修飾する連用形の副詞。"}, {"text": "特別ではなかった", "is_correct": false, "explanation": "過去の否定形で、「好き」を修飾する副詞として使えない。"}, {"text": "特別ではない", "is_correct": false, "explanation": "否定形は「好き」を修飾する副詞として成り立たず、文の意味とも合わない。"}, {"text": "特別だろう", "is_correct": false, "explanation": "推量形で、「好き」を修飾できない。"}], "correct_form": "特別に", "base_form": "特別", "form_label": "連用形", "sentence_index": 7, "explanations": {"特別に": "正解。後ろの「好き」を修飾する連用形の副詞。", "特別ではなかった": "過去の否定形で、「好き」を修飾する副詞として使えない。", "特別ではない": "否定形は「好き」を修飾する副詞として成り立たず、文の意味とも合わない。", "特別だろう": "推量形で、「好き」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「片づける」の目的語を示す格助詞で、物を片づけると言える。"}, {"text": "に", "is_correct": false, "explanation": "「片づける」は「に」を目的語に取らず、文が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「物が片づける」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同を示す助詞で、「物と片づける」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「片づける」の目的語を示す格助詞で、物を片づけると言える。", "に": "「片づける」は「に」を目的語に取らず、文が通らない。", "が": "主語を示す助詞で、「物が片づける」は不自然。", "と": "共同を示す助詞で、「物と片づける」は意味が通らない。"}, "error_tags": {"に": "方向・場所", "が": "主語", "と": "相手・共同"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "運ばれる対象を示す格助詞で、重い物を運ぶと言える。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞だが、運ばれる対象には使えない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「重い物が運んだ」では物が運ぶ主体になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す助詞で、運ばれる対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "運ばれる対象を示す格助詞で、重い物を運ぶと言える。", "へ": "方向を示す助詞だが、運ばれる対象には使えない。", "が": "主語を示す助詞で、「重い物が運んだ」では物が運ぶ主体になり不自然。", "より": "比較の基準を示す助詞で、運ばれる対象には使えない。"}, "error_tags": {"へ": "方向", "が": "主語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が作ったり、使ったりする、形のあるものです。", "primary_collocate": null, "pronunciation": "もの", "ipa": "mono", "syllable_count": 2, "sentences": [{"text": "机の上の物を片づけてください。", "target_word": "物", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の物[もの]を片[かた]づけてください。", "sentence_source": "generated"}, {"text": "軽い物なら、私が持ちます。", "target_word": "物", "complexity_tier": "T3", "furigana": "軽[かる]い物[もの]なら、私[わたし]が持[も]ちます。", "sentence_source": "generated"}, {"text": "駅で落とした物が見つかりました。", "target_word": "物", "complexity_tier": "T3", "furigana": "駅[えき]で落[お]とした物[もの]が見[み]つかりました。", "sentence_source": "generated"}, {"text": "旅行に持って行く物をかばんに入れた。", "target_word": "物", "complexity_tier": "T3", "furigana": "旅行[りょこう]に持[も]って行[い]く物[もの]をかばんに入[い]れた。", "sentence_source": "generated"}, {"text": "古い物でも、大切に使っています。", "target_word": "物", "complexity_tier": "T3", "furigana": "古[ふる]い物[もの]でも、大切[たいせつ]に使[つか]っています。", "sentence_source": "generated"}, {"text": "あの店には珍しい物がたくさんある。", "target_word": "物", "complexity_tier": "T3", "furigana": "あの店[みせ]には珍[めずら]しい物[もの]がたくさんある。", "sentence_source": "generated"}, {"text": "危ない物には触らないでください。", "target_word": "物", "complexity_tier": "T3", "furigana": "危[あぶ]ない物[もの]には触[さわ]らないでください。", "sentence_source": "generated"}, {"text": "重い物を運んだので、腰が痛い。", "target_word": "物", "complexity_tier": "T3", "furigana": "重[おも]い物[もの]を運[はこ]んだので、腰[こし]が痛[いた]い。", "sentence_source": "generated"}, {"text": "ここにある物は自由に使ってもいいです。", "target_word": "物", "complexity_tier": "T3", "furigana": "ここにある物[もの]は自由[じゆう]に使[つか]ってもいいです。", "sentence_source": "generated"}, {"text": "高い物は買えないので、安い物を探しています。", "target_word": "物", "complexity_tier": "T3", "furigana": "高[たか]い物[もの]は買[か]えないので、安[やす]い物[もの]を探[さが]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "形のある品物・道具としての物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物", "is_correct": true, "explanation": "片づけるべき品物を指し、机の上の文脈に合う。"}, {"text": "時間", "is_correct": false, "explanation": "時間を片づけるのは意味が通らず、文として成立しない。"}, {"text": "機会", "is_correct": false, "explanation": "機会を片づけるのは不自然で、文が通らない。"}, {"text": "意見", "is_correct": false, "explanation": "意見を机の上で片づけるのは意味が通らない。"}], "explanations": {"物": "片づけるべき品物を指し、机の上の文脈に合う。", "時間": "時間を片づけるのは意味が通らず、文として成立しない。", "機会": "機会を片づけるのは不自然で、文が通らない。", "意見": "意見を机の上で片づけるのは意味が通らない。"}, "sentence_index": 0, "correct_answer": "物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で物が意見を述べた。", "explanation": "人には〈人〉〈者〉を使う。ここは〈人〉の意味で、〈物〉は形のあるものを指すので合わない。"}, {"text": "庭で物が鳴いている。", "explanation": "動物には〈動物〉を使う。ここは生き物の意味で、〈物〉は形のあるものを指すので合わない。"}, {"text": "この物は三十分かかる。", "explanation": "所要時間には〈時間〉を使う。ここは時間の意味で、〈物〉は形のあるものを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物", "is_correct": true, "explanation": "危険な品物に触らないという意味に合う。"}, {"text": "理由", "is_correct": false, "explanation": "理由に触るのは意味が通らず、文が成立しない。"}, {"text": "季節", "is_correct": false, "explanation": "季節に触るのは不自然で、文が通らない。"}, {"text": "約束", "is_correct": false, "explanation": "約束に触るのは意味が通らず、文が成立しない。"}], "explanations": {"物": "危険な品物に触らないという意味に合う。", "理由": "理由に触るのは意味が通らず、文が成立しない。", "季節": "季節に触るのは不自然で、文が通らない。", "約束": "約束に触るのは意味が通らず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この説は物が面白い。", "explanation": "考えや説には〈内容〉〈説〉を使う。ここは〈内容〉の意味で、〈物〉は形のあるものを指すので合わない。"}, {"text": "この物は三階建てで、庭も広い。", "explanation": "建物には〈建物〉を使う。〈物〉は個々の品物を指すので、ここは建物の意味にならず合わない。"}, {"text": "この店は物ぞろえが豊富だ。", "explanation": "ここは〈品〉の意味。品物の取りそろえは「品ぞろえ」と言い、「物ぞろえ」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍵のかかった引き出しの中の物に取り出した。", "corrected_sentence": "鍵のかかった引き出しの中の物を取り出した。", "error_description": "「取り出す」の目的語は「を」で示す。「物に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35124, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い物が箱に入れて保管した。", "corrected_sentence": "古い物を箱に入れて保管した。", "error_description": "「保管する」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有る", "is_correct": true, "explanation": "存在するという意味で、「無い」の対義語。"}, {"text": "得る", "is_correct": false, "explanation": "手に入れるという意味の動詞で、対義語ではない。"}, {"text": "残る", "is_correct": false, "explanation": "残存する意味の動詞で、「無い」の対義語ではない。"}, {"text": "増える", "is_correct": false, "explanation": "数量が増える意味の動詞で、対義語ではない。"}], "correct_answer": "有る", "explanations": {"有る": "存在するという意味で、「無い」の対義語。", "得る": "手に入れるという意味の動詞で、対義語ではない。", "残る": "残存する意味の動詞で、「無い」の対義語ではない。", "増える": "数量が増える意味の動詞で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有る", "is_correct": true, "explanation": "存在するという意味で、「無い」の対義語。"}, {"text": "出る", "is_correct": false, "explanation": "外へ現れる意味の動詞で、対義語ではない。"}, {"text": "立つ", "is_correct": false, "explanation": "立ち上がるなどの意味の動詞で、対義語ではない。"}, {"text": "見る", "is_correct": false, "explanation": "視覚の動作を表す動詞で、対義語ではない。"}], "correct_answer": "有る", "explanations": {"有る": "存在するという意味で、「無い」の対義語。", "出る": "外へ現れる意味の動詞で、対義語ではない。", "立つ": "立ち上がるなどの意味の動詞で、対義語ではない。", "見る": "視覚の動作を表す動詞で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物や事がそこに存在しないこと。", "primary_collocate": null, "pronunciation": "ない", "ipa": "nai", "syllable_count": 2, "sentences": [{"text": "冷蔵庫の中には、食べる物が何も無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の中[なか]には、食[た]べる物[もの]が何[なに]も無[な]い。", "sentence_source": "generated"}, {"text": "今日は時間が無いので、急ぎましょう。", "target_word": "無い", "complexity_tier": "T3", "furigana": "今日[きょう]は時間[じかん]が無[な]いので、急[いそ]ぎましょう。", "sentence_source": "generated"}, {"text": "この町には大きい病院が無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "この町[まち]には大[おお]きい病院[びょういん]が無[な]い。", "sentence_source": "generated"}, {"text": "お金が無い時は、家で映画を見ます。", "target_word": "無い", "complexity_tier": "T3", "furigana": "お金[かね]が無[な]い時[とき]は、家[いえ]で映画[えいが]を見[み]ます。", "sentence_source": "generated"}, {"text": "部屋にはテレビも机も無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "部屋[へや]にはテレビも机[つくえ]も無[な]い。", "sentence_source": "generated"}, {"text": "この道には信号が無いから、気をつけて。", "target_word": "無い", "complexity_tier": "T3", "furigana": "この道[みち]には信号[しんごう]が無[な]いから、気[き]をつけて。", "sentence_source": "generated"}, {"text": "約束の時間まで、もう五分しか無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]まで、もう五分[ごふん]しか無[な]い。", "sentence_source": "generated"}, {"text": "辞書が無いと、この本は読めません。", "target_word": "無い", "complexity_tier": "T3", "furigana": "辞書[じしょ]が無[な]いと、この本[ほん]は読[よ]めません。", "sentence_source": "generated"}, {"text": "昨日は宿題が無かったので、早く寝た。", "target_word": "無かった", "complexity_tier": "T3", "furigana": "昨日[きのう]は宿題[しゅくだい]が無[な]かったので、早[はや]く寝[ね]た。", "sentence_source": "generated"}, {"text": "かばんの中を探したが、鍵は無い。", "target_word": "無い", "complexity_tier": "T3", "furigana": "かばんの中[なか]を探[さが]したが、鍵[かぎ]は無[な]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無い", "label": "終止形"}, {"form": "無かった", "label": "過去形"}, {"form": "無くて", "label": "て形"}, {"form": "無ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物や事がそこに存在しない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無い", "is_correct": true, "explanation": "「何も無い」で、食べる物が存在しないという意味に合う。"}, {"text": "高い", "is_correct": false, "explanation": "「何も」と合わず、食べる物の状態として意味が通らない。"}, {"text": "寒い", "is_correct": false, "explanation": "温度を表す語で、食べる物が何も無いという文に合わない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さの語で、存在しないことを表せない。"}], "explanations": {"無い": "「何も無い」で、食べる物が存在しないという意味に合う。", "高い": "「何も」と合わず、食べる物の状態として意味が通らない。", "寒い": "温度を表す語で、食べる物が何も無いという文に合わない。", "軽い": "重さの語で、存在しないことを表せない。"}, "sentence_index": 0, "correct_answer": "無い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "動物園に象が無い。", "explanation": "動物の存在は〈いる〉で表す。ここは〈いない〉の意味で、〈無い〉は物や事の不在に使うので合わない。"}, {"text": "教室に生徒が無い。", "explanation": "ここは〈いない〉の意味。人や動物の存在には「いない」を使い、「無い」は合わない。"}, {"text": "この計画は無いと思う。", "explanation": "実現が難しいという意味では〈無理〉を使う。ここは〈無理〉の意味で、〈無い〉の存在しないという意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無い", "is_correct": true, "explanation": "「しか」と合い、残りが少ないことを表す文に合う。"}, {"text": "多い", "is_correct": false, "explanation": "「しか」と合わず、残りの少なさを言う文が成立しない。"}, {"text": "長い", "is_correct": false, "explanation": "時間の長さを表し、「五分しか」の残り少なさと矛盾する。"}, {"text": "太い", "is_correct": false, "explanation": "太さの語で、時間には対応しない。"}], "explanations": {"無い": "「しか」と合い、残りが少ないことを表す文に合う。", "多い": "「しか」と合わず、残りの少なさを言う文が成立しない。", "長い": "時間の長さを表し、「五分しか」の残り少なさと矛盾する。", "太い": "太さの語で、時間には対応しない。"}, "sentence_index": 6, "correct_answer": "無い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は客が無いので、すぐ閉まった。", "explanation": "人の存在には〈いない〉を使う。ここは〈いない〉の意味で、〈無い〉は合わない。"}, {"text": "この森には鳥が無い。", "explanation": "生き物の存在は〈いる〉で表す。ここは〈いない〉の意味で、〈無い〉は合わない。"}, {"text": "彼女は猫が無い。", "explanation": "動物の存在は〈いる〉で表す。ここは〈いない〉の意味で、〈無い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の前に猫が無い。", "corrected_sentence": "駅の前に猫がいない。", "error_description": "猫のような生き物の存在は「いない」で表す。「無い」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無い", "is_correct": true, "explanation": "終止形で、「時間が無いので」と理由の文に自然に続く。"}, {"text": "無かろう", "is_correct": false, "explanation": "推量形で、「ので」に続けると文が成立せず、理由の文として使えない。"}, {"text": "無ければ", "is_correct": false, "explanation": "仮定形で「もし無ければ」の意味になり、文の意味が変わる。"}, {"text": "無くて", "is_correct": false, "explanation": "て形で、「ので」で理由を示す文には不自然。"}], "correct_form": "無い", "base_form": "無い", "form_label": "終止形", "sentence_index": 1, "explanations": {"無い": "終止形で、「時間が無いので」と理由の文に自然に続く。", "無かろう": "推量形で、「ので」に続けると文が成立せず、理由の文として使えない。", "無ければ": "仮定形で「もし無ければ」の意味になり、文の意味が変わる。", "無くて": "て形で、「ので」で理由を示す文には不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35126, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は予定が無いで、ゆっくりする。", "corrected_sentence": "明日は予定が無いので、ゆっくりする。", "error_description": "理由を示すには「ので」を使う。「無いで」は文が続かず不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無い", "is_correct": true, "explanation": "終止形で、「と」で条件を示す文に続く。"}, {"text": "無く", "is_correct": false, "explanation": "連用形で、文を終わらせる形として不自然。"}, {"text": "無ければ", "is_correct": false, "explanation": "仮定形で「ば」の形になり、「と」に続けると条件の文として成立しない。"}, {"text": "無かったら", "is_correct": false, "explanation": "過去の仮定形で、現在の話と時制が合わない。"}], "correct_form": "無い", "base_form": "無い", "form_label": "終止形", "sentence_index": 7, "explanations": {"無い": "終止形で、「と」で条件を示す文に続く。", "無く": "連用形で、文を終わらせる形として不自然。", "無ければ": "仮定形で「ば」の形になり、「と」に続けると条件の文として成立しない。", "無かったら": "過去の仮定形で、現在の話と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
