INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35128, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの人のこと。", "primary_collocate": null, "pronunciation": "ひとびと", "ipa": "çitobito", "syllable_count": 4, "sentences": [{"text": "駅前の広場には、たくさんの人々が集まっていた。", "target_word": "人々", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]には、たくさんの人々[ひとびと]が集[あつ]まっていた。", "sentence_source": "generated"}, {"text": "町の人々は、新しい橋の完成を喜んだ。", "target_word": "人々", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]は、新[あたら]しい橋[はし]の完成[かんせい]を喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "世界の人々が、同じ空の下で暮らしている。", "target_word": "人々", "complexity_tier": "T3", "furigana": "世界[せかい]の人々[ひとびと]が、同[おな]じ空[そら]の下[した]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "祭りの日は、道の両側に人々が並んで見物した。", "target_word": "人々", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、道[みち]の両側[りょうがわ]に人々[ひとびと]が並[なら]んで見物[けんぶつ]した。", "sentence_source": "generated"}, {"text": "地震のあと、人々は助け合って生活した。", "target_word": "人々", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、人々[ひとびと]は助[たす]け合[あ]って生活[せいかつ]した。", "sentence_source": "generated"}, {"text": "この本は、多くの人々に読まれている。", "target_word": "人々", "complexity_tier": "T3", "furigana": "この本[ほん]は、多[おお]くの人々[ひとびと]に読[よ]まれている。", "sentence_source": "generated"}, {"text": "雨の中でも、人々は傘をさして歩き続けた。", "target_word": "人々", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]でも、人々[ひとびと]は傘[かさ]をさして歩[ある]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "昔の人々は、星を見て季節を知った。", "target_word": "人々", "complexity_tier": "T3", "furigana": "昔[むかし]の人々[ひとびと]は、星[ほし]を見[み]て季節[きせつ]を知[し]った。", "sentence_source": "generated"}, {"text": "外国から来た人々を、町の人が温かく迎えた。", "target_word": "人々", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た人々[ひとびと]を、町[まち]の人[ひと]が温[あたた]かく迎[むか]えた。", "sentence_source": "generated"}, {"text": "大きな音を聞いて、周りの人々が振り向いた。", "target_word": "人々", "complexity_tier": "T3", "furigana": "大[おお]きな音[おと]を聞[き]いて、周[まわ]りの人々[ひとびと]が振[ふ]り向[む]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人々", "label": "基本形"}, {"form": "人々の", "label": "連体形"}, {"form": "人々が", "label": "主格"}], "register": "neutral", "sense_fingerprint": "多くの人の集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35128, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人々", "is_correct": true, "explanation": "「たくさんの」の後に入る、人の集まりを表す名詞。「が集まっていた」の主語として自然に続く。"}, {"text": "人々を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。「集まる」は自動詞なので、「人々を」の後に「が集まっていた」は続かない。"}, {"text": "人々に", "is_correct": false, "explanation": "「に」は集まる場所や相手を示す。主語が立たず、「が集まっていた」と続けられない。"}, {"text": "人々の", "is_correct": false, "explanation": "「の」で終わると名詞修飾のままになり、文の主語がなくなる。"}], "explanations": {"人々": "「たくさんの」の後に入る、人の集まりを表す名詞。「が集まっていた」の主語として自然に続く。", "人々を": "「を」は他動詞の目的語を示す。「集まる」は自動詞なので、「人々を」の後に「が集まっていた」は続かない。", "人々に": "「に」は集まる場所や相手を示す。主語が立たず、「が集まっていた」と続けられない。", "人々の": "「の」で終わると名詞修飾のままになり、文の主語がなくなる。"}, "sentence_index": 0, "correct_answer": "人々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は人々として、誰にも誠実に接する。", "explanation": "ここは〈人として（人間として）〉の意味。人間らしい態度を言うときは「人として」と言い、「人々」は人の集まりを指すので合わない。"}, {"text": "彼は人々がよくて、誰からも好かれている。", "explanation": "ここは〈人がいい〉（人柄が善良だ）の意味。人柄を言うときは「人」を単数で使い、「人々」とは言わない。"}, {"text": "道の向こうに人々が一人立っていた。", "explanation": "「一人」と数えると、多くの人の集まりを表す「人々」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35128, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人々", "is_correct": true, "explanation": "「雨の中でも、」の後に続く、傘をさして歩く主語として自然。"}, {"text": "人々が", "is_correct": false, "explanation": "「が」の後に「は」が続くと格助詞が二重になり、不自然になる。"}, {"text": "人々も", "is_correct": false, "explanation": "「も」の後に「は」は続かないので、主題を示せない。"}, {"text": "人々や", "is_correct": false, "explanation": "「や」は並列を示すが、「や」の後に「は」は続かず、主語として成り立たない。"}], "explanations": {"人々": "「雨の中でも、」の後に続く、傘をさして歩く主語として自然。", "人々が": "「が」の後に「は」が続くと格助詞が二重になり、不自然になる。", "人々も": "「も」の後に「は」は続かないので、主題を示せない。", "人々や": "「や」は並列を示すが、「や」の後に「は」は続かず、主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "人々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店は人々が足りず、朝から大忙しだった。", "explanation": "ここは〈人手〉の意味。「人手が足りない」の「人手」にあたり、人々そのものが不足するとは言わない。"}, {"text": "空には鳥の人々が飛んでいた。", "explanation": "ここは〈群れ〉の意味。鳥の集まりには「群れ」を使い、「人々」は人間の集まりにしか使わない。"}, {"text": "欠員の人々を補うため、求人を出した。", "explanation": "ここは〈人員〉の意味。欠けた職務を補う人員は「人員」や「人手」で表し、「人々」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35128, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園の入り口に人々を並んでいた。", "corrected_sentence": "公園の入り口に人々が並んでいた。", "error_description": "「並ぶ」は自動詞なので、動作の主体には「が」を使う。「人々を」の「を」は誤りで、正しくは「人々が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35128, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人の人々が仲良く話していた。", "corrected_sentence": "二人の人が仲良く話していた。", "error_description": "「人々」は多くの人の集まりを表すので、「二人の」と数えて使うことはできない。個人を数える「人」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「妹のところに届く」の「に」で、届く先を示します。"}, {"text": "を", "is_correct": false, "explanation": "「ところを届く」は届くを他動詞のように扱う誤りです。"}, {"text": "が", "is_correct": false, "explanation": "「ところが届く」では場所が主語になり、文が通りません。"}, {"text": "と", "is_correct": false, "explanation": "「ところと届く」は並列になり、届く先を示せません。"}], "correct_answer": "に", "explanations": {"に": "「妹のところに届く」の「に」で、届く先を示します。", "を": "「ところを届く」は届くを他動詞のように扱う誤りです。", "が": "「ところが届く」では場所が主語になり、文が通りません。", "と": "「ところと届く」は並列になり、届く先を示せません。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、遠くの人のところまで行く。", "primary_collocate": null, "pronunciation": "とどく", "ipa": "todokɯ", "syllable_count": 3, "sentences": [{"text": "遠い国の友だちに、私の手紙が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "とおいくにのともだちに、わたしのてがみがとどく。", "sentence_source": "generated"}, {"text": "海をこえて、プレゼントが妹のところに届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "うみをこえて、プレゼントがいもうとのところにとどく。", "sentence_source": "generated"}, {"text": "離れて住む祖母へ、りんごの箱が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "はなれてすむそぼへ、りんごのはこがとどく。", "sentence_source": "generated"}, {"text": "山の上の小屋にも、郵便が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "やまのうえのこやにも、ゆうびんがとどく。", "sentence_source": "generated"}, {"text": "外国から荷物が届くまで、一週間かかる。", "target_word": "届く", "complexity_tier": "T3", "furigana": "がいこくからにもつがとどくまで、いっしゅうかんかかる。", "sentence_source": "generated"}, {"text": "遠くの町にいる兄から、小包が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "とおくのまちにいるあにから、こづつみがとどく。", "sentence_source": "generated"}, {"text": "この荷物は船で運ぶので、届くまでに二か月かかります。", "target_word": "届く", "complexity_tier": "T3", "furigana": "このにもつはふねではこぶので、とどくまでににかげつかかります。", "sentence_source": "generated"}, {"text": "雪で道が閉ざされ、村に荷物が届くのが遅れた。", "target_word": "届く", "complexity_tier": "T3", "furigana": "ゆきでみちがとざされ、むらににもつがとどくのがおくれた。", "sentence_source": "generated"}, {"text": "北の島に住む友人に、お土産が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "きたのしまにすむゆうじんに、おみやげがとどく。", "sentence_source": "generated"}, {"text": "宇宙にいる飛行士のもとにも、家族からの手紙が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "うちゅうにいるひこうしのもとにも、かぞくからのてがみがとどく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "届く", "label": "辞書形"}, {"form": "届き", "label": "連用形"}, {"form": "届かない", "label": "否定形"}, {"form": "届いた", "label": "過去形"}, {"form": "届いて", "label": "て形"}, {"form": "届けば", "label": "仮定形"}, {"form": "届こう", "label": "意志形"}], "register": "標準（中立）", "sense_fingerprint": "送られたものが離れた相手のところへ着くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "届く", "is_correct": true, "explanation": "「私の手紙が届く」は、遠くの相手に手紙が着く意味で、この文脈に合います。"}, {"text": "眠る", "is_correct": false, "explanation": "手紙は眠らないため、「手紙が眠る」は文として成り立ちません。"}, {"text": "凍る", "is_correct": false, "explanation": "手紙は凍らないため、遠い国の友人に送る文脈と合いません。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "手紙は叫ばないため、この文の述語として成り立ちません。"}], "explanations": {"届く": "「私の手紙が届く」は、遠くの相手に手紙が着く意味で、この文脈に合います。", "眠る": "手紙は眠らないため、「手紙が眠る」は文として成り立ちません。", "凍る": "手紙は凍らないため、遠い国の友人に送る文脈と合いません。", "叫ぶ": "手紙は叫ばないため、この文の述語として成り立ちません。"}, "sentence_index": 0, "correct_answer": "届く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一週間が、あっという間に届く。", "explanation": "ここは〈経つ〉の意味です。届くは物や情報が相手に渡る意味なので、時間の経過には使いません。"}, {"text": "夜行フェリーが朝六時に港に届く。", "explanation": "ここは〈着く〉の意味です。届くは主語が物や情報のときに使い、船の到着には使いません。"}, {"text": "登山者が山頂に届く。", "explanation": "ここは〈登る〉の意味です。届くは物や情報に使い、人が登る場合には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "届く", "is_correct": true, "explanation": "「届くまでに二か月かかる」は、荷物が届くまでの期間を表し、この文脈に合います。"}, {"text": "踊る", "is_correct": false, "explanation": "荷物は踊らないため、「踊るまでに二か月かかる」は文として成り立ちません。"}, {"text": "歌う", "is_correct": false, "explanation": "荷物は歌わないため、船で運ぶ文脈と合いません。"}, {"text": "割る", "is_correct": false, "explanation": "「割るまで」は目的語を欠いた形になり、荷物の輸送の文として成り立ちません。"}], "explanations": {"届く": "「届くまでに二か月かかる」は、荷物が届くまでの期間を表し、この文脈に合います。", "踊る": "荷物は踊らないため、「踊るまでに二か月かかる」は文として成り立ちません。", "歌う": "荷物は歌わないため、船で運ぶ文脈と合いません。", "割る": "「割るまで」は目的語を欠いた形になり、荷物の輸送の文として成り立ちません。"}, "sentence_index": 6, "correct_answer": "届く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小屋は、山の上の村に届く。", "explanation": "ここは〈建つ〉の意味です。届くは物や情報が受け手に渡る意味で、建物には使いません。"}, {"text": "祖母は毎年夏、遠い島に住む親戚のもとに届く。", "explanation": "ここは〈訪ねる〉の意味です。届くは物や情報に使い、人が島の親戚を訪ねる場合には使いません。"}, {"text": "渡り鳥が冬になると南の島に届く。", "explanation": "ここは〈渡る〉の意味です。届くは物や情報に使い、生き物が島へ移動する場合には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遠くの町の友人を、この写真が無事に届いた。", "corrected_sentence": "遠くの町の友人に、この写真が無事に届いた。", "error_description": "「届く」の到達先は「に」で示します。「を」は届く相手には使えないため誤りです。正しくは「友人に」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "届く", "is_correct": true, "explanation": "「プレゼントが届く」の述語として、辞書形で文を終えます。"}, {"text": "届き", "is_correct": false, "explanation": "連用形では文を終えられず、述語になりません。"}, {"text": "届けば", "is_correct": false, "explanation": "仮定形で文を終えると条件文になり、届いた事実を述べられません。"}, {"text": "届こう", "is_correct": false, "explanation": "意志形になると、届けようという意志の文になり、プレゼントの到着とは合いません。"}], "correct_form": "届く", "base_form": "届く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"届く": "「プレゼントが届く」の述語として、辞書形で文を終えます。", "届き": "連用形では文を終えられず、述語になりません。", "届けば": "仮定形で文を終えると条件文になり、届いた事実を述べられません。", "届こう": "意志形になると、届けようという意志の文になり、プレゼントの到着とは合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35130, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "嵐のため、救援物資が届きのが遅れた。", "corrected_sentence": "嵐のため、救援物資が届くのが遅れた。", "error_description": "「届くのが」の形で、名詞句の前には辞書形を使います。連用形の「届き」は誤りで、正しくは「届く」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "届く", "is_correct": true, "explanation": "「届くのが遅れた」の名詞句を作る辞書形で、届くこと自体を表します。"}, {"text": "届かない", "is_correct": false, "explanation": "否定形にすると、届かないことが遅れたという別の意味になります。"}, {"text": "届こう", "is_correct": false, "explanation": "意志形は「のが」に続かず、遅れたという事実を表せません。"}, {"text": "届いて", "is_correct": false, "explanation": "て形は「のが」に続けられず、名詞句を作れません。"}], "correct_form": "届く", "base_form": "届く", "form_label": "辞書形", "sentence_index": 7, "explanations": {"届く": "「届くのが遅れた」の名詞句を作る辞書形で、届くこと自体を表します。", "届かない": "否定形にすると、届かないことが遅れたという別の意味になります。", "届こう": "意志形は「のが」に続かず、遅れたという事実を表せません。", "届いて": "て形は「のが」に続けられず、名詞句を作れません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「までに届く」の「に」で、届く時点の期限を示します。"}, {"text": "が", "is_correct": false, "explanation": "「までが届く」は届く主語の位置に期限が来る形になり、文が通りません。"}, {"text": "を", "is_correct": false, "explanation": "「までを届く」は届くを他動詞のように扱う誤りです。"}, {"text": "で", "is_correct": false, "explanation": "「までで届く」は手段や場所を表す形になり、時点を示す文脈に合いません。"}], "correct_answer": "に", "explanations": {"に": "「までに届く」の「に」で、届く時点の期限を示します。", "が": "「までが届く」は届く主語の位置に期限が来る形になり、文が通りません。", "を": "「までを届く」は届くを他動詞のように扱う誤りです。", "で": "「までで届く」は手段や場所を表す形になり、時点を示す文脈に合いません。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「カードが届く」の「が」で、届く物の主語を示します。"}, {"text": "を", "is_correct": false, "explanation": "「カードを届く」は届くを他動詞のように扱う誤りです。"}, {"text": "で", "is_correct": false, "explanation": "「カードで届く」は手段の意味になり、届く主語を示す場面に合いません。"}, {"text": "と", "is_correct": false, "explanation": "「カードと届く」は並列の形になり、届く主語にはなりません。"}], "correct_answer": "が", "explanations": {"が": "「カードが届く」の「が」で、届く物の主語を示します。", "を": "「カードを届く」は届くを他動詞のように扱う誤りです。", "で": "「カードで届く」は手段の意味になり、届く主語を示す場面に合いません。", "と": "「カードと届く」は並列の形になり、届く主語にはなりません。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や情報が、ある場所や人のもとへ到達する。", "primary_collocate": null, "pronunciation": "とどく", "ipa": "todokɯ", "syllable_count": 3, "sentences": [{"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "届く", "complexity_tier": "T5", "furigana": "このあこがれのかんじょうは、やがてグローバルなたいしゅうむけブランドによってこうみょうにそしゃくされ、だれもがてがとどくかかくたいへとしょうかされるのだ。", "sentence_source": "mined"}, {"text": "注文した荷物は、明日の午後までに届く予定です。", "target_word": "届く", "complexity_tier": "T3", "furigana": "ちゅうもんしたにもつは、あしたのごごまでにとどくよていです。", "sentence_source": "generated"}, {"text": "手紙が相手に届く前に、住所をもう一度確認した。", "target_word": "届く", "complexity_tier": "T3", "furigana": "てがみがあいてにとどくまえに、じゅうしょをもういちどかくにんした。", "sentence_source": "generated"}, {"text": "災害のニュースは、数分で全国の人に届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "さいがいのニュースは、すうふんでぜんこくのひとにとどく。", "sentence_source": "generated"}, {"text": "母からのメールが、夜遅くに届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "はははからのメールが、よるおそくにとどく。", "sentence_source": "generated"}, {"text": "荷物が届く日は、一日中家にいることにしている。", "target_word": "届く", "complexity_tier": "T3", "furigana": "にもつがとどくひは、いちにちじゅういえにいることにしている。", "sentence_source": "generated"}, {"text": "小さな島にも、毎週船で食料が届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "ちいさなしまにも、まいしゅうふねでしょくりょうがとどく。", "sentence_source": "generated"}, {"text": "祖父に誕生日のカードが届く頃、私は旅行に出ていた。", "target_word": "届く", "complexity_tier": "T3", "furigana": "そふにたんじょうびのカードがとどくころ、わたしはりょこうにでていた。", "sentence_source": "generated"}, {"text": "雨で道が塞がれ、荷物が予定通りに届く見込みはない。", "target_word": "届く", "complexity_tier": "T3", "furigana": "あめでみちがふさがれ、にもつがよていどおりにとどくみこみはない。", "sentence_source": "generated"}, {"text": "山奥の村にも、新聞が毎朝届く。", "target_word": "届く", "complexity_tier": "T3", "furigana": "やまおくのむらにも、しんぶんがまいあさとどく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "届く", "label": "辞書形"}, {"form": "届き", "label": "連用形"}, {"form": "届かない", "label": "否定形"}, {"form": "届いた", "label": "過去形"}, {"form": "届いて", "label": "て形"}, {"form": "届けば", "label": "仮定形"}, {"form": "届こう", "label": "意志形"}], "register": "標準（中立）", "sense_fingerprint": "荷物・手紙・知らせなどが相手や目的地に着くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "届く", "is_correct": true, "explanation": "「ガラスの置物が届く」は、品物が遠くから相手のもとへ着く意味で、この文脈に合います。"}, {"text": "凍る", "is_correct": false, "explanation": "置物が凍るという意味になり、遠くから届く文脈と合いません。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "置物は叫ばないため、この文の述語として成り立ちません。"}, {"text": "割る", "is_correct": false, "explanation": "「割る」は目的語を取る他動詞なので、「置物が割る」とは言えません。"}], "explanations": {"届く": "「ガラスの置物が届く」は、品物が遠くから相手のもとへ着く意味で、この文脈に合います。", "凍る": "置物が凍るという意味になり、遠くから届く文脈と合いません。", "叫ぶ": "置物は叫ばないため、この文の述語として成り立ちません。", "割る": "「割る」は目的語を取る他動詞なので、「置物が割る」とは言えません。"}, "sentence_index": 0, "correct_answer": "届く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜行列車が朝六時に終点の駅に届く。", "explanation": "ここは〈着く〉の意味です。届くは物や情報が受け手のもとに渡る意味なので、列車の到着には使いません。"}, {"text": "父は明日の朝、空港に届く。", "explanation": "ここは〈着く〉の意味です。届くは物や情報が受け手のもとへ渡る意味なので、人が空港に着く場合には使いません。"}, {"text": "私は来年の春、東京の大学に届く。", "explanation": "ここは〈入学する〉の意味です。届くは人が学校に入る場合には使わず、物や情報が渡るときに使います。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "届く", "is_correct": true, "explanation": "「船で食料が届く」は、物資が島へ着くという意味で、この文脈に合います。"}, {"text": "眠る", "is_correct": false, "explanation": "食料は眠らないため、「食料が眠る」は文として成り立ちません。"}, {"text": "泣く", "is_correct": false, "explanation": "食料は泣かないため、「食料が泣く」は文として成り立ちません。"}, {"text": "吠える", "is_correct": false, "explanation": "「吠える」は犬などの動物が声を出す語で、食料には使えないため文が成り立ちません。"}], "explanations": {"届く": "「船で食料が届く」は、物資が島へ着くという意味で、この文脈に合います。", "眠る": "食料は眠らないため、「食料が眠る」は文として成り立ちません。", "泣く": "食料は泣かないため、「食料が泣く」は文として成り立ちません。", "吠える": "「吠える」は犬などの動物が声を出す語で、食料には使えないため文が成り立ちません。"}, "sentence_index": 6, "correct_answer": "届く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は毎年夏、山奥の村に届く。", "explanation": "ここは〈訪れる〉の意味です。届くは物や情報に使い、人が村を訪れる場合には使いません。"}, {"text": "夜行バスが朝六時に、山奥の村に届く。", "explanation": "ここは〈到着する〉の意味です。届くは主語が物や情報のときに使い、乗り物の到着には使いません。"}, {"text": "記者が取材のため、山奥の村に届く。", "explanation": "ここは〈行く〉の意味です。届くは物や情報に使い、人が出向く場合には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この手紙は、三日後に彼女のもとを届く予定だ。", "corrected_sentence": "この手紙は、三日後に彼女のもとへ届く予定だ。", "error_description": "「届く」の到達先は「へ」（または「に」）で示します。「を」は届くの相手を表せないため誤りです。正しくは「もとへ」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "届く", "is_correct": true, "explanation": "「予定です」に続く辞書形で、これから届くという未来の予定を表します。"}, {"text": "届いた", "is_correct": false, "explanation": "過去形だと、これから届く予定という意味と矛盾します。"}, {"text": "届かない", "is_correct": false, "explanation": "否定形だと、届かない予定という意味になり、文の内容が変わります。"}, {"text": "届き", "is_correct": false, "explanation": "連用形では文を終えられず、「予定です」に続きません。"}], "correct_form": "届く", "base_form": "届く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"届く": "「予定です」に続く辞書形で、これから届くという未来の予定を表します。", "届いた": "過去形だと、これから届く予定という意味と矛盾します。", "届かない": "否定形だと、届かない予定という意味になり、文の内容が変わります。", "届き": "連用形では文を終えられず、「予定です」に続きません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35131, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪のため、荷物は三日遅れて村を届いた。", "corrected_sentence": "雪のため、荷物は三日遅れて村に届いた。", "error_description": "「届く」の到達先は「に」で示します。「を」は届くの相手を表せないため誤りです。正しくは「村に」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "届く", "is_correct": true, "explanation": "「頃」の前に置く辞書形で、カードが届く時を表します。"}, {"text": "届き", "is_correct": false, "explanation": "連用形は「頃」に続けられず、時を表す文になりません。"}, {"text": "届こう", "is_correct": false, "explanation": "意志形は「頃」の前に置くと意味が通らず、時の表現になりません。"}, {"text": "届けば", "is_correct": false, "explanation": "仮定形は「頃」に続けられず、時を表す文になりません。"}], "correct_form": "届く", "base_form": "届く", "form_label": "辞書形", "sentence_index": 7, "explanations": {"届く": "「頃」の前に置く辞書形で、カードが届く時を表します。", "届き": "連用形は「頃」に続けられず、時を表す文になりません。", "届こう": "意志形は「頃」の前に置くと意味が通らず、時の表現になりません。", "届けば": "仮定形は「頃」に続けられず、時を表す文になりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
