INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35134, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "つれて行く", "primary_collocate": null, "pronunciation": "つれる", "ipa": "tsɯɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "日曜日に、子どもを公園へ連れて行きます。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、子[こ]どもを公園[こうえん]へ連[つ]れて行[い]きます。", "sentence_source": "generated"}, {"text": "友だちを家に連れて来てもいいですか。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "友[とも]だちを家[いえ]に連[つ]れて来[き]てもいいですか。", "sentence_source": "generated"}, {"text": "妹は犬を連れて散歩に出かけた。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "妹[いもうと]は犬[いぬ]を連[つ]れて散歩[さんぽ]に出[で]かけた。", "sentence_source": "generated"}, {"text": "父は私を海へ連れて行ってくれた。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "父[ちち]は私[わたし]を海[うみ]へ連[つ]れて行[い]ってくれた。", "sentence_source": "generated"}, {"text": "初めての町なので、案内してくれる人を連れて行った。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "初[はじ]めての町[まち]なので、案内[あんない]してくれる人[ひと]を連[つ]れて行[い]った。", "sentence_source": "generated"}, {"text": "病気の猫を病院に連れて行かなければならない。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "病気[びょうき]の猫[ねこ]を病院[びょういん]に連[つ]れて行[い]かなければならない。", "sentence_source": "generated"}, {"text": "彼は恋人を連れて、パーティーに来た。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "彼[かれ]は恋人[こいびと]を連[つ]れて、パーティーに来[き]た。", "sentence_source": "generated"}, {"text": "明日は弟を連れて、動物園に行く予定です。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "明日[あした]は弟[おとうと]を連[つ]れて、動物園[どうぶつえん]に行[い]く予定[よてい]です。", "sentence_source": "generated"}, {"text": "母は小さい子を連れて買い物に出た。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "母[はは]は小[ちい]さい子[こ]を連[つ]れて買[か]い物[もの]に出[で]た。", "sentence_source": "generated"}, {"text": "留学生を日本料理の店に連れて行った。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]を日本[にほん]料理[りょうり]の店[みせ]に連[つ]れて行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連れる", "label": "終止形"}, {"form": "連れて", "label": "て形"}, {"form": "連れた", "label": "た形"}, {"form": "連れない", "label": "ない形"}, {"form": "連れます", "label": "ます形"}], "register": "neutral", "sense_fingerprint": "人や動物を伴って目的地へ行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35134, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「〜て行きます」につながるて形で、人や動物を伴って目的地へ行くことを表す。"}, {"text": "連れた", "is_correct": false, "explanation": "た形は文を終えてしまうので、後ろの「行きます」と続かない。"}, {"text": "連れない", "is_correct": false, "explanation": "否定形では「行きます」につながらず、文の流れが成り立たない。"}, {"text": "連れます", "is_correct": false, "explanation": "ます形は文末に使うので、後ろの「行きます」と続けられない。"}], "explanations": {"連れて": "「〜て行きます」につながるて形で、人や動物を伴って目的地へ行くことを表す。", "連れた": "た形は文を終えてしまうので、後ろの「行きます」と続かない。", "連れない": "否定形では「行きます」につながらず、文の流れが成り立たない。", "連れます": "ます形は文末に使うので、後ろの「行きます」と続けられない。"}, "sentence_index": 0, "correct_answer": "連れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は荷物を連れて海へ行ってくれた。", "explanation": "ここは〈持つ〉の意味。「連れる」は人や動物に使い、荷物には使わない。"}, {"text": "父は車を連れて海へ行ってくれた。", "explanation": "ここは〈引く〉の意味。車は引いて動かすもので、一緒に連れて行く相手ではない。"}, {"text": "父は海で大きな魚を連れて帰ってくれた。", "explanation": "ここは〈釣る〉の意味。魚は釣るものであり、一緒に伴う相手ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35134, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「、パーティーに来た」へ続くて形で、恋人を伴って来たことを表す。"}, {"text": "連れる", "is_correct": false, "explanation": "終止形で文が切れてしまい、後ろの「パーティーに来た」と続かない。"}, {"text": "連れられ", "is_correct": false, "explanation": "受身の連用形で、伴う相手は「に」で示すため、「恋人を」とは合わない。"}, {"text": "連れよう", "is_correct": false, "explanation": "意志形は文の流れに合わず、「パーティーに来た」と続かない。"}], "explanations": {"連れて": "「、パーティーに来た」へ続くて形で、恋人を伴って来たことを表す。", "連れる": "終止形で文が切れてしまい、後ろの「パーティーに来た」と続かない。", "連れられ": "受身の連用形で、伴う相手は「に」で示すため、「恋人を」とは合わない。", "連れよう": "意志形は文の流れに合わず、「パーティーに来た」と続かない。"}, "sentence_index": 6, "correct_answer": "連れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は重い機材を連れて店へ行った。", "explanation": "ここは〈運ぶ〉の意味。機材は運ぶものであり、「連れる」とは言わない。"}, {"text": "私はベビーカーを連れて店へ行った。", "explanation": "ここは〈押す〉の意味。ベビーカーは押すもので、一緒に連れて行く相手ではない。"}, {"text": "配達の人が郵便物を連れて来た。", "explanation": "ここは〈届ける〉の意味。郵便物は届けるもので、連れて来る相手ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35134, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は犬と連れて公園を散歩した。", "corrected_sentence": "父は犬を連れて公園を散歩した。", "error_description": "「連れる」で伴う相手は「を」で示す。「犬と連れて」の「と」は誤りで、正しくは「犬を連れて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「〜て来てもいいですか」につながるて形。"}, {"text": "連れた", "is_correct": false, "explanation": "た形は過去を表すので、「来てもいい」の前には入らない。"}, {"text": "連れない", "is_correct": false, "explanation": "否定形は「来てもいい」の前に入らず、文が成り立たない。"}, {"text": "連れます", "is_correct": false, "explanation": "ます形は丁寧な文末形なので、後ろの「来て」とつながらない。"}], "correct_form": "連れて", "base_form": "連れる", "form_label": "て形", "sentence_index": 1, "explanations": {"連れて": "「〜て来てもいいですか」につながるて形。", "連れた": "た形は過去を表すので、「来てもいい」の前には入らない。", "連れない": "否定形は「来てもいい」の前に入らず、文が成り立たない。", "連れます": "ます形は丁寧な文末形なので、後ろの「来て」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35134, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は孫を連れた、公園を歩いた。", "corrected_sentence": "祖母は孫を連れて、公園を歩いた。", "error_description": "「連れた」は過去形で文を切ってしまう。並べて続ける文では「連れて」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「、動物園に行く」へ続くて形。"}, {"text": "連れる", "is_correct": false, "explanation": "終止形は「、」の前に続かず、文の流れが成り立たない。"}, {"text": "連れよう", "is_correct": false, "explanation": "意志形は「、動物園に行く」へ続けられない。"}, {"text": "連れられ", "is_correct": false, "explanation": "受身の連用形で、伴う相手は「に」で示すため「弟を」とは合わない。"}], "correct_form": "連れて", "base_form": "連れる", "form_label": "て形", "sentence_index": 7, "explanations": {"連れて": "「、動物園に行く」へ続くて形。", "連れる": "終止形は「、」の前に続かず、文の流れが成り立たない。", "連れよう": "意志形は「、動物園に行く」へ続けられない。", "連れられ": "受身の連用形で、伴う相手は「に」で示すため「弟を」とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
