INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35135, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や動物を一緒に連れて行くこと", "primary_collocate": null, "pronunciation": "つれる", "ipa": "tsɯɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "母は赤ちゃんを連れて、電車に乗った。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "母[はは]は赤[あか]ちゃんを連[つ]れて、電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}, {"text": "先生は生徒を連れて、博物館を見学した。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]を連[つ]れて、博物館[はくぶつかん]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "犬を連れて行ける公園を探している。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "犬[いぬ]を連[つ]れて行[い]ける公園[こうえん]を探[さが]している。", "sentence_source": "generated"}, {"text": "おじいさんは孫を連れて、川へ魚を釣りに行った。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "おじいさんは孫[まご]を連[つ]れて、川[かわ]へ魚[さかな]を釣[つ]りに行[い]った。", "sentence_source": "generated"}, {"text": "子どもを連れて旅行するときは、荷物が多くなる。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "子[こ]どもを連[つ]れて旅行[りょこう]するときは、荷物[にもつ]が多[おお]くなる。", "sentence_source": "generated"}, {"text": "彼女は大きな犬を連れて、毎朝走っている。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大[おお]きな犬[いぬ]を連[つ]れて、毎朝[まいあさ]走[はし]っている。", "sentence_source": "generated"}, {"text": "兄は新しい友人を連れて帰ってきた。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "兄[あに]は新[あたら]しい友人[ゆうじん]を連[つ]れて帰[かえ]ってきた。", "sentence_source": "generated"}, {"text": "ガイドは観光客を連れて、山の上まで歩いて登った。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "ガイドは観光客[かんこうきゃく]を連[つ]れて、山[やま]の上[うえ]まで歩[ある]いて登[のぼ]った。", "sentence_source": "generated"}, {"text": "休みの日は、家族を連れて祖父母の家へ行く。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、家族[かぞく]を連[つ]れて祖父母[そふぼ]の家[いえ]へ行[い]く。", "sentence_source": "generated"}, {"text": "友だちを連れて来たら、母がお茶を出してくれた。", "target_word": "連れて", "complexity_tier": "T3", "furigana": "友[とも]だちを連[つ]れて来[き]たら、母[はは]がお茶[ちゃ]を出[だ]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連れる", "label": "終止形"}, {"form": "連れて", "label": "て形"}, {"form": "連れた", "label": "た形"}, {"form": "連れない", "label": "ない形"}, {"form": "連れます", "label": "ます形"}], "register": "neutral", "sense_fingerprint": "人や動物を一緒に伴って行動する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「、電車に乗った」へ続くて形で、赤ちゃんを伴って乗ったことを表す。"}, {"text": "連れた", "is_correct": false, "explanation": "た形は文を終えてしまい、後ろの「電車に乗った」と続かない。"}, {"text": "連れない", "is_correct": false, "explanation": "否定形は「電車に乗った」へ続けられず、文が成り立たない。"}, {"text": "連れます", "is_correct": false, "explanation": "ます形は文末に使うので、後ろの「電車に乗った」と続かない。"}], "explanations": {"連れて": "「、電車に乗った」へ続くて形で、赤ちゃんを伴って乗ったことを表す。", "連れた": "た形は文を終えてしまい、後ろの「電車に乗った」と続かない。", "連れない": "否定形は「電車に乗った」へ続けられず、文が成り立たない。", "連れます": "ます形は文末に使うので、後ろの「電車に乗った」と続かない。"}, "sentence_index": 0, "correct_answer": "連れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "おじいさんは釣り竿を連れて、川へ魚を釣りに行った。", "explanation": "ここは〈持つ〉の意味。釣り竿は持って運ぶもので、人や動物のように連れるとは言わない。"}, {"text": "おじいさんは川で魚を連れて帰った。", "explanation": "ここは〈釣る〉の意味。魚は釣るものであり、一緒に伴う相手ではない。"}, {"text": "おじいさんは船を連れて、川へ魚を釣りに行った。", "explanation": "ここは〈引く〉の意味。船は引いて動かすもので、連れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「帰ってきた」へ続くて形で、友人を伴って戻ったことを表す。"}, {"text": "連れる", "is_correct": false, "explanation": "終止形で文が切れてしまい、後ろの「帰ってきた」と続かない。"}, {"text": "連れられ", "is_correct": false, "explanation": "受身の連用形で、伴う相手は「に」で示すため、「友人を」とは合わない。"}, {"text": "連れよう", "is_correct": false, "explanation": "意志形は文の流れに合わず、「帰ってきた」と続かない。"}], "explanations": {"連れて": "「帰ってきた」へ続くて形で、友人を伴って戻ったことを表す。", "連れる": "終止形で文が切れてしまい、後ろの「帰ってきた」と続かない。", "連れられ": "受身の連用形で、伴う相手は「に」で示すため、「友人を」とは合わない。", "連れよう": "意志形は文の流れに合わず、「帰ってきた」と続かない。"}, "sentence_index": 6, "correct_answer": "連れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "注文の品を連れて来たら、母がお茶を出してくれた。", "explanation": "ここは〈届ける〉の意味。注文の品は届けるもので、連れて来る相手ではない。"}, {"text": "料理を連れて来たら、母がお茶を出してくれた。", "explanation": "ここは〈作る〉の意味。料理は作るもので、一緒に連れて来る相手ではない。"}, {"text": "お菓子を連れて来たら、母がお茶を出してくれた。", "explanation": "ここは〈買う〉の意味。お菓子は買うもので、連れて来る相手ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35135, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は孫に連れて、公園へ行った。", "corrected_sentence": "祖母は孫を連れて、公園へ行った。", "error_description": "「連れる」で伴う相手は「を」で示す。「孫に」の「に」は誤りで、正しくは「孫を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "連れて", "is_correct": true, "explanation": "て形で、後ろの「見学した」へ続けられる。"}, {"text": "連れた", "is_correct": false, "explanation": "た形は文を終えてしまい、後ろの「見学した」と続かない。"}, {"text": "連れない", "is_correct": false, "explanation": "否定形は「見学した」へ続けられず、文が成り立たない。"}, {"text": "連れます", "is_correct": false, "explanation": "ます形は文末に使うので、後ろの「見学した」と続かない。"}], "correct_form": "連れて", "base_form": "連れる", "form_label": "て形", "sentence_index": 1, "explanations": {"連れて": "て形で、後ろの「見学した」へ続けられる。", "連れた": "た形は文を終えてしまい、後ろの「見学した」と続かない。", "連れない": "否定形は「見学した」へ続けられず、文が成り立たない。", "連れます": "ます形は文末に使うので、後ろの「見学した」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35135, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は小さな妹を連れた、買い物に出た。", "corrected_sentence": "姉は小さな妹を連れて、買い物に出た。", "error_description": "「連れた」は過去形で文を切ってしまう。並べて続ける文では「連れて」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "連れて", "is_correct": true, "explanation": "「、山の上まで歩いて登った」へ続くて形。"}, {"text": "連れる", "is_correct": false, "explanation": "終止形は「、」の前に続かず、文の流れが成り立たない。"}, {"text": "連れよう", "is_correct": false, "explanation": "意志形は後ろの「山の上まで歩いて登った」と続けられない。"}, {"text": "連れられ", "is_correct": false, "explanation": "受身の連用形で、伴う相手は「に」で示すため「観光客を」とは合わない。"}], "correct_form": "連れて", "base_form": "連れる", "form_label": "て形", "sentence_index": 7, "explanations": {"連れて": "「、山の上まで歩いて登った」へ続くて形。", "連れる": "終止形は「、」の前に続かず、文の流れが成り立たない。", "連れよう": "意志形は後ろの「山の上まで歩いて登った」と続けられない。", "連れられ": "受身の連用形で、伴う相手は「に」で示すため「観光客を」とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知識」は「学んでおいた」の目的語になるので、「を」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「学んでおいた」の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、ここでは「学んでおいた」の対象として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「学んでおいた」の動作主は人なので、「知識が」は主語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「知識」は「学んでおいた」の目的語になるので、「を」で示す。", "へ": "「へ」は方向を示すが、「学んでおいた」の対象にはならない。", "と": "「と」は並列や相手を示すが、ここでは「学んでおいた」の対象として成り立たない。", "が": "「学んでおいた」の動作主は人なので、「知識が」は主語として成り立たない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "が": "主語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無知", "is_correct": true, "explanation": "「知識」の対義語で、知らないこと・知識がないことを表す。"}, {"text": "記憶", "is_correct": false, "explanation": "覚えておく働きを表し、知識の反対語ではない。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを表し、知識とは反対の関係にない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表し、知識とは反対の関係にない。"}], "correct_answer": "無知", "explanations": {"無知": "「知識」の対義語で、知らないこと・知識がないことを表す。", "記憶": "覚えておく働きを表し、知識の反対語ではない。", "感情": "心の動きを表し、知識とは反対の関係にない。", "天気": "空模様を表し、知識とは反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知識」は「生かしたい」の目的語になるので、「を」で示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、後ろに動詞が続かず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「生かしたい」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示すが、「生かす」は「を」で目的語を取るので合わない。"}], "correct_answer": "を", "explanations": {"を": "「知識」は「生かしたい」の目的語になるので、「を」で示す。", "の": "「の」は名詞をつなぐ助詞で、後ろに動詞が続かず文が成り立たない。", "から": "「から」は起点を示し、「生かしたい」の目的語にはならない。", "に": "「に」は方向や対象を示すが、「生かす」は「を」で目的語を取るので合わない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "に": "方向・対象"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無知", "is_correct": true, "explanation": "「知識」の対義語で、知らないこと・知識がないことを表す。"}, {"text": "感想", "is_correct": false, "explanation": "受け取った印象を表し、知識の反対語ではない。"}, {"text": "友情", "is_correct": false, "explanation": "友人との間の情を表し、知識とは反対の関係にない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表し、知識とは反対の関係にない。"}], "correct_answer": "無知", "explanations": {"無知": "「知識」の対義語で、知らないこと・知識がないことを表す。", "感想": "受け取った印象を表し、知識の反対語ではない。", "友情": "友人との間の情を表し、知識とは反対の関係にない。", "機械": "装置を表し、知識とは反対の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを知っていること。知っていることがら。", "primary_collocate": null, "pronunciation": "ちしき", "ipa": "tɕiɕiki", "syllable_count": 3, "sentences": [{"text": "彼は鳥について、とても深い知識を持っている。", "target_word": "知識", "complexity_tier": "T3", "furigana": "彼[かれ]は鳥[とり]について、とても深[ふか]い知識[ちしき]を持[も]っている。", "sentence_source": "generated"}, {"text": "旅行の前に、その国の知識を少し学んでおいた。", "target_word": "知識", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、その国[くに]の知識[ちしき]を少[すこ]し学[まな]んでおいた。", "sentence_source": "generated"}, {"text": "本を読むと、新しい知識が増える。", "target_word": "知識", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]むと、新[あたら]しい知識[ちしき]が増[ふ]える。", "sentence_source": "generated"}, {"text": "料理の知識がないので、レシピを見ながら作る。", "target_word": "知識", "complexity_tier": "T3", "furigana": "料理[りょうり]の知識[ちしき]がないので、レシピを見[み]ながら作[つく]る。", "sentence_source": "generated"}, {"text": "医者は病気について広い知識が必要だ。", "target_word": "知識", "complexity_tier": "T3", "furigana": "医者[いしゃ]は病気[びょうき]について広[ひろ]い知識[ちしき]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "インターネットで得た知識だけでは、不安です。", "target_word": "知識", "complexity_tier": "T3", "furigana": "インターネットで得[え]た知識[ちしき]だけでは、不安[ふあん]です。", "sentence_source": "generated"}, {"text": "祖父は植物の知識が豊富で、花の名前を何でも教えてくれる。", "target_word": "知識", "complexity_tier": "T3", "furigana": "祖父[そふ]は植物[しょくぶつ]の知識[ちしき]が豊富[ほうふ]で、花[はな]の名前[なまえ]を何[なん]でも教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "学校で学んだ知識を、仕事で生かしたい。", "target_word": "知識", "complexity_tier": "T3", "furigana": "学校[がっこう]で学[まな]んだ知識[ちしき]を、仕事[しごと]で生[い]かしたい。", "sentence_source": "generated"}, {"text": "防災の知識があったので、落ち着いて行動できた。", "target_word": "知識", "complexity_tier": "T3", "furigana": "防災[ぼうさい]の知識[ちしき]があったので、落[お]ち着[つ]いて行動[こうどう]できた。", "sentence_source": "generated"}, {"text": "この知識は、先生に聞いて初めて身についた。", "target_word": "知識", "complexity_tier": "T3", "furigana": "この知識[ちしき]は、先生[せんせい]に聞[き]いて初[はじ]めて身[み]についた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知識", "label": "基本形"}, {"form": "知識の", "label": "連体形"}, {"form": "知識が", "label": "主格"}], "register": "neutral", "sense_fingerprint": "学んだり経験したりして得た知っている事柄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b718e997-b651-45e6-a707-e173179bd3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知識", "is_correct": true, "explanation": "「深い」に続く名詞で、「を持っている」の目的語として自然に続く。"}, {"text": "知識が", "is_correct": false, "explanation": "「が」を付けると後ろの「を」と重なり、「持っている」の目的語にならない。"}, {"text": "知識の", "is_correct": false, "explanation": "「の」で続くと名詞修飾のままになり、後ろの「を持っている」が宙に浮く。"}, {"text": "知識に", "is_correct": false, "explanation": "「に」は「持っている」の目的語にならず、後ろの「を」と二重になる。"}], "explanations": {"知識": "「深い」に続く名詞で、「を持っている」の目的語として自然に続く。", "知識が": "「が」を付けると後ろの「を」と重なり、「持っている」の目的語にならない。", "知識の": "「の」で続くと名詞修飾のままになり、後ろの「を持っている」が宙に浮く。", "知識に": "「に」は「持っている」の目的語にならず、後ろの「を」と二重になる。"}, "sentence_index": 0, "correct_answer": "知識"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この職人は知識が高く、木材を正確に切る。", "explanation": "ここは〈技術〉（腕前）の意味。知識は知っている内容を指し、腕前の高さを「知識が高い」とは言わない。"}, {"text": "この料理人は味の知識が鋭い。", "explanation": "ここは〈感覚〉の意味。味の鋭さは感覚で言うもので、知っている内容の知識は鋭いとは言わない。"}, {"text": "知識で窓を拭いた。", "explanation": "ここは道具の意味。窓を拭くのは雑巾などの道具で、知識は道具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知識", "is_correct": true, "explanation": "「植物の」に続き、「が豊富で」の主語になる。"}, {"text": "知識を", "is_correct": false, "explanation": "「を」は「豊富で」の主語にならず、「豊富で」と続かない。"}, {"text": "知識や", "is_correct": false, "explanation": "「や」は並列を示すが、「豊富で」の主語としては成り立たない。"}, {"text": "知識へ", "is_correct": false, "explanation": "「へ」は方向を示し、「豊富で」と続かない。"}], "explanations": {"知識": "「植物の」に続き、「が豊富で」の主語になる。", "知識を": "「を」は「豊富で」の主語にならず、「豊富で」と続かない。", "知識や": "「や」は並列を示すが、「豊富で」の主語としては成り立たない。", "知識へ": "「へ」は方向を示し、「豊富で」と続かない。"}, "sentence_index": 6, "correct_answer": "知識"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は知識を込めて歌った。", "explanation": "ここは〈感情〉の意味。歌に込めるのは感情であり、知識ではない。"}, {"text": "彼は私の知識で、昔からの友人だ。", "explanation": "ここは〈知人〉の意味。人を指す語なので、「知識」は人の代わりに使えない。"}, {"text": "週末、知識と旅行した。", "explanation": "ここは〈友人〉の意味。旅行の相手は人であり、知識は旅行の相手にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は英語の知識を豊富で、外国の本を読める。", "corrected_sentence": "彼女は英語の知識が豊富で、外国の本を読める。", "error_description": "「豊富」は「が」で主語を示す。「知識を」の「を」は誤りで、正しくは「知識が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の知識を、家族のために着たい。", "corrected_sentence": "祖母の知識を、家族のために生かしたい。", "error_description": "「知識」には「生かす」が合う。「着たい」は誤りで、正しい動詞は「生かしたい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75b4dd7c-847c-4450-a85b-78f6156f9818') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「私が生まれた町は」と、町について「海のそばにある」と述べる主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "町を目的語にすると「町を、海のそばにあります」となり、「ある」の主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、町が存在する場所を示す文の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "動作の場所を表す「で」は「ある」とは合わず、文が不自然になる。"}], "correct_answer": "は", "explanations": {"は": "「私が生まれた町は」と、町について「海のそばにある」と述べる主題を示す。", "を": "町を目的語にすると「町を、海のそばにあります」となり、「ある」の主語として成り立たない。", "へ": "方向を表すので、町が存在する場所を示す文の主語にはならない。", "で": "動作の場所を表す「で」は「ある」とは合わず、文が不自然になる。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この町の祭り」と、町を祭りの所属先として結ぶ「の」。"}, {"text": "が", "is_correct": false, "explanation": "「この町が祭り」となり、町が祭りを行う主語になって意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「この町より祭りには」は文の流れに合わない。"}, {"text": "を", "is_correct": false, "explanation": "「町を」は目的語の形だが、「来ます」の対象にならず、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「この町の祭り」と、町を祭りの所属先として結ぶ「の」。", "が": "「この町が祭り」となり、町が祭りを行う主語になって意味が通らない。", "より": "比較を表すので、「この町より祭りには」は文の流れに合わない。", "を": "「町を」は目的語の形だが、「来ます」の対象にならず、文として成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お店や家がたくさんあるところです。", "primary_collocate": null, "pronunciation": "まち", "ipa": "matɕi", "syllable_count": 2, "sentences": [{"text": "駅の近くは店や家が多くて、にぎやかな町です。", "target_word": "町", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くは店[みせ]や家[いえ]が多[おお]くて、にぎやかな町[まち]です。", "sentence_source": "generated"}, {"text": "私が生まれた町は、海のそばにあります。", "target_word": "町", "complexity_tier": "T2", "furigana": "私[わたし]が生[う]まれた町[まち]は、海[うみ]のそばにあります。", "sentence_source": "generated"}, {"text": "週末は友達と町で買い物をします。", "target_word": "町", "complexity_tier": "T2", "furigana": "週末[しゅうまつ]は友達[ともだち]と町[まち]で買[か]い物[もの]をします。", "sentence_source": "generated"}, {"text": "古い町なので、細い道がたくさんあります。", "target_word": "町", "complexity_tier": "T3", "furigana": "古[ふる]い町[まち]なので、細[ほそ]い道[みち]がたくさんあります。", "sentence_source": "generated"}, {"text": "駅からバスで町の中心まで行きます。", "target_word": "町", "complexity_tier": "T3", "furigana": "駅[えき]からバスで町[まち]の中心[ちゅうしん]まで行[い]きます。", "sentence_source": "generated"}, {"text": "雨の日は、町を歩く人が少なくなります。", "target_word": "町", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、町[まち]を歩[ある]く人[ひと]が少[すく]なくなります。", "sentence_source": "generated"}, {"text": "新しい町に引っ越して、近所の人にあいさつしました。", "target_word": "町", "complexity_tier": "T4", "furigana": "新[あたら]しい町[まち]に引[ひ]っ越[こ]して、近所[きんじょ]の人[ひと]にあいさつしました。", "sentence_source": "generated"}, {"text": "この町の祭りには、毎年たくさんの人が来ます。", "target_word": "町", "complexity_tier": "T3", "furigana": "この町[まち]の祭[まつ]りには、毎年[まいとし]たくさんの人[ひと]が来[き]ます。", "sentence_source": "generated"}, {"text": "山の上から見ると、町の明かりがきれいです。", "target_word": "町", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から見[み]ると、町[まち]の明[あ]かりがきれいです。", "sentence_source": "generated"}, {"text": "小さな町ですが、おいしいパン屋が何軒もあります。", "target_word": "町", "complexity_tier": "T4", "furigana": "小[ちい]さな町[まち]ですが、おいしいパン屋[や]が何軒[なんげん]もあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "町", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "店や家が集まっている、人が暮らす地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "町", "is_correct": true, "explanation": "店や家が集まった地域を指すので、「にぎやかな町」として文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "空から降るものなので、「にぎやかな雨」とは言わない。"}, {"text": "紙", "is_correct": false, "explanation": "書いたり包んだりする物で、「にぎやかな紙」とは言えない。"}, {"text": "靴", "is_correct": false, "explanation": "履く物で、店や家が多い場所を表す語としては合わない。"}], "explanations": {"町": "店や家が集まった地域を指すので、「にぎやかな町」として文に合う。", "雨": "空から降るものなので、「にぎやかな雨」とは言わない。", "紙": "書いたり包んだりする物で、「にぎやかな紙」とは言えない。", "靴": "履く物で、店や家が多い場所を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "町"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町は毎朝、校長先生が全校生徒にあいさつをする。", "explanation": "校長先生と全校生徒がいる場面は「学校」。「町」は店や家が集まる地域の意味なので、学校には使わない。"}, {"text": "この町は毎朝四時にパンを焼き、お客さんに配る。", "explanation": "パンを焼いて売るのは「パン屋」。「町」は地域を指す言葉で、店として使う意味はない。"}, {"text": "この町は一階が書店で、二階が映画館になっている。", "explanation": "一つの建物の中身を説明するときは「建物」と言う。「町」は地域の意味で、建物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "町", "is_correct": true, "explanation": "住んでいる地域を指す語で、「新しい町に引っ越して」と自然につながる。"}, {"text": "魚", "is_correct": false, "explanation": "泳ぐ生き物で、住む場所として「新しい魚に引っ越す」とは言えない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の一部で、人が引っ越す先にはならない。"}, {"text": "傘", "is_correct": false, "explanation": "雨具で、引っ越す先として文が成り立たない。"}], "explanations": {"町": "住んでいる地域を指す語で、「新しい町に引っ越して」と自然につながる。", "魚": "泳ぐ生き物で、住む場所として「新しい魚に引っ越す」とは言えない。", "窓": "建物の一部で、人が引っ越す先にはならない。", "傘": "雨具で、引っ越す先として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "町"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は夜九時まで開いていて、週末は行列ができる。", "explanation": "開いて営業するのは「店」。「町」は地域を指すので、営業時間があるとは言わない。"}, {"text": "この町は山奥の数軒からなる集落で、水道もない。", "explanation": "数軒の小さな集まりを指すのは「村」。「町」はお店や家がたくさんある地域の意味なので、数軒だけでは合わない。"}, {"text": "この町は時速百キロで走り、駅で乗客を降ろす。", "explanation": "走って乗客を降ろすのは「電車」。「町」は地域を指す言葉なので、乗り物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日曜日は家族と町を食事をします。", "corrected_sentence": "日曜日は家族と町で食事をします。", "error_description": "「町で食事をする」が正しい形。「町を」は目的語を表すので、場所を表す「で」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35138, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父の町を、古い神社がたくさんあります。", "corrected_sentence": "祖父の町には、古い神社がたくさんあります。", "error_description": "「ある」の場所を示すには「には」が正しい。「町を」は目的語になるので、存在を表す文では不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「私の国は」と、国を主題として「冬が長い」と説明する「は」。"}, {"text": "を", "is_correct": false, "explanation": "「私の国を冬が長い」となり、目的語の形では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では「私の国へ冬が長い」となり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「私の国と冬が長い」は国と冬を並べる形になり、文の主題として不自然。"}], "correct_answer": "は", "explanations": {"は": "「私の国は」と、国を主題として「冬が長い」と説明する「は」。", "を": "「私の国を冬が長い」となり、目的語の形では文が成り立たない。", "へ": "方向を表す「へ」では「私の国へ冬が長い」となり、意味が通らない。", "と": "「私の国と冬が長い」は国と冬を並べる形になり、文の主題として不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「南の国へ旅行します」と、旅行の行き先（方向）を示す「へ」。"}, {"text": "が", "is_correct": false, "explanation": "「南の国が旅行します」となり、国が旅行する主語になって不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、旅行の行き先の説明にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「南の国の旅行します」は、旅行を行う助詞が欠けて文が成り立たない。"}], "correct_answer": "へ", "explanations": {"へ": "「南の国へ旅行します」と、旅行の行き先（方向）を示す「へ」。", "が": "「南の国が旅行します」となり、国が旅行する主語になって不自然。", "より": "比較を表すので、旅行の行き先の説明にはならない。", "の": "「南の国の旅行します」は、旅行を行う助詞が欠けて文が成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がたくさん住んでいる、決まった土地のまとまり。それぞれに国という名前がある。", "primary_collocate": null, "pronunciation": "くに", "ipa": "kɯɲi", "syllable_count": 2, "sentences": [{"text": "日本は、海にかこまれた島の国です。", "target_word": "国", "complexity_tier": "T2", "furigana": "日本[にほん]は、海[うみ]にかこまれた島[しま]の国[くに]です。", "sentence_source": "generated"}, {"text": "私の国は冬がとても長くて、雪がたくさん降ります。", "target_word": "国", "complexity_tier": "T3", "furigana": "私[わたし]の国[くに]は冬[ふゆ]がとても長[なが]くて、雪[ゆき]がたくさん降[ふ]ります。", "sentence_source": "generated"}, {"text": "世界には、二百ほどの国があります。", "target_word": "国", "complexity_tier": "T2", "furigana": "世界[せかい]には、二百[にひゃく]ほどの国[くに]があります。", "sentence_source": "generated"}, {"text": "暑い国で育ったので、寒い冬は苦手です。", "target_word": "国", "complexity_tier": "T3", "furigana": "暑[あつ]い国[くに]で育[そだ]ったので、寒[さむ]い冬[ふゆ]は苦手[にがて]です。", "sentence_source": "generated"}, {"text": "この国では、お正月に家族みんなで集まります。", "target_word": "国", "complexity_tier": "T3", "furigana": "この国[くに]では、お正月[しょうがつ]に家族[かぞく]みんなで集[あつ]まります。", "sentence_source": "generated"}, {"text": "国ごとに、あいさつのしかたが少しちがいます。", "target_word": "国", "complexity_tier": "T3", "furigana": "国[くに]ごとに、あいさつのしかたが少[すこ]しちがいます。", "sentence_source": "generated"}, {"text": "ブラジルは広くて、サッカーがさかんな国です。", "target_word": "国", "complexity_tier": "T3", "furigana": "ブラジルは広[ひろ]くて、サッカーがさかんな国[くに]です。", "sentence_source": "generated"}, {"text": "来月、はじめて南の国へ旅行します。", "target_word": "国", "complexity_tier": "T2", "furigana": "来月[らいげつ]、はじめて南[みなみ]の国[くに]へ旅行[りょこう]します。", "sentence_source": "generated"}, {"text": "小さな国でも、その国にしかない文化があります。", "target_word": "国", "complexity_tier": "T3", "furigana": "小[ちい]さな国[くに]でも、その国[くに]にしかない文化[ぶんか]があります。", "sentence_source": "generated"}, {"text": "地図で国の名前を調べるのが好きです。", "target_word": "国", "complexity_tier": "T3", "furigana": "地図[ちず]で国[くに]の名前[なまえ]を調[しら]べるのが好[す]きです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "人々が住む、名前のある土地としての国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: かこま (Zipf 2.15)','sentence 5 above tier T1: 3 words above tier T1 (max 2): あいさつ (Zipf 3.66), しかた (Zipf 3.9), ちがい (Zipf 3.6)']::text[], '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国", "is_correct": true, "explanation": "人が住む、名前のある土地のまとまりを指し、「島の国」として文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "空から降るものなので、「島の雨」とは言わない。"}, {"text": "紙", "is_correct": false, "explanation": "書いたり包んだりする物で、土地の名前には合わない。"}, {"text": "靴", "is_correct": false, "explanation": "履く物で、島を表す語としては合わない。"}], "explanations": {"国": "人が住む、名前のある土地のまとまりを指し、「島の国」として文に合う。", "雨": "空から降るものなので、「島の雨」とは言わない。", "紙": "書いたり包んだりする物で、土地の名前には合わない。", "靴": "履く物で、島を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国は革製で、教科書とノートが入る。", "explanation": "教科書やノートを入れて持ち歩くのは「かばん」。「国」は土地のまとまりなので、物には使わない。"}, {"text": "東京は人口が千四百万人を超える国だ。", "explanation": "都市の規模を説明するときは「都市」と言う。「国」は独立した土地のまとまりなので、東京には使わない。"}, {"text": "この国は五階建てで、一階がカフェになっている。", "explanation": "建物の階数を言うのは「建物」。「国」は土地の区分なので、階数の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国", "is_correct": true, "explanation": "一つの独立した土地のまとまりを指し、「サッカーがさかんな国」として文に合う。"}, {"text": "魚", "is_correct": false, "explanation": "泳ぐ生き物で、「サッカーがさかんな魚」とは言わない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の一部で、この文の内容には合わない。"}, {"text": "傘", "is_correct": false, "explanation": "雨具で、サッカーに関係する土地の名前ではない。"}], "explanations": {"国": "一つの独立した土地のまとまりを指し、「サッカーがさかんな国」として文に合う。", "魚": "泳ぐ生き物で、「サッカーがさかんな魚」とは言わない。", "窓": "建物の一部で、この文の内容には合わない。", "傘": "雨具で、サッカーに関係する土地の名前ではない。"}, "sentence_index": 6, "correct_answer": "国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国はとても辛くて、食べると汗が出る。", "explanation": "辛くて食べると汗が出るのは「料理」。「国」は土地のまとまりなので、食べ物には使わない。"}, {"text": "この国は一日に十万人が乗り降りする。", "explanation": "人が乗り降りするのは「駅」。「国」は土地のまとまりなので、乗り降りの場所には合わない。"}, {"text": "この国は毎朝八時に開店する。", "explanation": "お客に品物を売る場所は「商店」。「国」は土地のまとまりで、商売はしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父母は海外の国を住んでいます。", "corrected_sentence": "祖父母は海外の国に住んでいます。", "error_description": "「住む」は場所に「に」を取る動詞。「国を」は目的語になるので、「国に住んでいる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35140, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多くの国が、留学生が日本に来ています。", "corrected_sentence": "多くの国から、留学生が日本に来ています。", "error_description": "出発点を表すには「から」が正しい。「国が」は主語になり、「留学生が来る」ことの主語として意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この国の政府」と、政府が国に属することを示す「の」。"}, {"text": "が", "is_correct": false, "explanation": "「この国が政府は」となり、主語が二つ重なって不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「この国を政府は」は目的語の形で、文の構造が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では「この国へ政府は」となり、政府の所属を示せない。"}], "correct_answer": "の", "explanations": {"の": "「この国の政府」と、政府が国に属することを示す「の」。", "が": "「この国が政府は」となり、主語が二つ重なって不自然になる。", "を": "「この国を政府は」は目的語の形で、文の構造が成り立たない。", "へ": "方向を表す「へ」では「この国へ政府は」となり、政府の所属を示せない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「国は災害にあった町を」と、国を主題として取り上げ、その行動を述べる「は」。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「国より…お金を出しました」は文脈に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「国を、町を助ける」と目的語が二つ並び、文の形が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「国に」は相手や場所を示すが、「お金を出しました」の主語としては文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「国は災害にあった町を」と、国を主題として取り上げ、その行動を述べる「は」。", "より": "比較を表すので、「国より…お金を出しました」は文脈に合わない。", "を": "「国を、町を助ける」と目的語が二つ並び、文の形が成り立たない。", "に": "「国に」は相手や場所を示すが、「お金を出しました」の主語としては文が成り立たない。"}, "error_tags": {"より": "比較", "に": "場所・相手", "を": "二重の目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1fa91a-7aca-4910-94dc-199f440e31bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35141, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間が作り出した、政治的な境界によって区切られた地域。国民や政府があり、他の地域とは異なるルールで動く。", "primary_collocate": null, "pronunciation": "くに", "ipa": "kɯɲi", "syllable_count": 2, "sentences": [{"text": "国は、国民のために新しい法律を作ります。", "target_word": "国", "complexity_tier": "T3", "furigana": "国[くに]は、国民[こくみん]のために新[あたら]しい法律[ほうりつ]を作[つく]ります。", "sentence_source": "generated"}, {"text": "この国の政府は、来年から税金を下げると発表しました。", "target_word": "国", "complexity_tier": "T4", "furigana": "この国[くに]の政府[せいふ]は、来年[らいねん]から税金[ぜいきん]を下[さ]げると発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "国によって、法律やルールがちがいます。", "target_word": "国", "complexity_tier": "T3", "furigana": "国[くに]によって、法律[ほうりつ]やルールがちがいます。", "sentence_source": "generated"}, {"text": "国が学校の費用を出してくれるので、子どもは無料で通えます。", "target_word": "国", "complexity_tier": "T4", "furigana": "国[くに]が学校[がっこう]の費用[ひよう]を出[だ]してくれるので、子[こ]どもは無料[むりょう]で通[かよ]えます。", "sentence_source": "generated"}, {"text": "二つの国は、国境のことで長い間話し合っています。", "target_word": "国", "complexity_tier": "T4", "furigana": "二[ふた]つの国[くに]は、国境[こっきょう]のことで長[なが]い間[あいだ]話[はな]し合[あ]っています。", "sentence_source": "generated"}, {"text": "選挙で、国の代表を選びます。", "target_word": "国", "complexity_tier": "T3", "furigana": "選挙[せんきょ]で、国[くに]の代表[だいひょう]を選[えら]びます。", "sentence_source": "generated"}, {"text": "その国では、十八歳になると選挙に行けます。", "target_word": "国", "complexity_tier": "T3", "furigana": "その国[くに]では、十八歳[じゅうはっさい]になると選挙[せんきょ]に行[い]けます。", "sentence_source": "generated"}, {"text": "国は災害にあった町を助けるために、お金を出しました。", "target_word": "国", "complexity_tier": "T4", "furigana": "国[くに]は災害[さいがい]にあった町[まち]を助[たす]けるために、お金[かね]を出[だ]しました。", "sentence_source": "generated"}, {"text": "国のルールを守らないと、罰を受けます。", "target_word": "国", "complexity_tier": "T3", "furigana": "国[くに]のルールを守[まも]らないと、罰[ばつ]を受[う]けます。", "sentence_source": "generated"}, {"text": "国どうしが協力して、環境問題に取り組んでいます。", "target_word": "国", "complexity_tier": "T4", "furigana": "国[くに]どうしが協力[きょうりょく]して、環境[かんきょう]問題[もんだい]に取[と]り組[く]んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "政府・国民・法律を持つ政治的なまとまりとしての国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82bc3f5f-a777-4e8f-a68b-12799a2d2b95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
